/// <summary>
/// Browser-facing runtime seam for page script execution. This keeps the browser
/// pipeline independent from the concrete JS engine so FenJS can replace the
/// legacy runtime without rewriting every rendering/navigation call site.
/// </summary>
public interface IBrowserScriptEngine
{
    IExecutionContext GlobalContext { get; }
    JavaScriptRuntimeProfile RuntimeProfile { get; }
    Func<Uri, Task<string>> FetchOverride { get; set; }
    Func<Uri, string, bool> SubresourceAllowed { get; set; }
    Func<Uri, string, bool> TrustedDynamicSubresourceAllowed { get; set; }
    Func<string, bool> NonceAllowed { get; set; }
    Func<HttpRequestMessage, Task<HttpResponseMessage>> FetchHandler { get; set; }
    Func<Uri, string> CookieReadBridge { get; set; }
    Action<Uri, string> CookieWriteBridge { get; set; }
    Action RequestRender { get; set; }
Action<Element> FlushPendingLayout { get; set; }
    Func<Uri, Uri, Task<string>> ExternalScriptFetcher { get; set; }

    /// <summary>
    /// Optional nonce-aware variant preferred over <see cref="ExternalScriptFetcher"/>
    /// when set; the third argument is the authorizing element's CSP nonce (or null).
    /// </summary>
    Func<Uri, Uri, string, Task<string>> ExternalScriptFetcherWithNonce { get; set; }

    /// <summary>
    /// Fetches a dedicated worker's script. A worker is not a classic script:
    /// it is requested with a "worker" destination and checked against
    /// worker-src, so the nonce-carrying script fetcher would ask the wrong
    /// question of the policy and be refused.
    /// </summary>
    Func<Uri, Uri, Task<string>> WorkerScriptFetcher { get; set; }
    Func<Element, Uri, Task> FrameElementLoader { get; set; }

    /// <summary>
    /// Runs <paramref name="work"/> on the thread that executes this engine's
    /// scripts, after any script currently running and before the next one:
    /// the slot where a browser's main thread does style recalc and other
    /// rendering-update steps (HTML "update the rendering"), so the work sees a
    /// DOM no script is mutating. Always queued, even when called from the
    /// script thread itself: a mutation observer or attribute setter that
    /// schedules work must not have it run before the mutation has finished.
    /// The returned task completes when the work has finished.
    /// </summary>
    Task RunOnScriptThreadAsync(Func<Task> work);

    /// <summary>
    /// Enters the host's image-loader request scope, so image fetches the
    /// script engine starts share the cache and cache keys of the ones
    /// layout starts. Null means unscoped.
    /// </summary>
    Func<IDisposable> ImageLoaderScope { get; set; }

    /// <summary>
    /// Top-viewport hit test: the element painted at (x, y), which may sit in
    /// a nested frame's document. Backs document.elementFromPoint.
    /// </summary>
    Func<double, double, Element> ViewportHitTester { get; set; }
    Func<Element, object> LayoutBoxResolver { get; set; }
    Func<Element, (double X, double Y)> FrameScrollReader { get; set; }
    Action<Element, double, double> FrameScrollWriter { get; set; }
    SandboxPolicy Sandbox { get; set; }
    FenBrowser.Core.Security.DocumentSecurityContext DocumentSecurityContext { get; set; }
    CancellationToken ExecutionCancellation { get; set; }
    bool AllowExternalScripts { get; set; }
    bool ExecuteInlineScriptsOnInnerHTML { get; set; }
    double WindowWidth { get; set; }
    double WindowHeight { get; set; }
    int PageScriptByteBudget { get; set; }
    event Func<string, JsPermissions, Task<bool>> PermissionRequested;

    void CaptureNavigationGlobals(Uri documentUri, long navigationId);
    BrowserScriptLoadingSnapshot GetScriptLoadingSnapshot();
    BrowserEventLoopSnapshot GetEventLoopSnapshot();
    void SetHistoryBridge(IHistoryBridge bridge);
    void NotifyPopState(object state);
    void NotifyFrameScrollChanged(Element frameElement);
    bool IsEventDispatchBusy(Element element);
    bool DispatchEventForElement(Element element, string eventName, BrowserDomEventInit eventInit = null);
    /// <summary>
    /// Phase 12: non-blocking variant. Dispatches a JS event asynchronously so
    /// the engine thread is not blocked while the JS worker executes handlers.
    /// </summary>
    Task<bool> DispatchEventForElementAsync(Element element, string eventName, BrowserDomEventInit eventInit = null);
    object Evaluate(string script);

    /// <summary>
    /// Evaluates <paramref name="script"/> in the browsing context that
    /// <paramref name="frameElement"/> embeds, rather than in this realm.
    /// WebDriver's Execute Script runs in the current browsing context, so a
    /// script issued while a frame is selected has to see that frame's window,
    /// document and location. Falls back to this realm when the frame has no
    /// realm of its own.
    /// </summary>
    object EvaluateInFrame(Element frameElement, string script);
    bool TryResolveHostObject(FenBrowser.Js.Runtime.JsValue value, out object hostObject);
    object ConvertJsValueToObject(FenBrowser.Js.Runtime.JsValue value);
    void SyncDomContext(Node domRoot, Uri baseUri = null);
    Task SetDomAsync(Node domRoot, Uri baseUri = null, CancellationToken cancellationToken = default);

    /// <summary>
    /// Returns the JS engine for the frame containing <paramref name="element"/>,
    /// or null if the element is in the top-level document.
    /// This allows event dispatch to route to the correct frame's JS engine.
    /// </summary>
    IBrowserScriptEngine GetFrameEngineForElement(Element element);
}

