/// <summary>
/// FenJS browser script engine â€” the sole JS runtime for the browser pipeline.
/// All page scripts execute through FenJS; there is no legacy fallback.
/// </summary>
public sealed partial class FenJsBrowserScriptEngine : IBrowserScriptEngine, IHeapRootSource
{
    private sealed class MessagePortEndpoint
    {
        // Transfer detaches a port from one realm before the receiving realm
        // binds it, so for a moment it has no owner. HTML 9.4.5 keeps the port
        // message queue with the port across that hop: messages posted to it
        // while it is in transit are queued and delivered once it is
        // re-entangled. Dropping them instead cost reCAPTCHA its three setup
        // payloads and left it waiting for a reply that could never come.
        public readonly object TransitLock = new();

        public long TraceId { get; init; }
        public MessagePortEndpoint Peer { get; set; }
        public FenJsBrowserScriptEngine Owner { get; set; }
        public JsValue Port { get; set; } = JsValue.Undefined;
        public bool Closed { get; set; }
        public List<PendingPortMessage> InTransitQueue { get; set; }
    }

    /// <summary>
    /// One message held for a port that is between realms. Everything here has
    /// already been converted out of the sending realm's heap, so it stays
    /// valid however long the hop takes.
    /// </summary>
    private sealed class PendingPortMessage
    {
        public object Data { get; init; }
        public IReadOnlyList<MessagePortEndpoint> Transferred { get; init; }
        public long MessageId { get; init; }
        public long SourcePortId { get; init; }
        public string SourceFrame { get; init; }
        public string TargetFrame { get; init; }
        public string Payload { get; init; }
    }

    // A port that is transferred and never bound would otherwise buffer without
    // limit. The cap is far above any real handshake and only exists so a lost
    // port cannot become a leak.
    private const int MaxInTransitPortMessages = 256;

    private sealed class FenJsTimerRegistration : IDisposable
    {
        public Timer Timer { get; set; }
        public JsValue Callback { get; init; }
        public IReadOnlyList<JsValue> Arguments { get; init; } = Array.Empty<JsValue>();
        public FenJsWindowCallbackContext WindowContext { get; init; }
        public int CallbackPending;

        public void Dispose() => Timer?.Dispose();
    }

    private sealed class FenJsPinScope : IDisposable
    {
        private readonly FenJsBrowserScriptEngine _owner;

        public FenJsPinScope(FenJsBrowserScriptEngine owner, int generation, ObjectHandle[] handles)
        {
            _owner = owner;
            Generation = generation;
            Handles = handles;
        }

        public int Generation { get; }

        public ObjectHandle[] Handles { get; }

        public void Dispose() => _owner._fenJsPinScopes.TryRemove(this, out _);
    }

    // Pins object-tagged values for the lifetime of the returned scope. Values
    // without an object handle (numbers, strings, undefined, host objects) need
    // no heap rooting; a null scope is returned when nothing requires pinning.
    private IDisposable PinFenJsValues(params JsValue[] values)
    {
        if (values == null || values.Length == 0)
        {
            return null;
        }

        ObjectHandle[] handles = null;
        var objectCount = 0;
        for (var i = 0; i < values.Length; i++)
        {
            if (values[i].Tag == JsValueTag.Object)
            {
                objectCount++;
            }
        }

        if (objectCount > 0)
        {
            handles = new ObjectHandle[objectCount];
            var write = 0;
            for (var i = 0; i < values.Length; i++)
            {
                if (values[i].Tag == JsValueTag.Object)
                {
                    handles[write++] = values[i].AsObjectHandle();
                }
            }
        }

        if (handles == null)
        {
            return null;
        }

        var scope = new FenJsPinScope(this, _fenJsSessionGeneration, handles);
        _fenJsPinScopes[scope] = 1;
        return scope;
    }

    private readonly object _fenJsLock = new();
    private readonly object _windowMessageQueueLock = new();
    private Task _windowMessageDeliveryTail = Task.CompletedTask;

    /// <summary>
    /// Completes when this document's own scripts have finished running.
    ///
    /// A message posted into a frame is a task, and a task does not run in the
    /// middle of another one. The script batch releases the interpreter lock
    /// between scripts, though, so a delivery waiting on that lock takes the
    /// gap -- reCAPTCHA's challenge frame was handed the page's set-up message
    /// 1.5ms before the inline script that registers its listener ran, and then
    /// waited forever for a message it had already been given.
    ///
    /// Chaining a barrier onto the delivery queue was not enough: a message
    /// queued before the batch began sits ahead of the barrier. Every delivery
    /// waits on this instead, whenever it was queued.
    /// </summary>
    private volatile Task _pageScriptsFinished = Task.CompletedTask;

    private void WaitForPageScripts()
    {
        var gate = _pageScriptsFinished;
        if (gate.IsCompleted)
        {
            return;
        }

        try
        {
            // Bounded: a batch that never finishes must not wedge messaging for
            // the life of the page.
            gate.Wait(PageScriptGateTimeoutMs);
        }
        catch
        {
            // A failed batch is still a finished one as far as delivery goes.
        }
    }

    private const int PageScriptGateTimeoutMs = 10_000;
    private readonly ConcurrentDictionary<long, FenJsTimerRegistration> _fenJsTimers = new();
    // JsValues held only by C# locals across a worker-thread marshal (event
    // facades, queued message payloads, restored window.event values) are
    // invisible to the FenJS GC root set, so a collection triggered by other
    // engine work can sweep them and the later use throws "Stale heap handle".
    // Pin scopes keep those handles traced from creation until the marshaled
    // work completes. Scopes are generation-tagged so a session reset (new
    // heap) never traces old-heap handles.
    private readonly ConcurrentDictionary<FenJsPinScope, byte> _fenJsPinScopes = new();
    private long _fenJsTimerIdCounter;
    private long _diagnosticCookieCaptureCounter;
    private JsValue _fenJsGlobalThis = JsValue.Undefined;
    private JsValue _visualViewport = JsValue.Undefined;
    private JsValue _fenJsTopWindowFacade = JsValue.Undefined;
    private JsValue _fenJsSameOriginTopWindowFacade = JsValue.Undefined;
    private readonly System.Diagnostics.Stopwatch _fenJsClock = System.Diagnostics.Stopwatch.StartNew();
    private static readonly Dictionary<string, JsValue> ComputedStyleInitialValues = BuildComputedStyleInitialValues();
    private readonly BrowserFenJsHostHooks _hostHooks = new();
    private readonly NavigationEpoch _navigationEpoch = NavigationEpoch.Initial;
    private string _currentDocumentId = string.Empty;
    // How many times this realm has been bound to a document. A second bind runs
    // ResetFenJsSession, so everything the previous document's scripts built --
    // globals, listener maps, message-port handlers -- is discarded while the DOM
    // survives. That is invisible from the page's side and looks exactly like a
    // widget that rendered and then ignored every event, so count and report it.
    private int _domBindCount;
    private long _callbackFailureSequence;
    private long _diagnosticCallbackIdSequence;
    private FenJsDiagnosticPromiseRejectionTracker _diagnosticPromiseRejectionTracker;
    private readonly Dictionary<BytecodeFunction, CallbackSourceProvenance> _callbackFunctionProvenance = new();
    private readonly Dictionary<JsValue, PendingPromiseRejectionDiagnostic> _pendingPromiseRejectionDiagnostics = new();
