    public void CaptureNavigationGlobals(Uri documentUri, long navigationId)
    {
        if (!ShouldCaptureNavigationGlobals() || _interpreter == null)
        {
            return;
        }

        try
        {
            var snapshot = new Dictionary<string, object>
            {
                ["globals"] = CaptureProbeGlobals(),
                ["cookies"] = CaptureCookieNames(documentUri),
            };
            var envelope = new Dictionary<string, object>
            {
                ["schema"] = "fenbrowser.navigation-globals.v1",
                ["capturedAtUtc"] = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture),
                ["navigationId"] = navigationId,
                ["documentUri"] = documentUri?.AbsoluteUri ?? string.Empty,
                ["snapshot"] = snapshot,
            };

            var fileName = "nav_globals_" +
                navigationId.ToString(CultureInfo.InvariantCulture) + "_" +
                DateTimeOffset.UtcNow.ToString("yyyyMMdd_HHmmss_fff", CultureInfo.InvariantCulture) +
                ".json";
            var path = Path.Combine(DiagnosticPaths.GetLogsDirectory(), fileName);
            var json = JsonSerializer.Serialize(envelope, new JsonSerializerOptions { WriteIndented = true });
            File.WriteAllText(path, json, new UTF8Encoding(false));
        }
        catch (Exception ex)
        {
            EngineLogCompat.Debug(
                $"[NavigationGlobalsProbe] capture failed: {ex.GetType().Name}: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    private static bool ShouldCaptureNavigationGlobals()
    {
        if (string.Equals(Environment.GetEnvironmentVariable("FEN_NAV_GLOBALS_SNAPSHOT"), "1", StringComparison.Ordinal))
        {
            return true;
        }

        try
        {
            return BrowserSettings.Instance?.Logging?.LogNavigationGlobals == true;
        }
        catch
        {
            return false;
        }
    }

    private Dictionary<string, object> CaptureProbeGlobals()
    {
        var globals = new Dictionary<string, object>(StringComparer.Ordinal);
        foreach (var (alias, expression) in NavigationGlobalProbeNames)
        {
            globals[alias] = DescribeProbeValue(ReadProbeExpression(expression));
        }

        return globals;
    }

    private static readonly (string Alias, string Expression)[] NavigationGlobalProbeNames =
    {
        ("sgs", "globalThis.sgs"),
        ("ussv", "globalThis.ussv"),
        ("sp", "globalThis.sp"),
        ("prs", "globalThis.prs"),
        ("st", "globalThis.st"),
        ("td", "globalThis.td"),
        ("google", "globalThis.google"),
        ("challenge_version", "globalThis.challenge_version"),
        ("cbs", "globalThis.cbs"),
        ("ce", "globalThis.ce"),
        ("r", "globalThis.r"),
        ("ss_cgi", "globalThis.ss_cgi"),
        ("sclm", "globalThis.sclm"),
        ("sctm", "globalThis.sctm"),
        ("eid", "globalThis.eid"),
        ("fetch", "globalThis.fetch"),
        ("XMLHttpRequest", "globalThis.XMLHttpRequest"),
        ("crypto", "globalThis.crypto"),
        ("navigator", "globalThis.navigator"),
        ("performance", "globalThis.performance"),
        ("webdriver", "globalThis.navigator && globalThis.navigator.webdriver"),
        ("chrome", "globalThis.chrome"),
        ("React", "globalThis.React"),
        ("jQuery", "globalThis.jQuery"),
        ("$", "globalThis.$"),
        ("reactDevtoolsHook_alias", "globalThis.__REACT_DEVTOOLS_GLOBAL_HOOK__"),
        ("nextData_alias", "globalThis.__NEXT_DATA__"),
    };

    private JsValue ReadProbeExpression(string expression)
    {
        const string prefix = "globalThis.";
        try
        {
            if (expression.StartsWith(prefix, StringComparison.Ordinal) &&
                expression.IndexOfAny(new[] { '&', ' ', '(', ')' }) < 0)
            {
                var globalName = expression.Substring(prefix.Length);
                return _interpreter.TryReadGlobalValue(globalName, out var globalValue)
                    ? globalValue
                    : JsValue.Undefined;
            }

            if (string.Equals(expression, "globalThis.navigator && globalThis.navigator.webdriver", StringComparison.Ordinal) &&
                _interpreter.TryReadGlobalValue("navigator", out var navigator))
            {
                return ReadJsProperty(navigator, "webdriver");
            }
        }
        catch
        {
        }

        return JsValue.Undefined;
    }

    private Dictionary<string, object> DescribeProbeValue(JsValue value)
    {
        var description = new Dictionary<string, object>(StringComparer.Ordinal)
        {
            ["exists"] = value.Tag != JsValueTag.Undefined,
            ["type"] = GetProbeType(value),
        };

        try
        {
            switch (value.Tag)
            {
                case JsValueTag.Boolean:
                    description["value"] = value.AsBoolean();
                    break;
                case JsValueTag.Int32:
                    description["value"] = value.AsInt32();
                    break;
                case JsValueTag.Number:
                    description["value"] = value.AsNumber();
                    break;
                case JsValueTag.String:
                    description["charCount"] = value.AsString().Length;
                    break;
                case JsValueTag.Object:
                    if (_interpreter.CanCallValue(value))
                    {
                        var length = ReadJsProperty(value, "length");
                        if (TryReadProbeNumber(length, out var arity))
                        {
                            description["arity"] = (int)Math.Max(0, arity);
                        }
                    }

                    var obj = _interpreter.Heap.GetObject(value.AsObjectHandle());
                    if (obj != null)
                    {
                        description["ownKeys"] = obj.EnumerateOwnProperties()
                            .Select(p => p.Key)
                            .Take(80)
                            .ToArray();
                    }
                    break;
            }
        }
        catch
        {
            description["probeError"] = true;
        }

        return description;
    }

    private string GetProbeType(JsValue value)
    {
        if (value.Tag == JsValueTag.Object && _interpreter != null && _interpreter.CanCallValue(value))
        {
            return "function";
        }

        return value.Tag switch
        {
            JsValueTag.Undefined => "undefined",
            JsValueTag.Null => "null",
            JsValueTag.Boolean => "boolean",
            JsValueTag.Int32 => "number",
            JsValueTag.Number => "number",
            JsValueTag.String => "string",
            JsValueTag.Symbol => "symbol",
            JsValueTag.BigInt => "bigint",
            JsValueTag.Object => "object",
            JsValueTag.HostObject => "hostobject",
            _ => "unknown",
        };
    }

    private static bool TryReadProbeNumber(JsValue value, out double number)
    {
        switch (value.Tag)
        {
            case JsValueTag.Int32:
                number = value.AsInt32();
                return true;
            case JsValueTag.Number:
                number = value.AsNumber();
                return true;
            default:
                number = 0;
                return false;
        }
    }

    private Dictionary<string, object> CaptureCookieNames(Uri documentUri)
    {
        var result = new Dictionary<string, object>(StringComparer.Ordinal)
        {
            ["names"] = Array.Empty<string>(),
        };

        if (documentUri == null || CookieReadBridge == null)
        {
            return result;
        }

        try
        {
            var cookie = CookieReadBridge(documentUri) ?? string.Empty;
            var names = cookie.Split(';', StringSplitOptions.RemoveEmptyEntries)
                .Select(part => part.Trim())
                .Select(part =>
                {
                    var eq = part.IndexOf('=');
                    return eq > 0 ? part.Substring(0, eq).Trim() : part;
                })
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .Distinct(StringComparer.Ordinal)
                .OrderBy(name => name, StringComparer.Ordinal)
                .Select(RedactSensitiveCookieName)
                .ToArray();
            result["names"] = names;
            result["count"] = names.Length;
        }
        catch
        {
            result["probeError"] = true;
        }

        return result;
    }

    // Cookie *names* can themselves reveal identity-bearing identifiers
    // (e.g. "session-token", "csrf", "auth-user"). Hash names that match a
    // sensitive pattern so the diagnostic never records a usable identifier.
    private static string RedactSensitiveCookieName(string name)
    {
        if (string.IsNullOrWhiteSpace(name))
        {
            return name ?? string.Empty;
        }

        var lower = name.ToLowerInvariant();
        bool sensitive =
            lower.Contains("token", StringComparison.Ordinal) ||
            lower.Contains("session", StringComparison.Ordinal) ||
            lower.Contains("auth", StringComparison.Ordinal) ||
            lower.Contains("csrf", StringComparison.Ordinal) ||
            lower.Contains("secret", StringComparison.Ordinal) ||
            lower.Contains("key", StringComparison.Ordinal) ||
            lower.Contains("sid", StringComparison.Ordinal) ||
            lower.Contains("ssid", StringComparison.Ordinal) ||
            lower.Contains("credential", StringComparison.Ordinal) ||
            lower.Contains("password", StringComparison.Ordinal) ||
            lower.Contains("passwd", StringComparison.Ordinal);

        if (!sensitive)
        {
            return name;
        }

        // Stable, short FNV-1a hash so the same cookie is identifiable across
        // captures without revealing its name.
        return "h:" + StableHash(name);
    }

    private static string StableHash(string text)
    {
        var bytes = System.Text.Encoding.UTF8.GetBytes(text ?? string.Empty);
        unchecked
        {
            ulong hash = 1469598103934665603UL; // FNV-1a 64 offset basis
            for (int i = 0; i < bytes.Length; i++)
            {
                hash ^= bytes[i];
                hash *= 1099511628211UL;
            }
            return hash.ToString("x12");
        }
    }

    public void NotifyPopState(object state)
    {
        // popstate events are dispatched through the FenJS event system
        // when the history bridge fires.
    }

    public bool DispatchEventForElement(Element element, string eventName, BrowserDomEventInit eventInit = null)
    {
        if (element == null || string.IsNullOrWhiteSpace(eventName))
            return true;

        if (TryGetFrameRealm(element.OwnerDocument, out var frameRealm))
        {
            if (DiagnosticPaths.IframeDiagnosticsEnabled)
            {
                var tag = element?.TagName ?? "null";
                var id = element?.GetAttribute("id") ?? "";
                var classAttr = element?.GetAttribute("class") ?? "";
                DiagnosticPaths.AppendLogText(
                    "iframe_diagnostics.txt",
                    $"{DateTimeOffset.UtcNow:O} DispatchEventForElement (iframe): element=<{tag}> id='{id}' class='{classAttr}' event={eventName}");
            }
            LogInputPipelineDispatch(element, eventName, "iframe");
            var defaultAllowed = frameRealm.DispatchEventForElement(element, eventName, eventInit);
            if (DiagnosticPaths.IframeDiagnosticsEnabled)
            {
                DiagnosticPaths.AppendLogText(
                    "iframe_diagnostics.txt",
                    $"{DateTimeOffset.UtcNow:O} DispatchEventForElement (iframe) result: defaultAllowed={defaultAllowed}");
            }
            SyncFrameRealmObservables(TryGetFrameElementForDocument(element.OwnerDocument), frameRealm);
            LogInputPipelineCompletion(element, eventName, defaultAllowed);
            return defaultAllowed;
        }

        try
        {
            if (DiagnosticPaths.IframeDiagnosticsEnabled)
            {
                var tag = element?.TagName ?? "null";
                var id = element?.GetAttribute("id") ?? "";
                var classAttr = element?.GetAttribute("class") ?? "";
                DiagnosticPaths.AppendLogText(
                    "iframe_diagnostics.txt",
                    $"{DateTimeOffset.UtcNow:O} DispatchEventForElement (local): element=<{tag}> id='{id}' class='{classAttr}' event={eventName}");
            }
            var inputTimeoutMs = ResolveFenJsInputEventTimeoutMs();
            return RunFenJsWithLargeStack(() =>
            {
                using (ScriptEngineLockProbe.Hold(_fenJsLock))
                {
                    var currentDocument = _currentDomRoot as Document ?? _currentDomRoot?.OwnerDocument;
                    var windowContext = _parentRealmOwner != null &&
                        ReferenceEquals(element.OwnerDocument, currentDocument)
                            ? null
                            : ActivateSubdocumentWindowContext(element.OwnerDocument, null);
                    using (windowContext)
                    {
                        return _interpreter.RunWithExecutionBudget(
                            inputTimeoutMs,
                            FenJsBrowserInstructionBudget,
                            () =>
                            {
                                var eventValue = CreateBrowserDomEventValue(element, eventName, eventInit, out var dispatchState);
                                var defaultAllowed = DispatchElementEventWithActivation(
                                    element,
                                    eventName,
                                    eventValue,
                                    dispatchState);
                                _interpreter.PumpMicrotasks();
                                RecordMicrotaskCheckpoint("event:" + eventName);
                                if (DiagnosticPaths.IframeDiagnosticsEnabled)
                                {
                                    DiagnosticPaths.AppendLogText(
                                        "iframe_diagnostics.txt",
                                        $"{DateTimeOffset.UtcNow:O} DispatchEventForElement (local) result: defaultAllowed={defaultAllowed}");
                                }
                                return defaultAllowed;
                            });
                    }
                }
            }, inputTimeoutMs, FenJsBrowserInstructionBudget, prioritize: true);
        }
        catch (JsThrownException ex) when (IsFenJsInputEventTimeout(ex))
        {
            throw new FenBrowser.FenEngine.Errors.FenTimeoutError(
                $"Timed out dispatching '{eventName}' event.");
        }
    }

    /// <summary>
    /// Phase 12: non-blocking variant of <see cref="DispatchEventForElement"/>.
    /// Dispatches a JS event to the given element and returns a Task that
    /// completes when JS execution finishes (or times out). The calling thread
    /// is never blocked â€” the JS worker signals completion via TCS.
    /// </summary>
    public async Task<bool> DispatchEventForElementAsync(Element element, string eventName, BrowserDomEventInit eventInit = null)
    {
        if (element == null || string.IsNullOrWhiteSpace(eventName))
            return true;

        if (TryGetFrameRealm(element.OwnerDocument, out var frameRealm))
        {
            if (DiagnosticPaths.IframeDiagnosticsEnabled)
            {
                var tag = element?.TagName ?? "null";
                var id = element?.GetAttribute("id") ?? "";
                var classAttr = element?.GetAttribute("class") ?? "";
                DiagnosticPaths.AppendLogText(
                    "iframe_diagnostics.txt",
                    $"{DateTimeOffset.UtcNow:O} DispatchEventForElementAsync (iframe): element=<{tag}> id='{id}' class='{classAttr}' event={eventName}");
            }
            LogInputPipelineDispatch(element, eventName, "iframe");
            var defaultAllowed = await frameRealm.DispatchEventForElementAsync(element, eventName, eventInit)
                .ConfigureAwait(false);
            if (DiagnosticPaths.IframeDiagnosticsEnabled)
            {
                DiagnosticPaths.AppendLogText(
                    "iframe_diagnostics.txt",
                    $"{DateTimeOffset.UtcNow:O} DispatchEventForElementAsync (iframe) result: defaultAllowed={defaultAllowed}");
            }
            SyncFrameRealmObservables(TryGetFrameElementForDocument(element.OwnerDocument), frameRealm);
            LogInputPipelineCompletion(element, eventName, defaultAllowed);
            return defaultAllowed;
        }

        try
        {
            var inputTimeoutMs = ResolveFenJsInputEventTimeoutMs();
            return await RunFenJsWithLargeStackAsync(() =>
            {
                using (ScriptEngineLockProbe.Hold(_fenJsLock))
                {
                    var currentDocument = _currentDomRoot as Document ?? _currentDomRoot?.OwnerDocument;
                    var windowContext = _parentRealmOwner != null &&
                        ReferenceEquals(element.OwnerDocument, currentDocument)
                            ? null
                            : ActivateSubdocumentWindowContext(element.OwnerDocument, null);
                    using (windowContext)
                    {
                        return _interpreter.RunWithExecutionBudget(
                            inputTimeoutMs,
                            FenJsBrowserInstructionBudget,
                            () =>
                            {
                                var eventValue = CreateBrowserDomEventValue(element, eventName, eventInit, out var dispatchState);
                                var defaultAllowed = DispatchElementEventWithActivation(
                                    element,
                                    eventName,
                                    eventValue,
                                    dispatchState);
                                _interpreter.PumpMicrotasks();
                                RecordMicrotaskCheckpoint("event:" + eventName);
                                if (DiagnosticPaths.IframeDiagnosticsEnabled)
                                {
                                    DiagnosticPaths.AppendLogText(
                                        "iframe_diagnostics.txt",
                                        $"{DateTimeOffset.UtcNow:O} DispatchEventForElementAsync (local) result: defaultAllowed={defaultAllowed}");
                                }
                                return defaultAllowed;
                            });
                    }
                }
            }, inputTimeoutMs, FenJsBrowserInstructionBudget, prioritize: true).ConfigureAwait(false);
        }
        catch (JsThrownException ex) when (IsFenJsInputEventTimeout(ex))
        {
            throw new FenBrowser.FenEngine.Errors.FenTimeoutError(
                $"Timed out dispatching '{eventName}' event.");
        }
    }

    private static bool IsFenJsInputEventTimeout(JsThrownException ex)
    {
        var message = ex?.Message ?? string.Empty;
        return message.Contains("Script wall-clock timeout exceeded", StringComparison.Ordinal) ||
               message.Contains("Maximum instruction budget exceeded", StringComparison.Ordinal) ||
               message.Contains("Execution interrupted", StringComparison.Ordinal);
    }

    private static bool IsInputPipelineEvent(string eventName) =>
        string.Equals(eventName, "pointerdown", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(eventName, "mousedown", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(eventName, "pointerup", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(eventName, "mouseup", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(eventName, "click", StringComparison.OrdinalIgnoreCase);

    private static void LogInputPipelineDispatch(Element element, string eventName, string realm)
    {
        if (!IsInputPipelineEvent(eventName)) return;
        var id = element?.GetAttribute("id");
        var target = element == null
            ? "<none>"
            : string.IsNullOrEmpty(id) ? $"<{element.TagName}>" : $"<{element.TagName}#{id}>";
        FenBrowser.Core.EngineLogCompat.Info(
            $"[InputPipeline] JS dispatch type='{eventName}' target='{target}' realm='{realm}'",
            FenBrowser.Core.Logging.LogCategory.Events);
    }

    private static void LogInputPipelineCompletion(Element element, string eventName, bool defaultAllowed)
    {
        if (!IsInputPipelineEvent(eventName)) return;
        var id = element?.GetAttribute("id");
        var target = element == null
            ? "<none>"
            : string.IsNullOrEmpty(id) ? $"<{element.TagName}>" : $"<{element.TagName}#{id}>";
        FenBrowser.Core.EngineLogCompat.Info(
            $"[InputPipeline] JS complete type='{eventName}' target='{target}' defaultAllowed={defaultAllowed}",
            FenBrowser.Core.Logging.LogCategory.Events);
    }

    public object Evaluate(string script)
    {
        if (CanEvaluateWithFenJs(script))
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                CollectFenJsHeapAtSafeBoundary();
            }
            return EvaluateWithFenJs(script);
        }
        return null;
    }

    /// <inheritdoc />
    public object EvaluateInFrame(Element frameElement, string script)
    {
        var realm = FindRealmForFrame(frameElement);
        return realm != null ? realm.Evaluate(script) : Evaluate(script);
    }

    /// <inheritdoc />
    public IBrowserScriptEngine GetFrameEngineForElement(Element element)
    {
        if (element == null) return null;
        var doc = element.OwnerDocument;
        if (doc == null) return null;
        var result = TryGetFrameRealm(doc, out var realm) ? realm : null;
        if (DiagnosticPaths.IframeDiagnosticsEnabled)
        {
            var tag = element?.TagName ?? "null";
            var id = element?.GetAttribute("id") ?? "";
            var classAttr = element?.GetAttribute("class") ?? "";
            DiagnosticPaths.AppendLogText(
                "iframe_diagnostics.txt",
                $"{DateTimeOffset.UtcNow:O} GetFrameEngineForElement: element=<{element?.TagName ?? "null"}> id='{element?.GetAttribute("id") ?? ""}' class='{element?.GetAttribute("class") ?? ""}' doc={doc != null} realm={result != null}");
        }
        return result;
    }

    // A frame's realm is owned by the realm of the document that embeds it,
    // so a frame nested two levels down is not in this realm's table. Walk the
    // realm tree to find whoever owns it. Frame trees are acyclic, so this
    // terminates at the nesting depth of the page.
    private FenJsBrowserScriptEngine FindRealmForFrame(Element frameElement)
    {
        if (frameElement == null)
        {
            return null;
        }

        if (_iframeRealms.TryGetValue(frameElement, out var realm) && realm != null)
        {
            return realm;
        }

        foreach (var entry in _iframeRealms)
        {
            var nested = entry.Value?.FindRealmForFrame(frameElement);
            if (nested != null)
            {
                return nested;
            }
        }

        return null;
    }

    public void SyncDomContext(Node domRoot, Uri baseUri = null)
    {
        // Lightweight DOM sync for recascades/re-renders â€” update the cached
        // DOM root WITHOUT recreating the interpreter, so pending timers,
        // promises, and async state survive.  The host hooks' document
        // reference is kept alive by BindFenJsDomContext on initial load.
        if (domRoot == null) return;
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            _currentDomRoot = domRoot;
            if (baseUri != null) _currentBaseUri = baseUri;
        }
    }

    public Task SetDomAsync(Node domRoot, Uri baseUri = null, CancellationToken cancellationToken = default)
    {
        ExecutionCancellation = cancellationToken;
        cancellationToken.ThrowIfCancellationRequested();
        return SetDomAsyncCore(domRoot, baseUri);
    }

    public Task SetSubdocumentDomAsync(
        Node domRoot,
        Uri baseUri = null,
        BrowserFrameExecutionOptions options = null)
    {
        var document = domRoot as Document ?? domRoot?.OwnerDocument;
        var frameElement = TryGetFrameElementForDocument(document);
        if (frameElement == null)
        {
            return SetDomAsyncCore(domRoot, baseUri, resetSession: false, restorePreviousContext: true);
        }

        // HTML 7.3.1: a frame's browsing context is a child of the one whose document
        // holds the frame element. The host hands every frame to the top realm, so a frame
        // inside a frame goes to the realm of the document it sits in - otherwise its
        // window.parent would be the top window.
        var owner = FindRealmOwningDocument(frameElement.OwnerDocument) ?? this;
        return owner.SetSubdocumentRealmAsync(frameElement, domRoot, baseUri, options);
    }

    private async Task SetSubdocumentRealmAsync(
        Element frameElement,
        Node domRoot,
        Uri baseUri,
        BrowserFrameExecutionOptions options)
    {
        var frameRealm = _iframeRealms.GetValue(frameElement, CreateFrameRealm);
        frameRealm._parentRealmOwner = this;
        frameRealm._embeddingFrameElement = frameElement;
        CopyFrameRealmConfiguration(frameRealm);
        if (options != null)
        {
            frameRealm.SubresourceAllowed = options.SubresourceAllowed ?? frameRealm.SubresourceAllowed;
            frameRealm.TrustedDynamicSubresourceAllowed = options.TrustedDynamicSubresourceAllowed ?? frameRealm.TrustedDynamicSubresourceAllowed;
            frameRealm.NonceAllowed = options.NonceAllowed ?? frameRealm.NonceAllowed;
            frameRealm.ExternalScriptFetcher = options.ExternalScriptFetcher ?? frameRealm.ExternalScriptFetcher;
            frameRealm.ExternalScriptFetcherWithNonce = options.ExternalScriptFetcherWithNonce ?? frameRealm.ExternalScriptFetcherWithNonce;
            frameRealm.WorkerScriptFetcher = options.WorkerScriptFetcher ?? frameRealm.WorkerScriptFetcher;
            frameRealm.FetchHandler = options.FetchHandler ?? frameRealm.FetchHandler;
        }

        await frameRealm.SetDomAsync(domRoot, baseUri).ConfigureAwait(false);

        var observables = frameRealm.CaptureObservableWindowProperties();
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            var frameDocument = domRoot as Document ?? domRoot?.OwnerDocument;
            var proxy = GetOrCreateIFrameContentWindow(frameElement, frameDocument, baseUri);
            CopyFrameRealmObservables(frameRealm, proxy, observables);
        }

        RefreshChildFrameTables();
    }

    private FenJsBrowserScriptEngine CreateFrameRealm(Element frameElement)
    {
        var realm = new FenJsBrowserScriptEngine(_host)
        {
            _parentRealmOwner = this,
            _embeddingFrameElement = frameElement
        };
        CopyFrameRealmConfiguration(realm);
        Interlocked.Increment(ref _frameRealmCount);
        EnsureFrameTeardownObserver();
        return realm;
    }

    private void CopyFrameRealmConfiguration(FenJsBrowserScriptEngine realm)
    {
        realm.RuntimeProfile = RuntimeProfile;
        realm.ImageLoaderScope = ImageLoaderScope;
        realm.ViewportHitTester = ViewportHitTester;
        realm.FetchOverride = FetchOverride;
        realm.SubresourceAllowed = SubresourceAllowed;
        realm.TrustedDynamicSubresourceAllowed = TrustedDynamicSubresourceAllowed;
        realm.NonceAllowed = NonceAllowed;
        realm.FetchHandler = FetchHandler;
        realm.CookieReadBridge = CookieReadBridge;
        realm.CookieWriteBridge = CookieWriteBridge;
        realm.RequestRender = () =>
        {
            // Never wait for the parent's lock here: this runs while the child
            // frame's own script is trying to make progress.
            SyncFrameRealmObservables(realm._embeddingFrameElement, realm, waitForParentLock: false);
            RequestRender?.Invoke();
        };
        realm.FlushPendingLayout = FlushPendingLayout;
        realm.ExternalScriptFetcher = ExternalScriptFetcher;
        realm.ExternalScriptFetcherWithNonce = ExternalScriptFetcherWithNonce;
        realm.WorkerScriptFetcher = WorkerScriptFetcher;
        realm.FrameElementLoader = FrameElementLoader;
        realm.LayoutBoxResolver = LayoutBoxResolver;
        realm.FrameScrollReader = FrameScrollReader;
        realm.FrameScrollWriter = FrameScrollWriter;
        realm.ExecutionCancellation = ExecutionCancellation;
        realm.Sandbox = realm._embeddingFrameElement?.HasAttribute("sandbox") == true
            ? SandboxPolicy.FromIframeSandboxAttribute(realm._embeddingFrameElement.GetAttribute("sandbox"))
            : Sandbox;
        realm.AllowExternalScripts = AllowExternalScripts && realm.Sandbox.Allows(SandboxFeature.ExternalScripts);
        realm.ExecuteInlineScriptsOnInnerHTML = ExecuteInlineScriptsOnInnerHTML && realm.Sandbox.Allows(SandboxFeature.InlineScripts);
        realm.PermissionsPolicyProvider = PermissionsPolicyProvider;
        realm.DocumentSecurityContext = DocumentSecurityContext;
        realm.WindowWidth = ResolveFrameViewportDimension(realm._embeddingFrameElement, "width", WindowWidth);
        realm.WindowHeight = ResolveFrameViewportDimension(realm._embeddingFrameElement, "height", WindowHeight);
        realm.PageScriptByteBudget = PageScriptByteBudget;
        realm.IndexedDbBackend = IndexedDbBackend;
    }

    private static double ResolveFrameViewportDimension(Element frame, string attribute, double fallback) =>
        frame != null && TryReadDeclaredPixelDimension(frame, attribute, out var value) ? value : fallback;

    private bool TryGetFrameRealm(Document document, out FenJsBrowserScriptEngine realm)
    {
        var frame = TryGetFrameElementForDocument(document);
        if (DiagnosticPaths.IframeDiagnosticsEnabled)
        {
            DiagnosticPaths.AppendLogText(
                "iframe_diagnostics.txt",
                $"{DateTimeOffset.UtcNow:O} TryGetFrameRealm: doc={document != null} frame={frame != null}");
        }
        realm = FindRealmForFrame(frame);
        if (realm != null)
        {
            if (DiagnosticPaths.IframeDiagnosticsEnabled)
            {
                DiagnosticPaths.AppendLogText(
                    "iframe_diagnostics.txt",
                    $"{DateTimeOffset.UtcNow:O} TryGetFrameRealm: FOUND realm for frame={frame.TagName} id='{frame.GetAttribute("id") ?? ""}'");
            }
            return true;
        }

        if (DiagnosticPaths.IframeDiagnosticsEnabled)
        {
            DiagnosticPaths.AppendLogText(
                "iframe_diagnostics.txt",
                $"{DateTimeOffset.UtcNow:O} TryGetFrameRealm: NOT FOUND realm for frame={frame?.TagName ?? "null"}");
        }

        realm = null;
        return false;
    }

    internal object EvaluateInSubdocumentForTest(Document document, string script) =>
        TryGetFrameRealm(document, out var realm) ? realm.Evaluate(script) : null;

    private void SyncFrameRealmObservables(Element frame, FenJsBrowserScriptEngine realm)
        => SyncFrameRealmObservables(frame, realm, waitForParentLock: true);

    /// <summary>
    /// Publishes a child frame's expando globals onto the parent's view of
    /// <c>iframe.contentWindow</c>.
    /// </summary>
    /// <remarks>
    /// The snapshot is always taken before the parent lock. The child render
    /// path already enters these realms in child-to-parent order; taking them in
    /// the reverse order here can stall the parent event loop behind a busy
    /// frame.
    ///
    /// <paramref name="waitForParentLock"/> is what the render path turns off.
    /// The parent holds its lock for as long as its own script runs — on the
    /// reCAPTCHA demo a single setTimeout callback held it for nine seconds —
    /// and a child frame asking to render is the child delivering its own
    /// script. Waiting there serialises the child behind the parent: the child
    /// blocked on 489 of 921 publishes for 21 seconds in total, which is what
    /// stalled the captcha handshake for thirteen seconds at a time and let the
    /// widget's own twenty-second watchdog fire.
    ///
    /// Skipping is safe because this is a cache refresh rather than a step in
    /// any algorithm: the parent can only read these values while holding the
    /// lock it is currently holding, renders follow one another closely enough
    /// that the next one republishes, and the authoritative sync points (a
    /// document being set, a frame being attached) still publish unconditionally.
    /// </remarks>
    private void SyncFrameRealmObservables(
        Element frame,
        FenJsBrowserScriptEngine realm,
        bool waitForParentLock)
    {
        if (frame == null || realm == null)
        {
            return;
        }

        var observables = realm.CaptureObservableWindowProperties();

        if (waitForParentLock)
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                PublishFrameRealmObservables(frame, realm, observables);
            }

            return;
        }

        if (!Monitor.TryEnter(_fenJsLock))
        {
            return;
        }

        try
        {
            PublishFrameRealmObservables(frame, realm, observables);
        }
        finally
        {
            Monitor.Exit(_fenJsLock);
        }
    }

    private void PublishFrameRealmObservables(
        Element frame,
        FenJsBrowserScriptEngine realm,
        Dictionary<string, object> observables)
    {
        var proxy = GetOrCreateIFrameContentWindow(frame);
        CopyFrameRealmObservables(realm, proxy, observables);
    }

    private async Task SetDomAsyncCore(
        Node domRoot,
        Uri baseUri,
        bool resetSession = true,
        bool restorePreviousContext = false)
    {
        var previousDomRoot = _currentDomRoot;
        var previousBaseUri = _currentBaseUri;
        var previousReadyState = _documentReadyState;

        BeginScriptLoadingSnapshot(domRoot, baseUri);
        BeginEventLoopSnapshot(domRoot, baseUri);
        LogScriptLoading(
            "SetDomStarted",
            LogSeverity.Debug,
            "[FenJsBridge] SetDomAsyncCore called",
            new Dictionary<string, object>
            {
                ["domRootPresent"] = domRoot != null,
                ["baseUri"] = baseUri?.AbsoluteUri ?? string.Empty
            });

        if (domRoot == null)
        {
            return;
        }

        if (resetSession)
        {
            BindFenJsDomContext(domRoot, baseUri, documentReadyState: "loading");
        }
        else
        {
            RebindFenJsDomContext(domRoot, baseUri, documentReadyState: "loading");
        }

        EnsureImageLoadObserver();
        EnsureLinkLoadObserver();
        EnsureObjectLoadObserver();
        EnsureMediaElementObserver();

        if (resetSession && _parentRealmOwner != null && _embeddingFrameElement != null)
        {
            ConfigureEmbeddedRealmGlobals();
        }

        var windowContext = !resetSession
            ? ActivateSubdocumentWindowContext(domRoot, baseUri)
            : null;

        try
        {
            LogScriptLoading(
                "SetDomReadyForScripts",
                LogSeverity.Debug,
                "[FenJsBridge] About to execute page scripts",
                new Dictionary<string, object>
                {
                    ["domRootTag"] = (domRoot as Element)?.TagName ?? "null",
                    ["descendantCount"] = domRoot.Descendants().Count()
                });
            WireInlineEventHandlers(domRoot);
            EnsureChildNavigableWindows(domRoot);
            await ExecutePageScriptsWithFenJsAsync(domRoot, baseUri).ConfigureAwait(false);
            // Images the parser created never went through the mutation
            // observer. Their requests start here, after the page's scripts
            // have had the chance to attach listeners, the way an image that
            // loads asynchronously during parsing would be seen.
            TrackImagesInSubtree(domRoot);
            TrackObjectsInSubtree(domRoot);
            // Likewise media elements: a parser-created video with a src or
            // source children starts resource selection once scripts have run.
            TrackMediaElementsInSubtree(domRoot);
            ApplyScriptingEnabledSanitizer(domRoot);
            // The media elements start selecting on the JS worker; let those tasks
            // run before deciding whether anything delays the load event.
            await FlushMediaTasksAsync().ConfigureAwait(false);
            var startupLinkLoads = StartStartupLinkLoads(domRoot);
            var loadingDocument = DispatchDomContentLoaded();
            if (loadingDocument != null)
            {
                await FinishStartupLinkLoadsAsync(startupLinkLoads).ConfigureAwait(false);
                DispatchWindowLoad(loadingDocument);
            }
        }
        finally
        {
            windowContext?.Dispose();
            if (restorePreviousContext && previousDomRoot != null)
            {
                RebindFenJsDomContext(previousDomRoot, previousBaseUri, previousReadyState);
            }
        }
    }

    private bool CanEvaluateWithFenJs(string script)
    {
        return !string.IsNullOrWhiteSpace(script);
    }

    private static long ResolveFenJsScriptTimeoutMs()
    {
        const long defaultTimeoutMs = 300000;
        var raw = Environment.GetEnvironmentVariable("FEN_FENJS_SCRIPT_TIMEOUT_MS");
        if (!string.IsNullOrWhiteSpace(raw) &&
            long.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) &&
            parsed >= 0)
        {
            return parsed;
        }

        return defaultTimeoutMs;
    }

    private static long ResolveFenJsInputEventTimeoutMs()
    {
        const long defaultTimeoutMs = 2000;
        var raw = Environment.GetEnvironmentVariable("FEN_FENJS_INPUT_EVENT_TIMEOUT_MS");
        if (!string.IsNullOrWhiteSpace(raw) &&
            long.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) &&
            parsed >= 0)
        {
            return parsed;
        }

        return defaultTimeoutMs;
    }

    private static int ResolveFenJsMicrotaskTraceSetting(
        string variableName,
        int defaultValue,
        int minimumValue)
    {
        var raw = Environment.GetEnvironmentVariable(variableName);
        if (!string.IsNullOrWhiteSpace(raw) &&
            int.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) &&
            parsed >= minimumValue)
        {
            return parsed;
        }

        return defaultValue;
    }

    private static int ResolveFenJsTaskInstructionBudget()
    {
        var raw = Environment.GetEnvironmentVariable("FEN_FENJS_TASK_INSTRUCTION_BUDGET");
        if (!string.IsNullOrWhiteSpace(raw) &&
            int.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) &&
            parsed > 0)
        {
            return parsed;
        }

        return FenJsBrowserInstructionBudget;
    }

    // Diagnostic knob: FEN_FENJS_GC_STRESS=before-every-alloc|after-every-alloc|random
    // drives the FenJs heap with the same stress modes the Js shell exposes, so
    // unrooted host-to-JS value windows reproduce deterministically in tests and
    // site triage instead of only under real-site allocation pressure.
    private static GcStressMode ResolveFenJsGcStressMode()
    {
        var configured = Environment.GetEnvironmentVariable("FEN_FENJS_GC_STRESS");
        if (string.IsNullOrWhiteSpace(configured))
        {
            return GcStressMode.None;
        }

        return configured.Trim().ToLowerInvariant() switch
        {
            "before-every-alloc" => GcStressMode.BeforeEveryAlloc,
            "after-every-alloc" => GcStressMode.AfterEveryAlloc,
            "random" => GcStressMode.Random,
            _ => GcStressMode.None
        };
    }

    private object EvaluateWithFenJs(string script)
    {
        var rawResult = EvaluateWithFenJsRaw(script);
        if (rawResult.Tag == FenBrowser.Js.Runtime.JsValueTag.Object ||
            rawResult.Tag == FenBrowser.Js.Runtime.JsValueTag.HostObject)
        {
            return ConvertJsValueToObject(rawResult);
        }
        return ConvertFenJsValue(rawResult);
    }

    private sealed class FenJsSessionResetException(string message) : InvalidOperationException(message);

    private JsValue EvaluateWithFenJsRaw(string script)
    {
        // Snapshot the session generation at dispatch time. If a navigation
        // resets the session before the worker executes this lambda, the
        // generation will have changed and we can abort cleanly.
        var dispatchGeneration = _fenJsSessionGeneration;

        try
        {
            return RunFenJsWithLargeStack(() =>
            {
                using (ScriptEngineLockProbe.Hold(_fenJsLock))
                {
                    // If the session was reset between dispatch and now, the
                    // compiler/interpreter are gone â€” bail cleanly.
                    if (dispatchGeneration != _fenJsSessionGeneration ||
                        _compiler == null || _interpreter == null)
                    {
                        throw new FenJsSessionResetException(
                            "[FenJsBridge] JS session was reset during evaluation dispatch " +
                            $"(dispatchGen={dispatchGeneration} currentGen={_fenJsSessionGeneration} " +
                            $"_compiler={_compiler != null} _interpreter={_interpreter != null}). " +
                            "This is expected when a page script triggers a navigation " +
                            "(e.g. WAF challenge â†’ location.reload).");
                    }
                    _fenJsEvaluationCount++;
                    // Split these: front-end cost on a megabyte bundle is most of
                    // the time before a page shows anything, and "compile+verify"
                    // as one number cannot say whether to attack the parser, the
                    // bytecode emitter or the verifier.
                    var compileWatch = System.Diagnostics.Stopwatch.StartNew();
                    // Name the source after the script being run so stack frames from
                    // a minified bundle say which file they came from.
                    var currentRecord = GetCurrentScriptRecord();
                    var sourcePath = !string.IsNullOrWhiteSpace(currentRecord?.Src)
                        ? currentRecord.Src
                        : !string.IsNullOrWhiteSpace(currentRecord?.SourceLabel)
                            ? currentRecord.SourceLabel
                            : "<fenbrowser-fenjs-eval>";
                    var function = _compiler.CompileScript(new SourceText(script, sourcePath));
                    var compileMs = compileWatch.ElapsedMilliseconds;
                    RegisterCallbackFunctionProvenance(function, currentRecord);
                    compileWatch.Restart();
                    new BytecodeVerifier().Verify(function);
                    var verifyMs = compileWatch.ElapsedMilliseconds;
                    compileWatch.Restart();
                    var evalResult = _interpreter.Execute(function);
                    if (script.Length > 20000)
                    {
                        FenBrowser.Core.EngineLogCompat.Info(
                            $"[FenJsBridge] script {script.Length} chars: " +
                            $"parse+compile {compileMs}ms, verify {verifyMs}ms, " +
                            $"execute {compileWatch.ElapsedMilliseconds}ms",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }

                    return evalResult;
                }
            });
        }
        catch (FenJsSessionResetException ex)
        {
            // Expected after async navigation: surface it cleanly without a stack trace.
            LogScriptLoading(
                "ScriptEvaluationSkipped",
                LogSeverity.Warn,
                "[FenJsBridge] EvaluateWithFenJsRaw skipped after session reset",
                new Dictionary<string, object>
                {
                    ["scriptSample"] = TruncateForLog(script, 160),
                    ["error"] = ex.Message
                });
            return JsValue.Undefined;
        }
        catch (InvalidOperationException ex)
        {
            // A script the compiler or verifier rejected. The page carries on with its
            // next script as before, but this is an engine fault, not a navigation: it
            // used to share the session-reset message above, which hid a compiler bug
            // that dropped w3schools' resize-handler script.
            LogScriptLoading(
                "ScriptEvaluationInfrastructureFailed",
                LogSeverity.Error,
                $"[FenJsBridge] EvaluateWithFenJsRaw rejected script: {ex.Message}",
                new Dictionary<string, object>
                {
                    ["scriptSample"] = TruncateForLog(script, 160),
                    ["errorType"] = ex.GetType().Name,
                    ["error"] = ex.Message
                });
            return JsValue.Undefined;
        }
        catch (Exception ex) when (ex is not JsThrownException)
        {
            var message = $"[FenJsBridge] EvaluateWithFenJsRaw FAILED for script '{script}': {ex.GetType().Name}: {ex.Message}";
            if (ex.StackTrace is { } st)
                message += "\n  Stack: " + st.Split('\n').FirstOrDefault()?.Trim();
            LogScriptLoading(
                "ScriptEvaluationInfrastructureFailed",
                LogSeverity.Error,
                message,
                new Dictionary<string, object>
                {
                    ["scriptSample"] = TruncateForLog(script, 160),
                    ["errorType"] = ex.GetType().Name,
                    ["error"] = ex.Message
                });
            throw;
        }
    }

    private JsValue CreateLegacyDomEvent(string interfaceName)
    {
        var constructorName = (interfaceName ?? "Event").Trim().ToLowerInvariant() switch
        {
            "customevent" => "CustomEvent",
            "mouseevent" or "mouseevents" => "MouseEvent",
            "wheelevent" or "wheelevents" => "WheelEvent",
            "keyboardevent" or "keyboardevents" => "KeyboardEvent",
            "uievent" or "uievents" => "UIEvent",
            "beforeunloadevent" => "BeforeUnloadEvent",
            _ => "Event"
        };

        return EvaluateWithFenJsRaw($"new {constructorName}('')");
    }

    // The recursive-descent parser, the bytecode compiler, and the interpreter all
    // recurse with the AST/call depth. Real-world minified bundles (x.com's main.js is
    // 1.4 MB) nest expressions thousands deep and blow the ~1 MB stack of a threadpool
    // thread â€” the path page scripts run on. FenBrowser.Host already re-enters its main
    // loop on a 16 MB thread for exactly this reason; mirror that here so every FenJS
    // compile/execute gets a fat stack. A ThreadStatic flag makes re-entrant calls (a
    // native callback that evaluates more script) run inline instead of spawning â€” and,
    // critically, avoids dead-locking on _fenJsLock which the outer worker already holds.
    [ThreadStatic] private static bool _onFenJsLargeStackThread;
    // 256 MB: real-world minified bundles nest very deeply. The parser builds
    // operator chains iteratively, but the compiler's tree-walk recurses â€” and
    // x.com's i18n bundle compiles an ~8800-deep left-associative chain (16 MB
    // overflowed at ~1550). Give the compile/execute thread a fat stack; the
    // compiler's TryEnsureSufficientExecutionStack guard still aborts catchably
    // if even this is exceeded, rather than crashing the process.
    private const int FenJsLargeStackBytes = 256 * 1024 * 1024;
    // A real page's own scripts are deliberately CPU-heavy, and an interpreter
    // counts instructions a native engine never would. Google's search page
    // spends over 100M interpreter instructions in one inline script, and
    // reCAPTCHA's post-click signal collection burns more than that again by
    // design. Both used to die with "Maximum instruction budget exceeded" --
    // the callback path was raised for the second case, and the page-script
    // path was left behind for the first, which killed the script mid-run and
    // left the page believing scripting was unavailable.
    //
    // The wall-clock script timeout is the runaway guard. This only backstops
    // a loop that spins without ever yielding, so one value serves both.
    private const int FenJsBrowserInstructionBudget = 2_000_000_000;
    private const int FenJsBrowserParserMaxRecursionDepth = 1024;
    private void CollectFenJsHeapAtSafeBoundary()
    {
        if (_interpreter == null || _interpreter.IsExecuting)
        {
            return;
        }

        var heap = _interpreter.Heap;
        var previousMinorCount = heap.MinorCollectionCount;
        var previousMajorCount = heap.GcCollectionCount;
        heap.CollectAtSafePointIfRequested();
        if (heap.MinorCollectionCount == previousMinorCount &&
            heap.GcCollectionCount == previousMajorCount)
        {
            return;
        }

        ReportFenJsRootAudit(heap);

        // Attributing a slow callback needs to distinguish script from
        // collection, and there was no way to tell them apart.
        if (heap.GcCollectionCount <= 2 || heap.GcCollectionCount % 10 == 0)
        {
            FenBrowser.Core.EngineLogCompat.Info(
                $"[FenJsGc] major={heap.GcCollectionCount} ({heap.MajorGcMilliseconds:F0}ms) " +
                $"minor={heap.MinorCollectionCount} ({heap.MinorGcMilliseconds:F0}ms) " +
                $"allocs={heap.AllocationCount} slots={heap.CellSlotCount} " +
                $"marked={heap.LastGcMarkedCells} swept={heap.LastGcSweptCells} " +
                $"propSlots={heap.LastGcPropertySlots} " +
                $"microtasks={_interpreter.MicrotaskJobsRun} ({_interpreter.MicrotaskMilliseconds:F0}ms) " +
                $"instructions={_interpreter.TotalInstructionsExecuted} " +
                $"slowestJob={_interpreter.SlowestJobMilliseconds:F0}ms/{_interpreter.SlowestJobInstructions}instr " +
                $"natives=[{_interpreter.DescribeNativeCallCost()}] " +
                $"nativeRooting={_interpreter.NativeRootingMilliseconds:F0}ms/{_interpreter.NativeRootedCalls} " +
                $"slotPool=[hit={_interpreter.SlotFileHits} miss={_interpreter.SlotFileMisses}] " +
                $"slotElig=[{_interpreter.DescribeSlotEligibility()}] " +
                $"topCalled=[{_interpreter.DescribeNativeCallCounts()}] " +
                // Whether the JIT tiered in at all decides how to read every
                // number above it: 70M instructions is a different problem when
                // the compiler took the hot function than when it refused it.
                // The refusal reason - the opcode it could not emit - is the
                // one fact that says which opcode to teach it next, and it was
                // only ever written to the child's stderr, where nothing reads it.
                $"jit=[{DescribeJitTierUp()}]",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    private static string DescribeJitTierUp()
    {
#if PUBLISH_AOT
        return "unavailable";
#else
        if (!FenBrowser.Js.Bytecode.JitCompiler.Enabled)
        {
            return "disabled";
        }

        // DescribeRejections lists every opcode that ever blocked a
        // compilation, most-frequent first. Only the head of that list names
        // the work worth doing, and the tail would crowd the entry.
        var refusals = FenBrowser.Js.Bytecode.JitCompiler.DescribeRejections().Split(' ');
        var topRefusals = string.Join(' ', refusals.Take(6));

        return $"attempts={FenBrowser.Js.Bytecode.JitCompiler.CompileAttempts} " +
               $"compiled={FenBrowser.Js.Bytecode.JitCompiler.CompileSuccesses} " +
               $"exprTree={FenBrowser.Js.Bytecode.JitCompiler.CompileExpressionTreeSuccesses} " +
               // Compilation runs on the thread that wanted to run the function,
               // so this is time the page waited for, not background work.
               $"compileMs={FenBrowser.Js.Bytecode.JitCompiler.CompileMilliseconds:F0} " +
               $"refusedOn={topRefusals}";
#endif
    }

    // Persistent large-stack worker thread â€” created once per engine instance
    // and reused across all page-script evaluations.  Creating+joining a 256 MB
    // thread per script (60+ for a typical SPA) wastes ~500 ms per page load in
    // thread start/stop overhead alone; reusing the same thread cuts that to
    // near-zero after the first evaluation.
    private Thread _fenJsWorkerThread;
    private readonly AutoResetEvent _fenJsWorkAvailable = new AutoResetEvent(false);
    private readonly ConcurrentQueue<FenJsWorkItem> _fenJsInputWorkQueue = new();
    private readonly ConcurrentQueue<FenJsWorkItem> _fenJsWorkQueue = new();
    private bool _fenJsWorkerRunning;

    // Set once this realm's frame has been detached from the tree (or the owning
    // document navigated away). A detached nested browsing context is discarded
    // per HTML "destroy a child navigable", so its scripts must stop: the flag
    // aborts the in-flight script at the next interrupt check, stops the worker
    // loop, and makes every later enqueue a no-op. Volatile because it is set
    // from the render thread and read by the JS worker thread.
    private volatile bool _realmAbandoned;

    internal bool IsRealmAbandoned => _realmAbandoned;
    private int _fenJsWorkerActive;
    private long _fenJsWorkItemSequence;
    private FenJsWorkItem _activeFenJsWorkItem;

    // The work item that was running when the current document was installed.
    // It legitimately carries the previous document's id, so it is never stale.
    private FenJsWorkItem _documentTransitionWorkItem;

    // Work belongs to a document that has since been replaced: its results can no
    // longer be observed, so running it only starves the live document.
    // The document a timer was scheduled against is gone, so the timer goes with
    // it. Mirrors IsWorkItemStale, which is what refuses the callback itself.
    private bool IsRetiredTimerDocument(string timerDocumentId)
    {
        if (string.IsNullOrEmpty(timerDocumentId))
        {
            return false;
        }

        var currentDocumentId = _currentDocumentId;
        return currentDocumentId.Length != 0 &&
               !string.Equals(timerDocumentId, currentDocumentId, StringComparison.Ordinal);
    }

    private bool IsWorkItemStale(FenJsWorkItem workItem)
    {
        if (workItem == null || workItem.DocumentId.Length == 0)
        {
            return false;
        }

        if (ReferenceEquals(workItem, Volatile.Read(ref _documentTransitionWorkItem)))
        {
            return false;
        }

        var currentDocumentId = _currentDocumentId;
        return currentDocumentId.Length != 0 &&
               !string.Equals(workItem.DocumentId, currentDocumentId, StringComparison.Ordinal);
    }

    private sealed class FenJsWorkItem
    {
        public FenJsWorkItem(
            long sequence,
            Func<object> work,
            int instructionBudget,
            string kind,
            string documentId,
            string url)
        {
            Sequence = sequence;
            Work = work ?? throw new ArgumentNullException(nameof(work));
            InstructionBudget = instructionBudget;
            Kind = string.IsNullOrWhiteSpace(kind) ? "unspecified" : kind;
            DocumentId = documentId ?? string.Empty;
            Url = url ?? string.Empty;
            EnqueuedTick = Environment.TickCount64;
        }

        public long Sequence { get; }
        public Func<object> Work { get; }
        public int InstructionBudget { get; }
        public string Kind { get; }
        public string DocumentId { get; }
        public string Url { get; }
        public long EnqueuedTick { get; }
        public string Phase { get; private set; } = "queued";
        public TaskCompletionSource<object> Completion { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public void SetPhase(string phase) =>
            Phase = string.IsNullOrWhiteSpace(phase) ? "unspecified" : phase;
    }

    private void EnsureFenJsWorkerRunning()
    {
        if (_realmAbandoned)
            return;

        if (_fenJsWorkerThread != null && _fenJsWorkerThread.IsAlive)
            return;

        _fenJsWorkerRunning = true;
        _fenJsWorkerThread = new Thread(FenJsWorkerLoop, FenJsLargeStackBytes)
        {
            IsBackground = true,
            Name = "FenJs-LargeStack"
        };
        _fenJsWorkerThread.Start();
    }

    private void FenJsWorkerLoop()
    {
        _onFenJsLargeStackThread = true;
        while (_fenJsWorkerRunning)
        {
            _fenJsWorkAvailable.WaitOne();
            if (!_fenJsWorkerRunning) break;

            while (TryDequeueFenJsWork(out var workItem))
            {
                // A bounded caller may time out while its item is still queued.
                // Do not execute that stale event after the caller has moved on.
                if (workItem.Completion.Task.IsCompleted)
                    continue;

                // The frame was detached while this item sat in the queue.
                if (_realmAbandoned)
                {
                    workItem.Completion.TrySetResult(null);
                    continue;
                }

                // The document this item belongs to was replaced while it queued.
                if (IsWorkItemStale(workItem))
                {
                    workItem.Completion.TrySetResult(null);
                    continue;
                }

                try
                {
                    Interlocked.Exchange(ref _fenJsWorkerActive, 1);
                    Volatile.Write(ref _activeFenJsWorkItem, workItem);
                    workItem.SetPhase("executing");
                    var interpreter = _interpreter;
                    var startedTick = Environment.TickCount64;
                    var queuedMs = Math.Max(0, startedTick - workItem.EnqueuedTick);
                    FenBrowser.Core.EngineLogCompat.Debug(
                        $"[FenJsWorker] Started id={workItem.Sequence} kind={workItem.Kind} queuedMs={queuedMs} " +
                        $"budget={workItem.InstructionBudget} inputQueue={_fenJsInputWorkQueue.Count} " +
                        $"normalQueue={_fenJsWorkQueue.Count} documentId={workItem.DocumentId} url={workItem.Url}",
                        FenBrowser.Core.Logging.LogCategory.JavaScript);
                    using var longRunningProbe = new Timer(
                        _ =>
                        {
                            try
                            {
                                if (workItem.Completion.Task.IsCompleted)
                                {
                                    return;
                                }

                            var elapsedMs = Math.Max(0, Environment.TickCount64 - startedTick);
                            var instructions = interpreter?.InstructionsExecuted ?? 0;
                            var heap = interpreter?.Heap;
                            var managedAllocated = GC.GetTotalAllocatedBytes(precise: false);
                            var managedMemory = GC.GetTotalMemory(forceFullCollection: false);
                            FenBrowser.Core.EngineLogCompat.Warn(
                                $"[FenJsWorker] StillRunning id={workItem.Sequence} kind={workItem.Kind} " +
                                $"phase={workItem.Phase} elapsedMs={elapsedMs} instructions={instructions} " +
                                $"budget={workItem.InstructionBudget} allocations={heap?.AllocationCount ?? 0} " +
                                $"minorGc={heap?.MinorCollectionCount ?? 0} majorGc={heap?.GcCollectionCount ?? 0} " +
                                $"liveCells={heap?.LiveCellCount ?? 0} " +
                                // A job that allocates a million cells and frees
                                // none is not slow because it is doing work; it is
                                // slow because nothing dies. These say whether the
                                // nursery is surviving and, if so, which root
                                // source is holding it.
                                $"frames={interpreter?.FramesCreated ?? 0} " +
                                // Where the job is right now: the one line that
                                // says which page function a stalled job is in.
                                $"stack=[{interpreter?.DescribeActiveFrames() ?? string.Empty}] " +
                                $"regMB={(interpreter?.RegisterBytesAllocated ?? 0) / (1024.0 * 1024.0):F0} " +
                                $"regPool=[hit={interpreter?.RegisterFileHits ?? 0} " +
                                $"miss={interpreter?.RegisterFileMisses ?? 0} " +
                                $"largest={interpreter?.LargestRegisterFile ?? 0}] " +
                                $"nursery={heap?.NurserySize ?? 0} " +
                                $"lastMinor=[size={heap?.LastMinorNurserySize ?? 0} " +
                                $"marked={heap?.LastMinorMarked ?? 0} " +
                                $"swept={heap?.LastMinorSwept ?? 0} " +
                                $"scannedOld={heap?.LastMinorScannedOldCells ?? 0} " +
                                $"dirtyCards={heap?.RememberedSetEdgeCount ?? 0} " +
                                $"rememberedEnvs={heap?.RememberedEnvironmentCount ?? 0}] " +
                                $"roots=[{heap?.LastMinorRootBreakdown ?? string.Empty}] " +
                                // A job that stops allocating but keeps its
                                // elapsed time climbing is waiting, not working;
                                // with FEN_FENJS_LOCKPROBE=1 this names the lock.
                                $"waits=[{ScriptEngineLockProbe.DescribeActiveWaits()}] " +
                                $"clr=[allocatedMB={managedAllocated / (1024.0 * 1024.0):F0} " +
                                $"managedMB={managedMemory / (1024.0 * 1024.0):F0} " +
                                $"gen0={GC.CollectionCount(0)} gen1={GC.CollectionCount(1)} gen2={GC.CollectionCount(2)}] " +
                                $"execution=[{interpreter?.CaptureExecutionDiagnosticSnapshot() ?? "<no-interpreter>"}] " +
                                $"inputQueue={_fenJsInputWorkQueue.Count} normalQueue={_fenJsWorkQueue.Count} " +
                                $"documentId={workItem.DocumentId} url={workItem.Url}",
                                FenBrowser.Core.Logging.LogCategory.JavaScript);
                            if (FenBrowser.Js.Diagnostics.InterpreterProfiler.Enabled)
                            {
                                FenBrowser.Core.EngineLogCompat.Warn(
                                    FenBrowser.Js.Diagnostics.InterpreterProfiler.Report(),
                                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                                // The opcode histogram says LoadVar dominates; only
                                // this says whether that is scope-chain walking (a
                                // cache would pay) or already-resolved local reads
                                // (it would not).
                                FenBrowser.Core.EngineLogCompat.Warn(
                                    FenBrowser.Js.Diagnostics.InterpreterProfiler.VarReport(),
                                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                                // ...and this says what that walking costs, which
                                // is what decides whether building the cache beats
                                // the other candidates.
                                FenBrowser.Core.EngineLogCompat.Warn(
                                    FenBrowser.Js.Diagnostics.InterpreterProfiler.TimingReport(),
                                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                            }
                            if (FenBrowser.Js.Diagnostics.InterpreterProfiler.OpTimingEnabled)
                            {
                                FenBrowser.Core.EngineLogCompat.Warn(
                                    FenBrowser.Js.Diagnostics.InterpreterProfiler.OpTimeReport(40),
                                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                            }
                            if (FenBrowser.Js.Diagnostics.CallPathProfiler.Enabled)
                            {
                                FenBrowser.Core.EngineLogCompat.Warn(
                                    FenBrowser.Js.Diagnostics.CallPathProfiler.Report(),
                                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                            }
                                if (FenBrowser.Js.Diagnostics.CallTargetProfiler.Enabled)
                                {
                                    FenBrowser.Core.EngineLogCompat.Warn(
                                        FenBrowser.Js.Diagnostics.CallTargetProfiler.Report(40),
                                        FenBrowser.Core.Logging.LogCategory.JavaScript);
                                }
                            }
                            catch (Exception diagnosticException)
                            {
                                FenBrowser.Core.EngineLogCompat.Warn(
                                    $"[FenJsWorker] ProbeFailed id={workItem.Sequence} " +
                                    $"errorType={diagnosticException.GetType().Name} error={diagnosticException.Message}",
                                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                            }
                        },
                        null,
                        dueTime: IsFenJsDeepTraceEnabled ? 500 : LongRunningProbeDueMs,
                        period: IsFenJsDeepTraceEnabled ? 1_000 : LongRunningProbePeriodMs);
                    var result = interpreter == null
                        ? workItem.Work()
                        : interpreter.RunWithExecutionBudget(
                            ResolveFenJsScriptTimeoutMs(),
                            workItem.InstructionBudget,
                            workItem.Work);
                    workItem.Completion.TrySetResult(result);
                    var elapsedMs = Math.Max(0, Environment.TickCount64 - startedTick);
                    var completion =
                        $"[FenJsWorker] Completed id={workItem.Sequence} kind={workItem.Kind} " +
                        $"elapsedMs={elapsedMs} instructions={interpreter?.LastExecutionInstructions ?? 0}";
                    // A job that ran long enough to announce itself has to
                    // announce that it finished, at the same level: otherwise the
                    // only evidence it ended is that StillRunning stopped
                    // repeating, and its duration cannot be read off the log at
                    // all. LongRunningProbeDueMs is the threshold either way.
                    if (elapsedMs >= LongRunningProbeDueMs)
                    {
                        FenBrowser.Core.EngineLogCompat.Warn(
                            completion,
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }
                    else
                    {
                        FenBrowser.Core.EngineLogCompat.Debug(
                            completion,
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }
                }
                catch (Exception ex)
                {
                    workItem.Completion.TrySetException(ex);
                    FenBrowser.Core.EngineLogCompat.Warn(
                        $"[FenJsWorker] Failed id={workItem.Sequence} kind={workItem.Kind} " +
                        $"errorType={ex.GetType().Name} error={ex.Message}",
                        FenBrowser.Core.Logging.LogCategory.JavaScript);
                }
                finally
                {
                    Volatile.Write(ref _activeFenJsWorkItem, null);
                    Volatile.Write(ref _fenJsWorkerActive, 0);
                }
            }
        }
    }

    public bool IsEventDispatchBusy(Element element)
    {
        if (element?.OwnerDocument != null &&
            TryGetFrameRealm(element.OwnerDocument, out var frameRealm))
        {
            return frameRealm.IsEventDispatchBusy(element);
        }

        return Volatile.Read(ref _fenJsWorkerActive) != 0;
    }

    private bool TryDequeueFenJsWork(out FenJsWorkItem workItem)
    {
        return _fenJsInputWorkQueue.TryDequeue(out workItem) ||
               _fenJsWorkQueue.TryDequeue(out workItem);
    }

    private T RunFenJsWithLargeStack<T>(
        Func<T> work,
        [CallerMemberName] string workKind = null)
    {
        return RunFenJsWithLargeStack(
            work,
            waitForWorkerMs: -1,
            instructionBudget: FenJsBrowserInstructionBudget,
            workKind: workKind);
    }

    private JsValue EvaluateBootstrapWithFenJsRaw(string script)
    {
        Interlocked.Increment(ref _suppressMissingHostAssignmentTracking);
        try
        {
            return EvaluateWithFenJsRaw(script);
        }
        finally
        {
            Interlocked.Decrement(ref _suppressMissingHostAssignmentTracking);
        }
    }

    private T RunFenJsWithLargeStack<T>(
        Func<T> work,
        long waitForWorkerMs,
        int instructionBudget = FenJsBrowserInstructionBudget,
        bool prioritize = false,
        [CallerMemberName] string workKind = null)
    {
        if (_realmAbandoned)
        {
            // The frame is gone; its scripts must not run and no caller should
            // block waiting for a worker that has stopped.
            return default;
        }

        if (_onFenJsLargeStackThread)
        {
            // Re-entrant call from within the large-stack thread itself â€”
            // run inline to avoid deadlocking the persistent worker.
            return work();
        }

        EnsureFenJsWorkerRunning();

        var workItem = CreateFenJsWorkItem(() => (object)work(), instructionBudget, workKind);
        (prioritize ? _fenJsInputWorkQueue : _fenJsWorkQueue).Enqueue(workItem);
        _fenJsWorkAvailable.Set();

        object result;
        if (waitForWorkerMs >= 0)
        {
            try
            {
                result = workItem.Completion.Task
                    .WaitAsync(TimeSpan.FromMilliseconds(waitForWorkerMs))
                    .GetAwaiter()
                    .GetResult();
            }
            catch (TimeoutException)
            {
                var timeout = new FenBrowser.FenEngine.Errors.FenTimeoutError(
                    $"Timed out waiting for FenJS worker after {waitForWorkerMs} ms.");
                // The caller stopped waiting, but the queued work itself is still
                // valid: dropping it here loses dispatched events/timers whose
                // handlers legitimately exceed the caller's wait (e.g. reCAPTCHA
                // signal collection). Leave it runnable; just observe a later
                // fault so no unobserved-task exception reaches the finalizer.
                ObserveAbandonedCompletion(workItem.Completion.Task);
                throw timeout;
            }
        }
        else
        {
            result = workItem.Completion.Task.GetAwaiter().GetResult();
        }

        if (result == null && typeof(T).IsValueType)
        {
            throw new InvalidOperationException(
                "[FenJsBridge] JS worker returned null; the JS session was likely " +
                "reset by a navigation while the evaluation was in flight. " +
                "(_fenJsSessionGeneration=" + _fenJsSessionGeneration + ")");
        }

        return (T)result;
    }

    public Task RunOnScriptThreadAsync(Func<Task> work)
    {
        ArgumentNullException.ThrowIfNull(work);
        if (_realmAbandoned)
        {
            return Task.CompletedTask;
        }

        // Queued even from the script thread: a style pass scheduled from
        // inside an attribute setter ran before the element had finished
        // updating (its ancestor selector filter was still stale) and styled
        // the subtree against the old state, after which nothing was dirty.
        // Running after the current task also coalesces a script's many
        // mutations into one pass instead of one per mutation.
        //
        // The work is not script: it runs with no instruction budget of its own
        // and is never abandoned on timeout. Blocking the worker on the task is
        // what makes the pass atomic with respect to scripts; a continuation of
        // the work on another thread can still run, but no script runs
        // alongside it because the only script thread is waiting here.
        EnsureFenJsWorkerRunning();
        var workItem = CreateFenJsWorkItem(
            () =>
            {
                work().GetAwaiter().GetResult();
                return null;
            },
            int.MaxValue,
            "RenderingUpdate");
        _fenJsWorkQueue.Enqueue(workItem);
        _fenJsWorkAvailable.Set();
        return workItem.Completion.Task;
    }

    /// <summary>
    /// Phase 12: non-blocking variant of <see cref="RunFenJsWithLargeStack{T}"/>.
    /// Posts work to the JS worker thread and returns a Task that completes when
    /// the worker finishes, without blocking the calling (engine) thread. Applies
    /// the same timeout policy as the synchronous path via CancellationToken.
    /// </summary>
    private async Task<T> RunFenJsWithLargeStackAsync<T>(
        Func<T> work,
        long timeoutMs = -1,
        int instructionBudget = FenJsBrowserInstructionBudget,
        bool prioritize = false,
        [CallerMemberName] string workKind = null)
    {
        if (_realmAbandoned)
        {
            return default;
        }

        if (_onFenJsLargeStackThread)
        {
            // Re-entrant: run inline.
            return work();
        }

        EnsureFenJsWorkerRunning();

        var workItem = CreateFenJsWorkItem(() => (object)work(), instructionBudget, workKind);
        var cts = timeoutMs > 0
            ? new CancellationTokenSource(TimeSpan.FromMilliseconds(timeoutMs))
            : null;

        (prioritize ? _fenJsInputWorkQueue : _fenJsWorkQueue).Enqueue(workItem);
        _fenJsWorkAvailable.Set();

        try
        {
            if (cts != null)
            {
                // The timeout bounds only how long the CALLER waits. The queued
                // work must still run: cancelling it here silently drops
                // dispatched input events and timer callbacks whose handlers
                // legitimately exceed the wait (e.g. reCAPTCHA signal
                // collection), leaving the page stuck mid-flow.
                using var reg = cts.Token.Register(() =>
                {
                    ObserveAbandonedCompletion(workItem.Completion.Task);
                });

                using (cts)
                {
                    try
                    {
                        var result = await workItem.Completion.Task.WaitAsync(cts.Token).ConfigureAwait(false);
                        return (T)result;
                    }
                    catch (OperationCanceledException)
                    {
                        throw new FenBrowser.FenEngine.Errors.FenTimeoutError(
                            $"FenJS async work timed out after {timeoutMs}ms; the queued work continues on the JS worker.");
                    }
                }
            }
            else
            {
                var result = await workItem.Completion.Task.ConfigureAwait(false);
                return (T)result;
            }
        }
        catch (FenBrowser.FenEngine.Errors.FenTimeoutError)
        {
            // Propagate timeout directly without wrapping.
            throw;
        }
    }

    private FenJsWorkItem CreateFenJsWorkItem(
        Func<object> work,
        int instructionBudget,
        string workKind)
    {
        return new FenJsWorkItem(
            Interlocked.Increment(ref _fenJsWorkItemSequence),
            work,
            instructionBudget,
            workKind,
            _currentDocumentId,
            _currentBaseUri?.AbsoluteUri);
    }

    private void SetFenJsWorkerPhase(string phase)
    {
        Volatile.Read(ref _activeFenJsWorkItem)?.SetPhase(phase);
    }

    /// <summary>
    /// Keeps an abandoned (caller-timed-out) work item's completion task from
    /// surfacing an unobserved task exception on the finalizer thread if the
    /// worker later executes it and it throws.
    /// </summary>
    private static void ObserveAbandonedCompletion(Task task)
    {
        _ = task.ContinueWith(
            static t => _ = t.Exception,
            CancellationToken.None,
            TaskContinuationOptions.OnlyOnFaulted,
            TaskScheduler.Default);
    }

    private void BeginScriptLoadingSnapshot(Node domRoot, Uri baseUri)
    {
        _currentNavigationId = LogContext.CurrentCorrelationId;
        using (ScriptEngineLockProbe.Hold(_scriptLoadingLock))
        {
            _lastScriptLoadingSnapshot = new BrowserScriptLoadingSnapshot
            {
                Status = "running",
                StartedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture),
                BaseUrl = baseUri?.AbsoluteUri ?? string.Empty,
                DomRootPresent = domRoot != null
            };
        }
    }

    private void UpdateScriptLoadingSnapshot(Action<BrowserScriptLoadingSnapshot> update)
    {
        if (update == null)
        {
            return;
        }

        using (ScriptEngineLockProbe.Hold(_scriptLoadingLock))
        {
            _lastScriptLoadingSnapshot ??= new BrowserScriptLoadingSnapshot();
            update(_lastScriptLoadingSnapshot);
        }
    }

    private BrowserScriptLoadingRecord AddScriptLoadingRecord(Element scriptElement, int ordinal, bool isModule, bool isAsync, bool isDefer)
    {
        var src = scriptElement?.GetAttribute("src") ?? string.Empty;
        var record = new BrowserScriptLoadingRecord
        {
            Ordinal = ordinal,
            ScriptId = BuildScriptId(ordinal),
            SourceLabel = BuildScriptSourceLabel(scriptElement, ordinal),
            SourceOffset = scriptElement?.SourceOffset ?? -1,
            SourceLine = scriptElement?.SourceLine ?? 0,
            SourceColumn = scriptElement?.SourceColumn ?? 0,
            Kind = isModule ? "module" : "classic",
            SourceType = string.IsNullOrEmpty(src) ? "inline" : "external",
            Src = src,
            Type = scriptElement?.GetAttribute("type") ?? string.Empty,
            IsAsync = isAsync,
            IsDefer = isDefer,
            IsNoModule = scriptElement?.HasAttribute("nomodule") ?? false,
            TextLength = scriptElement?.TextContent?.Length ?? 0,
            StartedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture)
        };

        using (ScriptEngineLockProbe.Hold(_scriptLoadingLock))
        {
            _lastScriptLoadingSnapshot ??= new BrowserScriptLoadingSnapshot();
            _lastScriptLoadingSnapshot.Scripts.Add(record);
        }

        return record;
    }

    private BrowserScriptLoadingRecord AddDynamicScriptLoadingRecord(Element scriptElement)
    {
        var ordinal = Interlocked.Increment(ref _dynamicScriptTraceCounter);
        var src = scriptElement?.GetAttribute("src") ?? string.Empty;
        var type = scriptElement?.GetAttribute("type")?.ToLowerInvariant() ?? string.Empty;
        var isModule = type == "module";
        var record = new BrowserScriptLoadingRecord
        {
            Ordinal = ordinal,
            ScriptId = "dynamic-script-" + ordinal.ToString(CultureInfo.InvariantCulture),
            SourceLabel = string.IsNullOrWhiteSpace(src)
                ? "dynamic-inline#" + ordinal.ToString(CultureInfo.InvariantCulture)
                : "dynamic-external:" + src.Trim(),
            SourceOffset = scriptElement?.SourceOffset ?? -1,
            SourceLine = scriptElement?.SourceLine ?? 0,
            SourceColumn = scriptElement?.SourceColumn ?? 0,
            Kind = isModule ? "module" : "classic",
            SourceType = string.IsNullOrEmpty(src) ? "inline" : "external",
            Src = src,
            Type = scriptElement?.GetAttribute("type") ?? string.Empty,
            IsAsync = true,
            IsDefer = false,
            IsNoModule = scriptElement?.HasAttribute("nomodule") ?? false,
            ParserInserted = false,
            TextLength = scriptElement?.TextContent?.Length ?? 0,
            StartedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture)
        };

        using (ScriptEngineLockProbe.Hold(_scriptLoadingLock))
        {
            _lastScriptLoadingSnapshot ??= new BrowserScriptLoadingSnapshot();
            _lastScriptLoadingSnapshot.Scripts.Add(record);
        }

        return record;
    }

    private void UpdateScriptLoadingRecord(BrowserScriptLoadingRecord record, Action<BrowserScriptLoadingRecord> update)
    {
        if (record == null || update == null)
        {
            return;
        }

        using (ScriptEngineLockProbe.Hold(_scriptLoadingLock))
        {
            update(record);
        }
    }

    private void MarkScriptSkipped(BrowserScriptLoadingRecord record, string reason)
    {
        UpdateScriptLoadingRecord(record, script =>
        {
            script.Status = "skipped";
            script.Failure = reason ?? string.Empty;
            script.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        });
        UpdateScriptLoadingSnapshot(snapshot => snapshot.SkippedScripts++);
        var fields = CreateScriptRecordFields(record);
        fields["ordinal"] = record?.Ordinal ?? 0;
        fields["src"] = record?.Src ?? string.Empty;
        fields["reason"] = reason ?? string.Empty;
        LogScriptLoading(
            "ScriptSkipped",
            LogSeverity.Debug,
            "[FenJsBridge] Script skipped",
            fields);
    }

    private static string BuildScriptId(int ordinal)
    {
        return "script-" + Math.Max(0, ordinal).ToString(CultureInfo.InvariantCulture);
    }

    private static string BuildScriptSourceLabel(Element scriptElement, int ordinal)
    {
        var scriptId = BuildScriptId(ordinal);
        var src = scriptElement?.GetAttribute("src");
        if (!string.IsNullOrWhiteSpace(src))
        {
            return "external:" + src.Trim();
        }

        return "inline#" + scriptId.Substring("script-".Length);
    }

    private static void AddScriptRecordFields(IDictionary<string, object> fields, BrowserScriptLoadingRecord record)
    {
        if (fields == null || record == null)
        {
            return;
        }

        fields["scriptId"] = record.ScriptId ?? string.Empty;
        fields["scriptOrdinal"] = record.Ordinal;
        fields["scriptSourceLabel"] = record.SourceLabel ?? string.Empty;
        fields["scriptSourceType"] = record.SourceType ?? string.Empty;
        fields["scriptSourceOffset"] = record.SourceOffset;
        fields["scriptSourceLine"] = record.SourceLine;
        fields["scriptSourceColumn"] = record.SourceColumn;
        fields["sourceLabel"] = record.SourceLabel ?? string.Empty;
        fields["sourceType"] = record.SourceType ?? string.Empty;
        fields["scriptSrc"] = record.Src ?? string.Empty;
        fields["scriptResolvedUrl"] = record.ResolvedUrl ?? string.Empty;
        fields["url"] = string.IsNullOrWhiteSpace(record.ResolvedUrl) ? record.Src ?? string.Empty : record.ResolvedUrl;
        fields["inline"] = string.Equals(record.SourceType, "inline", StringComparison.OrdinalIgnoreCase);
        fields["external"] = string.Equals(record.SourceType, "external", StringComparison.OrdinalIgnoreCase);
        fields["classic"] = string.Equals(record.Kind, "classic", StringComparison.OrdinalIgnoreCase);
        fields["module"] = string.Equals(record.Kind, "module", StringComparison.OrdinalIgnoreCase);
        fields["async"] = record.IsAsync;
        fields["defer"] = record.IsDefer;
        fields["parserInserted"] = record.ParserInserted;
        fields["blockingStatus"] = ResolveScriptBlockingStatus(record);
        fields["fetchStatus"] = record.Status ?? string.Empty;
        fields["mimeType"] = record.Type ?? string.Empty;
        fields["executionOrder"] = record.Ordinal;
    }

    private static Dictionary<string, object> CreateScriptRecordFields(BrowserScriptLoadingRecord record)
    {
        var fields = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        AddScriptRecordFields(fields, record);
        return fields;
    }

    private static string ResolveScriptBlockingStatus(BrowserScriptLoadingRecord record)
    {
        if (record == null)
        {
            return string.Empty;
        }

        if (record.IsAsync)
        {
            return "non-blocking";
        }

        if (record.IsDefer)
        {
            return "domcontentloaded-blocking";
        }

        return "parser-blocking";
    }

    private static EngineLogContext CreateScriptLogContext(IReadOnlyDictionary<string, object> fields)
    {
        if (fields == null)
        {
            return new EngineLogContext(NavigationId: LogContext.CurrentCorrelationId);
        }

        var resourceUrl = GetStringField(fields, "scriptResolvedUrl");
        if (string.IsNullOrWhiteSpace(resourceUrl))
        {
            resourceUrl = GetStringField(fields, "url");
        }

        if (string.IsNullOrWhiteSpace(resourceUrl))
        {
            resourceUrl = GetStringField(fields, "scriptSrc");
        }

        return new EngineLogContext(
            NavigationId: LogContext.CurrentCorrelationId,
            Url: GetStringField(fields, "baseUri"),
            ResourceUrl: resourceUrl,
            ScriptId: GetStringField(fields, "scriptId"));
    }

    private static string GetStringField(IReadOnlyDictionary<string, object> fields, string key)
    {
        if (fields == null ||
            string.IsNullOrWhiteSpace(key) ||
            !fields.TryGetValue(key, out var value) ||
            value == null)
        {
            return null;
        }

        return Convert.ToString(value, CultureInfo.InvariantCulture);
    }

    private static void LogScriptLoading(
        string eventName,
        LogSeverity severity,
        string message,
        IReadOnlyDictionary<string, object> fields = null,
        LogMarker marker = LogMarker.None,
        [CallerFilePath] string sourceFile = "",
        [CallerLineNumber] int sourceLine = 0,
        [CallerMemberName] string sourceMember = "")
    {
        var payload = fields != null
            ? new Dictionary<string, object>(fields, StringComparer.OrdinalIgnoreCase)
            : new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        payload["event"] = eventName ?? string.Empty;
        payload["eventName"] = eventName ?? string.Empty;
        payload["traceCategory"] = "ScriptLoader";
        var context = CreateScriptLogContext(payload);

        EngineLog.Write(
            LogSubsystem.Js,
            severity,
            message,
            marker,
            context,
            payload,
            sourceFile,
            sourceLine,
            sourceMember);
    }

    private static string TruncateForLog(string value, int maxLength)
    {
        if (string.IsNullOrEmpty(value) || maxLength <= 0 || value.Length <= maxLength)
        {
            return value ?? string.Empty;
        }

        return value.Substring(0, maxLength) + "...";
    }

    private void BeginEventLoopSnapshot(Node domRoot, Uri baseUri)
    {
        // A frame that is re-navigated (reCAPTCHA replaces its widget rather than
        // removing the iframe) keeps the same realm and worker, so the previous
        // document's in-flight script would otherwise keep running against a
        // document nobody can see any more — burning the CPU the new document
        // needs. Retiring the id here makes that work stale; the interrupt hook
        // and the worker loop then abandon it.
        //
        // The item performing this transition captured the outgoing id, so exempt
        // it or it would abort itself mid-navigation.
        Volatile.Write(ref _documentTransitionWorkItem, Volatile.Read(ref _activeFenJsWorkItem));
        _currentDocumentId = "document-" + Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
        Interlocked.Exchange(ref _callbackFailureSequence, 0);
        Interlocked.Exchange(ref _diagnosticCallbackIdSequence, 0);
        _diagnosticPromiseRejectionTracker?.Reset();
        _callbackFunctionProvenance.Clear();
        _pendingPromiseRejectionDiagnostics.Clear();
        using (ScriptEngineLockProbe.Hold(_eventLoopLock))
        {
            _lastEventLoopSnapshot = new BrowserEventLoopSnapshot
            {
                Status = "running",
                StartedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture),
                BaseUrl = baseUri?.AbsoluteUri ?? string.Empty,
                DomRootPresent = domRoot != null,
                DocumentReadyState = "loading",
                PendingHostTimers = _fenJsTimers.Count
            };
        }

        AddEventLoopRecord("EventLoopStarted", "document-bound");
    }

    private void UpdateEventLoopSnapshot(Action<BrowserEventLoopSnapshot> update)
    {
        if (update == null)
        {
            return;
        }

        var readyState = GetDocumentReadyState();
        var pendingHostTimers = _fenJsTimers.Count;
        using (ScriptEngineLockProbe.Hold(_eventLoopLock))
        {
            _lastEventLoopSnapshot ??= new BrowserEventLoopSnapshot();
            update(_lastEventLoopSnapshot);
            _lastEventLoopSnapshot.PendingHostTimers = pendingHostTimers;
            _lastEventLoopSnapshot.DocumentReadyState = readyState;
        }
    }

    private void AddEventLoopRecord(string eventName, string detail = "", long id = 0, int delayMs = 0, bool repeating = false)
    {
        var timestamp = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        var readyState = GetDocumentReadyState();
        var pendingHostTimers = _fenJsTimers.Count;
        using (ScriptEngineLockProbe.Hold(_eventLoopLock))
        {
            _lastEventLoopSnapshot ??= new BrowserEventLoopSnapshot();
            _lastEventLoopSnapshot.Events.Add(new BrowserEventLoopRecord
            {
                EventName = eventName ?? string.Empty,
                TimestampUtc = timestamp,
                Detail = detail ?? string.Empty,
                Id = id,
                DelayMs = delayMs,
                Repeating = repeating,
                DocumentReadyState = readyState
            });
            _lastEventLoopSnapshot.PendingHostTimers = pendingHostTimers;
            _lastEventLoopSnapshot.DocumentReadyState = readyState;
        }
    }

    private void RecordMicrotaskCheckpoint(string detail)
    {
        _diagnosticPromiseRejectionTracker?.FlushPending();
        var timestamp = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        UpdateEventLoopSnapshot(snapshot =>
        {
            snapshot.MicrotaskCheckpoints++;
            snapshot.LastMicrotaskCheckpointUtc = timestamp;
        });
        AddEventLoopRecord("MicrotaskCheckpointCompleted", detail ?? string.Empty);
        LogEventLoop(
            "MicrotaskCheckpointCompleted",
            LogSeverity.Debug,
            "[FenJsBridge] Microtask checkpoint completed",
            new Dictionary<string, object>
            {
                ["detail"] = detail ?? string.Empty
            });
    }

    private void MarkEventLoopCompleted()
    {
        _diagnosticPromiseRejectionTracker?.FlushPending();
        UpdateEventLoopSnapshot(snapshot =>
        {
            snapshot.Status = "completed";
            snapshot.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        });
    }

    private static void LogEventLoop(
        string eventName,
        LogSeverity severity,
        string message,
        IReadOnlyDictionary<string, object> fields = null,
        LogMarker marker = LogMarker.None,
        [CallerFilePath] string sourceFile = "",
        [CallerLineNumber] int sourceLine = 0,
        [CallerMemberName] string sourceMember = "")
    {
        var payload = fields != null
            ? new Dictionary<string, object>(fields, StringComparer.OrdinalIgnoreCase)
            : new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        payload["event"] = eventName ?? string.Empty;
        payload["eventName"] = eventName ?? string.Empty;
        payload["traceCategory"] = "EventLoop";
        var taskId = ResolveEventLoopTaskId(payload, eventName);

        EngineLog.Write(
            LogSubsystem.Event,
            severity,
            message,
            marker,
            new EngineLogContext(
                NavigationId: LogContext.CurrentCorrelationId,
                TaskId: taskId),
            payload,
            sourceFile,
            sourceLine,
            sourceMember);
    }

    private static string ResolveEventLoopTaskId(IReadOnlyDictionary<string, object> fields, string eventName)
    {
        var taskId = GetStringField(fields, "taskId");
        if (!string.IsNullOrWhiteSpace(taskId))
        {
            return taskId;
        }

        var id = GetStringField(fields, "id");
        if (string.IsNullOrWhiteSpace(id) || id == "0")
        {
            return null;
        }

        var origin = GetStringField(fields, "origin");
        if (string.Equals(origin, "requestAnimationFrame", StringComparison.Ordinal) ||
            (eventName?.IndexOf("AnimationFrame", StringComparison.OrdinalIgnoreCase) ?? -1) >= 0)
        {
            return "raf-" + id;
        }

        if (string.Equals(origin, "setTimeout", StringComparison.Ordinal) ||
            string.Equals(origin, "setInterval", StringComparison.Ordinal) ||
            (eventName?.IndexOf("Timer", StringComparison.OrdinalIgnoreCase) ?? -1) >= 0 ||
            (eventName?.IndexOf("Interval", StringComparison.OrdinalIgnoreCase) ?? -1) >= 0)
        {
            return "timer-" + id;
        }

        return "callback-" + id;
    }

    private async Task ExecutePageScriptsWithFenJsAsync(Node domRoot, Uri baseUri)
    {
        // Anything the parent posts at us waits for these, however early it
        // was posted.
        var batchDone = new TaskCompletionSource<bool>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        _pageScriptsFinished = batchDone.Task;
        try
        {
            await ExecutePageScriptsCoreAsync(domRoot, baseUri).ConfigureAwait(false);
        }
        finally
        {
            batchDone.TrySetResult(true);
        }
    }

    private async Task ExecutePageScriptsCoreAsync(Node domRoot, Uri baseUri)
    {
        LogScriptLoading(
            "ScriptLoadingStarted",
            LogSeverity.Debug,
            "[FenJsBridge] ExecutePageScriptsWithFenJsAsync START",
            new Dictionary<string, object>
            {
                ["domRootPresent"] = domRoot != null,
                ["baseUri"] = baseUri?.AbsoluteUri ?? string.Empty
            });
        try
        {
            var allScripts = EnumerateScriptElements(domRoot).ToList();
            UpdateScriptLoadingSnapshot(snapshot =>
            {
                snapshot.ScriptElements = allScripts.Count;
                snapshot.TotalScripts = allScripts.Count;
            });
            LogScriptLoading(
                "ScriptDiscovered",
                LogSeverity.Info,
                "[FenJsBridge] Script elements discovered",
                new Dictionary<string, object>
                {
                    ["scriptElements"] = allScripts.Count
                });

            // Phase 1: validate all scripts and kick off external fetches concurrently.
            // Each entry holds everything needed to execute the script in order.
            var items = new List<ScriptExecutionItem>(allScripts.Count);
            var fetchTasks = new Dictionary<string, Task<string>>(StringComparer.Ordinal);

            for (int i = 0; i < allScripts.Count; i++)
            {
                var scriptElement = allScripts[i];
                var type = scriptElement.GetAttribute("type")?.ToLowerInvariant() ?? string.Empty;
                var src = scriptElement.GetAttribute("src");
                bool isModule = type == "module";
                bool isAsync = false;
                bool isDefer = false;
                if (isModule)
                {
                    isDefer = !scriptElement.HasAttribute("async");
                    isAsync = scriptElement.HasAttribute("async");
                }
                else
                {
                    bool hasSrc = !string.IsNullOrEmpty(src);
                    isAsync = scriptElement.HasAttribute("async") && hasSrc;
                    isDefer = scriptElement.HasAttribute("defer") && hasSrc;
                }
                var scriptRecord = AddScriptLoadingRecord(scriptElement, i + 1, isModule, isAsync, isDefer);
                var seenFields = CreateScriptRecordFields(scriptRecord);
                seenFields["tag"] = scriptElement.TagName ?? string.Empty;
                seenFields["src"] = src ?? string.Empty;
                seenFields["type"] = scriptElement.GetAttribute("type") ?? string.Empty;
                seenFields["textLength"] = scriptElement.TextContent?.Length ?? 0;
                LogScriptLoading(
                    "ScriptDiscovered",
                    LogSeverity.Debug,
                    "[FenJsBridge] Script element seen",
                    seenFields);

                if (type == "importmap")
                {
                    RegisterImportMapScript(scriptElement);
                    MarkScriptSkipped(scriptRecord, "importmap");
                    continue;
                }

                if (!string.IsNullOrEmpty(type) &&
                    type != "text/javascript" &&
                    type != "application/javascript" &&
                    type != "module")
                {
                    if (type != "application/ld+json")
                        FenBrowser.Core.EngineLogCompat.Debug(
                            $"[FenJsBridge] Skipping script with unknown type '{type}': src={scriptElement.GetAttribute("src")}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    MarkScriptSkipped(scriptRecord, $"unsupported-type:{type}");
                    continue;
                }

                if (scriptElement.HasAttribute("nomodule"))
                {
                    FenBrowser.Core.EngineLogCompat.Debug(
                        $"[FenJsBridge] Skipping nomodule script: src={scriptElement.GetAttribute("src")}",
                        FenBrowser.Core.Logging.LogCategory.JavaScript);
                    MarkScriptSkipped(scriptRecord, "nomodule");
                    continue;
                }


                // Determine async/defer per WHATWG HTML Â§4.12.1
                // - async: execute as soon as available (external only per spec)
                // - defer: execute after parsing, before DOMContentLoaded (external only per spec)
                // - Module scripts are deferred by default; async on modules = execute ASAP
                if (isModule)
                {
                    // Modules are deferred by default; async makes them execute ASAP
                    isDefer = !scriptElement.HasAttribute("async");
                    isAsync = scriptElement.HasAttribute("async");
                }
                else
                {
                    // Classic scripts: async/defer only apply to external scripts
                    bool hasSrc = !string.IsNullOrEmpty(src);
                    isAsync = scriptElement.HasAttribute("async") && hasSrc;
                    isDefer = scriptElement.HasAttribute("defer") && hasSrc;
                }
                if (!string.IsNullOrEmpty(src))
                {
                    // External script â€” validate, then kick off fetch concurrently
                    UpdateScriptLoadingSnapshot(snapshot =>
                    {
                        snapshot.ExternalScripts++;
                        if (isModule)
                        {
                            snapshot.ModuleScripts++;
                        }
                    });
                    var externalFields = CreateScriptRecordFields(scriptRecord);
                    externalFields["src"] = src;
                    externalFields["isModule"] = isModule;
                    externalFields["isAsync"] = isAsync;
                    externalFields["isDefer"] = isDefer;
                    LogScriptLoading(
                        "ScriptExternalDiscovered",
                        LogSeverity.Debug,
                        "[FenJsBridge] External script discovered",
                        externalFields);

                    if (!AllowExternalScripts || !Sandbox.Allows(SandboxFeature.ExternalScripts))
                    {
                        FenBrowser.Core.EngineLogCompat.Warn(
                            $"[FenJsBridge] Skipping external script (AllowExternal={AllowExternalScripts}, SandboxExternal={Sandbox.Allows(SandboxFeature.ExternalScripts)}): {src}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                        MarkScriptSkipped(scriptRecord, $"external-disabled:allowExternal={AllowExternalScripts};sandbox={Sandbox.Allows(SandboxFeature.ExternalScripts)}");
                        continue;
                    }

                    if (baseUri == null || !Uri.TryCreate(baseUri, src, out var scriptUri))
                    {
                        FenBrowser.Core.EngineLogCompat.Warn(
                            $"[FenJsBridge] Skipping script with unresolvable src (baseUri={baseUri}): {src}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                        MarkScriptSkipped(scriptRecord, $"unresolvable-src:baseUri={baseUri}");
                        continue;
                    }

                    if (SubresourceAllowed != null && !SubresourceAllowed(scriptUri, "script"))
                    {
                        var nonce = scriptElement.GetAttribute("nonce");
                        if (string.IsNullOrEmpty(nonce) || NonceAllowed == null || !NonceAllowed(nonce))
                        {
                            FenBrowser.Core.EngineLogCompat.Warn(
                                $"[FenJsBridge] Skipping script due to SubresourceAllowed (CSP) block: {scriptUri}",
                                FenBrowser.Core.Logging.LogCategory.JavaScript);
                            MarkScriptSkipped(scriptRecord, $"csp-block:{scriptUri}");
                            continue;
                        }
                        FenBrowser.Core.EngineLogCompat.Info(
                            $"[FenJsBridge] External script allowed via nonce bypass: {scriptUri}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }

                    // CSP Level 3 Â§6.2.2.9: under 'strict-dynamic' the resource layer's
                    // URL-only re-validation cannot see this element, so carry the
                    // authorizing nonce with the fetch context.
                    var elementNonce = scriptElement.GetAttribute("nonce");

                    // Deduplicate: same URL â†’ same fetch task
                    var fetchKey = $"{scriptUri.AbsoluteUri}\n{elementNonce ?? string.Empty}";
                    if (!fetchTasks.TryGetValue(fetchKey, out var fetchTask))
                    {
                        fetchTask = FetchExternalPageScriptAsync(scriptUri, baseUri, string.IsNullOrEmpty(elementNonce) ? null : elementNonce);
                        if (isModule)
                        {
                            // HTML "fetch an external module script graph": the
                            // descendants load now, alongside every other script on
                            // the page, not when this script's turn to run comes.
                            fetchTask = FetchModuleScriptGraphAsync(scriptUri, fetchTask);
                        }
                        fetchTasks[fetchKey] = fetchTask;
                        UpdateScriptLoadingSnapshot(snapshot => snapshot.FetchStarted++);
                        UpdateScriptLoadingRecord(scriptRecord, record =>
                        {
                            record.ResolvedUrl = scriptUri.AbsoluteUri;
                            record.Status = "fetch-started";
                        });
                        var fetchStartedFields = CreateScriptRecordFields(scriptRecord);
                        fetchStartedFields["url"] = scriptUri.AbsoluteUri;
                        LogScriptLoading(
                            "ScriptFetchStarted",
                            LogSeverity.Debug,
                            "[FenJsBridge] External script fetch started",
                            fetchStartedFields);
                    }

                    UpdateScriptLoadingRecord(scriptRecord, record => record.ResolvedUrl = scriptUri.AbsoluteUri);
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.EligibleScripts++);
                    items.Add(new ScriptExecutionItem(scriptElement, isModule, isAsync, isDefer, fetchKey, fetchTask, scriptUri, null, scriptRecord));
                }
                else
                {
                    // Inline script â€” validate now, code is already in DOM
                    UpdateScriptLoadingSnapshot(snapshot =>
                    {
                        snapshot.InlineScripts++;
                        if (isModule)
                        {
                            snapshot.ModuleScripts++;
                        }
                    });
                    FenBrowser.Core.EngineLogCompat.Debug(
                        $"[FenJsBridge] Processing inline {(isModule ? "module" : "script")} len={scriptElement.TextContent?.Length}",
                        FenBrowser.Core.Logging.LogCategory.JavaScript);

                    if (!Sandbox.Allows(SandboxFeature.InlineScripts))
                    {
                        MarkScriptSkipped(scriptRecord, "inline-disabled");
                        continue;
                    }

                    var inlineNonce = scriptElement.GetAttribute("nonce");
                    if (NonceAllowed != null && !NonceAllowed(inlineNonce))
                    {
                        MarkScriptSkipped(scriptRecord, "csp-inline-blocked");
                        continue;
                    }

                    var code = CollectScriptText(scriptElement);
                    if (string.IsNullOrWhiteSpace(code))
                    {
                        MarkScriptSkipped(scriptRecord, "empty-inline-code");
                        continue;
                    }

                    // Inline scripts: async/defer have no effect per spec; treat as blocking
                    // unless type="module" (modules are deferred by default)
                    bool inlineIsAsync = isModule && scriptElement.HasAttribute("async");
                    bool inlineIsDefer = isModule && !scriptElement.HasAttribute("async");
                    UpdateScriptLoadingRecord(scriptRecord, record =>
                    {
                        record.CodeLength = code.Length;
                        record.IsAsync = inlineIsAsync;
                        record.IsDefer = inlineIsDefer;
                        record.Status = "ready";
                    });
                    var readyFields = CreateScriptRecordFields(scriptRecord);
                    readyFields["codeLength"] = code.Length;
                    LogScriptLoading(
                        "ScriptReady",
                        LogSeverity.Debug,
                        "[FenJsBridge] Inline script ready",
                        readyFields);
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.EligibleScripts++);
                    items.Add(new ScriptExecutionItem(scriptElement, isModule, inlineIsAsync, inlineIsDefer, null, null, null, code, scriptRecord));
                }
            }

            // Categorize scripts for phased execution per WHATWG HTML Â§4.12.1
            var blockingItems = new List<ScriptExecutionItem>();
            var deferItems = new List<ScriptExecutionItem>();
            var asyncItems = new List<ScriptExecutionItem>();
            foreach (var item in items)
            {
                if (item.IsAsync)
                    asyncItems.Add(item);
                else if (item.IsDefer)
                    deferItems.Add(item);
                else
                    blockingItems.Add(item);
            }
            UpdateScriptLoadingSnapshot(snapshot =>
            {
                snapshot.BlockingScripts = blockingItems.Count;
                snapshot.DeferScripts = deferItems.Count;
                snapshot.AsyncScripts = asyncItems.Count;
            });
            foreach (var item in blockingItems)
            {
                UpdateScriptLoadingRecord(item.ScriptRecord, record => record.Batch = "blocking");
            }
            foreach (var item in deferItems)
            {
                UpdateScriptLoadingRecord(item.ScriptRecord, record => record.Batch = "defer");
            }
            foreach (var item in asyncItems)
            {
                UpdateScriptLoadingRecord(item.ScriptRecord, record => record.Batch = "async");
            }
            LogScriptLoading(
                "ScriptCategorized",
                LogSeverity.Info,
                "[FenJsBridge] Scripts categorized",
                new Dictionary<string, object>
                {
                    ["blocking"] = blockingItems.Count,
                    ["defer"] = deferItems.Count,
                    ["async"] = asyncItems.Count
                });

            // Phase 2a: Execute blocking scripts in document order.
            // Each blocking script must complete before the next one starts.
            LogScriptLoading("ScriptBatchStarted", LogSeverity.Debug, "[FenJsBridge] Executing blocking scripts", new Dictionary<string, object> { ["batch"] = "blocking", ["count"] = blockingItems.Count });
            await ExecuteScriptBatchAsync(blockingItems, baseUri, "blocking").ConfigureAwait(false);

            // Phase 2b: Execute defer scripts in document order after all blocking
            // scripts have completed. Deferred scripts execute before DOMContentLoaded.
            LogScriptLoading("ScriptBatchStarted", LogSeverity.Debug, "[FenJsBridge] Executing defer scripts", new Dictionary<string, object> { ["batch"] = "defer", ["count"] = deferItems.Count });
            await ExecuteScriptBatchAsync(deferItems, baseUri, "defer").ConfigureAwait(false);

            // Phase 2c: Fire-and-forget async scripts. Per WHATWG HTML Â§4.12.1,
            // async scripts execute as soon as they are available and must NOT
            // block DOMContentLoaded. We launch them as a background continuation
            // so the caller can fire DOMContentLoaded immediately.
            if (asyncItems.Count > 0)
            {
                UpdateScriptLoadingSnapshot(snapshot => snapshot.AsyncPendingScripts += asyncItems.Count);
                LogScriptLoading("ScriptBatchStarted", LogSeverity.Debug, "[FenJsBridge] Launching async scripts", new Dictionary<string, object> { ["batch"] = "async", ["count"] = asyncItems.Count });
                var asyncBatch = ExecuteScriptBatchAsync(asyncItems, baseUri, "async");
                _ = asyncBatch.ContinueWith(
                    task =>
                    {
                        var ex = task.Exception?.GetBaseException();
                        LogScriptLoading(
                            "AsyncScriptBatchInfrastructureFailed",
                            LogSeverity.Error,
                            "[FenJsBridge] Async script batch failed",
                            new Dictionary<string, object>
                            {
                                ["batch"] = "async",
                                ["count"] = asyncItems.Count,
                                ["errorType"] = ex?.GetType().Name ?? "TaskFaulted",
                                ["error"] = ex?.Message ?? task.Exception?.Message ?? string.Empty
                            },
                            LogMarker.EngineBug);
                    },
                    TaskContinuationOptions.OnlyOnFaulted);
            }

            UpdateScriptLoadingSnapshot(snapshot =>
            {
                snapshot.Status = "completed";
                snapshot.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            });
            LogScriptLoading(
                "ScriptLoadingCompleted",
                LogSeverity.Info,
                "[FenJsBridge] ExecutePageScriptsWithFenJsAsync DONE",
                new Dictionary<string, object>
                {
                    ["processedSync"] = blockingItems.Count + deferItems.Count,
                    ["asyncPending"] = asyncItems.Count
                });
            // LogFenJsPageBootstrapState(); // DEBUG: disabled until NRE is fixed
        }
        catch (Exception ex)
        {
            // Per-script errors are already caught inside the execution loop.
            // This outer catch only handles infrastructure failures (e.g.
            // null _interpreter after a session reset). Log and surface but
            // do NOT re-throw â€” the page should render even if scripts fail.
            if (ex is JsThrownException jte && string.IsNullOrEmpty(jte.Description))
            {
                try { jte.Description = _interpreter.DescribeThrownValue(jte.Value); } catch { }
            }
            UpdateScriptLoadingSnapshot(snapshot =>
            {
                snapshot.Status = "infrastructure-error";
                snapshot.InfrastructureError = ex.Message;
                snapshot.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            });
            LogScriptLoading(
                "ScriptLoadingInfrastructureFailed",
                LogSeverity.Error,
                "[FenJsBridge] ExecutePageScriptsWithFenJsAsync infrastructure error",
                new Dictionary<string, object>
                {
                    ["errorType"] = ex.GetType().Name,
                    ["error"] = ex.Message
                },
                LogMarker.EngineBug);
        }
    }

    private void LogFenJsPageBootstrapState()
    {
        try
        {
            var state = EvaluateWithFenJsRaw(
                """
                (function () {
                    var waf = globalThis.AwsWafIntegration;
                    if (!waf) return 'AwsWafIntegration=<missing>';
                    return 'AwsWafIntegration=' + typeof waf +
                        ';checkForceRefresh=' + typeof waf.checkForceRefresh +
                        ';getToken=' + typeof waf.getToken +
                        ';forceRefreshToken=' + typeof waf.forceRefreshToken +
                        ';hasToken=' + typeof waf.hasToken;
                })()
                """);
            EvaluateWithFenJsRaw(
                """
                (function () {
                    var waf = globalThis.AwsWafIntegration;
                    if (!waf ||
                        typeof waf.hasToken !== 'function' ||
                        typeof waf.checkForceRefresh !== 'function') return;
                    try {
                        globalThis.__fenWafCheckProbe = 'pending';
                        waf.checkForceRefresh().then(function (value) {
                            globalThis.__fenWafCheckProbe = 'resolved:' + String(value);
                        }, function (error) {
                            globalThis.__fenWafCheckProbe = 'rejected:' + String(error && error.message ? error.message : error);
                        });
                        globalThis.__fenWafForceProbe = 'pending';
                        waf.forceRefreshToken().then(function (value) {
                            globalThis.__fenWafForceProbe = 'resolved:' + String(value);
                        }, function (error) {
                            globalThis.__fenWafForceProbe = 'rejected:' + String(error && error.message ? error.message : error);
                        });
                    } catch (error) {
                        globalThis.__fenWafCheckProbe = 'threw:' + String(error && error.message ? error.message : error);
                    }
                })()
                """);
            _interpreter.PumpMicrotasks();
            RecordMicrotaskCheckpoint("page-bootstrap-state-probe");
            var checkProbe = EvaluateWithFenJsRaw("String(globalThis.__fenWafCheckProbe)");
            var forceProbe = EvaluateWithFenJsRaw("String(globalThis.__fenWafForceProbe)");
            FenBrowser.Core.EngineLogCompat.Info(
                "[FenJsBridge] Page bootstrap state: " + CoerceToHostString(state) +
                ";checkProbe=" + CoerceToHostString(checkProbe) +
                ";forceProbe=" + CoerceToHostString(forceProbe),
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                "[FenJsBridge] Page bootstrap state probe failed: " + ex.Message,
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    /// <summary>
    /// Execute a batch of scripts (blocking, defer, or async) in document order.
    /// Each script's external fetch is awaited individually; execution errors are
    /// logged but never re-thrown (per WHATWG HTML Â§8.1.3.2).
    /// </summary>
    private async Task ExecuteScriptBatchAsync(
        List<ScriptExecutionItem> batch, Uri baseUri, string batchLabel)
    {
        if (batch.Count == 0) return;

        for (int i = 0; i < batch.Count; i++)
        {
            var item = batch[i];
            string code;
            Uri moduleUri = item.ModuleUri;
            bool isModule = item.IsModule;
            if (string.Equals(batchLabel, "blocking", StringComparison.OrdinalIgnoreCase))
            {
                // The parser would have inserted, and started, every media
                // element before this script by the time the script ran.
                TrackMediaElementsBefore(item.ScriptElement);
            }

            if (!string.Equals(batchLabel, "async", StringComparison.OrdinalIgnoreCase))
            {
                var blockedFields = CreateScriptRecordFields(item.ScriptRecord);
                blockedFields["batch"] = batchLabel;
                blockedFields["blocksDOMContentLoaded"] = true;
                blockedFields["reason"] = string.Equals(batchLabel, "defer", StringComparison.OrdinalIgnoreCase)
                    ? "defer-script-before-domcontentloaded"
                    : "parser-blocking-script";
                LogScriptLoading(
                    "DOMContentLoadedBlockedByScript",
                    LogSeverity.Debug,
                    "[FenJsBridge] Script blocks DOMContentLoaded",
                    blockedFields);
            }

            if (item.FetchKey != null)
            {
                // Await this individual fetch â€” it may already be complete since
                // all fetches were kicked off concurrently in Phase 1.
                try
                {
                    code = await item.FetchTask.ConfigureAwait(false);
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.FetchCompleted++);
                    UpdateScriptLoadingRecord(item.ScriptRecord, record =>
                    {
                        record.CodeLength = code?.Length ?? 0;
                        record.Status = "ready";
                    });
                    var fetchCompletedFields = CreateScriptRecordFields(item.ScriptRecord);
                    fetchCompletedFields["url"] = item.FetchKey;
                    fetchCompletedFields["batch"] = batchLabel;
                    fetchCompletedFields["codeLength"] = code?.Length ?? 0;
                    LogScriptLoading(
                        "ScriptFetchCompleted",
                        LogSeverity.Debug,
                        "[FenJsBridge] External script fetch completed",
                        fetchCompletedFields);
                    var readyFields = CreateScriptRecordFields(item.ScriptRecord);
                    readyFields["url"] = item.FetchKey;
                    readyFields["batch"] = batchLabel;
                    readyFields["codeLength"] = code?.Length ?? 0;
                    LogScriptLoading(
                        "ScriptReady",
                        LogSeverity.Debug,
                        "[FenJsBridge] External script ready",
                        readyFields);
                }
                catch (Exception ex)
                {
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.FetchFailed++);
                    UpdateScriptLoadingRecord(item.ScriptRecord, record =>
                    {
                        record.Status = "fetch-failed";
                        record.Failure = ex.GetType().Name + ": " + ex.Message;
                        record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
                    });
                    FenBrowser.Core.EngineLogCompat.Warn(
                        $"[FenJsBridge] Fetch failed for '{item.FetchKey}' ({batchLabel}): {ex.Message}",
                        FenBrowser.Core.Logging.LogCategory.JavaScript);
                    var fetchFailedFields = CreateScriptRecordFields(item.ScriptRecord);
                    fetchFailedFields["url"] = item.FetchKey;
                    fetchFailedFields["batch"] = batchLabel;
                    fetchFailedFields["errorType"] = ex.GetType().Name;
                    fetchFailedFields["error"] = ex.Message;
                    LogScriptLoading(
                        "ScriptFetchFailed",
                        LogSeverity.Warn,
                        "[FenJsBridge] Fetch failed",
                        fetchFailedFields);
                    continue;
                }
                if (string.IsNullOrWhiteSpace(code))
                {
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.SkippedScripts++);
                    UpdateScriptLoadingRecord(item.ScriptRecord, record =>
                    {
                        record.Status = "skipped";
                        record.Failure = "empty-code";
                        record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
                    });
                    var skippedFields = CreateScriptRecordFields(item.ScriptRecord);
                    skippedFields["url"] = item.FetchKey;
                    skippedFields["batch"] = batchLabel;
                    LogScriptLoading(
                        "ScriptSkipped",
                        LogSeverity.Debug,
                        "[FenJsBridge] Script skipped because fetched code was empty",
                        skippedFields);
                    continue;
                }
            }
            else
            {
                code = item.InlineCode;
            }

            UpdateScriptLoadingSnapshot(snapshot => snapshot.ExecutionStarted++);
            UpdateScriptLoadingRecord(item.ScriptRecord, record =>
            {
                record.Batch = batchLabel;
                record.CodeLength = code?.Length ?? record.CodeLength;
                record.Status = "execution-started";
            });
            var executionStartedFields = CreateScriptRecordFields(item.ScriptRecord);
            executionStartedFields["batch"] = batchLabel;
            executionStartedFields["source"] = item.FetchKey ?? "inline";
            executionStartedFields["isModule"] = isModule;
            executionStartedFields["codeLength"] = code?.Length ?? 0;
            var executionLogSeverity = string.Equals(batchLabel, "async", StringComparison.OrdinalIgnoreCase)
                ? LogSeverity.Info
                : LogSeverity.Debug;
            LogScriptLoading(
                "ScriptExecutionStarted",
                executionLogSeverity,
                "[FenJsBridge] Script execution started",
                executionStartedFields);
            FenBrowser.Core.EngineLogCompat.Info($"[DEBUG] About to call EvaluateWithFenJsRaw for script {item.ScriptRecord.ScriptId} ({item.FetchKey ?? "inline"}) length {code?.Length}", FenBrowser.Core.Logging.LogCategory.JavaScript);
            RunFenJsWithLargeStack<object>(() =>
            {
                try
                {
                    SetCurrentScriptElement(item.ScriptElement, item.ScriptRecord);
                    if (isModule)
                    {
                        EvaluateModuleWithFenJs(code, moduleUri);
                    }
                    else
                    {
                        EvaluateWithFenJsRaw(code);
                    }
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.ExecutionCompleted++);
                    UpdateScriptLoadingRecord(item.ScriptRecord, record =>
                    {
                        record.Status = "executed";
                        record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
                    });
                    var executionCompletedFields = CreateScriptRecordFields(item.ScriptRecord);
                    executionCompletedFields["batch"] = batchLabel;
                    executionCompletedFields["source"] = item.FetchKey ?? "inline";
                    executionCompletedFields["isModule"] = isModule;
                    LogScriptLoading(
                        "ScriptExecutionCompleted",
                        executionLogSeverity,
                        "[FenJsBridge] Script execution completed",
                        executionCompletedFields);
                }
                catch (JsThrownException jte)
                {
                    var desc = jte.Description;
                    if (string.IsNullOrEmpty(desc))
                    {
                        try { desc = _interpreter.DescribeThrownValue(jte.Value); } catch { }
                    }
                    var srcAttr = item.ScriptElement?.GetAttribute("src");
                    var origin = string.IsNullOrEmpty(srcAttr)
                        ? $"inline script (first {Math.Min(code?.Length ?? 0, 120)} chars)"
                        : srcAttr;
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.ExecutionFailed++);
                    UpdateScriptLoadingRecord(item.ScriptRecord, record =>
                    {
                        record.Status = "execution-failed";
                        record.Failure = desc ?? jte.Message ?? string.Empty;
                        record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
                    });
                    RecordMissingGlobalReference(desc ?? jte.Message, item.ScriptRecord, baseUri);
                    ReportFenJsException(jte);
                    var scriptFailedFields = CreateScriptRecordFields(item.ScriptRecord);
                    scriptFailedFields["batch"] = batchLabel;
                    scriptFailedFields["origin"] = origin;
                    scriptFailedFields["errorType"] = "JsThrownException";
                    scriptFailedFields["error"] = desc ?? jte.Message;
                    LogScriptLoading(
                        "ScriptExecutionFailed",
                        LogSeverity.Error,
                        "[FenJsBridge] Script error",
                        scriptFailedFields,
                        LogMarker.EngineBug);
                }
                catch (Exception ex)
                {
                    var srcAttr = item.ScriptElement?.GetAttribute("src");
                    var origin = string.IsNullOrEmpty(srcAttr)
                        ? $"inline script (first {Math.Min(code?.Length ?? 0, 120)} chars)"
                        : srcAttr;
                    UpdateScriptLoadingSnapshot(snapshot => snapshot.ExecutionFailed++);
                    UpdateScriptLoadingRecord(item.ScriptRecord, record =>
                    {
                        record.Status = "execution-failed";
                        record.Failure = ex.GetType().Name + ": " + ex.Message;
                        record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
                    });
                    var scriptFailedFields = CreateScriptRecordFields(item.ScriptRecord);
                    scriptFailedFields["batch"] = batchLabel;
                    scriptFailedFields["origin"] = origin;
                    scriptFailedFields["errorType"] = ex.GetType().Name;
                    scriptFailedFields["error"] = ex.Message;
                    // A JsEngineFatalException is an engine defect, not a page
                    // error, and its message names the broken cell but never the
                    // code that touched it. The managed stack is the only record
                    // of which call dereferenced the handle, and it is gone the
                    // moment this catch returns.
                    if (ex is FenBrowser.Js.Heap.JsEngineFatalException)
                    {
                        scriptFailedFields["engineFatalStack"] = ex.StackTrace ?? "<none>";
                    }
                    LogScriptLoading(
                        "ScriptExecutionFailed",
                        LogSeverity.Error,
                        "[FenJsBridge] Non-JS script error",
                        scriptFailedFields,
                        LogMarker.EngineBug);
                }
                finally
                {
                    if (ShouldCaptureNavigationGlobals() && baseUri != null)
                    {
                        CaptureNavigationGlobals(baseUri, -2000 - i);
                    }
                    SetCurrentScriptElement(null);
                }
                return null;
            });
            FenBrowser.Core.EngineLogCompat.Info($"[DEBUG] Finished EvaluateWithFenJsRaw for script {item.ScriptRecord.ScriptId}", FenBrowser.Core.Logging.LogCategory.JavaScript);
        }

        if (string.Equals(batchLabel, "async", StringComparison.OrdinalIgnoreCase))
        {
            UpdateScriptLoadingSnapshot(snapshot => snapshot.AsyncPendingScripts = Math.Max(0, snapshot.AsyncPendingScripts - batch.Count));
            try
            {
                RequestRender?.Invoke();
                LogScriptLoading(
                    "AsyncScriptBatchRenderRequested",
                    LogSeverity.Debug,
                    "[FenJsBridge] Async script batch requested repaint",
                    new Dictionary<string, object> { ["batch"] = batchLabel, ["count"] = batch.Count });
            }
            catch
            {
                // Repaint requests are best-effort; script execution already completed.
            }
        }
    }

    private void RecordMissingGlobalReference(
        string errorDescription,
        BrowserScriptLoadingRecord scriptRecord = null,
        Uri baseUri = null)
    {
        if (!TryExtractMissingGlobalReference(errorDescription, out var apiName))
        {
            return;
        }

        EngineCapabilities.LogUnsupportedJs("globalThis", apiName, "missing global reference");
        RecordMissingBrowserApi(
            "globalThis",
            apiName,
            "missing global reference",
            errorDescription,
            scriptRecord,
            baseUri);
    }

    private static bool TryExtractMissingGlobalReference(string errorDescription, out string apiName)
    {
        apiName = null;
        if (string.IsNullOrWhiteSpace(errorDescription))
        {
            return false;
        }

        var referencePrefix = "ReferenceError:";
        var prefixIndex = errorDescription.IndexOf(referencePrefix, StringComparison.OrdinalIgnoreCase);
        if (prefixIndex < 0)
        {
            return false;
        }

        var nameStart = prefixIndex + referencePrefix.Length;
        var suffixIndex = errorDescription.IndexOf(" is not defined", nameStart, StringComparison.OrdinalIgnoreCase);
        if (suffixIndex <= nameStart)
        {
            return false;
        }

        var candidate = errorDescription.Substring(nameStart, suffixIndex - nameStart).Trim();
        if (!IsMissingGlobalReferenceName(candidate))
        {
            return false;
        }

        apiName = candidate;
        return true;
    }

    private static bool IsMissingGlobalReferenceName(string candidate)
    {
        if (string.IsNullOrWhiteSpace(candidate))
        {
            return false;
        }

        var first = candidate[0];
        if (!(char.IsLetter(first) || first == '_' || first == '$'))
        {
            return false;
        }

        for (var i = 1; i < candidate.Length; i++)
        {
            var ch = candidate[i];
            if (!(char.IsLetterOrDigit(ch) || ch == '_' || ch == '$'))
            {
                return false;
            }
        }

        return true;
    }

    private void RecordMissingHostProperty(
        object receiver,
        string ownerName,
        string property,
        Uri baseUri,
        bool functionPrototypeMarkerObserved = false,
        MissingApiOperationKind operationKind = MissingApiOperationKind.Read)
    {
        if (receiver != null)
        {
            var reads = _missingHostPropertyReads.GetOrCreateValue(receiver);
            lock (reads)
            {
                reads.Add(property);
            }
        }

        EngineCapabilities.LogUnsupportedJs(ownerName, property, "missing host property");
        RecordMissingBrowserApi(
            ownerName,
            property,
            "missing host property",
            string.Empty,
            GetCurrentScriptRecord(),
            baseUri ?? _currentBaseUri,
            operationKind,
            functionPrototypeMarkerObserved: functionPrototypeMarkerObserved);
    }

    private void RecordHostPropertyAssignment(object receiver, string ownerName, string property, Uri baseUri)
    {
        if (Volatile.Read(ref _suppressMissingHostAssignmentTracking) != 0 ||
            receiver == null ||
            string.IsNullOrWhiteSpace(property))
        {
            return;
        }

        var reads = _missingHostPropertyReads.GetOrCreateValue(receiver);
        bool assignmentBeforeRead;
        lock (reads)
        {
            assignmentBeforeRead = !reads.Contains(property);
        }

        if (GetHostPropertyStore(receiver).ContainsKey(property))
        {
            return;
        }

        RecordMissingBrowserApi(
            ownerName,
            property,
            assignmentBeforeRead
                ? "host property assigned before read"
                : "host property assigned after read",
            string.Empty,
            GetCurrentScriptRecord(),
            baseUri ?? _currentBaseUri,
            MissingApiOperationKind.Write,
            assignmentBeforeRead,
            assignmentObserved: true);
    }

    private void RecordMissingBrowserApi(
        string objectOrPrototype,
        string propertyName,
        string reason,
        string exceptionText,
        BrowserScriptLoadingRecord scriptRecord,
        Uri baseUri,
        MissingApiOperationKind operationKind = MissingApiOperationKind.Read,
        bool assignmentBeforeRead = false,
        bool assignmentObserved = false,
        bool functionPrototypeMarkerObserved = false,
        bool descriptorTargetIsPrototype = false)
    {
        if (string.IsNullOrWhiteSpace(objectOrPrototype) || string.IsNullOrWhiteSpace(propertyName))
        {
            return;
        }

        scriptRecord ??= GetCurrentScriptRecord();
        var currentScriptElement = scriptRecord == null ? GetCurrentScriptElement() : null;
        var siteUri = baseUri ?? _currentBaseUri;
        var scriptUrl = ResolveMissingApiScriptUrl(scriptRecord, currentScriptElement, siteUri);
        var line = NormalizeSourcePosition(scriptRecord?.SourceLine ?? currentScriptElement?.SourceLine ?? 0);
        var column = NormalizeSourcePosition(scriptRecord?.SourceColumn ?? currentScriptElement?.SourceColumn ?? 0);
        var ownerName = objectOrPrototype.Trim();
        var property = propertyName.Trim();

        MissingApiTracker.Record(new MissingApiObservation
        {
            ApiName = ownerName + "." + property,
            ObjectOrPrototype = ownerName,
            PropertyName = property,
            SiteUrl = siteUri?.AbsoluteUri ?? string.Empty,
            ScriptUrl = scriptUrl,
            ScriptId = scriptRecord?.ScriptId ?? string.Empty,
            NavigationId = _currentNavigationId ?? LogContext.CurrentCorrelationId ?? string.Empty,
            Line = line,
            Column = column,
            Reason = reason ?? string.Empty,
            ExceptionText = exceptionText ?? string.Empty,
            OperationKind = operationKind,
            ReceiverType = ownerName,
            AssignmentBeforeRead = assignmentBeforeRead,
            AssignmentObserved = assignmentObserved,
            FunctionPrototypeMarkerObserved = functionPrototypeMarkerObserved,
            DescriptorTargetIsPrototype = descriptorTargetIsPrototype
        });
    }

    private static int? NormalizeSourcePosition(int value)
        => value > 0 ? value : null;

    private static string ResolveMissingApiScriptUrl(
        BrowserScriptLoadingRecord scriptRecord,
        Element scriptElement,
        Uri baseUri)
    {
        if (!string.IsNullOrWhiteSpace(scriptRecord?.ResolvedUrl))
        {
            return scriptRecord.ResolvedUrl;
        }

        var src = !string.IsNullOrWhiteSpace(scriptRecord?.Src)
            ? scriptRecord.Src
            : scriptElement?.GetAttribute("src");
        if (!string.IsNullOrWhiteSpace(src) &&
            TryResolveUri(src, baseUri, out var scriptUri))
        {
            return scriptUri.AbsoluteUri;
        }

        if (Uri.TryCreate(src, UriKind.Absolute, out var absoluteScriptUri))
        {
            return absoluteScriptUri.AbsoluteUri;
        }

        return string.Empty;
    }

    private sealed class ScriptExecutionItem
    {
        public readonly Element ScriptElement;
        public readonly bool IsModule;
        public readonly bool IsAsync;           // async attribute (external scripts only per spec)
        public readonly bool IsDefer;           // defer attribute (external scripts only per spec)
        public readonly string FetchKey;        // non-null for external scripts
        public readonly Task<string> FetchTask; // non-null for external scripts
        public readonly Uri ModuleUri;          // non-null for external scripts
        public readonly string InlineCode;      // non-null for inline scripts
        public readonly BrowserScriptLoadingRecord ScriptRecord;

        public ScriptExecutionItem(Element scriptElement, bool isModule, bool isAsync, bool isDefer,
            string fetchKey, Task<string> fetchTask, Uri moduleUri, string inlineCode,
            BrowserScriptLoadingRecord scriptRecord)
        {
            ScriptElement = scriptElement;
            IsModule = isModule;
            IsAsync = isAsync;
            IsDefer = isDefer;
            FetchKey = fetchKey;
            FetchTask = fetchTask;
            ModuleUri = moduleUri;
            InlineCode = inlineCode;
            ScriptRecord = scriptRecord;
        }
    }

    private async Task<string> FetchModuleTextAsync(Uri uri)
    {
        if (uri == null) return string.Empty;
        try
        {
            if (ExternalScriptFetcher != null)
            {
                return await ExternalScriptFetcher(uri, _currentBaseUri).ConfigureAwait(false) ?? string.Empty;
            }
            if (FetchOverride != null)
            {
                return await FetchOverride(uri).ConfigureAwait(false) ?? string.Empty;
            }
            if (FetchHandler != null)
            {
                using var request = new System.Net.Http.HttpRequestMessage(System.Net.Http.HttpMethod.Get, uri);
                request.Headers.TryAddWithoutValidation("Sec-Fetch-Dest", "script");
                request.Headers.TryAddWithoutValidation("Sec-Fetch-Mode", "no-cors");
                if (_currentBaseUri != null)
                {
                    request.Headers.Referrer = _currentBaseUri;
                    if (!CorsHandler.IsSameOrigin(uri, _currentBaseUri))
                    {
                        var origin = CorsHandler.SerializeOrigin(new UriBuilder(
                            _currentBaseUri.Scheme,
                            _currentBaseUri.Host,
                            _currentBaseUri.IsDefaultPort ? -1 : _currentBaseUri.Port).Uri);
                        if (!string.IsNullOrWhiteSpace(origin))
                        {
                            request.Headers.TryAddWithoutValidation("Origin", origin);
                        }
                    }
                }
                using var response = await FetchHandler(request).ConfigureAwait(false);
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadAsStringAsync().ConfigureAwait(false) ?? string.Empty;
            }
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn($"[FenJsBridge] FetchModuleText failed for '{uri}': {ex.Message}", FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
        return string.Empty;
    }

    /// <summary>
    /// HTML "resolve a module specifier": a URL-like specifier (absolute, or
    /// starting with "/", "./" or "../") resolves against the requesting module -
    /// or the document base for the inline entry module - and the import map may
    /// still remap the resulting URL; a bare specifier ("react") resolves only
    /// through the import map. A bare specifier no map entry covers is resolved as
    /// a relative URL, which fails at fetch time the way the spec's TypeError would.
    /// </summary>
    private Uri ResolveModuleRequestUri(string specifier, string referrer, Uri moduleBase)
    {
        Uri baseUri = Uri.TryCreate(referrer, UriKind.Absolute, out var referrerUri) ? referrerUri : moduleBase;
        Uri asUrl = ImportMap.ParseUrlLikeSpecifier(specifier, baseUri);
        if (_importMap.TryResolve(specifier, asUrl, baseUri, out var mapped))
        {
            return mapped;
        }
        if (asUrl != null)
        {
            return asUrl;
        }
        return baseUri != null && Uri.TryCreate(baseUri, specifier, out var relativeToBase)
            ? relativeToBase
            : null;
    }

    /// <summary>
    /// HTML 8.1.6.2.2 "register an import map": parse the JSON of a
    /// &lt;script type=importmap&gt;, normalise its keys and values against the
    /// document base, and merge it into the document's import map.
    /// </summary>
    private void RegisterImportMapScript(Element scriptElement)
    {
        var text = scriptElement?.TextContent;
        if (string.IsNullOrWhiteSpace(text) || !string.IsNullOrEmpty(scriptElement.GetAttribute("src")))
        {
            return;
        }

        try
        {
            _importMap.Merge(text, _currentBaseUri);
        }
        catch (JsonException ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] Ignoring malformed import map: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    /// <summary>
    /// HTML 8.1.6.2 import map: top-level "imports" plus "scopes", each a specifier
    /// map whose keys are bare specifiers or normalised URLs. Keys ending in "/"
    /// are package prefixes and remap everything below them.
    /// </summary>
    private sealed class ImportMap
    {
        private readonly Dictionary<string, Uri> _imports = new(StringComparer.Ordinal);
        private readonly List<KeyValuePair<string, Dictionary<string, Uri>>> _scopes = new();

        public void Clear()
        {
            _imports.Clear();
            _scopes.Clear();
        }

        /// <summary>
        /// A specifier is URL-like when it parses as an absolute URL or starts with
        /// "/", "./" or "../"; only those resolve against a base.
        /// </summary>
        public static Uri ParseUrlLikeSpecifier(string specifier, Uri baseUri)
        {
            if (string.IsNullOrEmpty(specifier))
            {
                return null;
            }

            if (specifier.StartsWith("/", StringComparison.Ordinal) ||
                specifier.StartsWith("./", StringComparison.Ordinal) ||
                specifier.StartsWith("../", StringComparison.Ordinal))
            {
                return baseUri != null && Uri.TryCreate(baseUri, specifier, out var relative) ? relative : null;
            }

            return Uri.TryCreate(specifier, UriKind.Absolute, out var absolute) && absolute.Scheme.Length > 1
                ? absolute
                : null;
        }

        /// <summary>
        /// "Merge existing and new import maps": later maps add entries; an entry an
        /// earlier map already has keeps the earlier value.
        /// </summary>
        public void Merge(string json, Uri baseUri)
        {
            using var document = JsonDocument.Parse(json);
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                return;
            }

            if (root.TryGetProperty("imports", out var imports) && imports.ValueKind == JsonValueKind.Object)
            {
                foreach (var entry in NormalizeSpecifierMap(imports, baseUri))
                {
                    _imports.TryAdd(entry.Key, entry.Value);
                }
            }

            if (root.TryGetProperty("scopes", out var scopes) && scopes.ValueKind == JsonValueKind.Object)
            {
                foreach (var scope in scopes.EnumerateObject())
                {
                    if (scope.Value.ValueKind != JsonValueKind.Object ||
                        !Uri.TryCreate(baseUri, scope.Name, out var scopeUri))
                    {
                        continue;
                    }

                    var key = scopeUri.AbsoluteUri;
                    var index = _scopes.FindIndex(existing => string.Equals(existing.Key, key, StringComparison.Ordinal));
                    var map = index >= 0 ? _scopes[index].Value : new Dictionary<string, Uri>(StringComparer.Ordinal);
                    foreach (var entry in NormalizeSpecifierMap(scope.Value, baseUri))
                    {
                        map.TryAdd(entry.Key, entry.Value);
                    }
                    if (index < 0)
                    {
                        _scopes.Add(new KeyValuePair<string, Dictionary<string, Uri>>(key, map));
                        // Longest (most specific) scope first.
                        _scopes.Sort((a, b) => b.Key.Length.CompareTo(a.Key.Length));
                    }
                }
            }
        }

        /// <summary>
        /// "Sort and normalize a module specifier map": URL-like keys and every value
        /// resolve against the base; a "/"-ending key needs a "/"-ending value.
        /// </summary>
        private static IEnumerable<KeyValuePair<string, Uri>> NormalizeSpecifierMap(JsonElement map, Uri baseUri)
        {
            foreach (var property in map.EnumerateObject())
            {
                if (property.Name.Length == 0 || property.Value.ValueKind != JsonValueKind.String)
                {
                    continue;
                }

                var key = ParseUrlLikeSpecifier(property.Name, baseUri)?.AbsoluteUri ?? property.Name;
                var value = property.Value.GetString();
                var valueUri = ParseUrlLikeSpecifier(value, baseUri);
                if (valueUri == null ||
                    (key.EndsWith("/", StringComparison.Ordinal) && !valueUri.AbsoluteUri.EndsWith("/", StringComparison.Ordinal)))
                {
                    continue;
                }

                yield return new KeyValuePair<string, Uri>(key, valueUri);
            }
        }

        /// <summary>
        /// "Resolve a module specifier" steps 6-10: the most specific scope whose
        /// prefix covers the referrer is consulted first, then the top-level imports.
        /// </summary>
        public bool TryResolve(string specifier, Uri asUrl, Uri referrerBase, out Uri resolved)
        {
            resolved = null;
            if (_imports.Count == 0 && _scopes.Count == 0)
            {
                return false;
            }

            var normalized = asUrl?.AbsoluteUri ?? specifier;
            if (referrerBase != null)
            {
                var referrerKey = referrerBase.AbsoluteUri;
                foreach (var scope in _scopes)
                {
                    bool covers = string.Equals(scope.Key, referrerKey, StringComparison.Ordinal) ||
                                  (scope.Key.EndsWith("/", StringComparison.Ordinal) &&
                                   referrerKey.StartsWith(scope.Key, StringComparison.Ordinal));
                    if (covers && TryResolveImportsMatch(normalized, scope.Value, out resolved))
                    {
                        return true;
                    }
                }
            }

            return TryResolveImportsMatch(normalized, _imports, out resolved);
        }

        /// <summary>
        /// "Resolve an imports match": an exact key wins; otherwise the longest
        /// "/"-ending key that prefixes the specifier maps the remainder under its value.
        /// </summary>
        private static bool TryResolveImportsMatch(string normalized, Dictionary<string, Uri> map, out Uri resolved)
        {
            resolved = null;
            if (map.TryGetValue(normalized, out var exact))
            {
                resolved = exact;
                return true;
            }

            string bestKey = null;
            foreach (var key in map.Keys)
            {
                if (key.EndsWith("/", StringComparison.Ordinal) &&
                    normalized.StartsWith(key, StringComparison.Ordinal) &&
                    (bestKey == null || key.Length > bestKey.Length))
                {
                    bestKey = key;
                }
            }

            if (bestKey == null)
            {
                return false;
            }

            var remainder = normalized.Substring(bestKey.Length);
            var prefix = map[bestKey];
            if (!Uri.TryCreate(prefix, remainder, out var candidate) ||
                !candidate.AbsoluteUri.StartsWith(prefix.AbsoluteUri, StringComparison.Ordinal))
            {
                return false;
            }

            resolved = candidate;
            return true;
        }
    }

    // Upper bound on in-flight module fetches during graph prefetch. Browsers issue
    // every request of a level at once; the cap only keeps a huge graph from opening
    // an unbounded number of connections against an HTTP/1.1 origin.
    private const int ModuleGraphPrefetchConcurrency = 16;

    /// <summary>
    /// HTML "fetch the descendants of a module script": walk the static import graph,
    /// scheduling every request of a module the moment that module's source arrives,
    /// so independent branches of the graph are in flight together and the critical
    /// path is the graph's depth, not its size. Sources land in the per-document
    /// module source cache, where the evaluator's synchronous resolver finds them
    /// instead of paying one blocking round-trip per import.
    /// </summary>
    private async Task PrefetchModuleGraphAsync(string entrySpecifier, string entryCode, Uri moduleBase)
    {
        var sync = new object();
        var scheduled = new HashSet<string>(StringComparer.Ordinal);
        var pending = new List<Task>();
        using var gate = new System.Threading.SemaphoreSlim(ModuleGraphPrefetchConcurrency);

        void Schedule(string referrer, string specifier)
        {
            var uri = ResolveModuleRequestUri(specifier, referrer, moduleBase);
            if (uri == null) return;
            var key = uri.AbsoluteUri;
            lock (sync)
            {
                if (_moduleSourceCache.ContainsKey(key) || !scheduled.Add(key)) return;
            }
            if (SubresourceAllowed != null && !SubresourceAllowed(uri, "script")) return;
            var visit = VisitAsync(uri, key);
            lock (sync)
            {
                pending.Add(visit);
            }
        }

        async Task VisitAsync(Uri uri, string key)
        {
            string source;
            await gate.WaitAsync().ConfigureAwait(false);
            try
            {
                source = await FetchModuleTextAsync(uri).ConfigureAwait(false);
            }
            finally
            {
                gate.Release();
            }
            _moduleSourceCache[key] = source;
            if (source.Length == 0) return;
            foreach (var request in FenBrowser.Js.Modules.ModuleEvaluator.CollectModuleRequests(source))
            {
                Schedule(key, request);
            }
        }

        foreach (var request in FenBrowser.Js.Modules.ModuleEvaluator.CollectModuleRequests(entryCode))
        {
            Schedule(entrySpecifier, request);
        }

        // Visits append to `pending` as they discover imports; drain until a full
        // pass completes with nothing new in flight.
        while (true)
        {
            Task[] inFlight;
            lock (sync)
            {
                pending.RemoveAll(t => t.IsCompleted);
                if (pending.Count == 0) return;
                inFlight = pending.ToArray();
            }
            await Task.WhenAll(inFlight).ConfigureAwait(false);
        }
    }

    /// <summary>
    /// Parse and execute a script in ES module goal (allowing import/export syntax).
    /// Uses ModuleEvaluator to resolve, link, rewrite, and evaluate module dependencies recursively.
    /// </summary>
    private void EvaluateModuleWithFenJs(string code, Uri moduleUri = null)
    {
        Uri moduleBase = moduleUri ?? _currentBaseUri;
        // Inline module scripts get a unique key each: they are distinct modules
        // even when several appear on one page, unlike an external URL, which the
        // module map evaluates once regardless of how many tags or imports name it.
        string entrySpecifier = moduleUri?.AbsoluteUri
            ?? $"<inline-module-{Interlocked.Increment(ref _inlineModuleCounter)}>";
        // Fetch the whole static graph before taking the engine lock: the evaluator
        // below resolves imports synchronously, so anything not prefetched costs a
        // blocking round-trip per import while the engine is held.
        PrefetchModuleGraphAsync(entrySpecifier, code, moduleBase).GetAwaiter().GetResult();

        RunFenJsWithLargeStack<object>(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                _fenJsEvaluationCount++;
                var evaluator = _moduleEvaluator ??= CreateModuleEvaluator();
                evaluator.RegisterSource(entrySpecifier, code);
                evaluator.Evaluate(entrySpecifier);
                return null;
            }
        });
    }

    private async Task<string> FetchModuleScriptGraphAsync(Uri scriptUri, Task<string> fetch)
    {
        var code = await fetch.ConfigureAwait(false);
        if (!string.IsNullOrEmpty(code))
        {
            await PrefetchModuleGraphAsync(scriptUri.AbsoluteUri, code, scriptUri).ConfigureAwait(false);
        }
        return code;
    }

    /// <summary>
    /// The per-document module evaluator. Its resolver serves sources from the
    /// module source cache and falls back to a blocking fetch for anything the
    /// prefetch did not reach (dynamic import() of a URL not statically imported).
    /// </summary>
    private FenBrowser.Js.Modules.ModuleEvaluator CreateModuleEvaluator()
    {
        var evaluator = new FenBrowser.Js.Modules.ModuleEvaluator(_interpreter, hostSourceResolver: specifier =>
        {
            var resolvedUri = ResolveModuleRequestUri(specifier, referrer: null, _currentBaseUri);
            if (resolvedUri == null)
            {
                return null;
            }
            if (SubresourceAllowed != null && !SubresourceAllowed(resolvedUri, "script"))
            {
                return null;
            }
            // Reads the cache and nothing else. This runs on the FenJS worker, which
            // is the one thread that also drains the input queue, so a miss must not
            // turn into a fetch: it means no loader has run for this module yet, and
            // reporting it as unresolved is how that bug stays visible instead of
            // becoming a network round-trip that freezes the page.
            return _moduleSourceCache.TryGetValue(resolvedUri.AbsoluteUri, out var cachedSource)
                ? cachedSource
                : null;
        },
        hostSpecifierResolver: (specifier, referrer) =>
        {
            // Answer only what HTML resolves: an import-map match or a URL-like
            // specifier. Anything else (an inline entry module's synthetic key,
            // a bare specifier with no map) is left to the evaluator's own rules.
            Uri baseUri = Uri.TryCreate(referrer, UriKind.Absolute, out var referrerUri) ? referrerUri : _currentBaseUri;
            Uri asUrl = ImportMap.ParseUrlLikeSpecifier(specifier, baseUri);
            return _importMap.TryResolve(specifier, asUrl, baseUri, out var mapped)
                ? mapped.AbsoluteUri
                : asUrl?.AbsoluteUri;
        });

        // ECMA-262 16.2.1.8 HostLoadImportedModule. Installed after construction
        // because ModuleEvaluator's constructor claims the synchronous hook for
        // itself, and this one takes precedence over that.
        _interpreter.DynamicImportLoader = StartDynamicModuleImport;
        return evaluator;
    }

    /// <summary>
    /// Loads a dynamically imported module and settles <paramref name="capability"/>
    /// when it is ready. Returns as soon as the fetch is scheduled, so the worker
    /// goes back to its queue instead of holding the page still for a round-trip -
    /// a page whose chunks all arrive through import(), as a rolldown or Vite build's
    /// do, otherwise spends its whole load unable to answer a click.
    /// </summary>
    private void StartDynamicModuleImport(string specifier, string referrerUrl, PromiseCapability capability)
    {
        Uri referrerBase = Uri.TryCreate(referrerUrl, UriKind.Absolute, out var parsedReferrer)
            ? parsedReferrer
            : _currentBaseUri;
        var resolvedUri = ResolveModuleRequestUri(specifier, referrerUrl, referrerBase);

        // The capability is three heap objects the JS side no longer references -
        // the promise is pending and its resolvers are held only here - so without a
        // pin a collection before it settles would sweep them.
        var pin = PinFenJsValues(capability.Promise, capability.Resolve, capability.Reject);

        // Every path settles from the delivery tail, never inline. This runs inside
        // the import() that is still executing, and settling here would pump that
        // script's microtasks in the middle of its own evaluation.
        void Settle(string failure) => QueueOnDeliveryTail(
            () =>
            {
                try
                {
                    SettleDynamicModuleImport(capability, specifier, referrerUrl, failure);
                }
                finally
                {
                    pin?.Dispose();
                }
            },
            $"import('{specifier}') completion failed");

        if (resolvedUri == null)
        {
            Settle($"Failed to resolve module specifier '{specifier}'.");
            return;
        }

        if (SubresourceAllowed != null && !SubresourceAllowed(resolvedUri, "script"))
        {
            Settle($"Refused to load the module '{resolvedUri}'.");
            return;
        }

        _ = Task.Run(async () =>
        {
            string failure = null;
            try
            {
                await LoadModuleGraphAsync(resolvedUri).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                FenBrowser.Core.EngineLogCompat.Warn(
                    $"[FenJsBridge] import('{specifier}') could not load '{resolvedUri}': {ex.Message}",
                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                failure = $"Failed to fetch the module '{resolvedUri}': {ex.Message}";
            }

            Settle(failure);
        });
    }

    /// <summary>
    /// Evaluates an imported module whose source is already cached and settles the
    /// capability with its namespace, or rejects it. Runs on the FenJS worker: every
    /// source it needs was fetched before this was queued, so the evaluation the
    /// synchronous resolver performs here reads memory and never the network.
    /// </summary>
    private void SettleDynamicModuleImport(
        PromiseCapability capability,
        string specifier,
        string referrerUrl,
        string failure)
    {
        if (!capability.IsComplete)
        {
            return;
        }

        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            try
            {
                if (failure != null)
                {
                    RejectDynamicModuleImport(capability, failure);
                    return;
                }

                var resolver = _interpreter.DynamicImportResolver;
                if (resolver == null)
                {
                    RejectDynamicModuleImport(capability, $"No module evaluator for '{specifier}'.");
                    return;
                }

                // The referrer decides what a relative specifier resolves against,
                // so it has to survive the trip through the fetch: a chunk that
                // imports "./b.js" means the one beside itself, not beside the page.
                var moduleNamespace = resolver(specifier, referrerUrl);
                _interpreter.InvokeFunction(
                    capability.Resolve,
                    new[] { moduleNamespace },
                    JsValue.Undefined);
            }
            catch (FenBrowser.Js.Interpreter.JsThrownException thrown)
            {
                // A module that throws while evaluating rejects the import promise
                // with the thrown value, not with a host-built error.
                _interpreter.InvokeFunction(
                    capability.Reject,
                    new[] { thrown.Value },
                    JsValue.Undefined);
            }
            catch (Exception ex)
            {
                RejectDynamicModuleImport(capability, ex.Message);
            }
            finally
            {
                _interpreter.PumpMicrotasks();
            }
        }
    }

    private void RejectDynamicModuleImport(PromiseCapability capability, string message)
    {
        _interpreter.InvokeFunction(
            capability.Reject,
            new[] { _interpreter.CreateTypeErrorValue(message) },
            JsValue.Undefined);
    }

    /// <summary>
    /// Fetches a module and everything it statically imports into the source cache.
    /// The one loader in the engine: static graphs go through
    /// <see cref="PrefetchModuleGraphAsync"/> at discovery time and dynamic imports
    /// come here, so nothing ever fetches a module from the FenJS worker thread.
    /// </summary>
    private async Task LoadModuleGraphAsync(Uri uri)
    {
        var key = uri.AbsoluteUri;
        if (_moduleSourceCache.ContainsKey(key))
        {
            return;
        }

        var source = await FetchModuleTextAsync(uri).ConfigureAwait(false);
        _moduleSourceCache[key] = source;
        if (source.Length == 0)
        {
            return;
        }

        await PrefetchModuleGraphAsync(key, source, uri).ConfigureAwait(false);
    }

    private async Task<string> FetchExternalPageScriptAsync(Uri scriptUri, Uri referer, string cspNonce = null)
    {
        if (scriptUri == null)
        {
            return null;
        }

        string code = null;

        if (ExternalScriptFetcherWithNonce != null)
        {
            code = await ExternalScriptFetcherWithNonce(scriptUri, referer, cspNonce).ConfigureAwait(false);
            FenBrowser.Core.EngineLogCompat.Info($"[FenJsBridge] ExternalScriptFetcherWithNonce result for '{scriptUri}': len={code?.Length ?? -1}", FenBrowser.Core.Logging.LogCategory.JavaScript);
            return code;
        }

        if (ExternalScriptFetcher != null)
        {
            code = await ExternalScriptFetcher(scriptUri, referer).ConfigureAwait(false);
            FenBrowser.Core.EngineLogCompat.Info($"[FenJsBridge] ExternalScriptFetcher result for '{scriptUri}': len={code?.Length ?? -1}", FenBrowser.Core.Logging.LogCategory.JavaScript);
            return code;
        }

        if (FetchOverride != null)
        {
            code = await FetchOverride(scriptUri).ConfigureAwait(false);
            FenBrowser.Core.EngineLogCompat.Info($"[FenJsBridge] FetchOverride result for '{scriptUri}': len={code?.Length ?? -1}", FenBrowser.Core.Logging.LogCategory.JavaScript);
            return code;
        }

        if (FetchHandler == null)
        {
            FenBrowser.Core.EngineLogCompat.Warn($"[FenJsBridge] FetchHandler is null, cannot fetch script: {scriptUri}", FenBrowser.Core.Logging.LogCategory.JavaScript);
            return null;
        }

        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, scriptUri);
            request.Headers.TryAddWithoutValidation("Sec-Fetch-Dest", "script");
            request.Headers.TryAddWithoutValidation("Sec-Fetch-Mode", "no-cors");
            if (referer != null)
            {
                request.Headers.Referrer = referer;
                if (!CorsHandler.IsSameOrigin(scriptUri, referer))
                {
                    var origin = CorsHandler.SerializeOrigin(new UriBuilder(
                        referer.Scheme,
                        referer.Host,
                        referer.IsDefaultPort ? -1 : referer.Port).Uri);
                    if (!string.IsNullOrWhiteSpace(origin))
                    {
                        request.Headers.TryAddWithoutValidation("Origin", origin);
                    }
                }
            }

            using var response = await FetchHandler(request).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();
            code = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
            FenBrowser.Core.EngineLogCompat.Info($"[FenJsBridge] FetchHandler result for '{scriptUri}': HTTP {response.StatusCode}, len={code?.Length ?? -1}", FenBrowser.Core.Logging.LogCategory.JavaScript);
            return code;
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn($"[FenJsBridge] FetchExternalPageScriptAsync failed for '{scriptUri}': {ex.Message}", FenBrowser.Core.Logging.LogCategory.JavaScript);
            return null;
        }
    }

    // HTML "destroy a child navigable": when an iframe leaves the tree its
    // nested browsing context is discarded, so the frame's scripts, timers and
    // pending tasks stop. Without this a timed-out or replaced widget keeps its
    // realm running forever on its own worker thread — observed on
    // google.com/recaptcha, where reCAPTCHA's own anchor-ms/execute-ms deadlines
    // expire, it rebuilds the widget, and every abandoned copy keeps burning the
    // CPU the replacement needs, so the page can never recover.
    internal void AbandonRealm()
    {
        if (_realmAbandoned)
        {
            return;
        }

        // Set first and unlocked: this is what aborts a script already running on
        // the worker thread (via InterruptCallback), so the worker can reach a
        // safe point and drop _fenJsLock before the teardown below needs it.
        _realmAbandoned = true;
        UnsubscribeFrameTeardownObserver();
        UnsubscribeAttributeReactionObserver();
        UnsubscribeImageLoadObserver();
        UnsubscribeLinkLoadObserver();
        UnsubscribeObjectLoadObserver();
        UnsubscribeMediaElementObserver();

        foreach (var childRealm in DetachFrameRealms())
        {
            childRealm.AbandonRealm();
        }

        _fenJsWorkerRunning = false;
        try { _fenJsWorkAvailable.Set(); }
        catch (ObjectDisposedException) { }

        DrainAbandonedWorkQueue(_fenJsInputWorkQueue);
        DrainAbandonedWorkQueue(_fenJsWorkQueue);

        try
        {
            ReleaseRealmResources();
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] AbandonRealm cleanup failed: {ex.GetType().Name}: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    // Unblock anything already waiting on queued work. A null result is the
    // signal callers already understand for "the session went away".
    private static void DrainAbandonedWorkQueue(ConcurrentQueue<FenJsWorkItem> queue)
    {
        while (queue.TryDequeue(out var pending))
        {
            pending.Completion.TrySetResult(null);
        }
    }

    // Node.OnMutation is process-wide, so the handler must stay cheap and must
    // only ever act on frames this realm actually owns: the _iframeRealms lookup
    // is the ownership check, and _frameRealmCount short-circuits pages that
    // have no frames at all.
    private int _frameRealmCount;
    private bool _frameTeardownObserverSubscribed;

    private void EnsureFrameTeardownObserver()
    {
        if (_frameTeardownObserverSubscribed)
        {
            return;
        }

        _frameTeardownObserverSubscribed = true;
        Node.OnMutation += OnDomMutationForFrameTeardown;
    }

    private bool _attributeReactionObserverSubscribed;

    private void EnsureAttributeReactionObserver()
    {
        if (_attributeReactionObserverSubscribed)
        {
            return;
        }

        _attributeReactionObserverSubscribed = true;
        Node.OnAttributeChanged += OnDomAttributeChangedForCustomElements;
    }

    private void UnsubscribeAttributeReactionObserver()
    {
        if (!_attributeReactionObserverSubscribed)
        {
            return;
        }

        _attributeReactionObserverSubscribed = false;
        Node.OnAttributeChanged -= OnDomAttributeChangedForCustomElements;
    }

    // Node.OnAttributeChanged is process-wide and fires for every attribute
    // write on every document, so the filter here has to be cheap and exact:
    // only this realm's document, only elements a definition could apply to,
    // and only from the script thread -- a parser or layout thread must never
    // re-enter the interpreter.
    private void OnDomAttributeChangedForCustomElements(
        Element element,
        string attributeName,
        string attributeNamespace,
        string oldValue,
        string newValue)
    {
        if (!_onFenJsLargeStackThread || _interpreter == null || _realmAbandoned || element == null)
        {
            return;
        }

        var localName = element.LocalName;
        if (string.IsNullOrEmpty(localName) ||
            (localName.IndexOf('-') < 0 && !element.HasAttribute("is")))
        {
            return;
        }

        var document = _currentDomRoot as Document ?? _currentDomRoot?.OwnerDocument;
        if (document == null || !ReferenceEquals(element.OwnerDocument, document))
        {
            return;
        }

        if (!_interpreter.TryReadGlobalValue("__fenCustomElementAttributeChanged", out var hook) ||
            !_interpreter.CanCallValue(hook))
        {
            return;
        }

        try
        {
            _ = _interpreter.InvokeFunction(
                hook,
                new[]
                {
                    ToHostNodeOrNull(element),
                    JsValue.FromString(attributeName),
                    oldValue == null ? JsValue.Null : JsValue.FromString(oldValue),
                    newValue == null ? JsValue.Null : JsValue.FromString(newValue),
                    attributeNamespace == null ? JsValue.Null : JsValue.FromString(attributeNamespace)
                },
                JsValue.Undefined);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] attributeChangedCallback dispatch failed for <{localName} {attributeName}>: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    private void UnsubscribeFrameTeardownObserver()
    {
        if (!_frameTeardownObserverSubscribed)
        {
            return;
        }

        _frameTeardownObserverSubscribed = false;
        Node.OnMutation -= OnDomMutationForFrameTeardown;
    }

    private void OnDomMutationForFrameTeardown(
        Node target,
        string type,
        string attributeName,
        string attributeNamespace,
        List<Node> addedNodes,
        List<Node> removedNodes)
    {
        if (Volatile.Read(ref _frameRealmCount) == 0 ||
            removedNodes == null ||
            removedNodes.Count == 0 ||
            !string.Equals(type, "childList", StringComparison.Ordinal))
        {
            return;
        }

        for (var i = 0; i < removedNodes.Count; i++)
        {
            AbandonRealmsInDetachedSubtree(removedNodes[i]);
        }
    }

    // The removed node may be the frame itself or an ancestor of one.
    private void AbandonRealmsInDetachedSubtree(Node removed)
    {
        if (removed == null)
        {
            return;
        }

        try
        {
            if (removed is Element removedElement)
            {
                AbandonRealmForFrameElement(removedElement);
            }

            foreach (var descendant in removed.Descendants())
            {
                if (descendant is Element descendantElement)
                {
                    AbandonRealmForFrameElement(descendantElement);
                }
            }
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] Frame teardown walk failed: {ex.GetType().Name}: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    private void AbandonRealmForFrameElement(Element element)
    {
        if (!IsIFrameElement(element))
        {
            return;
        }

        FenJsBrowserScriptEngine realm;
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            if (!_iframeRealms.TryGetValue(element, out realm))
            {
                return;
            }

            _iframeRealms.Remove(element);
            Interlocked.Decrement(ref _frameRealmCount);
        }

        FenBrowser.Core.EngineLogCompat.Info(
            "[FenJsBridge] iframe detached - abandoning its realm",
            FenBrowser.Core.Logging.LogCategory.JavaScript);
        realm.AbandonRealm();
    }

    private FenJsBrowserScriptEngine[] DetachFrameRealms()
    {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            var realms = _iframeRealms
                .Select(entry => entry.Value)
                .Distinct()
                .ToArray();
            _iframeRealms = new ConditionalWeakTable<Element, FenJsBrowserScriptEngine>();
            Interlocked.Exchange(ref _frameRealmCount, 0);
            return realms;
        }
    }

    private void ReleaseRealmResources()
    {
        foreach (var frameRealm in DetachFrameRealms())
        {
            frameRealm.AbandonRealm();
        }

        CloseAllWebAudioContexts();

        Interlocked.Increment(ref _fenJsSessionGeneration);
        RequestRender = null;
        _parentRealmOwner = null;
        _embeddingFrameElement = null;
        CloseOwnedMessagePorts();

        foreach (var timerEntry in _fenJsTimers.ToArray())
        {
            if (_fenJsTimers.TryRemove(timerEntry.Key, out var timer))
            {
                timer.Dispose();
            }
        }

        lock (_webSocketHosts)
        {
            foreach (var (_, host) in _webSocketHosts)
            {
                try { host.Close(1001, "Navigation"); } catch { }
                try { host.Dispose(); } catch { }
            }
            _webSocketHosts.Clear();
        }
    }

    private void CloseOwnedMessagePorts()
    {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            foreach (var endpoint in _messagePortEndpoints.Values.Distinct())
            {
                endpoint.Closed = true;
                endpoint.Owner = null;
                endpoint.Port = JsValue.Undefined;
            }
            _messagePortEndpoints.Clear();
        }
    }

    /// <summary>
    /// A dedicated worker: the realm it runs in, the page-side object its
    /// replies are delivered to, and the script it was started from.
    /// </summary>
    private sealed class DedicatedWorkerInstance
    {
        public int Id;
        public FenJsBrowserScriptEngine Realm;
        public JsValue PageObject;
        public Uri ScriptUri;
        public bool Terminated;

        /// <summary>
        /// Serializes this worker's start-up and every message after it, so a
        /// page that posts straight after new Worker() is not racing the script
        /// it is posting to.
        /// </summary>
        public Task Tail = Task.CompletedTask;
        public readonly object TailGate = new();

        /// <summary>
        /// Worker script runs on its own large-stack thread, and a log call made
        /// from there does not reach the sink. Anything the worker has to say
        /// waits here until the worker's task drains it.
        /// </summary>
        public readonly ConcurrentQueue<string> Diagnostics = new();
    }

    private readonly ConcurrentDictionary<int, DedicatedWorkerInstance> _dedicatedWorkers = new();

    private int _dedicatedWorkerIdCounter;

    // Runs in the worker's own realm, where the global is the worker itself.
    // Everything a worker shares with a window -- timers, XHR, fetch, console,
    // crypto -- the realm already installed; this adds what is specific to
    // being a worker.
    private const string DedicatedWorkerBootstrapScript = @"
        (function () {

            // The realm was given a document so that its Web API globals get
            // installed, but a worker must not look like a window: scripts pick
            // their worker branch by asking whether window and document exist,
            // and a bundle that runs in both will silently take the page path
            // and never answer the page that started it.
            try { delete globalThis.window; } catch (e) { globalThis.window = undefined; }
            try { delete globalThis.document; } catch (e) { globalThis.document = undefined; }
            try { delete globalThis.frames; } catch (e) { }
            try { delete globalThis.parent; } catch (e) { }
            try { delete globalThis.top; } catch (e) { }
            globalThis.WorkerGlobalScope = function WorkerGlobalScope() { };
            globalThis.DedicatedWorkerGlobalScope = function DedicatedWorkerGlobalScope() { };

            // Having the names is not the same as being one. A library asks
            // `self instanceof WorkerGlobalScope` or reads
            // Object.prototype.toString.call(self) before it decides it may
            // touch a document, and both still answered Window. The host makes
            // the global object, so it cannot be moved onto
            // WorkerGlobalScope.prototype -- teach the constructors to
            // recognise it instead. `instanceof` consults Symbol.hasInstance
            // first (ECMA-262 13.10.2), which is the supported way to answer
            // for an exotic global.
            (function () {
                var scopes = [globalThis.WorkerGlobalScope, globalThis.DedicatedWorkerGlobalScope];
                for (var s = 0; s < scopes.length; s++) {
                    try {
                        Object.defineProperty(scopes[s], Symbol.hasInstance, {
                            value: function (candidate) { return candidate === globalThis; },
                            configurable: true
                        });
                    } catch (e) { }
                }
                try {
                    Object.defineProperty(globalThis, Symbol.toStringTag, {
                        value: 'DedicatedWorkerGlobalScope',
                        configurable: true,
                        enumerable: false,
                        writable: false
                    });
                } catch (e) { }
                try {
                    Object.defineProperty(globalThis, 'constructor', {
                        value: globalThis.DedicatedWorkerGlobalScope,
                        configurable: true,
                        enumerable: false,
                        writable: true
                    });
                } catch (e) { }
            })();

            globalThis.self = globalThis;
            globalThis.onmessage = null;
            globalThis.onmessageerror = null;
            globalThis.onerror = null;
            globalThis.name = '';
            globalThis.postMessage = function (data, transfer) {
                // The transfer list is the whole point of the first message a
                // worker sends: it hands the page the port the rest of the
                // conversation happens over. Dropping it leaves the page holding
                // a message it cannot answer.
                __fenWorkerEmit(data, transfer || []);
            };
            globalThis.close = function () {
                __fenWorkerEmitClose();
            };
            globalThis.importScripts = function () {
                for (var i = 0; i < arguments.length; i++) {
                    var url = String(arguments[i]);
                    var code = __fenWorkerImportScript(url);
                    if (typeof code !== 'string' || !code.length) {
                        // HTML 10.2.2 importScripts(): a script that cannot be
                        // fetched is a NetworkError, not a no-op.
                        throw new Error('importScripts(' + url + '): nothing to run');
                    }
                    try {
                        __fenWorkerRunScript(code, url);
                    } catch (err) {
                        __fenWorkerReportError('importScripts(' + url + '): ' + err);
                        throw err;
                    }
                }
            };
            // A worker global is an EventTarget like any other. This one took
            // only 'message', dropped every other type on the floor, and never
            // looked at the options argument -- so error and unhandledrejection
            // handlers silently did not exist, once and signal did nothing, and
            // the passive feature-detect probe never ran its getter.
            var byType = Object.create(null);
            var flatten = function (options) {
                if (typeof options === 'boolean') {
                    return { capture: options, once: false, passive: false, signal: null };
                }
                if (!options || typeof options !== 'object') {
                    return { capture: false, once: false, passive: false, signal: null };
                }
                // Read every member: the conversion is observable and pages
                // detect passive support by watching for it.
                return {
                    capture: Boolean(options.capture),
                    once: Boolean(options.once),
                    passive: Boolean(options.passive),
                    signal: options.signal || null
                };
            };
            var fire = function (type, event) {
                var list = byType[type];
                if (!list) { return; }
                var snapshot = list.slice();
                for (var i = 0; i < snapshot.length; i++) {
                    var entry = snapshot[i];
                    if (entry.once) {
                        var live = byType[type];
                        var at = live ? live.indexOf(entry) : -1;
                        if (at >= 0) { live.splice(at, 1); }
                    }
                    entry.callback.call(globalThis, event);
                }
            };
            // options is optional, so WebIDL reports length 2; keep it off the
            // parameter list rather than let the arity drift.
            globalThis.addEventListener = function (type, callback) {
                if (typeof callback !== 'function') { return; }
                var flat = flatten(arguments[2]);
                if (flat.signal && flat.signal.aborted) { return; }
                var key = String(type);
                var list = byType[key] || (byType[key] = []);
                for (var i = 0; i < list.length; i++) {
                    if (list[i].callback === callback && list[i].capture === flat.capture) { return; }
                }
                var entry = {
                    callback: callback,
                    capture: flat.capture,
                    once: flat.once,
                    passive: flat.passive
                };
                list.push(entry);
                if (flat.signal && typeof flat.signal.addEventListener === 'function') {
                    flat.signal.addEventListener('abort', function () {
                        var live = byType[key];
                        if (!live) { return; }
                        var at = live.indexOf(entry);
                        if (at >= 0) { live.splice(at, 1); }
                    });
                }
            };
            globalThis.removeEventListener = function (type, callback) {
                var capture = flatten(arguments[2]).capture;
                var list = byType[String(type)];
                if (!list) { return; }
                for (var i = list.length - 1; i >= 0; i--) {
                    if (list[i].callback === callback && list[i].capture === capture) {
                        list.splice(i, 1);
                    }
                }
            };
            globalThis.dispatchEvent = function (event) {
                if (!event || typeof event.type !== 'string') { return true; }
                if (!event.target) { event.target = globalThis; }
                fire(event.type, event);
                return !event.defaultPrevented;
            };
            globalThis.__fenWorkerDeliver = function (event) {
                if (typeof globalThis.onmessage === 'function') {
                    globalThis.onmessage(event);
                }
                fire('message', event);
            };
        })();
        ";

    /// <summary>
    /// Starts a dedicated worker: fetches its script, gives it a realm of its
    /// own and runs it there. Returns the id the page-side object addresses it
    /// by, or -1 if it could not be started.
    /// </summary>
    private JsValue StartDedicatedWorker(IReadOnlyList<JsValue> args)
    {
        if (args == null || args.Count < 2 || _interpreter == null)
        {
            return JsValue.FromInt32(-1);
        }

        var rawUrl = CoerceToHostString(args[0]);
        if (string.IsNullOrWhiteSpace(rawUrl) ||
            !Uri.TryCreate(_currentBaseUri, rawUrl, out var scriptUri))
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] Worker script URL unresolvable against {_currentBaseUri}: {rawUrl}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            return JsValue.FromInt32(-1);
        }

        // new Worker(blobUrl) passes the blob's text from the creating realm's blob URL
        // store (File API 8.3). The worker runs it without a fetch, with the creator's
        // URL as its base so it keeps the creator's origin, as a blob URL worker does.
        var blobSource = args.Count > 2 && args[2].Tag == JsValueTag.String ? args[2].AsString() : null;
        var realmUri = blobSource != null ? _currentBaseUri ?? scriptUri : scriptUri;

        var id = Interlocked.Increment(ref _dedicatedWorkerIdCounter);
        var worker = new DedicatedWorkerInstance
        {
            Id = id,
            PageObject = args[1],
            ScriptUri = scriptUri
        };
        _dedicatedWorkers[id] = worker;

        // new Worker() returns as soon as the URL parses; fetching and running
        // the script happens after. Doing it inline charged the caller the whole
        // of that work -- for reCAPTCHA, 1.4s taken out of an anchor set-up that
        // has five seconds in total to finish its handshake.
        EnqueueWorkerTask(worker, () =>
        {
            var startedAt = System.Diagnostics.Stopwatch.StartNew();
            string source;
            try
            {
                source = blobSource ?? FetchWorkerScriptAsync(scriptUri, _currentBaseUri).GetAwaiter().GetResult();
            }
            catch (Exception ex)
            {
                FenBrowser.Core.EngineLogCompat.Warn(
                    $"[FenJsBridge] Worker script fetch failed for {scriptUri}: {ex.GetType().Name}: {ex.Message}",
                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                return;
            }

            if (string.IsNullOrEmpty(source))
            {
                FenBrowser.Core.EngineLogCompat.Warn(
                    $"[FenJsBridge] Worker script was empty: {scriptUri}",
                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                return;
            }

            if (worker.Terminated)
            {
                return;
            }

            try
            {
                worker.Realm = CreateWorkerRealm(realmUri, id);
                worker.Realm.EvaluateWithFenJsRaw(DedicatedWorkerBootstrapScript);
                worker.Realm.EvaluateWithFenJsRaw(source);
                DrainWorkerDiagnostics(worker);
            }
            catch (Exception ex)
            {
                FenBrowser.Core.EngineLogCompat.Warn(
                    $"[FenJsBridge] Worker script threw while starting ({scriptUri}): {ex.GetType().Name}: {ex.Message}",
                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                DrainWorkerDiagnostics(worker);
                _dedicatedWorkers.TryRemove(id, out _);
                worker.Realm?.AbandonRealm();
                return;
            }

            FenBrowser.Core.EngineLogCompat.Info(
                $"[FenJsBridge] Worker {id} started from {scriptUri} ({source.Length} chars) " +
                $"in {startedAt.ElapsedMilliseconds}ms",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        });

        return JsValue.FromInt32(id);
    }

    /// <summary>
    /// Appends work to a worker's own chain. Start-up is the first entry, so
    /// everything posted afterwards runs against a worker that is already there.
    /// </summary>
    private void EnqueueWorkerTask(DedicatedWorkerInstance worker, Action work)
    {
        lock (worker.TailGate)
        {
            worker.Tail = worker.Tail.ContinueWith(
                _ =>
                {
                    try
                    {
                        work();
                    }
                    catch (Exception ex)
                    {
                        FenBrowser.Core.EngineLogCompat.Warn(
                            $"[FenJsBridge] Worker {worker.Id} task threw: {ex.GetType().Name}: {ex.Message}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }
                },
                TaskScheduler.Default);
        }
    }

    private async Task<string> FetchWorkerScriptAsync(Uri scriptUri, Uri referer)
    {
        if (WorkerScriptFetcher != null)
        {
            var fromWorkerFetcher = await WorkerScriptFetcher(scriptUri, referer).ConfigureAwait(false);
            FenBrowser.Core.EngineLogCompat.Info(
                $"[FenJsBridge] WorkerScriptFetcher result for '{scriptUri}': len={fromWorkerFetcher?.Length ?? -1}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            if (!string.IsNullOrEmpty(fromWorkerFetcher))
            {
                return fromWorkerFetcher;
            }
        }

        return await FetchExternalPageScriptAsync(scriptUri, referer).ConfigureAwait(false);
    }

    private FenJsBrowserScriptEngine CreateWorkerRealm(Uri scriptUri, int workerId)
    {
        var realm = new FenJsBrowserScriptEngine(_host)
        {
            _parentRealmOwner = this
        };
        realm.RuntimeProfile = RuntimeProfile;
        realm.ImageLoaderScope = ImageLoaderScope;
        realm.ViewportHitTester = ViewportHitTester;
        realm.FetchOverride = FetchOverride;
        realm.SubresourceAllowed = SubresourceAllowed;
        realm.TrustedDynamicSubresourceAllowed = TrustedDynamicSubresourceAllowed;
        realm.NonceAllowed = NonceAllowed;
        realm.FetchHandler = FetchHandler;
        realm.CookieReadBridge = CookieReadBridge;
        realm.CookieWriteBridge = CookieWriteBridge;
        realm.ExternalScriptFetcher = ExternalScriptFetcher;
        realm.ExternalScriptFetcherWithNonce = ExternalScriptFetcherWithNonce;
        realm.WorkerScriptFetcher = WorkerScriptFetcher;
        realm.ExecutionCancellation = ExecutionCancellation;
        realm.Sandbox = Sandbox;
        realm.AllowExternalScripts = AllowExternalScripts;
        realm.DocumentSecurityContext = DocumentSecurityContext;
        realm.PermissionsPolicyProvider = PermissionsPolicyProvider;

        // A worker has no document, but the realm installs its Web API globals
        // alongside the DOM ones. An empty document the worker script cannot
        // reach is the smallest way to get a realm that actually works.
        realm.BindFenJsDomContext(new Document(), scriptUri, "complete");
        realm.StripWindowOnlyGlobalsForWorker();

        realm._interpreter.RegisterGlobalValue(
            "__fenWorkerEmit",
            realm._interpreter.AllocateNativeFunction(
                "__fenWorkerEmit",
                (_, emitArgs) => DeliverMessageFromWorker(workerId, emitArgs)));
        realm._interpreter.RegisterGlobalValue(
            "__fenWorkerEmitClose",
            realm._interpreter.AllocateNativeFunction(
                "__fenWorkerEmitClose",
                (_, _) => TerminateDedicatedWorkerById(workerId)));
        realm._interpreter.RegisterGlobalValue(
            "__fenWorkerImportScript",
            realm._interpreter.AllocateNativeFunction(
                "__fenWorkerImportScript",
                (_, importArgs) => ImportWorkerScript(workerId, importArgs)));
        // HTML 10.2.2 runs each imported script as a classic script: its
        // top-level let and const are the worker's global lexicals, not an
        // eval's locals.
        realm._interpreter.RegisterGlobalValue(
            "__fenWorkerRunScript",
            realm._interpreter.AllocateNativeFunction(
                "__fenWorkerRunScript",
                (_, runArgs) => realm._interpreter.EvaluateScript(
                    runArgs.Count > 0 ? CoerceToHostString(runArgs[0]) : string.Empty,
                    runArgs.Count > 1 ? CoerceToHostString(runArgs[1]) : "<importScripts>")));
        realm._interpreter.RegisterGlobalValue(
            "__fenWorkerReportError",
            realm._interpreter.AllocateNativeFunction(
                "__fenWorkerReportError",
                (_, errorArgs) =>
                {
                    NoteWorkerDiagnostic(
                        workerId,
                        errorArgs is { Count: > 0 } ? CoerceToHostString(errorArgs[0]) : "(no detail)");
                    return JsValue.Undefined;
                }));
        return realm;
    }

    /// <summary>
    /// A worker realm is built by binding the ordinary window context and then
    /// leaving out <c>window</c> and <c>document</c>. Everything else the window
    /// context installs stayed behind, so a worker advertised Element, Node,
    /// getComputedStyle, localStorage, history, screen, Image, DOMParser,
    /// MutationObserver, matchMedia and the rest -- none of which exist in a real
    /// DedicatedWorkerGlobalScope (HTML 10.2.1).
    ///
    /// (The matching identity half -- toStringTag and instanceof -- lives in
    /// <see cref="DedicatedWorkerBootstrapScript"/>, which runs after this and
    /// is where the two scope constructors are defined.)
    ///
    /// Scripts feature-detect on exactly those. reCAPTCHA's bundle read them,
    /// concluded it was running in a document, took the DOM path and dereferenced
    /// a bare <c>document</c>. That threw inside an async message handler, so the
    /// only trace was a promise that rejected with nobody listening: the anchor
    /// frame waited for a reply that was never coming and its own 20s watchdog
    /// eventually fired.
    /// </summary>
    private void StripWindowOnlyGlobalsForWorker()
    {
        try
        {
            EvaluateWithFenJsRaw("""
                (function () {
                    var windowOnly = [
                        'Window', 'Document', 'HTMLDocument', 'DocumentType',
                        'DOMImplementation', 'HTMLElement', 'Element', 'Node',
                        'NodeList', 'NamedNodeMap', 'HTMLCollection', 'Attr',
                        'DocumentFragment', 'CharacterData', 'Text', 'Comment',
                        'CDATASection', 'ProcessingInstruction',
                        'ShadowRoot', 'Range', 'Selection', 'getSelection',
                        'DOMParser', 'XMLSerializer', 'XPathResult', 'NodeFilter',
                        'TreeWalker', 'NodeIterator', 'MutationObserver',
                        'MutationRecord', 'IntersectionObserver', 'ResizeObserver',
                        'customElements', 'CustomElementRegistry',
                        'localStorage', 'sessionStorage', 'Storage',
                        'history', 'History', 'Location', 'screen', 'Screen', 'visualViewport',
                        'alert', 'confirm', 'prompt', 'print', 'open',
                        'focus', 'blur', 'scroll', 'scrollTo', 'scrollBy',
                        'getComputedStyle', 'matchMedia',
                        'Image', 'Audio', 'Option',
                        'requestAnimationFrame', 'cancelAnimationFrame',
                        'requestIdleCallback', 'cancelIdleCallback',
                        'find', 'stop',
                        // Every event a pointing device, a key or a page
                        // transition produces. A worker has none of them.
                        'UIEvent', 'MouseEvent', 'KeyboardEvent', 'WheelEvent',
                        'PointerEvent', 'TouchEvent', 'Touch', 'TouchList',
                        'FocusEvent', 'InputEvent', 'CompositionEvent',
                        'DragEvent', 'ClipboardEvent', 'BeforeUnloadEvent',
                        'PopStateEvent', 'HashChangeEvent', 'PageTransitionEvent',
                        'AnimationEvent', 'TransitionEvent',
                        // Window geometry, which is what a fingerprint reads
                        // first and what a worker has none of.
                        'innerWidth', 'innerHeight', 'outerWidth', 'outerHeight',
                        'scrollX', 'scrollY', 'pageXOffset', 'pageYOffset',
                        'screenX', 'screenY', 'screenLeft', 'screenTop',
                        'devicePixelRatio', 'frames', 'frameElement', 'opener',
                        'status', 'closed', 'menubar', 'toolbar', 'locationbar',
                        'personalbar', 'scrollbars', 'statusbar'
                    ];
                    for (var i = 0; i < windowOnly.length; i++) {
                        try { delete globalThis[windowOnly[i]]; } catch (e) { }
                        // A global the host installed may not be configurable, in
                        // which case delete is a silent no-op and the detection
                        // still sees it. Overwrite with undefined so `typeof` and
                        // a truthiness test both agree it is not there.
                        try {
                            if (typeof globalThis[windowOnly[i]] !== 'undefined') {
                                globalThis[windowOnly[i]] = undefined;
                            }
                        } catch (e) { }
                    }

                    // The element interfaces are ninety-odd names and the set
                    // grows with the DOM, so they go by prefix rather than by
                    // enumeration: a list that has to be maintained is a list
                    // that will be wrong again. Anything this realm installed
                    // whose name says markup, styling or vector graphics has no
                    // business in a worker.
                    try {
                        var installed = Object.getOwnPropertyNames(globalThis);
                        for (var n = 0; n < installed.length; n++) {
                            var name = installed[n];
                            if (name.lastIndexOf('HTML', 0) !== 0 &&
                                name.lastIndexOf('SVG', 0) !== 0 &&
                                name.lastIndexOf('CSS', 0) !== 0) {
                                continue;
                            }

                            try { delete globalThis[name]; } catch (e) { }
                            try {
                                if (typeof globalThis[name] !== 'undefined') {
                                    globalThis[name] = undefined;
                                }
                            } catch (e) { }
                        }
                    } catch (e) { }
                })()
                """);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] Could not strip window-only globals from worker realm: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    /// <summary>Records a line for <see cref="DrainWorkerDiagnostics"/> to log.</summary>
    private void NoteWorkerDiagnostic(int workerId, string message)
    {
        if (_dedicatedWorkers.TryGetValue(workerId, out var worker))
        {
            worker.Diagnostics.Enqueue(message);
        }
    }

    private void DrainWorkerDiagnostics(DedicatedWorkerInstance worker)
    {
        while (worker.Diagnostics.TryDequeue(out var line))
        {
            FenBrowser.Core.EngineLogCompat.Info(
                $"[FenJsBridge] Worker {worker.Id}: {line}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    /// <summary>
    /// Which frame a diagnostic line came from. The postMessage probe pools
    /// every realm into one file, and reCAPTCHA runs the same code in the page,
    /// the anchor and the challenge frame -- without this the three are
    /// indistinguishable.
    /// </summary>
    private string ProbeFrame() => _currentBaseUri?.AbsolutePath ?? "?";

    private JsValue ImportWorkerScript(int workerId, IReadOnlyList<JsValue> args)
    {
        // Every way out of here that isn't the script itself used to be an empty
        // string, and the caller ran on as though the import had happened. A
        // worker whose whole body is one importScripts() then sat there doing
        // nothing, with not a line in the log to say why. Say what went wrong.
        if (args == null || args.Count == 0)
        {
            return JsValue.FromString(string.Empty);
        }

        var raw = CoerceToHostString(args[0]);
        if (!_dedicatedWorkers.TryGetValue(workerId, out var worker) || worker.Terminated)
        {
            NoteWorkerDiagnostic(workerId, $"importScripts('{raw}') arrived after the worker was gone.");
            return JsValue.FromString(string.Empty);
        }

        if (string.IsNullOrWhiteSpace(raw) || !Uri.TryCreate(worker.ScriptUri, raw, out var uri))
        {
            NoteWorkerDiagnostic(workerId, $"importScripts('{raw}') does not resolve against {worker.ScriptUri}.");
            return JsValue.FromString(string.Empty);
        }

        string? code;
        try
        {
            code = FetchWorkerScriptAsync(uri, worker.ScriptUri).GetAwaiter().GetResult();
        }
        catch (Exception ex)
        {
            NoteWorkerDiagnostic(workerId, $"importScripts({uri}) failed: {ex.GetType().Name}: {ex.Message}");
            return JsValue.FromString(string.Empty);
        }

        NoteWorkerDiagnostic(workerId, $"importScripts({uri}) -> {code?.Length ?? -1} chars");
        return JsValue.FromString(code ?? string.Empty);
    }

    /// <summary>The page called worker.postMessage(data).</summary>
    private JsValue PostMessageToDedicatedWorker(IReadOnlyList<JsValue> args)
    {
        if (args == null || args.Count == 0 ||
            !_dedicatedWorkers.TryGetValue((int)CoerceToHostUInt32(args[0], 0), out var worker) ||
            worker.Terminated)
        {
            return JsValue.Undefined;
        }

        // Cross the realm boundary as data, never as a handle: the realms have
        // separate heaps and an object from one means nothing in the other.
        var payload = args.Count > 1 ? ConvertJsValueToObject(args[1]) : null;
        var transferred = args.Count > 2
            ? ExtractTransferredMessagePorts(args[2])
            : Array.Empty<MessagePortEndpoint>();
        // The payload already holds its own copy; transferred buffers leave the sender.
        if (args.Count > 2)
            DetachTransferredArrayBuffers(args[2]);
        if (DiagnosticPaths.AppendEnabled)
        {
            DiagnosticPaths.AppendLogText(
                "worker_probe.txt",
                $"{DateTimeOffset.UtcNow:O} page->worker{worker.Id} " +
                $"data={DescribePostMessageValue(args.Count > 1 ? args[1] : JsValue.Undefined)} " +
                $"transferCount={transferred.Count} " +
                $"ports=[{string.Join(",", transferred.Select(e => "#" + e.TraceId))}]{Environment.NewLine}");
        }

        var senderOrigin = GetCurrentWindowOrigin();
        EnqueueWorkerTask(worker, () =>
            worker.Realm?.DeliverMessageIntoWorkerRealm(payload, senderOrigin, transferred));
        return JsValue.Undefined;
    }

    private void DeliverMessageIntoWorkerRealm(
        object payload,
        string origin,
        IReadOnlyList<MessagePortEndpoint> transferred)
    {
        try
        {
            RunFenJsWithLargeStack<object>(() =>
            {
                using (ScriptEngineLockProbe.Hold(_fenJsLock))
                {
                    if (_interpreter == null)
                    {
                        return null;
                    }

                    var deliver = ReadGlobalValueOrUndefined("__fenWorkerDeliver");
                    if (!_interpreter.CanCallValue(deliver))
                    {
                        return null;
                    }

                    var eventValue = CreateMessageEventValue(
                        ConvertObjectToJsValue(payload),
                        origin,
                        JsValue.Undefined,
                        _fenJsGlobalThis,
                        ImportTransferredMessagePorts(transferred));
                    _interpreter.InvokeFunction(deliver, new[] { eventValue }, JsValue.Undefined);
                    return null;
                }
            });
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] Worker message delivery threw: {ex.GetType().Name}: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    /// <summary>The worker called postMessage(data); hand it to the page.</summary>
    private JsValue DeliverMessageFromWorker(int workerId, IReadOnlyList<JsValue> args)
    {
        if (!_dedicatedWorkers.TryGetValue(workerId, out var worker) || worker.Terminated)
        {
            return JsValue.Undefined;
        }

        var payload = args != null && args.Count > 0 && worker.Realm != null
            ? worker.Realm.ConvertJsValueToObject(args[0])
            : null;
        var transferred = args != null && args.Count > 1 && worker.Realm != null
            ? worker.Realm.ExtractTransferredMessagePorts(args[1])
            : Array.Empty<MessagePortEndpoint>();
        if (args != null && args.Count > 1 && worker.Realm != null)
            worker.Realm.DetachTransferredArrayBuffers(args[1]);
        if (DiagnosticPaths.AppendEnabled)
        {
            DiagnosticPaths.AppendLogText(
                "worker_probe.txt",
                $"{DateTimeOffset.UtcNow:O} worker{workerId}->page " +
                $"data={(args != null && args.Count > 0 ? worker.Realm.DescribePostMessageValue(args[0]) : "<none>")} " +
                $"transferCount={transferred.Count} args={args?.Count ?? 0} " +
                $"ports=[{string.Join(",", transferred.Select(e => "#" + e.TraceId))}]{Environment.NewLine}");
        }

        try
        {
            RunFenJsWithLargeStack<object>(() =>
            {
                using (ScriptEngineLockProbe.Hold(_fenJsLock))
                {
                    if (_interpreter == null || worker.PageObject.Tag != JsValueTag.Object)
                    {
                        return null;
                    }

                    var eventValue = CreateMessageEventValue(
                        ConvertObjectToJsValue(payload),
                        GetCurrentWindowOrigin(),
                        JsValue.Undefined,
                        worker.PageObject,
                        ImportTransferredMessagePorts(transferred));
                    var dispatch = ReadJsProperty(worker.PageObject, "dispatchEvent");
                    if (_interpreter.CanCallValue(dispatch))
                    {
                        // A worker reply that lands on a page object carrying no
                        // handler is dropped in silence, and from the send side it
                        // looks exactly like a delivered message. Say which it was.
                        var onmessage = ReadJsProperty(worker.PageObject, "onmessage");
                        // Worker._fenListeners is keyed by event type, not an
                        // array - count the bucket dispatchEvent will actually
                        // read rather than the map itself.
                        var listenerMap = ReadJsProperty(worker.PageObject, "_fenListeners");
                        var listeners = listenerMap.Tag == JsValueTag.Object
                            ? ReadArrayLikeLength(ReadJsProperty(listenerMap, "message"))
                            : 0;
                        var handlerCallable = _interpreter.CanCallValue(onmessage);
                        DiagnosticPaths.AppendLogText(
                            "worker_probe.txt",
                            $"{DateTimeOffset.UtcNow:O} worker{workerId}->page dispatch " +
                            $"onmessage={handlerCallable} listeners={listeners} " +
                            $"portsIn={ReadArrayLikeLength(ReadJsProperty(eventValue, "ports"))}" +
                            $"{(handlerCallable || listeners > 0 ? string.Empty : "  <-- NO HANDLER, message discarded")}" +
                            $"{Environment.NewLine}");
                        _interpreter.InvokeFunction(dispatch, new[] { eventValue }, worker.PageObject);
                    }
                    else
                    {
                        DiagnosticPaths.AppendLogText(
                            "worker_probe.txt",
                            $"{DateTimeOffset.UtcNow:O} worker{workerId}->page NOT DELIVERED: " +
                            $"page object has no callable dispatchEvent{Environment.NewLine}");
                    }
                    return null;
                }
            });
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] Worker {workerId} reply delivery threw: {ex.GetType().Name}: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            DiagnosticPaths.AppendLogText(
                "worker_probe.txt",
                $"{DateTimeOffset.UtcNow:O} worker{workerId}->page THREW " +
                $"{ex.GetType().Name}: {ex.Message}{Environment.NewLine}");
        }
        return JsValue.Undefined;
    }

    private JsValue TerminateDedicatedWorker(IReadOnlyList<JsValue> args)
    {
        if (args != null && args.Count > 0)
        {
            TerminateDedicatedWorkerById((int)CoerceToHostUInt32(args[0], 0));
        }
        return JsValue.Undefined;
    }

    private JsValue TerminateDedicatedWorkerById(int workerId)
    {
        if (_dedicatedWorkers.TryRemove(workerId, out var worker))
        {
            worker.Terminated = true;
            worker.Realm?.AbandonRealm();
        }
        return JsValue.Undefined;
    }

    private void TerminateAllDedicatedWorkers()
    {
        foreach (var worker in _dedicatedWorkers.Values.ToArray())
        {
            worker.Terminated = true;
            worker.Realm?.AbandonRealm();
        }
        _dedicatedWorkers.Clear();
    }

    private void ResetFenJsSession()
    {
        var detachedFrameRealms = DetachFrameRealms();
        foreach (var frameRealm in detachedFrameRealms)
        {
            frameRealm.AbandonRealm();
        }

        // A new document: the previous one's audio contexts stop and release their devices.
        CloseAllWebAudioContexts();

        // Establish the large-stack worker BEFORE taking _fenJsLock. ResetFenJsSession
        // transitively calls InstallFenJsDomGlobals -> EvaluateWithFenJsRaw, which spawns
        // the large-stack thread. If we held _fenJsLock on a plain render thread and then
        // spawned, the worker would block forever on the lock the joining caller still
        // holds (Monitor is not cross-thread reentrant) -> deadlock. Acquiring the fat
        // stack first means the nested EvaluateWithFenJsRaw sees _onFenJsLargeStackThread
        // and runs inline, so the lock is taken once, on a single thread, reentrantly.
        RunFenJsWithLargeStack<object>(() =>
        {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            CloseOwnedMessagePorts();
            foreach (var timerEntry in _fenJsTimers.ToArray())
            {
                if (_fenJsTimers.TryRemove(timerEntry.Key, out var timer))
                {
                    timer.Dispose();
                }
            }

            _compiler = new BytecodeCompiler
            {
                ParserMaxRecursionDepth = FenJsBrowserParserMaxRecursionDepth
            };
            var gcStressMode = ResolveFenJsGcStressMode();
            _interpreter = new BytecodeInterpreter(
                gcStressMode == GcStressMode.None ? null : new JsHeap(gcStressMode))
            {
                HostObjectTable = new HostObjectTable(),
                HostHooks = _hostHooks,
                HostResolveContext = new HostObjectResolveContext(
                    CurrentRealmId: 0,
                    CurrentDocumentEpoch: _documentEpoch,
                    CurrentNavigationEpoch: _navigationEpoch),
                // Bound per-invocation execution so a runaway or pathologically slow
                // page script (or one our interpreter mis-evaluates into a spin loop)
                // surfaces as a catchable RangeError instead of freezing the browser
                // thread forever. Override via FEN_FENJS_SCRIPT_TIMEOUT_MS.
                WallClockTimeoutMs = ResolveFenJsScriptTimeoutMs(),
                // Instruction budget prevents truly-infinite loops from hanging
                // the browser for the full wall-clock timeout (300 s).  100M
                // instructions is ~5-10 s of interpreted bytecode on a modern
                // CPU â€” enough for even the largest page bundles to finish.
                InstructionBudget = FenJsBrowserInstructionBudget,
                // Fail closed while unassigned: the constructor runs this before the
                // owner assigns Sandbox/DocumentSecurityContext; BindFenJsDomContext
                // re-runs the session reset per document with the real policies.
                ExposeSharedArrayBuffer = Sandbox?.Allows(SandboxFeature.SharedArrayBuffer) == true &&
                    DocumentSecurityContext?.Allows(SandboxFeature.SharedArrayBuffer) == true,
                InterruptCallback = () =>
                    !_realmAbandoned &&
                    !_executionCancellation.IsCancellationRequested &&
                    !IsWorkItemStale(Volatile.Read(ref _activeFenJsWorkItem)),
                MaxCallDepth = 1024,
                ParserMaxRecursionDepth = FenJsBrowserParserMaxRecursionDepth
            };
            _interpreter.Heap.AddRootSource(this);
            _moduleEvaluator = null;
            _moduleSourceCache.Clear();
            _inlineModuleCounter = 0;
            _importMap.Clear();
            EnsureAttributeReactionObserver();
            EnsureFenJsHeapDiagnosticSink();
            ConfigureFenJsMicrotaskTracing(_interpreter);

            // Wire a diagnostic Promise rejection tracker so unhandled rejections
            // surface in engine logs with the rejection reason and source ownership.
            _diagnosticPromiseRejectionTracker = new FenJsDiagnosticPromiseRejectionTracker(
                _interpreter.PromiseRejectionTracker,
                TrackPromiseRejection,
                RecordPromiseRejection);
            _interpreter.PromiseRejectionTracker = _diagnosticPromiseRejectionTracker;

            _hostHandleCache.Clear();
            _documentEventListeners.Clear();
            _windowEventListeners.Clear();
            _visualViewportEventListeners.Clear();
            _embeddedParentWindowListeners.Clear();
            // Pin scopes from the previous session reference old-heap handles;
            // the new heap's marker validates every traced handle and would
            // treat them as fatal. The generation bump below already makes
            // them invisible to tracing; clearing also releases their memory.
            _fenJsPinScopes.Clear();
            _hostCallableCache = new ConditionalWeakTable<object, Dictionary<string, JsValue>>();
            _hostPropertyStore = new ConditionalWeakTable<object, Dictionary<string, JsValue>>();
            // Media bindings hold promise and error objects from the old heap.
            _mediaElements.Clear();
            System.Threading.Volatile.Write(ref _mediaElementCount, 0);
            _mediaElementCursor = null;
            _mediaElementCursorRoot = null;
            _loadEventDelayCount = 0;
            _loadEventDeferred = false;
            _stickyUserActivation = false;
            _missingHostPropertyReads = new ConditionalWeakTable<object, HashSet<string>>();
            _elementEventListeners = new ConditionalWeakTable<object, List<BrowserEventListener>>();
            _iframeWindowEventListeners = new ConditionalWeakTable<Element, List<BrowserEventListener>>();
            _fenJsTopWindowFacade = JsValue.Undefined;
            _fenJsSameOriginTopWindowFacade = JsValue.Undefined;
            _visualViewport = JsValue.Undefined;
            _hostPrototypeNames.Clear();
            _activeWindowEventListeners = null;
            _activeWindowEventTarget = JsValue.Undefined;
            _fenJsFileConstructor = JsValue.Undefined;
            _fenJsStylePrototype = JsValue.Undefined;
            _activeParentBaseUri = null;
            _fenJsDomConstructorsInstalled = false;

            // Every JsValue the host is still holding names a cell in the heap
            // that is about to be thrown away. Resolving one against the new
            // heap is a fatal "Stale heap handle": the index is in range and the
            // generation is not, and no amount of looking at the new heap
            // explains it, because the object it names was never there.
            //
            // The window facades above were already dropped; these were not.
            // The parent-window proxy is the source of every message a parent
            // posts into this frame, so a frame that has been reset once -- an
            // iframe on its second document, which is exactly what reCAPTCHA
            // builds -- took one and died.
            _embeddedParentWindowProxy = JsValue.Undefined;
            _embeddedParentWindowTarget = JsValue.Undefined;
            _siblingWindowProxies.Clear();
            _pendingPromiseRejectionDiagnostics.Clear();

            // A worker outlives the document that made it only in the sense
            // that its thread is still running; the page object it posts to
            // belongs to the heap going away. Stop them.
            foreach (var workerId in _dedicatedWorkers.Keys.ToArray())
            {
                TerminateDedicatedWorkerById(workerId);
            }

            _dedicatedWorkers.Clear();

            // Close all active WebSocket connections on session reset.
            lock (_webSocketHosts)
            {
                foreach (var (_, host) in _webSocketHosts)
                {
                    try { host.Close(1001, "Navigation"); } catch { }
                    try { host.Dispose(); } catch { }
                }
                _webSocketHosts.Clear();
            }

            _hostHooks.Reset();

            if (_currentDomRoot != null)
            {
                InstallFenJsDomGlobals(_currentDomRoot, _currentBaseUri);
            }

            // The parent-window proxy was dropped above with the rest of the old
            // heap's handles, and it is what `event.source` names for every
            // message the parent posts in. Left undefined, the source came back
            // as the frame's own window, so a reply sent to event.source went to
            // the frame itself and the parent never heard it. Rebuild it here so
            // it exists no matter which path reset the session.
            if (_parentRealmOwner != null && _embeddingFrameElement != null)
            {
                ConfigureEmbeddedRealmGlobals();
            }

            // Bump the generation so any in-flight work lambdas from the
            // previous session can detect the reset and abort gracefully.
            Interlocked.Increment(ref _fenJsSessionGeneration);
        }
            return null;
        });
    }

    private static object ConvertFenJsValue(FenBrowser.Js.Runtime.JsValue value)
    {
        return value.Tag switch
        {
            FenBrowser.Js.Runtime.JsValueTag.Undefined => null,
            FenBrowser.Js.Runtime.JsValueTag.Null => null,
            FenBrowser.Js.Runtime.JsValueTag.Boolean => value.AsBoolean(),
            FenBrowser.Js.Runtime.JsValueTag.Int32 => value.AsInt32(),
            FenBrowser.Js.Runtime.JsValueTag.Number => value.AsNumber(),
            FenBrowser.Js.Runtime.JsValueTag.String => value.AsString(),
            FenBrowser.Js.Runtime.JsValueTag.Symbol => value.AsSymbolDescription() ?? "Symbol()",
            FenBrowser.Js.Runtime.JsValueTag.BigInt => value.AsBigInt().ToString(),
            _ => throw new InvalidOperationException("FenJS preview eval returned a host-bound or object result.")
        };
    }

    private void BindFenJsDomContext(Node domRoot, Uri baseUri, string documentReadyState)
    {
        var bindOrdinal = Interlocked.Increment(ref _domBindCount);
        if (bindOrdinal > 1)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] realm rebind #{bindOrdinal} realm={RuntimeHelpers.GetHashCode(this)} " +
                $"scope={(_embeddingFrameElement == null ? "top" : "frame<" + _embeddingFrameElement.TagName + ">")} " +
                $"uri='{baseUri?.AbsoluteUri ?? "<none>"}' - the previous document's JS state is discarded",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }


        // Acquire the large stack before _fenJsLock for the same reason as
        // ResetFenJsSession: the nested ResetFenJsSession -> InstallFenJsDomGlobals ->
        // EvaluateWithFenJsRaw must run inline on this worker rather than spawning a
        // second thread that deadlocks on the lock we hold here.
        RunFenJsWithLargeStack<object>(() =>
        {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            _currentDomRoot = domRoot;
            _currentBaseUri = baseUri;
            _documentReadyState = string.IsNullOrWhiteSpace(documentReadyState)
                ? "loading"
                : documentReadyState;
            _documentEpoch = _documentEpoch.Next();
            ClearSelectionState();
            ResetFenJsSession();

            // Process iframes that exist in the static HTML (src/srcdoc attributes).
            // Dynamic iframes inserted later are handled by QueueFrameLoadsForTree
            // called from appendChild/insertBefore/insertAdjacentHTML/insertBefore.
            QueueFrameLoadsForTree(domRoot);
        }
            return null;
        });
    }

    private void RebindFenJsDomContext(Node domRoot, Uri baseUri, string documentReadyState)
    {
        if (domRoot == null)
        {
            return;
        }

        RunFenJsWithLargeStack<object>(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                _currentDomRoot = domRoot;
                _currentBaseUri = baseUri;
                _documentReadyState = string.IsNullOrWhiteSpace(documentReadyState)
                    ? "loading"
                    : documentReadyState;
                ClearSelectionState();

                var document = domRoot as Document ?? domRoot.OwnerDocument;
                var navigator = CreateNavigatorHost();
                var location = new FenJsLocationHost(baseUri ?? TryCreateUri(document?.URL));
                var history = new FenJsHistoryHost(location);

                _hostHooks.Bind(
                    this,
                    document,
                    navigator,
                    location,
                    baseUri ?? TryCreateUri(document?.URL));

                if (document == null)
                {
                    return null;
                }

                _interpreter.RegisterGlobalHostObject(
                    "document",
                    RegisterHostObject(document, HostObjectKind.DomDocument));
                _interpreter.RegisterGlobalHostObject(
                    "navigator",
                    RegisterHostObject(navigator, HostObjectKind.Other));
                _interpreter.RegisterGlobalHostObject(
                    "location",
                    RegisterHostObject(location, HostObjectKind.Other));
                _interpreter.RegisterGlobalHostObject(
                    "history",
                    RegisterHostObject(history, HostObjectKind.Other));

                SeedFenJsDocumentAndNavigatorProperties(document, navigator);
                RegisterFenJsStorageGlobals(baseUri, document);
            }

            return null;
        });
    }

    private IDisposable ActivateSubdocumentWindowContext(Node domRoot, Uri baseUri)
    {
        var document = domRoot as Document ?? domRoot?.OwnerDocument;
        var frameElement = TryGetFrameElementForDocument(document);
        if (frameElement == null)
        {
            return null;
        }

        var frameWindow = GetOrCreateIFrameContentWindow(frameElement, document, baseUri);
        var frameWindowListeners = GetIFrameWindowListeners(frameElement);
        var previousListeners = _activeWindowEventListeners;
        var previousTarget = _activeWindowEventTarget;
        var previousWindow = ReadGlobalValueOrUndefined("window");
        var previousSelf = ReadGlobalValueOrUndefined("self");
        var previousFrames = ReadGlobalValueOrUndefined("frames");
        var previousParent = ReadGlobalValueOrUndefined("parent");
        var previousTop = ReadGlobalValueOrUndefined("top");
        var previousDocument = ReadGlobalValueOrUndefined("document");
        var previousLocation = ReadGlobalValueOrUndefined("location");
        var previousBaseUri = _currentBaseUri;
        var previousParentBaseUri = _activeParentBaseUri;
        var parentWindow = ReadJsProperty(frameWindow, "parent");
        if (parentWindow.Tag == JsValueTag.Undefined)
        {
            parentWindow = _fenJsGlobalThis.Tag == JsValueTag.Undefined
                ? previousWindow
                : GetOrCreateTopWindowFacade();
        }
        var frameBaseUri = baseUri ??
            TryCreateUri(document?.BaseURI) ??
            TryCreateUri(document?.DocumentURI) ??
            TryCreateUri(document?.URL);

        if (frameBaseUri != null)
        {
            _currentBaseUri = frameBaseUri;
        }
        _activeParentBaseUri = GetParentDocumentUri(frameElement) ?? previousBaseUri;
        _activeWindowEventListeners = frameWindowListeners;
        _activeWindowEventTarget = frameWindow;
        _interpreter.RegisterGlobalValue("window", frameWindow);
        _interpreter.RegisterGlobalValue("self", frameWindow);
        _interpreter.RegisterGlobalValue("frames", frameWindow);
        _interpreter.RegisterGlobalValue("parent", parentWindow);
        _interpreter.RegisterGlobalValue("top", parentWindow);
        var frameDocument = ReadJsProperty(frameWindow, "document");
        var frameLocation = ReadJsProperty(frameWindow, "location");
        if (frameDocument.Tag != JsValueTag.Undefined)
        {
            _interpreter.RegisterGlobalValue("document", frameDocument);
        }
        if (frameLocation.Tag != JsValueTag.Undefined)
        {
            _interpreter.RegisterGlobalValue("location", frameLocation);
        }

        return new WindowContextScope(
            this,
            previousListeners,
            previousTarget,
            previousWindow,
            previousSelf,
            previousFrames,
            previousParent,
            previousTop,
            previousDocument,
            previousLocation,
            previousBaseUri,
            previousParentBaseUri);
    }

    private IDisposable ActivateWindowCallbackContext(JsValue windowTarget, List<BrowserEventListener> listeners)
    {
        if (windowTarget.Tag != JsValueTag.Object)
        {
            return null;
        }

        var previousListeners = _activeWindowEventListeners;
        var previousTarget = _activeWindowEventTarget;
        var previousWindow = ReadGlobalValueOrUndefined("window");
        var previousSelf = ReadGlobalValueOrUndefined("self");
        var previousFrames = ReadGlobalValueOrUndefined("frames");
        var previousParent = ReadGlobalValueOrUndefined("parent");
        var previousTop = ReadGlobalValueOrUndefined("top");
        var previousDocument = ReadGlobalValueOrUndefined("document");
        var previousLocation = ReadGlobalValueOrUndefined("location");
        var previousBaseUri = _currentBaseUri;
        var previousParentBaseUri = _activeParentBaseUri;
        var frameDocument = ReadJsProperty(windowTarget, "document");
        var frameLocation = ReadJsProperty(windowTarget, "location");
        var parentWindow = ReadJsProperty(windowTarget, "parent");
        if (parentWindow.Tag == JsValueTag.Undefined)
        {
            parentWindow = _fenJsGlobalThis;
        }
        var frameHref = ReadJsProperty(frameLocation, "href");
        var frameBaseUri = TryCreateUri(CoerceToHostString(frameHref));

        if (frameBaseUri != null)
        {
            _currentBaseUri = frameBaseUri;
        }
        var callbackFrameElement = ResolveHostObjectOrNull<Element>(ReadJsProperty(windowTarget, "__fenFrameElement"));
        _activeParentBaseUri = GetParentDocumentUri(callbackFrameElement) ?? previousBaseUri;
        _activeWindowEventListeners = listeners;
        _activeWindowEventTarget = windowTarget;
        _interpreter.RegisterGlobalValue("window", windowTarget);
        _interpreter.RegisterGlobalValue("self", windowTarget);
        _interpreter.RegisterGlobalValue("frames", windowTarget);
        _interpreter.RegisterGlobalValue("parent", parentWindow);
        _interpreter.RegisterGlobalValue("top", parentWindow);
        if (frameDocument.Tag != JsValueTag.Undefined)
        {
            _interpreter.RegisterGlobalValue("document", frameDocument);
        }
        if (frameLocation.Tag != JsValueTag.Undefined)
        {
            _interpreter.RegisterGlobalValue("location", frameLocation);
        }

        return new WindowContextScope(
            this,
            previousListeners,
            previousTarget,
            previousWindow,
            previousSelf,
            previousFrames,
            previousParent,
            previousTop,
            previousDocument,
            previousLocation,
            previousBaseUri,
            previousParentBaseUri);
    }

    private JsValue ReadGlobalValueOrUndefined(string name)
    {
        return _interpreter != null
            ? _interpreter.ReadGlobalValueOrUndefined(name)
            : JsValue.Undefined;
    }

    private void RestoreWindowContext(
        List<BrowserEventListener> previousListeners,
        JsValue previousTarget,
        JsValue previousWindow,
        JsValue previousSelf,
        JsValue previousFrames,
        JsValue previousParent,
        JsValue previousTop,
        JsValue previousDocument,
        JsValue previousLocation,
        Uri previousBaseUri,
        Uri previousParentBaseUri)
    {
        _activeWindowEventListeners = previousListeners;
        _activeWindowEventTarget = previousTarget;
        _currentBaseUri = previousBaseUri;
        _activeParentBaseUri = previousParentBaseUri;
        RestoreGlobalValue("window", previousWindow);
        RestoreGlobalValue("self", previousSelf);
        RestoreGlobalValue("frames", previousFrames);
        RestoreGlobalValue("parent", previousParent);
        RestoreGlobalValue("top", previousTop);
        RestoreGlobalValue("document", previousDocument);
        RestoreGlobalValue("location", previousLocation);
    }

    private void RestoreGlobalValue(string name, JsValue value)
    {
        if (value.Tag != JsValueTag.Undefined)
        {
            _interpreter.RegisterGlobalValue(name, value);
        }
    }

    private List<BrowserEventListener> GetActiveWindowEventListeners()
    {
        return _activeWindowEventListeners ?? _windowEventListeners;
    }

    private FenJsWindowCallbackContext CaptureActiveWindowCallbackContext()
    {
        var target = GetActiveWindowEventTarget();
        if (target.Tag != JsValueTag.Object)
        {
            return null;
        }

        return new FenJsWindowCallbackContext(target, GetActiveWindowEventListeners());
    }

    private JsValue GetActiveWindowEventTarget()
    {
        if (_activeWindowEventTarget.Tag != JsValueTag.Undefined)
        {
            return _activeWindowEventTarget;
        }

        return _fenJsGlobalThis.Tag == JsValueTag.Undefined
            ? EvaluateWithFenJsRaw("window")
            : _fenJsGlobalThis;
    }

    // A job is "long" once it outlives this; both the progress probe and the
    // completion line key off the same number so a run can be read as pairs.
    private const int LongRunningProbeDueMs = 2_000;
    private const int LongRunningProbePeriodMs = 5_000;
    private static readonly bool IsFenJsDeepTraceEnabled = string.Equals(
        Environment.GetEnvironmentVariable("FEN_FENJS_DEEP_TRACE"),
        "1",
        StringComparison.Ordinal);

    private JsValue CreateTopWindowPostMessageFunction()
    {
        return _interpreter.AllocateNativeFunction(
            "postMessage",
            (_, args) =>
            {
                var data = args.Count > 0 ? args[0] : JsValue.Undefined;
                ReadPostMessageTarget(args, out var targetOrigin, out var ports);
                var sourceWindow = GetActiveWindowEventTarget();
                QueueWindowMessage(
                    _fenJsGlobalThis,
                    _windowEventListeners,
                    data,
                    sourceWindow,
                    ports,
                    targetOrigin,
                    GetTopWindowDeliveryOrigin());
                return JsValue.Undefined;
            },
            length: 1);
    }

    /// <summary>
    /// Creates a postMessage function for a cross-origin iframe's parent/top facade.
    /// Routes messages to the parent realm (_parentRealmOwner) instead of the current realm.
    /// This enables reCAPTCHA anchor frame to notify parent page of checkbox clicks.
    /// </summary>
    private JsValue CreateParentFacadePostMessageFunction(FenJsBrowserScriptEngine parentRealm)
    {
        return _interpreter.AllocateNativeFunction(
            "postMessage",
            (_, args) =>
            {
                var data = args.Count > 0 ? args[0] : JsValue.Undefined;
                ReadPostMessageTarget(args, out var targetOrigin, out var ports);
                var sourceWindow = GetActiveWindowEventTarget();
                
                if (DiagnosticPaths.IframeDiagnosticsEnabled)
                {
                    var dataStr = data.ToString();
                    if (dataStr.Length > 200) dataStr = dataStr.Substring(0, 200) + "...";
                    var portsCount = ports.Tag == JsValueTag.Object ? 1 : 0;
                    DiagnosticPaths.AppendLogText(
                        "iframe_diagnostics.txt",
                        $"{DateTimeOffset.UtcNow:O} CreateParentFacadePostMessageFunction (iframe->parent): data={dataStr} targetOrigin={targetOrigin} ports={portsCount} embeddingFrame={_embeddingFrameElement?.TagName ?? "null"} parentRealm={parentRealm != null}");
                }
                
                // Route to parent realm if available (cross-origin iframe -> parent)
                if (parentRealm != null)
                {
                    parentRealm.QueueCrossRealmMessage(() => parentRealm.QueueMessageFromChildFrame(
                        _embeddingFrameElement!,
                        ConvertJsValueToObject(data),
                        GetCurrentWindowOrigin(),
                        targetOrigin,
                        ExtractTransferredMessagePorts(ports)));
                    return JsValue.Undefined;
                }
                // Fallback: same behavior as top window postMessage
                QueueWindowMessage(
                    _fenJsGlobalThis,
                    _windowEventListeners,
                    data,
                    sourceWindow,
                    ports,
                    targetOrigin,
                    GetTopWindowDeliveryOrigin());
                return JsValue.Undefined;
            },
            length: 1);
    }

    private string GetTopWindowDeliveryOrigin()
    {
        if (_activeParentBaseUri != null)
        {
            return NormalizePostMessageOrigin(_activeParentBaseUri.AbsoluteUri);
        }

        return null;
    }

    private void InstallTopWindowPostMessageBridge(JsValue globalThisValue)
    {
        var topWindowPostMessage = CreateTopWindowPostMessageFunction();
        _interpreter.RegisterGlobalValue("postMessage", topWindowPostMessage);
        if (globalThisValue.Tag == JsValueTag.Object)
        {
            _interpreter.SetObjectProperty(globalThisValue, "postMessage", topWindowPostMessage);
        }
    }

    private List<BrowserEventListener> GetIFrameWindowListeners(Element iframe)
    {
        return _iframeWindowEventListeners.GetOrCreateValue(iframe);
    }

    private static Element TryGetFrameElementForDocument(Document document)
    {
        return document?.ParentNode is Element element && IsIFrameElement(element)
            ? element
            : null;
    }

    private sealed class WindowContextScope : IDisposable
    {
        private FenJsBrowserScriptEngine _owner;
        private readonly List<BrowserEventListener> _previousListeners;
        private readonly JsValue _previousTarget;
        private readonly JsValue _previousWindow;
        private readonly JsValue _previousSelf;
        private readonly JsValue _previousFrames;
        private readonly JsValue _previousParent;
        private readonly JsValue _previousTop;
        private readonly JsValue _previousDocument;
        private readonly JsValue _previousLocation;
        private readonly Uri _previousBaseUri;
        private readonly Uri _previousParentBaseUri;

        public WindowContextScope(
            FenJsBrowserScriptEngine owner,
            List<BrowserEventListener> previousListeners,
            JsValue previousTarget,
            JsValue previousWindow,
            JsValue previousSelf,
            JsValue previousFrames,
            JsValue previousParent,
            JsValue previousTop,
            JsValue previousDocument,
            JsValue previousLocation,
            Uri previousBaseUri,
            Uri previousParentBaseUri)
        {
            _owner = owner;
            _previousListeners = previousListeners;
            _previousTarget = previousTarget;
            _previousWindow = previousWindow;
            _previousSelf = previousSelf;
            _previousFrames = previousFrames;
            _previousParent = previousParent;
            _previousTop = previousTop;
            _previousDocument = previousDocument;
            _previousLocation = previousLocation;
            _previousBaseUri = previousBaseUri;
            _previousParentBaseUri = previousParentBaseUri;
        }

        public void Dispose()
        {
            var owner = _owner;
            _owner = null;
            owner?.RestoreWindowContext(
                _previousListeners,
                _previousTarget,
                _previousWindow,
                _previousSelf,
                _previousFrames,
                _previousParent,
                _previousTop,
                _previousDocument,
                _previousLocation,
                _previousBaseUri,
                _previousParentBaseUri);
        }
    }

    private sealed class FenJsWindowCallbackContext
    {
        public FenJsWindowCallbackContext(JsValue windowTarget, List<BrowserEventListener> windowListeners)
        {
            WindowTarget = windowTarget;
            WindowListeners = windowListeners;
        }

        public JsValue WindowTarget { get; }
        public List<BrowserEventListener> WindowListeners { get; }
    }

    private void InstallFenJsDomGlobals(Node domRoot, Uri baseUri)
    {
        // The DOM globals are built bottom-up (navigator/location/history
        // facades, seeded property bags, native constructors) and each
        // intermediate lives only in a CLR local until the call that links it
        // into the rooted global object. Any allocation in between - the next
        // facade, a property-name intern - can collect, sweeping a cell whose
        // handle the builder is still holding. Pin everything allocated for the
        // duration of the install; the window releases them once the graph
        // hangs off the global.
        using var constructionWindow = _interpreter.Heap.BeginConstructionWindow();

        var document = domRoot as Document ?? domRoot.OwnerDocument;
        var navigator = CreateNavigatorHost();
        var location = new FenJsLocationHost(baseUri ?? TryCreateUri(document?.URL));
        var history = new FenJsHistoryHost(location);
        // Always bind the host hooks so _owner is set â€” even if there's no
        // document, host-property resolution must not NRE when it looks up
        // _owner._interpreter.  Without this, a page that triggers a recascade
        // before the DOM is fully attached leaves the hooks orphaned.
        _hostHooks.Bind(
            this,
            document,
            navigator,
            location,
            baseUri ?? TryCreateUri(document?.URL));

        if (document == null)
        {
            return;
        }

        _interpreter.RegisterGlobalHostObject("document", RegisterHostObject(document, HostObjectKind.DomDocument));
        _interpreter.RegisterGlobalHostObject("navigator", RegisterHostObject(navigator, HostObjectKind.Other));
        _interpreter.RegisterGlobalValue(
            "__fenDispatchMessagePort",
            _interpreter.AllocateNativeFunction(
                "__fenDispatchMessagePort",
                (_, args) =>
                {
                    var windowTarget = args.Count > 0 ? args[0] : JsValue.Undefined;
                    var callback = args.Count > 1 ? args[1] : JsValue.Undefined;
                    var callbackThis = args.Count > 2 ? args[2] : JsValue.Undefined;
                    var eventValue = args.Count > 3 ? args[3] : JsValue.Undefined;
                    if (!_interpreter.CanCallValue(callback))
                    {
                        return JsValue.Undefined;
                    }

                    var frameElement = ResolveHostObjectOrNull<Element>(ReadJsProperty(windowTarget, "__fenFrameElement"));
                    var listeners = frameElement == null
                        ? _windowEventListeners
                        : GetIFrameWindowListeners(frameElement);
                    using (ActivateWindowCallbackContext(windowTarget, listeners))
                    {
                        _interpreter.InvokeFunction(callback, new[] { eventValue }, callbackThis);
                    }

                    return JsValue.Undefined;
                },
                length: 4));
        _interpreter.RegisterGlobalValue(
            "__fenRegisterMessageChannel",
            _interpreter.AllocateNativeFunction(
                "__fenRegisterMessageChannel",
                (_, args) => RegisterMessageChannel(args),
                length: 2));
        _interpreter.RegisterGlobalValue(
            "__fenPostMessagePort",
            _interpreter.AllocateNativeFunction(
                "__fenPostMessagePort",
                (_, args) => PostMessagePort(args),
                length: 3));
        _interpreter.RegisterGlobalValue(
            "__fenCloseMessagePort",
            _interpreter.AllocateNativeFunction(
                "__fenCloseMessagePort",
                (_, args) => CloseMessagePort(args),
                length: 1));
        // Register a native logging hook that console.log/warn/error forward to.
        // Uses FenLogger so output appears in engine logs and any attached debug console.
        _interpreter.RegisterGlobalValue(
            "__fenLog",
            _interpreter.AllocateNativeFunction(
                "__fenLog",
                (_, args) =>
                {
                    var level = args.Count > 0 ? args[0].AsString() : "log";
                    var msg = args.Count > 1 ? args[1].AsString() : "";
                    var category = LogCategory.JavaScript;
                    // Tag WhatsApp diagnostic messages so they surface even when
                    // JavaScript logging is filtered out.
                    if (msg.StartsWith("[IDB]") || msg.StartsWith("[WhatsApp]"))
                        category |= LogCategory.WhatsApp;
                    switch (level)
                    {
                        case "error":
                            FenLogger.Error($"[JS:{level}] {msg}", category);
                            break;
                        case "warn":
                            FenLogger.Warn($"[JS:{level}] {msg}", category);
                            break;
                        default:
                            FenLogger.Info($"[JS:{level}] {msg}", category);
                            break;
                    }
                    _host.Log(msg);
                    return JsValue.Undefined;
                },
                length: 2));

        // â”€â”€ DOMParser parse bridge â”€â”€
        // Parses XML (or HTML for the text/html MIME type) into a wrapped V2
        // Document host object. Malformed XML returns a <parsererror> error
        // document instead of throwing, matching browser-observable behavior.
        _interpreter.RegisterGlobalValue(
            "__fenParseDocument",
            _interpreter.AllocateNativeFunction(
                "__fenParseDocument",
                (_, args) =>
                {
                    var source = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                    var mimeType = args.Count > 1 ? CoerceToHostString(args[1]) : "application/xml";

                    Document parsedDocument;
                    if (string.Equals(mimeType, "text/html", StringComparison.OrdinalIgnoreCase))
                    {
                        var baseUri = _currentBaseUri ?? new Uri("about:blank");
                        parsedDocument = new HtmlParser(source, baseUri).Parse();
                    }
                    else
                    {
                        parsedDocument = XmlDomParser.ParseWithErrorDocument(source);
                    }

                    return ToHostOrNull(parsedDocument, HostObjectKind.DomDocument);
                },
                length: 2));

        // â”€â”€ IndexedDB persistence bridge â”€â”€
        // Register C# native functions that the JS IDB implementation calls for
        // persistent storage. The JS side falls back to in-memory when these are
        // unavailable, so registration failures are non-fatal.
        var idbBackend = IndexedDbBackend;
        if (idbBackend != null)
        {
            var idbOrigin = _currentBaseUri != null
                ? $"{_currentBaseUri.Scheme}://{_currentBaseUri.Host}"
                : "https://web.whatsapp.com";

            _interpreter.RegisterGlobalValue(
                "__fenIdbLoad",
                _interpreter.AllocateNativeFunction(
                    "__fenIdbLoad",
                    (_, args) =>
                    {
                        var dbName = args.Count > 0 ? args[0].AsString() : "default";
                        try
                        {
                            var info = idbBackend.GetDatabaseInfo(idbOrigin, dbName)
                                .GetAwaiter().GetResult();
                            if (info == null || info.ObjectStoreNames.Count == 0)
                                return JsValue.FromString("");
                            // Rebuild a JSON snapshot of all stores
                            var snapshot = new Dictionary<string, object>();
                            foreach (var storeName in info.ObjectStoreNames)
                            {
                                var data = idbBackend.GetAll(idbOrigin, dbName, storeName)
                                    .GetAwaiter().GetResult();
                                var dict = new Dictionary<string, object>();
                                int idx = 0;
                                foreach (var val in data)
                                {
                                    dict[idx.ToString()] = val;
                                    idx++;
                                }
                                snapshot[dbName + "\0" + storeName] = new Dictionary<string, object>
                                {
                                    ["_data"] = dict,
                                    ["_indexes"] = new Dictionary<string, object>(),
                                    ["_keyPath"] = (object)null
                                };
                            }
                            var json = JsonSerializer.Serialize(snapshot);
                            FenLogger.Info($"[IDB] Loaded {info.ObjectStoreNames.Count} stores from '{dbName}'", LogCategory.WhatsApp);
                            return JsValue.FromString(json);
                        }
                        catch (Exception ex)
                        {
                            FenLogger.Warn($"[IDB] Load failed for '{dbName}': {ex.Message}", LogCategory.WhatsApp);
                            return JsValue.FromString("");
                        }
                    },
                    length: 1));

            _interpreter.RegisterGlobalValue(
                "__fenIdbPut",
                _interpreter.AllocateNativeFunction(
                    "__fenIdbPut",
                    (_, args) =>
                    {
                        var dbName = args.Count > 0 ? args[0].AsString() : "default";
                        var storeName = args.Count > 1 ? args[1].AsString() : "store";
                        var key = args.Count > 2 ? args[2].AsString() : "0";
                        var jsonValue = args.Count > 3 ? args[3].AsString() : "{}";
                        try
                        {
                            idbBackend.Put(idbOrigin, dbName, storeName, key, jsonValue)
                                .GetAwaiter().GetResult();
                            return JsValue.FromBoolean(true);
                        }
                        catch (Exception ex)
                        {
                            FenLogger.Warn($"[IDB] Put failed for '{dbName}/{storeName}': {ex.Message}", LogCategory.WhatsApp);
                            return JsValue.FromBoolean(false);
                        }
                    },
                    length: 4));

            _interpreter.RegisterGlobalValue(
                "__fenIdbDelete",
                _interpreter.AllocateNativeFunction(
                    "__fenIdbDelete",
                    (_, args) =>
                    {
                        var dbName = args.Count > 0 ? args[0].AsString() : "default";
                        var storeName = args.Count > 1 ? args[1].AsString() : "store";
                        var key = args.Count > 2 ? args[2].AsString() : "";
                        try
                        {
                            idbBackend.Delete(idbOrigin, dbName, storeName, key)
                                .GetAwaiter().GetResult();
                            return JsValue.FromBoolean(true);
                        }
                        catch (Exception ex)
                        {
                            FenLogger.Warn($"[IDB] Delete failed for '{dbName}/{storeName}': {ex.Message}", LogCategory.WhatsApp);
                            return JsValue.FromBoolean(false);
                        }
                    },
                    length: 3));

            _interpreter.RegisterGlobalValue(
                "__fenIdbDeleteDatabase",
                _interpreter.AllocateNativeFunction(
                    "__fenIdbDeleteDatabase",
                    (_, args) =>
                    {
                        var dbName = args.Count > 0 ? args[0].AsString() : "default";
                        try
                        {
                            idbBackend.DeleteDatabase(idbOrigin, dbName)
                                .GetAwaiter().GetResult();
                            return JsValue.FromBoolean(true);
                        }
                        catch (Exception ex)
                        {
                            FenLogger.Warn($"[IDB] DeleteDatabase failed for '{dbName}': {ex.Message}", LogCategory.WhatsApp);
                            return JsValue.FromBoolean(false);
                        }
                    },
                    length: 1));
        }

