        // Border from Thickness + Brush
        var bt = cs.BorderThickness;
        if (bt.Left != 0 || bt.Right != 0 || bt.Top != 0 || bt.Bottom != 0)
        {
            props["border-top-width"] = JsValue.FromString(bt.Top + "px");
            props["border-right-width"] = JsValue.FromString(bt.Right + "px");
            props["border-bottom-width"] = JsValue.FromString(bt.Bottom + "px");
            props["border-left-width"] = JsValue.FromString(bt.Left + "px");
        }
        if (cs.BorderBrush.HasValue)
            props["border-top-color"] = JsValue.FromString(SerializeComputedColor(cs.BorderBrush.Value));

        // Margin/padding shorthand (from Map if not explicit)
        props["margin-top"] = JsValue.FromString(cs.Margin.Top + "px");
        props["margin-right"] = JsValue.FromString(cs.Margin.Right + "px");
        props["margin-bottom"] = JsValue.FromString(cs.Margin.Bottom + "px");
        props["margin-left"] = JsValue.FromString(cs.Margin.Left + "px");
        props["padding-top"] = JsValue.FromString(cs.Padding.Top + "px");
        props["padding-right"] = JsValue.FromString(cs.Padding.Right + "px");
        props["padding-bottom"] = JsValue.FromString(cs.Padding.Bottom + "px");
        props["padding-left"] = JsValue.FromString(cs.Padding.Left + "px");

        // Custom properties (CSS variables)
        if (cs.CustomProperties != null)
        {
            foreach (var kv in cs.CustomProperties)
            {
                var propName = kv.Key.StartsWith("--") ? kv.Key : "--" + kv.Key;
                if (!props.ContainsKey(propName))
                    props[propName] = JsValue.FromString(kv.Value ?? string.Empty);
            }
        }

        // CSSOM reads are synchronous. Inline mutations must be observable through
        // getComputedStyle immediately, even while the asynchronous recascade/layout
        // requested by the mutation is still pending.
        foreach (var declaration in (element.GetAttribute("style") ?? string.Empty)
            .Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var colonIndex = declaration.IndexOf(':');
            if (colonIndex <= 0)
            {
                continue;
            }

            var name = declaration[..colonIndex].Trim();
            var inlineValue = declaration[(colonIndex + 1)..].Trim();
            if (name.Length == 0)
            {
                continue;
            }

            var importantIndex = inlineValue.LastIndexOf("!important", StringComparison.OrdinalIgnoreCase);
            if (importantIndex >= 0)
            {
                inlineValue = inlineValue[..importantIndex].TrimEnd();
            }

            props[name] = JsValue.FromString(inlineValue);
        }

        ResolveComputedInsets(element, cs, props);
        ResolveComputedSizes(element, props);

        // CSSOM §6.7.3: every property is readable both as its dashed name
        // (getPropertyValue / bracket access) and as the camel-cased IDL
        // attribute, plus cssFloat for float. Everything above wrote dashed
        // names, so mirror each one here rather than at every write site.
        foreach (var dashed in props.Keys.ToArray())
        {
            if (dashed.StartsWith("--", StringComparison.Ordinal) || dashed.IndexOf('-') < 0)
            {
                continue;
            }

            var camel = CssPropToCamel(dashed);
            props[camel] = props[dashed];
        }

        if (props.TryGetValue("float", out var floatValue))
        {
            props["cssFloat"] = floatValue;
        }

        ResolveComputedCustomProperties(props);

        return CreateComputedStyleObject(props);
    }

    // CSS Variables 1 §3: a custom property's computed value is its specified
    // value with every var() substituted. The cascade keeps custom properties as
    // authored, so getComputedStyle substitutes here, and only for the ones that
    // hold a var().
    private static void ResolveComputedCustomProperties(Dictionary<string, JsValue> props)
    {
        List<string> pending = null;
        foreach (var (key, value) in props)
        {
            if (key.StartsWith("--", StringComparison.Ordinal) &&
                value.Tag == JsValueTag.String &&
                value.AsString().Contains("var(", StringComparison.OrdinalIgnoreCase))
            {
                (pending ??= new List<string>()).Add(key);
            }
        }

        if (pending == null)
        {
            return;
        }

        var resolved = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var key in pending)
        {
            resolved[key] = SubstituteCustomPropertyReferences(
                props[key].AsString(), props, new HashSet<string>(StringComparer.Ordinal) { key });
        }

        foreach (var (key, value) in resolved)
        {
            props[key] = JsValue.FromString(value);
        }
    }

    // A comment directly before a var() serialises as the empty comment, and two
    // adjacent var()s are kept apart by one, so that substitution cannot glue their
    // tokens together (CSS Syntax 3 §9, the serialisation pairs table).
    private static readonly System.Text.RegularExpressions.Regex CommentBeforeVar = new(@"/\*.*?\*/\s*(?=var\()", System.Text.RegularExpressions.RegexOptions.Compiled | System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Singleline);
    private static readonly System.Text.RegularExpressions.Regex AdjacentVars = new(@"\)\s*(?=var\()", System.Text.RegularExpressions.RegexOptions.Compiled | System.Text.RegularExpressions.RegexOptions.IgnoreCase);
    private static readonly System.Text.RegularExpressions.Regex RepeatedEmptyComments = new(@"(/\*\*/)+", System.Text.RegularExpressions.RegexOptions.Compiled);

    private static string SubstituteCustomPropertyReferences(string raw, Dictionary<string, JsValue> props, HashSet<string> referencing)
    {
        var text = AdjacentVars.Replace(CommentBeforeVar.Replace(raw, "/**/"), ")/**/");
        var output = new StringBuilder(text.Length);
        int i = 0;
        while (i < text.Length)
        {
            int start = text.IndexOf("var(", i, StringComparison.OrdinalIgnoreCase);
            if (start < 0 || !TryReadVarFunction(text, start, out var end, out var name, out var fallback))
            {
                output.Append(text, i, text.Length - i);
                break;
            }

            output.Append(text, i, start - i);
            var value = ResolveCustomPropertyReference(name, fallback, props, referencing);
            output.Append(value);

            // Keep an ident or number that follows from merging into the value's last token.
            if (end < text.Length && value.Length > 0 &&
                char.IsLetterOrDigit(value[^1]) && char.IsLetterOrDigit(text[end]))
            {
                output.Append("/**/");
            }

            i = end;
        }

        return RepeatedEmptyComments.Replace(output.ToString(), "/**/");
    }

    // var( <custom-property-name> [, <declaration-value>? ]? ) starting at `start`;
    // `end` is the index after its closing parenthesis. Parentheses in the fallback
    // nest, and a quoted string may hold any of them.
    private static bool TryReadVarFunction(string text, int start, out int end, out string name, out string fallback)
    {
        end = -1;
        name = null;
        fallback = null;
        int depth = 1, comma = -1;
        char quote = '\0';
        for (int j = start + 4; j < text.Length; j++)
        {
            char c = text[j];
            if (quote != '\0')
            {
                if (c == '\\') j++;
                else if (c == quote) quote = '\0';
                continue;
            }

            if (c == '"' || c == '\'') quote = c;
            else if (c == '(') depth++;
            else if (c == ',' && depth == 1 && comma < 0) comma = j;
            else if (c == ')' && --depth == 0)
            {
                end = j + 1;
                int nameEnd = comma >= 0 ? comma : j;
                name = text.Substring(start + 4, nameEnd - start - 4).Trim();
                fallback = comma >= 0 ? text.Substring(comma + 1, j - comma - 1).Trim() : null;
                return name.StartsWith("--", StringComparison.Ordinal);
            }
        }

        return false;
    }

    private static string ResolveCustomPropertyReference(
        string name, string fallback, Dictionary<string, JsValue> props, HashSet<string> referencing)
    {
        string value;
        if (!referencing.Contains(name) && props.TryGetValue(name, out var stored) && stored.Tag == JsValueTag.String)
        {
            value = stored.AsString();
            if (value.Contains("var(", StringComparison.OrdinalIgnoreCase))
            {
                value = SubstituteCustomPropertyReferences(value, props, new HashSet<string>(referencing, StringComparer.Ordinal) { name });
            }
        }
        else
        {
            // Undefined or part of a cycle: the fallback, itself substituted, or nothing.
            value = fallback == null ? string.Empty
                : fallback.Contains("var(", StringComparison.OrdinalIgnoreCase)
                    ? SubstituteCustomPropertyReferences(fallback, props, referencing)
                    : fallback;
        }

        return StripTrailingComment(value);
    }

    // A comment ending the substituted value is dropped; one inside a string is kept.
    private static string StripTrailingComment(string value)
    {
        var trimmed = value.TrimEnd();
        if (!trimmed.EndsWith("*/", StringComparison.Ordinal))
        {
            return value;
        }

        int commentStart = trimmed.LastIndexOf("/*", trimmed.Length - 2, StringComparison.Ordinal);
        if (commentStart < 0)
        {
            return value;
        }

        char quote = '\0';
        for (int k = 0; k < commentStart; k++)
        {
            char c = trimmed[k];
            if (quote != '\0') { if (c == quote) quote = '\0'; }
            else if (c == '"' || c == '\'') quote = c;
        }

        return quote == '\0' ? trimmed[..commentStart].TrimEnd() : value;
    }

    /// <summary>
    /// CSSOM §4.3 serialization of a computed color: rgb(r, g, b) when opaque,
    /// rgba(r, g, b, a) with a decimal alpha otherwise.
    /// </summary>
    private static string SerializeComputedColor(SKColor color)
    {
        if (color.Alpha == 255)
        {
            return string.Create(CultureInfo.InvariantCulture, $"rgb({color.Red}, {color.Green}, {color.Blue})");
        }

        var alpha = Math.Round(color.Alpha / 255d, 3);
        return string.Create(CultureInfo.InvariantCulture, $"rgba({color.Red}, {color.Green}, {color.Blue}, {alpha})");
    }

    private JsValue CreateComputedStyleObject(Dictionary<string, JsValue> props)
    {
        props ??= new Dictionary<string, JsValue>(StringComparer.OrdinalIgnoreCase);
        var styleObject = _interpreter.AllocateObject(props);
        _interpreter.SetObjectProperty(
            styleObject,
            "getPropertyValue",
            _interpreter.AllocateNativeFunction(
                "getPropertyValue",
                (_, propertyArgs) =>
                {
                    var propertyName = propertyArgs.Count > 0 ? CoerceToHostString(propertyArgs[0]) : string.Empty;
                    if (string.IsNullOrWhiteSpace(propertyName))
                    {
                        return JsValue.FromString(string.Empty);
                    }

                    if (props.TryGetValue(propertyName, out var directValue))
                    {
                        return directValue;
                    }

                    var kebabName = CamelToCssProp(propertyName);
                    if (!string.Equals(kebabName, propertyName, StringComparison.Ordinal) &&
                        props.TryGetValue(kebabName, out var kebabValue))
                    {
                        return kebabValue;
                    }

                    var camelName = CssPropToCamel(propertyName);
                    if (!string.Equals(camelName, propertyName, StringComparison.Ordinal) &&
                        props.TryGetValue(camelName, out var camelValue))
                    {
                        return camelValue;
                    }

                    return JsValue.FromString(string.Empty);
                },
                length: 1),
            enumerable: true);
        return styleObject;
    }

    private JsValue ExecuteSynchronousXmlHttpRequest(IReadOnlyList<JsValue> args)
    {
        var methodText = args.Count > 0 ? CoerceToHostString(args[0]) : "GET";
        var urlText = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
        var bodyValue = args.Count > 2 ? args[2] : JsValue.FromString(string.Empty);
        var isBinaryBody = args.Count > 4 && args[4].Tag == JsValueTag.Boolean && args[4].AsBoolean();

        if (FetchHandler == null || !TryResolveUri(urlText, _currentBaseUri, out var requestUri))
        {
            return CreateXhrResult(0, "Network Error", string.Empty);
        }

        try
        {
            using var request = new HttpRequestMessage(new HttpMethod(string.IsNullOrWhiteSpace(methodText) ? "GET" : methodText.ToUpperInvariant()), requestUri);
            if (_currentBaseUri != null)
            {
                request.Headers.Referrer = _currentBaseUri;
                if (!CorsHandler.IsSameOrigin(requestUri, _currentBaseUri))
                {
                    var origin = CorsHandler.SerializeOrigin(new UriBuilder(
                        _currentBaseUri.Scheme,
                        _currentBaseUri.Host,
                        _currentBaseUri.IsDefaultPort ? -1 : _currentBaseUri.Port).Uri);
                    if (!string.IsNullOrWhiteSpace(origin))
                    {
                        request.Headers.TryAddWithoutValidation("Origin", origin);
                    }
                }
            }

            if (!string.Equals(request.Method.Method, "GET", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(request.Method.Method, "HEAD", StringComparison.OrdinalIgnoreCase))
            {
                request.Content = CreateRequestContent(bodyValue, isBinaryBody);
            }

            if (args.Count > 3 && args[3].Tag == JsValueTag.Object)
            {
                ApplyXhrRequestHeaders(request, args[3]);
            }

            using var response = FetchHandler(request).GetAwaiter().GetResult();
            var responseText = response.Content?.ReadAsStringAsync().GetAwaiter().GetResult() ?? string.Empty;
            return CreateXhrResult((int)response.StatusCode, response.ReasonPhrase ?? string.Empty, responseText);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] XMLHttpRequest failed for '{requestUri}': {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            return CreateXhrResult(0, "Network Error", string.Empty);
        }
    }

    /// <summary>
    /// Fetch §"fetch(input, init)": the request goes out on a background task
    /// and the response is delivered to <c>onDone</c> as a later task on the
    /// script thread. Blocking the script thread on the network (the old
    /// __fenSyncFetch) stalled every page that fetched while other loads needed
    /// the script thread, and deadlocked github.com once its images were let in.
    /// Arguments: method, url, body, headers, isBinaryBody, onDone(result).
    /// </summary>
    private JsValue StartAsynchronousFetchRequest(IReadOnlyList<JsValue> args)
    {
        var callback = args.Count > 5 ? args[5] : JsValue.Undefined;
        if (!_interpreter.CanCallValue(callback))
        {
            return JsValue.Undefined;
        }

        var methodText = args.Count > 0 ? CoerceToHostString(args[0]) : "GET";
        var urlText = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
        var bodyValue = args.Count > 2 ? args[2] : JsValue.FromString(string.Empty);
        var isBinaryBody = args.Count > 4 && args[4].Tag == JsValueTag.Boolean && args[4].AsBoolean();

        // The callback and its receiver stay rooted until the completion runs.
        var pin = PinFenJsValues(callback);

        void Deliver(int status, string statusText, string text, string url, HttpResponseMessage response, byte[] bytes, HttpRequestMessage request)
        {
            QueueOnDeliveryTail(() =>
            {
                try
                {
                    using (ScriptEngineLockProbe.Hold(_fenJsLock))
                    {
                        var result = CreateFetchResult(status, statusText, text, url, response, bytes);
                        TryInvokeFenJsEventCallback(callback, _fenJsGlobalThis, result, "fetch");
                        _interpreter.PumpMicrotasks();
                    }
                }
                finally
                {
                    pin.Dispose();
                    response?.Dispose();
                    request?.Dispose();
                }
            }, "fetch completion failed");
        }

        if (FetchHandler == null || !TryResolveUri(urlText, _currentBaseUri, out var requestUri))
        {
            Deliver(0, "Network Error", string.Empty, urlText ?? string.Empty, null, null, null);
            return JsValue.Undefined;
        }

        HttpRequestMessage request;
        try
        {
            request = new HttpRequestMessage(new HttpMethod(string.IsNullOrWhiteSpace(methodText) ? "GET" : methodText.ToUpperInvariant()), requestUri);
            request.Headers.TryAddWithoutValidation("Sec-Fetch-Dest", "empty");
            request.Headers.TryAddWithoutValidation("Sec-Fetch-Mode", "cors");
            if (_currentBaseUri != null)
            {
                request.Headers.Referrer = _currentBaseUri;
                if (!CorsHandler.IsSameOrigin(requestUri, _currentBaseUri))
                {
                    var origin = CorsHandler.SerializeOrigin(new UriBuilder(
                        _currentBaseUri.Scheme,
                        _currentBaseUri.Host,
                        _currentBaseUri.IsDefaultPort ? -1 : _currentBaseUri.Port).Uri);
                    if (!string.IsNullOrWhiteSpace(origin))
                    {
                        request.Headers.TryAddWithoutValidation("Origin", origin);
                    }
                }
            }

            if (!string.Equals(request.Method.Method, "GET", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(request.Method.Method, "HEAD", StringComparison.OrdinalIgnoreCase))
            {
                request.Content = CreateRequestContent(bodyValue, isBinaryBody);
            }

            if (args.Count > 3 && args[3].Tag == JsValueTag.Object)
            {
                ApplyXhrRequestHeaders(request, args[3]);
            }
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] fetch could not build request for '{requestUri}': {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            Deliver(0, "Network Error", string.Empty, requestUri.ToString(), null, null, null);
            return JsValue.Undefined;
        }

        var handler = FetchHandler;
        _ = Task.Run(async () =>
        {
            HttpResponseMessage response = null;
            try
            {
                response = await handler(request).ConfigureAwait(false);
                var bytes = response.Content != null
                    ? await response.Content.ReadAsByteArrayAsync().ConfigureAwait(false)
                    : Array.Empty<byte>();
                var text = DecodeResponseText(bytes, response.Content?.Headers?.ContentType?.CharSet);
                Deliver(
                    (int)response.StatusCode,
                    response.ReasonPhrase ?? string.Empty,
                    text,
                    response.RequestMessage?.RequestUri?.ToString() ?? requestUri.ToString(),
                    response,
                    bytes,
                    request);
            }
            catch (Exception ex)
            {
                FenBrowser.Core.EngineLogCompat.Warn(
                    $"[FenJsBridge] fetch failed for '{requestUri}': {ex.Message}",
                    FenBrowser.Core.Logging.LogCategory.JavaScript);
                Deliver(0, "Network Error", string.Empty, requestUri.ToString(), response, null, request);
            }
        });

        return JsValue.Undefined;
    }

    private JsValue ExecuteSynchronousFetchRequest(IReadOnlyList<JsValue> args)
    {
        var methodText = args.Count > 0 ? CoerceToHostString(args[0]) : "GET";
        var urlText = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
        var bodyValue = args.Count > 2 ? args[2] : JsValue.FromString(string.Empty);
        var isBinaryBody = args.Count > 4 && args[4].Tag == JsValueTag.Boolean && args[4].AsBoolean();

        if (FetchHandler == null || !TryResolveUri(urlText, _currentBaseUri, out var requestUri))
        {
            return CreateFetchResult(0, "Network Error", string.Empty, string.Empty, null);
        }

        try
        {
            using var request = new HttpRequestMessage(new HttpMethod(string.IsNullOrWhiteSpace(methodText) ? "GET" : methodText.ToUpperInvariant()), requestUri);
            request.Headers.TryAddWithoutValidation("Sec-Fetch-Dest", "empty");
            request.Headers.TryAddWithoutValidation("Sec-Fetch-Mode", "cors");
            if (_currentBaseUri != null)
            {
                request.Headers.Referrer = _currentBaseUri;
                if (!CorsHandler.IsSameOrigin(requestUri, _currentBaseUri))
                {
                    var origin = CorsHandler.SerializeOrigin(new UriBuilder(
                        _currentBaseUri.Scheme,
                        _currentBaseUri.Host,
                        _currentBaseUri.IsDefaultPort ? -1 : _currentBaseUri.Port).Uri);
                    if (!string.IsNullOrWhiteSpace(origin))
                    {
                        request.Headers.TryAddWithoutValidation("Origin", origin);
                    }
                }
            }

            if (!string.Equals(request.Method.Method, "GET", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(request.Method.Method, "HEAD", StringComparison.OrdinalIgnoreCase))
            {
                request.Content = CreateRequestContent(bodyValue, isBinaryBody);
            }

            if (args.Count > 3 && args[3].Tag == JsValueTag.Object)
            {
                ApplyXhrRequestHeaders(request, args[3]);
            }

            using var response = FetchHandler(request).GetAwaiter().GetResult();
            // Fetch §"body": the body is bytes; text() decodes them and arrayBuffer()
            // hands them over as they are. Reading only a string lost every binary
            // response (a font, a model, a wasm module) to UTF-8 replacement.
            var responseBytes = response.Content?.ReadAsByteArrayAsync().GetAwaiter().GetResult() ?? Array.Empty<byte>();
            var responseText = DecodeResponseText(responseBytes, response.Content?.Headers?.ContentType?.CharSet);
            return CreateFetchResult(
                (int)response.StatusCode,
                response.ReasonPhrase ?? string.Empty,
                responseText,
                response.RequestMessage?.RequestUri?.ToString() ?? requestUri.ToString(),
                response,
                responseBytes);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] fetch failed for '{requestUri}': {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            return CreateFetchResult(0, "Network Error", string.Empty, requestUri.ToString(), null);
        }
    }

    private void ApplyXhrRequestHeaders(HttpRequestMessage request, JsValue headersValue)
    {
        if (headersValue.Tag != JsValueTag.Object)
        {
            return;
        }

        var headersObject = _interpreter.Heap.GetObject(headersValue.AsObjectHandle());
        var context = (IBuiltinContext)_interpreter;
        foreach (var property in headersObject.EnumerateOwnProperties())
        {
            var name = property.Key;
            if (string.IsNullOrWhiteSpace(name))
            {
                continue;
            }

            if (!context.TryGetPropertyValue(headersObject, headersValue, name, out var value) ||
                value.Tag == JsValueTag.Undefined ||
                value.Tag == JsValueTag.Null)
            {
                continue;
            }

            var headerValue = CoerceToHostString(value);
            if (string.Equals(name, "Content-Type", StringComparison.OrdinalIgnoreCase) && request.Content != null)
            {
                if (System.Net.Http.Headers.MediaTypeHeaderValue.TryParse(headerValue, out var mediaType))
                {
                    request.Content.Headers.ContentType = mediaType;
                }
                continue;
            }

            if (!request.Headers.TryAddWithoutValidation(name, headerValue) && request.Content != null)
            {
                request.Content.Headers.TryAddWithoutValidation(name, headerValue);
            }
        }
    }

    private static bool TryResolveUri(string urlText, Uri baseUri, out Uri requestUri)
    {
        requestUri = null;
        if (string.IsNullOrWhiteSpace(urlText))
        {
            return false;
        }

        if (Uri.TryCreate(urlText, UriKind.Absolute, out requestUri))
        {
            return true;
        }

        return baseUri != null && Uri.TryCreate(baseUri, urlText, out requestUri);
    }

    private static string ResolveElementUrlProperty(Element element, string attributeName)
    {
        var raw = element?.GetAttribute(attributeName) ?? string.Empty;
        if (string.IsNullOrWhiteSpace(raw))
        {
            return string.Empty;
        }

        if (Uri.TryCreate(raw, UriKind.Absolute, out var absolute))
        {
            return absolute.AbsoluteUri;
        }

        var ownerDocument = element.OwnerDocument;
        var baseRaw =
            ownerDocument?.BaseURI ??
            ownerDocument?.DocumentURI ??
            ownerDocument?.URL;

        if (Uri.TryCreate(baseRaw, UriKind.Absolute, out var baseUri) &&
            Uri.TryCreate(baseUri, raw, out var resolved))
        {
            return resolved.AbsoluteUri;
        }

        return raw;
    }

    private JsValue CreateXhrResult(int status, string statusText, string responseText)
    {
        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["status"] = JsValue.FromNumber(status),
            ["statusText"] = JsValue.FromString(statusText ?? string.Empty),
            ["responseText"] = JsValue.FromString(responseText ?? string.Empty)
        });
    }

    /// <summary>
    /// Encoding Standard "decode": the declared charset when it names a known
    /// encoding, UTF-8 otherwise, with the BOM stripped.
    /// </summary>
    private static string DecodeResponseText(byte[] bytes, string charset)
    {
        if (bytes == null || bytes.Length == 0)
        {
            return string.Empty;
        }

        System.Text.Encoding encoding = System.Text.Encoding.UTF8;
        if (!string.IsNullOrWhiteSpace(charset))
        {
            try
            {
                encoding = System.Text.Encoding.GetEncoding(charset.Trim().Trim('"'));
            }
            catch (ArgumentException)
            {
                // Unknown label: the Encoding Standard falls back to UTF-8.
            }
        }

        int offset = 0;
        var preamble = encoding.GetPreamble();
        if (preamble.Length > 0 && bytes.Length >= preamble.Length && bytes.AsSpan(0, preamble.Length).SequenceEqual(preamble))
        {
            offset = preamble.Length;
        }

        return encoding.GetString(bytes, offset, bytes.Length - offset);
    }

    private JsValue CreateFetchResult(int status, string statusText, string responseText, string url, HttpResponseMessage response, byte[] responseBytes = null)
    {
        var headers = new Dictionary<string, JsValue>(StringComparer.OrdinalIgnoreCase);
        if (response != null)
        {
            foreach (var header in response.Headers)
            {
                headers[header.Key.ToLowerInvariant()] = JsValue.FromString(string.Join(", ", header.Value));
            }

            if (response.Content != null)
            {
                foreach (var header in response.Content.Headers)
                {
                    headers[header.Key.ToLowerInvariant()] = JsValue.FromString(string.Join(", ", header.Value));
                }
            }
        }

        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["status"] = JsValue.FromNumber(status),
            ["statusText"] = JsValue.FromString(statusText ?? string.Empty),
            ["responseText"] = JsValue.FromString(responseText ?? string.Empty),
            ["responseBytes"] = responseBytes != null && responseBytes.Length > 0
                ? _interpreter.AllocateUint8ArrayFromBytes(responseBytes)
                : JsValue.Null,
            ["url"] = JsValue.FromString(url ?? string.Empty),
            ["headers"] = _interpreter.AllocateObject(headers)
        });
    }

    // â”€â”€ TextEncoder / TextDecoder helpers â”€â”€

    private JsValue CreateUint8ArrayFromBytes(byte[] bytes)
    {
        if (bytes == null) bytes = Array.Empty<byte>();
        // Return a dense integer-indexed array (quacks like Uint8Array enough for
        // indexed access and .length). The WAF challenge uses integer indexing
        // rather than instanceof checks, so this suffices for crypto interop.
        var elements = new JsValue[bytes.Length];
        for (var i = 0; i < bytes.Length; i++)
            elements[i] = JsValue.FromInt32(bytes[i]);
        return _interpreter.AllocateArray(elements);
    }

    /// <summary>
    /// The Blob a blob: URL of this realm names, as bytes and type; null when the URL names
    /// nothing, or a MediaSource. Runs on the realm's thread.
    /// </summary>
    internal (byte[] Bytes, string Type)? ReadBlobUrlBytes(string url)
    {
        if (_interpreter == null || _realmAbandoned || string.IsNullOrEmpty(url))
        {
            return null;
        }

        var reader = ReadGlobalValueOrUndefined("__fenReadBlobUrlBytes");
        if (!_interpreter.CanCallValue(reader))
        {
            return null;
        }

        var result = _interpreter.InvokeFunction(reader, new[] { JsValue.FromString(url) }, JsValue.Undefined);
        if (result.Tag != JsValueTag.Object ||
            !_interpreter.TryGetObjectProperty(result, "bytes", out var bytes) ||
            !_interpreter.TryGetObjectProperty(result, "type", out var type))
        {
            return null;
        }

        return (ExtractBytesFromArrayLike(bytes), type.Tag == JsValueTag.String ? CoerceToHostString(type) : string.Empty);
    }

    private byte[] ExtractBytesFromArrayLike(JsValue value)
    {
        if (value.Tag == JsValueTag.Undefined || value.Tag == JsValueTag.Null)
            return Array.Empty<byte>();
        if (value.Tag != JsValueTag.Object)
            return Array.Empty<byte>();
        try
        {
            var obj = _interpreter.Heap.GetObject(value.AsObjectHandle());
            if (obj == null) return Array.Empty<byte>();
            // A real buffer or view hands its bytes over directly - no per-element
            // property reads and no size cap, which a fetched model or font needs.
            if (obj is FenBrowser.Js.Objects.TypedArrayView view && !view.IsViewDetached && !view.IsViewOutOfBounds())
            {
                return view.Buffer.Data.AsSpan(view.ByteOffset, view.ByteLength).ToArray();
            }
            if (obj is FenBrowser.Js.Objects.ArrayBufferObject buffer && !buffer.IsDetached)
            {
                return buffer.Data.AsSpan(0, buffer.ByteLength).ToArray();
            }
            // Try to get the "length" property.
            var context = (IBuiltinContext)_interpreter;
            if (!context.TryGetPropertyValue(obj, value, "length", out var lengthVal))
                return Array.Empty<byte>();
            var len = (int)lengthVal.AsNumber();
            if (len <= 0 || len > 1024 * 1024) return Array.Empty<byte>();
            var bytes = new byte[len];
            for (var i = 0; i < len; i++)
            {
                if (context.TryGetPropertyValue(obj, value, i.ToString(CultureInfo.InvariantCulture), out var byteVal))
                    bytes[i] = (byte)((int)byteVal.AsNumber() & 0xFF);
            }
            return bytes;
        }
        catch { return Array.Empty<byte>(); }
    }

    // â”€â”€ crypto.subtle helpers â”€â”€

    // Per-engine crypto key storage (keys imported via crypto.subtle.importKey).
    private readonly Dictionary<long, byte[]> _cryptoKeyStore = new();
    private long _cryptoKeyIdCounter;

    private JsValue ImportCryptoKey(IReadOnlyList<JsValue> args)
    {
        // args: [format, keyData, algorithm, extractable, keyUsages]
        // format: "raw" â€” only format supported currently
        // keyData: Uint8Array containing the key bytes
        // algorithm: { name: "AES-CBC" }
        try
        {
            var format = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
            var keyData = args.Count > 1 ? ExtractBytesFromArrayLike(args[1]) : Array.Empty<byte>();
            var extractable = args.Count > 3 && args[3].Tag == JsValueTag.Boolean && args[3].AsBoolean();

            if (format != "raw" || keyData.Length == 0)
            {
                return _interpreter.AllocateObject(new Dictionary<string, JsValue>
                {
                    ["type"] = JsValue.FromString("secret"),
                    ["extractable"] = JsValue.FromBoolean(extractable),
                    ["algorithm"] = _interpreter.AllocateObject(new Dictionary<string, JsValue>
                    {
                        ["name"] = JsValue.FromString("AES-CBC")
                    }),
                    ["usages"] = _interpreter.AllocateArray(Array.Empty<JsValue>())
                });
            }

            var keyId = Interlocked.Increment(ref _cryptoKeyIdCounter);
            lock (_cryptoKeyStore) { _cryptoKeyStore[keyId] = keyData; }

            return _interpreter.AllocateObject(new Dictionary<string, JsValue>
            {
                ["type"] = JsValue.FromString("secret"),
                ["extractable"] = JsValue.FromBoolean(extractable),
                ["algorithm"] = _interpreter.AllocateObject(new Dictionary<string, JsValue>
                {
                    ["name"] = JsValue.FromString("AES-CBC")
                }),
                ["usages"] = _interpreter.AllocateArray(Array.Empty<JsValue>()),
                ["_fenKeyId"] = JsValue.FromNumber(keyId),
                ["_fenKeyLen"] = JsValue.FromNumber(keyData.Length)
            });
        }
        catch
        {
            return JsValue.Undefined;
        }
    }

    private JsValue CryptoDecrypt(IReadOnlyList<JsValue> args)
    {
        // args: [algorithm, key, data]
        // algorithm: { name: "AES-CBC", iv: Uint8Array }
        // key: object from importKey (carries _fenKeyId)
        // data: Uint8Array containing ciphertext
        try
        {
            var algorithm = args.Count > 0 ? args[0] : JsValue.Undefined;
            var key = args.Count > 1 ? args[1] : JsValue.Undefined;
            var data = args.Count > 2 ? ExtractBytesFromArrayLike(args[2]) : Array.Empty<byte>();

            if (data.Length == 0) return CreateUint8ArrayFromBytes(Array.Empty<byte>());

            // Extract IV from algorithm object.
            byte[] iv = new byte[16];
            if (algorithm.Tag == JsValueTag.Object)
            {
                var algoObj = _interpreter.Heap.GetObject(algorithm.AsObjectHandle());
                var context = (IBuiltinContext)_interpreter;
                if (context.TryGetPropertyValue(algoObj, algorithm, "iv", out var ivVal))
                {
                    var extractedIv = ExtractBytesFromArrayLike(ivVal);
                    if (extractedIv.Length > 0) iv = extractedIv;
                }
            }

            // Look up key bytes from the key store or extract directly.
            byte[] aesKey = iv; // fallback
            if (key.Tag == JsValueTag.Object)
            {
                var keyObj = _interpreter.Heap.GetObject(key.AsObjectHandle());
                if (keyObj.TryGetOwnProperty("_fenKeyId", out var keyIdDesc))
                {
                    var kid = (long)keyIdDesc.Value.AsNumber();
                    lock (_cryptoKeyStore)
                    {
                        if (_cryptoKeyStore.TryGetValue(kid, out var stored))
                            aesKey = stored;
                    }
                }
                if (aesKey == iv) // fallback still in place
                {
                    var rawFromKey = ExtractBytesFromArrayLike(key);
                    if (rawFromKey.Length > 0) aesKey = rawFromKey;
                }
            }

            using var aes = System.Security.Cryptography.Aes.Create();
            aes.Key = aesKey;
            aes.IV = iv;
            aes.Mode = System.Security.Cryptography.CipherMode.CBC;
            aes.Padding = System.Security.Cryptography.PaddingMode.PKCS7;

            using var decryptor = aes.CreateDecryptor();
            var decrypted = decryptor.TransformFinalBlock(data, 0, data.Length);
            return CreateUint8ArrayFromBytes(decrypted);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] CryptoDecrypt failed: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            var origData = args.Count > 2 ? ExtractBytesFromArrayLike(args[2]) : Array.Empty<byte>();
            return CreateUint8ArrayFromBytes(origData);
        }
    }

    private JsValue CryptoDigest(IReadOnlyList<JsValue> args)
    {
        // args: [algorithm, data]
        // algorithm: "SHA-256" or "SHA-1" or "SHA-384" or "SHA-512"
        try
        {
            var algoName = args.Count > 0 ? CoerceToHostString(args[0]) : "SHA-256";
            var data = args.Count > 1 ? ExtractBytesFromArrayLike(args[1]) : Array.Empty<byte>();

            if (data.Length == 0) return CreateUint8ArrayFromBytes(Array.Empty<byte>());

            using System.Security.Cryptography.HashAlgorithm hash = algoName switch
            {
                "SHA-1" => System.Security.Cryptography.SHA1.Create(),
                "SHA-384" => System.Security.Cryptography.SHA384.Create(),
                "SHA-512" => System.Security.Cryptography.SHA512.Create(),
                _ => System.Security.Cryptography.SHA256.Create()
            };
            var digest = hash.ComputeHash(data);
            return CreateUint8ArrayFromBytes(digest);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] CryptoDigest failed: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
            return CreateUint8ArrayFromBytes(Array.Empty<byte>());
        }
    }

    // â”€â”€ WebSocket bridge implementation â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    private JsValue ConnectWebSocket(string url, string[] protocols)
    {
        if (string.IsNullOrWhiteSpace(url))
            return JsValue.FromString("SyntaxError: invalid URL");

        try
        {
            var host = new FenWebSocketHost();
            var error = host.Connect(url, protocols);
            if (error != null)
                return JsValue.FromString(error);

            var id = Interlocked.Increment(ref _webSocketIdCounter);
            lock (_webSocketHosts) { _webSocketHosts[id] = host; }
            return JsValue.FromInt32(id);
        }
        catch (Exception ex)
        {
            return JsValue.FromString(ex.Message);
        }
    }

    private JsValue SendWebSocketMessage(int id, string data)
    {
        FenWebSocketHost host;
        lock (_webSocketHosts)
        {
            if (!_webSocketHosts.TryGetValue(id, out host))
                return JsValue.FromString("InvalidStateError: socket not found");
        }
        var error = host.Send(data);
        return error != null ? JsValue.FromString(error) : JsValue.Undefined;
    }

    private JsValue CloseWebSocket(int id, int code, string reason)
    {
        FenWebSocketHost host;
        lock (_webSocketHosts)
        {
            if (!_webSocketHosts.TryGetValue(id, out host))
                return JsValue.Undefined;
            _webSocketHosts.Remove(id);
        }
        host.Close(code, reason);
        host.Dispose();
        return JsValue.Undefined;
    }

    /// <summary>
    /// Poll a WebSocket for pending events and messages.
    /// Returns a JSON string like {"events":[{"type":"open"}],"messages":[{"text":"..."},{"binary":"base64..."}]}
    /// or "null" if nothing pending.
    /// </summary>
    private JsValue PollWebSocket(int id)
    {
        FenWebSocketHost host;
        lock (_webSocketHosts)
        {
            if (!_webSocketHosts.TryGetValue(id, out host))
                return JsValue.FromString("null");
        }

        var events = new List<object>();
        WsEvent evt;
        while ((evt = host.PollEvent()) != null)
            events.Add(new { type = evt.Type, code = evt.Code, reason = evt.Reason });

        var messages = new List<object>();
        WsMessage msg;
        while ((msg = host.PollMessage()) != null)
        {
            if (msg.IsText)
                messages.Add(new { text = msg.TextData });
            else
                messages.Add(new { binary = Convert.ToBase64String(msg.BinaryData) });
        }

        if (events.Count == 0 && messages.Count == 0)
            return JsValue.FromString("null");

        var result = new { events, messages };
        var json = System.Text.Json.JsonSerializer.Serialize(result);
        return JsValue.FromString(json);
    }

    private string DescribePromiseRejectionReason(JsValue reason)
    {
        if (reason.Tag != JsValueTag.Object)
        {
            return CoerceToHostString(reason);
        }

        try
        {
            var jsObject = _interpreter.Heap.GetObject(reason.AsObjectHandle());
            var context = (IBuiltinContext)_interpreter;
            if (context.TryGetPropertyValue(jsObject, reason, "stack", out var stack) &&
                stack.Tag != JsValueTag.Undefined &&
                stack.Tag != JsValueTag.Null)
            {
                return CoerceToHostString(stack);
            }

            if (context.TryGetPropertyValue(jsObject, reason, "message", out var message) &&
                message.Tag != JsValueTag.Undefined &&
                message.Tag != JsValueTag.Null)
            {
                return CoerceToHostString(message);
            }
        }
        catch
        {
        }

        return CoerceToHostString(reason);
    }

    /// <summary>
    /// Called by FenJsMutationObserverHost when its backing C# MutationObserver fires.
    /// Converts MutationRecord objects to JS and invokes the stored JS callback.
    /// Must run under the interpreter lock â€” the caller (OnMutations on the mutation
    /// callback thread) delegates here via RunFenJsWithLargeStack.
    /// </summary>
    internal void InvokeMutationObserverCallback(FenJsMutationObserverHost host, IReadOnlyList<MutationRecord> records)
    {
        if (records == null || records.Count == 0)
        {
            return;
        }

        if (!_interpreter.CanCallValue(host.Callback))
        {
            return;
        }

        // Convert records to JS objects. Each record is a plain object with the
        // MutationRecord properties defined by the spec. The construction window
        // keeps partially built record facades (strings, node arrays, nested
        // objects) alive across collections until the top-level array exists.
        using var _ = _interpreter.Heap.BeginConstructionWindow();

        var jsRecords = new JsValue[records.Count];
        for (int i = 0; i < records.Count; i++)
        {
            jsRecords[i] = CreateMutationRecordJsObject(records[i]);
        }

        var recordsArray = _interpreter.AllocateArray(jsRecords);
        var observerValue = ToHostOrNull(host, HostObjectKind.Other);

        InvokeFenJsCallbackSafely(host.Callback, new[] { recordsArray, observerValue }, "MutationObserver");
    }

    /// <summary>
    /// Converts a C# MutationRecord into a JS plain object matching the
    /// MutationRecord interface.
    /// https://dom.spec.whatwg.org/#mutationrecord
    /// </summary>
    private JsValue CreateMutationRecordJsObject(MutationRecord record)
    {
        var props = new Dictionary<string, JsValue>(StringComparer.Ordinal)
        {
            ["type"] = JsValue.FromString(record.Type switch
            {
                MutationRecordType.Attributes => "attributes",
                MutationRecordType.CharacterData => "characterData",
                MutationRecordType.ChildList => "childList",
                _ => "childList"
            }),
            ["target"] = ToHostNodeOrNull(record.Target),
            ["addedNodes"] = CreateNodeArrayLike(record.AddedNodes ?? Array.Empty<Node>()),
            ["removedNodes"] = CreateNodeArrayLike(record.RemovedNodes ?? Array.Empty<Node>()),
            ["previousSibling"] = ToHostNodeOrNull(record.PreviousSibling),
            ["nextSibling"] = ToHostNodeOrNull(record.NextSibling),
            ["attributeName"] = record.AttributeName != null
                ? JsValue.FromString(record.AttributeName)
                : JsValue.Null,
            ["attributeNamespace"] = record.AttributeNamespace != null
                ? JsValue.FromString(record.AttributeNamespace)
                : JsValue.Null,
            ["oldValue"] = record.OldValue != null
                ? JsValue.FromString(record.OldValue)
                : JsValue.Null,
        };

        return _interpreter.AllocateObject(props);
    }

    /// <summary>
    /// Handles property access on MutationObserver host objects.
    /// </summary>
    private bool TryGetMutationObserverProperty(FenJsMutationObserverHost host, string property, out JsValue value)
    {
        switch (property)
        {
            case "observe":
                value = GetOrCreateHostCallable(
                    host,
                    "observe",
                    (_, args) =>
                    {
                        if (args.Count < 2)
                        {
                            ThrowDomException("TypeError",
                                "Failed to execute 'observe' on 'MutationObserver': 2 arguments required.");
                            return JsValue.Undefined;
                        }

                        var target = ResolveHostObjectOrNull<Node>(args[0]);
                        if (target == null)
                        {
                            ThrowDomException("TypeError",
                                "Failed to execute 'observe' on 'MutationObserver': parameter 1 is not of type 'Node'.");
                            return JsValue.Undefined;
                        }

                        var options = ParseMutationObserverInit(args[1]);
                        host.Observe(target, options);
                        return JsValue.Undefined;
                    },
                    length: 2);
                return true;

            case "disconnect":
                value = GetOrCreateHostCallable(
                    host,
                    "disconnect",
                    (_, _) =>
                    {
                        host.Disconnect();
                        return JsValue.Undefined;
                    },
                    length: 0);
                return true;

            case "takeRecords":
                value = GetOrCreateHostCallable(
                    host,
                    "takeRecords",
                    (_, _) =>
                    {
                        using var _ = _interpreter.Heap.BeginConstructionWindow();
                        var records = host.TakeRecords();
                        var jsRecords = new JsValue[records.Count];
                        for (int i = 0; i < records.Count; i++)
                        {
                            jsRecords[i] = CreateMutationRecordJsObject(records[i]);
                        }

                        return _interpreter.AllocateArray(jsRecords);
                    },
                    length: 0);
                return true;

            default:
                value = JsValue.Undefined;
                return false;
        }
    }

    /// <summary>
    /// Parses a JS options object into a MutationObserverInit struct.
    /// https://dom.spec.whatwg.org/#dictdef-mutationobserverinit
    /// </summary>
    private MutationObserverInit ParseMutationObserverInit(JsValue optionsValue)
    {
        var init = new MutationObserverInit();

        if (optionsValue.Tag != JsValueTag.Object)
        {
            // If options is not an object, default all to false â†’ observe() will throw.
            return init;
        }

        var attributesValue = ReadJsProperty(optionsValue, "attributes");
        var characterDataValue = ReadJsProperty(optionsValue, "characterData");
        var attributesPresent = attributesValue.Tag != JsValueTag.Undefined;
        var characterDataPresent = characterDataValue.Tag != JsValueTag.Undefined;

        init.ChildList = ReadJsBoolProperty(optionsValue, "childList");
        init.Attributes = CoerceJsBoolean(attributesValue);
        init.CharacterData = CoerceJsBoolean(characterDataValue);
        init.Subtree = ReadJsBoolProperty(optionsValue, "subtree");
        init.AttributeOldValue = ReadJsBoolProperty(optionsValue, "attributeOldValue");
        init.CharacterDataOldValue = ReadJsBoolProperty(optionsValue, "characterDataOldValue");

        // attributeFilter: optional sequence<DOMString>
        var filterValue = ReadJsProperty(optionsValue, "attributeFilter");
        if (!attributesPresent &&
            (init.AttributeOldValue || filterValue.Tag != JsValueTag.Undefined))
        {
            init.Attributes = true;
        }

        if (!characterDataPresent && init.CharacterDataOldValue)
        {
            init.CharacterData = true;
        }

        if (filterValue.Tag == JsValueTag.Object)
        {
            var filterList = new List<string>();
            try
            {
                var lenValue = ReadJsProperty(filterValue, "length");
                int len = 0;
                if (lenValue.Tag == JsValueTag.Int32)
                    len = lenValue.AsInt32();
                else if (lenValue.Tag == JsValueTag.Number)
                    len = (int)lenValue.AsNumber();

                for (int i = 0; i < Math.Min(len, 100); i++)
                {
                    var item = ReadJsProperty(filterValue, i.ToString());
                    if (item.Tag == JsValueTag.String)
                        filterList.Add(item.AsString());
                }
            }
            catch
            {
                // Best-effort; leave filter empty.
            }

            if (filterList.Count > 0)
                init.AttributeFilter = filterList.ToArray();
        }

        return init;
    }

    /// <summary>
    /// Reads a boolean property from a JS object, coercing via JS truthiness rules.
    /// </summary>
    private bool ReadJsBoolProperty(JsValue obj, string property)
    {
        var value = ReadJsProperty(obj, property);
        return CoerceJsBoolean(value);
    }

    private static bool CoerceJsBoolean(JsValue value)
    {
        return value.Tag switch
        {
            JsValueTag.Undefined => false,
            JsValueTag.Null => false,
            JsValueTag.Boolean => value.AsBoolean(),
            JsValueTag.Int32 => value.AsInt32() != 0,
            JsValueTag.Number => value.AsNumber() != 0,
            JsValueTag.String => value.AsString().Length > 0,
            _ => true // objects, symbols etc. are truthy
        };
    }

    /// <summary>
    /// Reads a named property from a JS object via the interpreter's property
    /// resolution (own + prototype chain). Returns JsValue.Undefined if the
    /// value is not an object or the property does not exist.
    /// </summary>
    private JsValue ReadJsProperty(JsValue obj, string property)
    {
        if (obj.Tag != JsValueTag.Object)
            return JsValue.Undefined;

        var handle = obj.AsObjectHandle();
        var jsObj = _interpreter.Heap.GetObject(handle);
        if (((IBuiltinContext)_interpreter).TryGetPropertyValue(jsObj, obj, property, out var value))
            return value;

        return JsValue.Undefined;
    }

    private IReadOnlyList<JsValue> ExtractJsArgumentList(JsValue argumentsValue)
    {
        if (argumentsValue.Tag != JsValueTag.Object)
        {
            return Array.Empty<JsValue>();
        }

        var lengthValue = ReadJsProperty(argumentsValue, "length");
        var length = lengthValue.Tag switch
        {
            JsValueTag.Int32 => Math.Max(0, lengthValue.AsInt32()),
            JsValueTag.Number => Math.Max(0, (int)lengthValue.AsNumber()),
            _ => 0
        };

        if (length == 0)
        {
            return Array.Empty<JsValue>();
        }

        var values = new JsValue[length];
        for (var i = 0; i < length; i++)
        {
            values[i] = ReadJsProperty(argumentsValue, i.ToString(CultureInfo.InvariantCulture));
        }

        return values;
    }

    private bool TryInvokeHotHostMethod(
        JsValue receiver,
        string methodName,
        IReadOnlyList<JsValue> args,
        out JsValue result)
    {
        result = JsValue.Undefined;
        if (methodName is not (
            "createElement" or
            "createTextNode" or
            "getAttribute" or
            "setAttribute" or
            "getBoundingClientRect" or
            "getClientRects" or
            "getElementsByTagName" or
            "getElementsByClassName"))
        {
            return false;
        }

        if (!TryResolveHostObject(receiver, out var hostObject))
        {
            return false;
        }

        try
        {
            switch (hostObject)
            {
                case Document document when methodName == "createElement":
                {
                    var localName = args.Count > 0 ? CoerceToHostString(args[0]) : "div";
                    result = UpgradeCustomElementTreeIfDefined(ToHostNodeOrNull(document.CreateElement(localName)));
                    return true;
                }
                case Document document when methodName == "createTextNode":
                {
                    var data = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                    result = ToHostNodeOrNull(document.CreateTextNode(data));
                    return true;
                }
                case Element element when methodName == "getAttribute":
                {
                    var attributeName = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                    var attributeValue = element.GetAttribute(attributeName);
                    result = attributeValue == null ? JsValue.Null : JsValue.FromString(attributeValue);
                    return true;
                }
                case Element element when methodName == "setAttribute":
                {
                    var attributeName = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                    var attributeValue = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                    element.SetAttribute(attributeName, attributeValue);
                    ApplyElementSetAttributeSideEffects(element, attributeName, attributeValue);
                    result = JsValue.Undefined;
                    return true;
                }
                case Element element when methodName == "getBoundingClientRect":
                    result = ReadElementBoundingClientRect(element);
                    return true;
                case Element element when methodName == "getClientRects":
                    result = ReadElementClientRects(element);
                    return true;
                case Element element when methodName == "getElementsByTagName":
                {
                    var qualifiedName = args.Count > 0 ? CoerceToHostString(args[0]) : "*";
                    result = ToHostOrNull(
                        new FenJsHtmlCollectionHost(element.GetElementsByTagName(qualifiedName)),
                        HostObjectKind.Other);
                    return true;
                }
                case Element element when methodName == "getElementsByClassName":
                {
                    var className = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                    result = ToHostOrNull(
                        new FenJsHtmlCollectionHost(element.GetElementsByClassName(className)),
                        HostObjectKind.Other);
                    return true;
                }
                default:
                    return false;
            }
        }
        catch (DomException ex)
        {
            ThrowDomException(
                ex.Name,
                string.IsNullOrEmpty(ex.Message)
                    ? $"Failed to execute '{methodName}'."
                    : ex.Message);
        }

        return true;
    }

    private void ApplyElementSetAttributeSideEffects(
        Element element,
        string attributeName,
        string attributeValue)
    {
        ApplyEventHandlerContentAttributeChange(element, attributeName, attributeValue);
        if ((string.Equals(attributeName, "src", StringComparison.OrdinalIgnoreCase) ||
             string.Equals(attributeName, "srcdoc", StringComparison.OrdinalIgnoreCase)) &&
            IsIFrameElement(element))
        {
            QueueFrameElementLoad(element);
        }
        if (IsIFrameElement(element) &&
            (string.Equals(attributeName, "width", StringComparison.OrdinalIgnoreCase) ||
             string.Equals(attributeName, "height", StringComparison.OrdinalIgnoreCase) ||
             string.Equals(attributeName, "style", StringComparison.OrdinalIgnoreCase)))
        {
            NotifyResizeObservers(element);
        }
    }

    private JsValue InvokeFenJsHostMethod(JsValue receiver, string methodName, IReadOnlyList<JsValue> args)
    {
        if (receiver.Tag != JsValueTag.HostObject || string.IsNullOrWhiteSpace(methodName))
        {
            LogScriptLoading(
                "HostMethodIllegalInvocation",
                LogSeverity.Warn,
                "[FenJsBridge] Host method called with an invalid receiver",
                new Dictionary<string, object>
                {
                    ["method"] = methodName ?? string.Empty,
                    ["receiverTag"] = receiver.Tag.ToString()
                },
                LogMarker.EngineBug);
            ThrowDomException("TypeError", "Illegal invocation");
        }

        var normalizedArgs = args ?? Array.Empty<JsValue>();
        if (TryInvokeHotHostMethod(receiver, methodName, normalizedArgs, out var fastResult))
        {
            return fastResult;
        }

        var handle = receiver.AsHostObjectHandle();
        if (!_hostHooks.TryGetHostProperty(handle, methodName, out var method) ||
            !_interpreter.CanCallValue(method))
        {
            LogScriptLoading(
                "HostMethodMissing",
                LogSeverity.Warn,
                "[FenJsBridge] Host method missing or not callable",
                new Dictionary<string, object>
                {
                    ["method"] = methodName ?? string.Empty,
                    ["receiverTag"] = receiver.Tag.ToString()
                },
                LogMarker.EngineBug);
            ThrowDomException("TypeError", "Illegal invocation");
        }

        return _interpreter.InvokeFunction(method, normalizedArgs, receiver);
    }

    private HostObjectHandle RegisterHostObject(object hostObject, HostObjectKind kind)
    {
        if (_hostHandleCache.TryGetValue(hostObject, out var existing))
        {
            return existing;
        }

        var handle = _interpreter.HostObjectTable.Register(
            hostObject,
            new HostObjectEntry(
                Generation: 0,
                Kind: kind,
                RealmId: 0,
                Origin: _currentBaseUri?.GetLeftPart(UriPartial.Authority) ?? "about:blank",
                DocumentEpoch: _documentEpoch,
                NavigationEpoch: _navigationEpoch,
                FrameId: 0,
                PermissionFlags: 0));
        _hostHandleCache[hostObject] = handle;
        return handle;
    }

    private BrowserSurfaceProfile CreateNavigatorHost()
    {
        return BrowserSettings.GetBrowserSurface(BrowserSettings.Instance.SelectedUserAgent);
    }

    /// <summary>
    /// Register localStorage and sessionStorage as host objects on the global scope.
    /// Must be called after _interpreter is initialized and the base URI is known.
    /// </summary>
    private void RegisterFenJsStorageGlobals(Uri baseUri, Document document)
    {
        var origin = ResolveStorageOrigin(baseUri, document);
        var partitionKey = StoragePartitionKey.FirstParty(origin);

        var localStorage = new FenStorageAreaHost(
            _storageService.LocalStorage, partitionKey, origin);
        var sessionStorage = new FenStorageAreaHost(
            _storageService.SessionStorage, partitionKey, origin);

        _interpreter.RegisterGlobalHostObject(
            "localStorage",
            RegisterHostObject(localStorage, HostObjectKind.StorageArea));
        _interpreter.RegisterGlobalHostObject(
            "sessionStorage",
            RegisterHostObject(sessionStorage, HostObjectKind.StorageArea));
        if (_fenJsFileConstructor.Tag != JsValueTag.Undefined)
        {
            _interpreter.RegisterGlobalValue("File", _fenJsFileConstructor);
        }
    }

    private static string ResolveStorageOrigin(Uri baseUri, Document document)
    {
        if (baseUri != null && baseUri.IsAbsoluteUri)
            return baseUri.GetLeftPart(UriPartial.Authority);
        if (document != null && !string.IsNullOrWhiteSpace(document.URL) &&
            Uri.TryCreate(document.URL, UriKind.Absolute, out var docUri))
            return docUri.GetLeftPart(UriPartial.Authority);
        return "about:blank";
    }

    private JsValue CreateNavigatorUserAgentDataObject(BrowserUserAgentDataProfile userAgentData)
    {
        userAgentData ??= new BrowserUserAgentDataProfile();

        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["brands"] = CreateClientHintBrandArray(userAgentData.Brands),
            ["mobile"] = JsValue.FromBoolean(userAgentData.Mobile),
            ["platform"] = JsValue.FromString(userAgentData.Platform ?? string.Empty),
            ["toJSON"] = _interpreter.AllocateNativeFunction(
                "toJSON",
                (_, _) => _interpreter.AllocateObject(new Dictionary<string, JsValue>
                {
                    ["brands"] = CreateClientHintBrandArray(userAgentData.Brands),
                    ["mobile"] = JsValue.FromBoolean(userAgentData.Mobile),
                    ["platform"] = JsValue.FromString(userAgentData.Platform ?? string.Empty)
                }),
                length: 0),
            ["getHighEntropyValues"] = _interpreter.AllocateNativeFunction(
                "getHighEntropyValues",
                (_, args) =>
                {
                    var snapshot = CreateUserAgentHighEntropySnapshot(
                        userAgentData,
                        args.Count > 0 ? args[0] : JsValue.Undefined);
                    var (promise, resolve, _) = ((IBuiltinContext)_interpreter).CreatePromiseCapability();
                    _ = _interpreter.InvokeFunction(resolve, new[] { snapshot }, JsValue.Undefined);
                    return promise;
                },
                length: 1)
        });
    }

    private JsValue CreateNavigatorConnectionObject()
    {
        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["downlink"] = JsValue.FromNumber(10),
            ["effectiveType"] = JsValue.FromString("4g"),
            ["rtt"] = JsValue.FromNumber(50),
            ["saveData"] = JsValue.FromBoolean(false),
            ["type"] = JsValue.FromString("unknown"),
            ["onchange"] = JsValue.Null,
            ["addEventListener"] = _interpreter.AllocateNativeFunction(
                "addEventListener",
                (_, _) => JsValue.Undefined,
                length: 2),
            ["removeEventListener"] = _interpreter.AllocateNativeFunction(
                "removeEventListener",
                (_, _) => JsValue.Undefined,
                length: 2),
            ["dispatchEvent"] = _interpreter.AllocateNativeFunction(
                "dispatchEvent",
                (_, _) => JsValue.FromBoolean(true),
                length: 1),
            ["addListener"] = _interpreter.AllocateNativeFunction(
                "addListener",
                (_, _) => JsValue.Undefined,
                length: 1),
            ["removeListener"] = _interpreter.AllocateNativeFunction(
                "removeListener",
                (_, _) => JsValue.Undefined,
                length: 1)
        });
    }

    private JsValue CreateUserAgentHighEntropySnapshot(BrowserUserAgentDataProfile userAgentData, JsValue hintsValue)
    {
        var requested = ExtractStringArrayLike(hintsValue);
        var properties = new Dictionary<string, JsValue>();

        foreach (var hint in requested)
        {
            switch (hint)
            {
                case "architecture":
                    properties["architecture"] = JsValue.FromString(userAgentData.Architecture ?? string.Empty);
                    break;
                case "bitness":
                    properties["bitness"] = JsValue.FromString(userAgentData.Bitness ?? string.Empty);
                    break;
                case "brands":
                    properties["brands"] = CreateClientHintBrandArray(userAgentData.Brands);
                    break;
                case "fullVersionList":
                    properties["fullVersionList"] = CreateClientHintBrandArray(userAgentData.FullVersionList);
                    break;
                case "mobile":
                    properties["mobile"] = JsValue.FromBoolean(userAgentData.Mobile);
                    break;
                case "model":
                    properties["model"] = JsValue.FromString(userAgentData.Model ?? string.Empty);
                    break;
                case "platform":
                    properties["platform"] = JsValue.FromString(userAgentData.Platform ?? string.Empty);
                    break;
                case "platformVersion":
                    properties["platformVersion"] = JsValue.FromString(userAgentData.PlatformVersion ?? string.Empty);
                    break;
                case "uaFullVersion":
                    properties["uaFullVersion"] = JsValue.FromString(GetPrimaryUserAgentFullVersion(userAgentData));
                    break;
                case "wow64":
                    properties["wow64"] = JsValue.FromBoolean(userAgentData.Wow64);
                    break;
            }
        }

        return _interpreter.AllocateObject(properties);
    }

    private JsValue CreateClientHintBrandArray(IReadOnlyList<BrowserClientHintBrand> brands)
    {
        var values = (brands ?? Array.Empty<BrowserClientHintBrand>())
            .Select(brand => _interpreter.AllocateObject(new Dictionary<string, JsValue>
            {
                ["brand"] = JsValue.FromString(brand?.Brand ?? string.Empty),
                ["version"] = JsValue.FromString(brand?.Version ?? string.Empty)
            }))
            .ToArray();
        return _interpreter.AllocateArray(values);
    }

    private IReadOnlyList<string> ExtractStringArrayLike(JsValue value)
    {
        if (value.Tag != JsValueTag.Object)
        {
            return Array.Empty<string>();
        }

        var obj = _interpreter.Heap.GetObject(value.AsObjectHandle());
        var context = (IBuiltinContext)_interpreter;
        if (!context.TryGetPropertyValue(obj, value, "length", out var lengthValue))
        {
            return Array.Empty<string>();
        }

        var length = Math.Max(0, (int)Math.Min(128, lengthValue.AsNumber()));
        var items = new List<string>(length);
        for (var i = 0; i < length; i++)
        {
            if (context.TryGetPropertyValue(obj, value, i.ToString(CultureInfo.InvariantCulture), out var itemValue))
            {
                items.Add(CoerceToHostString(itemValue));
            }
        }

        return items;
    }

    private static string GetPrimaryUserAgentFullVersion(BrowserUserAgentDataProfile userAgentData)
    {
        if (userAgentData?.FullVersionList == null || userAgentData.FullVersionList.Count == 0)
        {
            return string.Empty;
        }

        var preferredBrand = userAgentData.FullVersionList.FirstOrDefault(brand =>
            !IsGreaseBrand(brand?.Brand) &&
            !string.Equals(brand?.Brand, "Chromium", StringComparison.OrdinalIgnoreCase));
        if (preferredBrand != null)
        {
            return preferredBrand.Version ?? string.Empty;
        }

        var nonGreaseBrand = userAgentData.FullVersionList.FirstOrDefault(brand => !IsGreaseBrand(brand?.Brand));
        return nonGreaseBrand?.Version ?? string.Empty;
    }

    private static bool IsGreaseBrand(string brand)
    {
        return string.Equals(brand, " Not;A Brand", StringComparison.Ordinal);
    }

    private JsValue ToHostOrNull(object hostObject, HostObjectKind kind)
    {
        if (hostObject == null)
        {
            return JsValue.Null;
        }

        var value = JsValue.FromHostObject(RegisterHostObject(hostObject, kind));
        TryAttachFenJsPrototype(value, hostObject, kind);
        return value;
    }

    private void TryAttachFenJsPrototype(JsValue target, object hostObject, HostObjectKind kind)
    {
        if (!_fenJsDomConstructorsInstalled ||
            hostObject == null ||
            target.Tag != JsValueTag.HostObject)
        {
            return;
        }

        var constructorName = GetFenJsPrototypeConstructorName(hostObject, kind);
        if (string.IsNullOrEmpty(constructorName))
        {
            return;
        }

        if (_hostPrototypeNames.TryGetValue(hostObject, out var existing) &&
            string.Equals(existing, constructorName, StringComparison.Ordinal))
        {
            return;
        }

        try
        {
            if (_interpreter.TrySetHostObjectPrototypeFromGlobalConstructor(target, constructorName))
            {
                _hostPrototypeNames[hostObject] = constructorName;
            }
            else if (hostObject is Element &&
                     !string.Equals(constructorName, "HTMLElement", StringComparison.Ordinal) &&
                     _interpreter.TrySetHostObjectPrototypeFromGlobalConstructor(target, "HTMLElement"))
            {
                _hostPrototypeNames[hostObject] = "HTMLElement";
            }
            else if (hostObject is Document &&
                     _interpreter.TrySetHostObjectPrototypeFromGlobalConstructor(target, "Document"))
            {
                _hostPrototypeNames[hostObject] = "Document";
            }
        }
        catch
        {
            // Some host wrappers intentionally have no DOM constructor surface.
        }
    }

    private static string GetFenJsPrototypeConstructorName(object hostObject, HostObjectKind kind)
    {
        return hostObject switch
        {
            // DOM 4.5: only an HTML document is an HTMLDocument; new Document()
            // and createDocument() produce plain Documents.
            Document document => string.Equals(document.ContentType, "text/html", StringComparison.OrdinalIgnoreCase)
                ? "HTMLDocument"
                : "Document",
            ShadowRoot => "ShadowRoot",
            DocumentFragment => "DocumentFragment",
            CDATASection => "CDATASection",
            ProcessingInstruction => "ProcessingInstruction",
            DocumentType => "DocumentType",
            Text => "Text",
            Comment => "Comment",
            CharacterData => "CharacterData",
            Element element => ResolveElementConstructorName(element),
            Attr => "Attr",
            DomRange => "Range",
            FenJsHtmlCollectionHost => "HTMLCollection",
            NodeList => "NodeList",
            NamedNodeMap => "NamedNodeMap",
            DOMTokenList => "DOMTokenList",
            FenJsTreeWalkerHost => "TreeWalker",
            FenJsNodeIteratorHost => "NodeIterator",
            Node when kind == HostObjectKind.DomNode => "Node",
            BrowserSurfaceProfile => "Navigator",
            FenJsLocationHost => "Location",
            FenJsHistoryHost => "History",
            FenJsDomStringMapHost => "DOMStringMap",
            _ => null
        };
    }

    // The element's own interface (td -> HTMLTableCellElement) when the realm
    // defines that constructor; HTMLElement otherwise, so the prototype chain
    // is never left bare.
    private static string ResolveElementConstructorName(Element element)
    {
        var name = FenBrowser.Core.Dom.V2.HtmlElementInterfaceCatalog.ResolveInterfaceName(
            element.LocalName ?? element.TagName?.ToLowerInvariant(),
            element.NamespaceUri);
        return string.IsNullOrEmpty(name) ? "HTMLElement" : name;
    }

    private JsValue ToHostNodeOrNull(Node node)
    {
        return node switch
        {
            Document document => ToHostOrNull(document, HostObjectKind.DomDocument),
            Element element => ToHostOrNull(element, HostObjectKind.DomElement),
            Node otherNode => ToHostOrNull(otherNode, HostObjectKind.DomNode),
            _ => JsValue.Null
        };
    }

    /// <summary>
    /// The nodes an insertion actually moves into the tree. A DocumentFragment
    /// hands its children over and comes back empty, so upgrading the returned
    /// node afterwards would find nothing; snapshot them first (DOM 4.2.3
    /// "insert": custom element reactions are enqueued for the moved nodes).
    /// </summary>
    private static Node[] SnapshotFragmentChildren(Node child)
    {
        if (child is not DocumentFragment fragment)
        {
            return null;
        }

        var moved = new List<Node>();
        for (var node = fragment.FirstChild; node != null; node = node.NextSibling)
        {
            moved.Add(node);
        }
        return moved.ToArray();
    }

    private void UpgradeInsertedCustomElements(Node child, Node[] movedFromFragment)
    {
        if (!_hasCustomElementDefinitions)
        {
            return;
        }

        if (movedFromFragment == null)
        {
            UpgradeCustomElementTreeIfDefined(ToHostNodeOrNull(child));
            return;
        }

        foreach (var node in movedFromFragment)
        {
            if (node is Element)
            {
                UpgradeCustomElementTreeIfDefined(ToHostNodeOrNull(node));
            }
        }
    }

    private bool HasCustomElementDefinitions(JsValue registry)
    {
        if (registry.Tag != JsValueTag.Object)
        {
            return false;
        }

        var registryObject = _interpreter.Heap.GetObject(registry.AsObjectHandle());
        if (!registryObject.TryGetOwnProperty("_registry", out var definitionsValue) ||
            definitionsValue.Value.Tag != JsValueTag.Object)
        {
            return false;
        }

        var definitions = _interpreter.Heap.GetObject(definitionsValue.Value.AsObjectHandle());
        foreach (var _ in definitions.EnumerateOwnProperties())
        {
            return true;
        }

        return false;
    }

    private JsValue UpgradeCustomElementTreeIfDefined(JsValue rootValue)
    {
        if (!_hasCustomElementDefinitions || rootValue.Tag != JsValueTag.HostObject || _interpreter == null)
        {
            return rootValue;
        }

        if (!_interpreter.TryReadGlobalValue("customElements", out var registry))
        {
            return rootValue;
        }

        var upgrade = ReadJsProperty(registry, "upgrade");
        if (!_interpreter.CanCallValue(upgrade) || !HasCustomElementDefinitions(registry))
        {
            return rootValue;
        }

        try
        {
            _ = _interpreter.InvokeFunction(upgrade, new[] { rootValue }, registry);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] customElements.upgrade callback failed: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }

        return rootValue;
    }

    private static Uri TryCreateUri(string raw)
    {
        return Uri.TryCreate(raw, UriKind.Absolute, out var parsed) ? parsed : null;
    }

    // HTML 4.12.1 defines the script element in the HTML namespace and SVG 2
    // gives SVG its own. A <script> in any other namespace - an XHTML file with a
    // mistyped xmlns, as in Acid3's xhtml.3 - is an unknown element and never runs.
    private static bool IsExecutableScriptElement(Element element) =>
        string.Equals(element.LocalName, "script", StringComparison.Ordinal) &&
        (string.Equals(element.NamespaceUri, Namespaces.Html, StringComparison.Ordinal) ||
         string.Equals(element.NamespaceUri, Namespaces.Svg, StringComparison.Ordinal));

    private IEnumerable<Element> EnumerateScriptElements(Node domRoot)
    {
        int totalElements = 0;
        int scriptElements = 0;
        int otherElements = 0;
        foreach (var node in domRoot.SelfAndDescendants())
        {
            if (node is Element element)
            {
                totalElements++;
                if (IsExecutableScriptElement(element))
                {
                    scriptElements++;
                    var src = element.GetAttribute("src") ?? string.Empty;
                    LogScriptLoading(
                        "ScriptElementDiscovered",
                        LogSeverity.Debug,
                        "[FenJsBridge] Found SCRIPT element",
                        new Dictionary<string, object>
                        {
                            ["scriptId"] = BuildScriptId(scriptElements),
                            ["ordinal"] = scriptElements,
                            ["sourceLabel"] = BuildScriptSourceLabel(element, scriptElements),
                            ["sourceType"] = string.IsNullOrEmpty(src) ? "inline" : "external",
                            ["scriptSourceOffset"] = element.SourceOffset,
                            ["scriptSourceLine"] = element.SourceLine,
                            ["scriptSourceColumn"] = element.SourceColumn,
                            ["src"] = src,
                            ["type"] = element.GetAttribute("type") ?? string.Empty,
                            ["parentType"] = element.ParentNode?.GetType().Name ?? string.Empty,
                            ["parentTag"] = (element.ParentNode as Element)?.TagName ?? string.Empty
                        });
                    yield return element;
                }
                else
                {
                    otherElements++;
                }
            }
        }
        UpdateScriptLoadingSnapshot(snapshot =>
        {
            snapshot.TotalElements = totalElements;
            snapshot.ScriptElements = scriptElements;
            snapshot.OtherElements = otherElements;
            snapshot.TotalScripts = scriptElements;
        });
        LogScriptLoading(
            "ScriptEnumerationCompleted",
            LogSeverity.Debug,
            "[FenJsBridge] EnumerateScriptElements DONE",
            new Dictionary<string, object>
            {
                ["totalElements"] = totalElements,
                ["scriptElements"] = scriptElements,
                ["otherElements"] = otherElements
            });
    }

    private static string CollectScriptText(Node node)
    {
        if (node == null)
        {
            return string.Empty;
        }

        if (node is Text text)
        {
            return text.Data ?? string.Empty;
        }

        var builder = new StringBuilder();
        foreach (var child in node.ChildNodes)
        {
            builder.Append(CollectScriptText(child));
        }

        return builder.ToString();
    }

    private static void CollectElementsByName(Node root, string name, List<Element> results)
    {
        if (root == null || string.IsNullOrEmpty(name)) return;
        if (root is Element el && string.Equals(el.GetAttribute("name"), name, StringComparison.Ordinal))
            results.Add(el);
        for (var child = root.FirstChild; child != null; child = child.NextSibling)
            CollectElementsByName(child, name, results);
    }

    internal static void ApplyScriptingEnabledSanitizer(Node root)
    {
        if (root == null)
        {
            return;
        }

        static void FlipNoJsClass(Element element)
        {
            if (element == null)
            {
                return;
            }

            var classValue = element.GetAttribute("class");
            if (string.IsNullOrWhiteSpace(classValue))
            {
                return;
            }

            var parts = new HashSet<string>(
                classValue.Split(new[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries),
                StringComparer.OrdinalIgnoreCase);
            // Only the no-js -> js convention (Modernizr and friends): a page that
            // marks itself no-js expects script to swap the class. Adding "js" to any
            // <html> or <body> that merely has a class is not something a browser
            // does, and the class change restyles the whole body after the first
            // cascade - on en.wikipedia.org that forced an extra full relayout.
            if (!parts.Remove("no-js"))
            {
                return;
            }

            parts.Add("js");
            element.SetAttribute("class", string.Join(" ", parts));
        }

        var container = root as ContainerNode ?? root.OwnerDocument;
        if (container == null)
        {
            return;
        }

        FlipNoJsClass(container.GetElementsByTagName("html").FirstOrDefault());
        FlipNoJsClass(container.GetElementsByTagName("body").FirstOrDefault());
    }

    private string GetDocumentReadyState()
    {
        return string.IsNullOrWhiteSpace(_documentReadyState) ? "loading" : _documentReadyState;
    }

    private void ClearSelectionState()
    {
        _selectionAnchorNode = null;
        _selectionFocusNode = null;
        _selectionAnchorOffset = 0;
        _selectionFocusOffset = 0;
    }

    internal void FocusElement(Element element)
    {
        if (element == null) return;

        var document = element.OwnerDocument;
        var alreadyFocused = document != null && ReferenceEquals(document.ActiveElement, element);
        if (document != null)
        {
            document.ActiveElement = element;
        }

        FenBrowser.FenEngine.Rendering.ElementStateManager.Instance.SetActiveElement(element);

        if (!alreadyFocused)
        {
            DispatchElementEvent(element, "focus");
        }

        if (IsContentEditableElement(element))
        {
            SetCollapsedSelectionForEditable(element);
        }
    }

    internal void BlurElement(Element element)
    {
        if (element == null) return;

        var document = element.OwnerDocument;
        var wasFocused = document != null && ReferenceEquals(document.ActiveElement, element);
        if (wasFocused)
        {
            document.ActiveElement = null;
        }

        FenBrowser.FenEngine.Rendering.ElementStateManager.Instance.SetActiveElement(null);

        if (wasFocused)
        {
            DispatchElementEvent(element, "blur");
        }
    }

    private static bool IsContentEditableElement(Element element)
    {
        if (element == null || !element.HasAttribute("contenteditable"))
        {
            return false;
        }

        var value = element.GetAttribute("contenteditable");
        return string.IsNullOrEmpty(value) ||
               string.Equals(value, "true", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(value, "plaintext-only", StringComparison.OrdinalIgnoreCase);
    }

    private void SetCollapsedSelectionForEditable(Element element)
    {
        var anchor = element.FirstChild ?? element;
        var changed =
            !ReferenceEquals(_selectionAnchorNode, anchor) ||
            !ReferenceEquals(_selectionFocusNode, anchor) ||
            _selectionAnchorOffset != 0 ||
            _selectionFocusOffset != 0;

        _selectionAnchorNode = anchor;
        _selectionFocusNode = anchor;
        _selectionAnchorOffset = 0;
        _selectionFocusOffset = 0;

        if (changed)
        {
            DispatchSelectionChange(element.OwnerDocument);
        }
    }

    private JsValue CreateSelectionValue()
    {
        var anchorNode = ToHostNodeOrNull(_selectionAnchorNode);
        var focusNode = ToHostNodeOrNull(_selectionFocusNode);
        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["anchorNode"] = anchorNode,
            ["focusNode"] = focusNode,
            ["anchorOffset"] = JsValue.FromInt32(_selectionAnchorOffset),
            ["focusOffset"] = JsValue.FromInt32(_selectionFocusOffset),
            ["isCollapsed"] = JsValue.FromBoolean(ReferenceEquals(_selectionAnchorNode, _selectionFocusNode) && _selectionAnchorOffset == _selectionFocusOffset),
            ["rangeCount"] = JsValue.FromInt32(_selectionAnchorNode == null ? 0 : 1),
            ["type"] = JsValue.FromString(_selectionAnchorNode == null ? "None" : "Caret")
        });
    }

    private void DispatchSelectionChange(Document document)
    {
        if (document == null || _interpreter == null)
        {
            return;
        }

        var target = ToHostOrNull(document, HostObjectKind.DomDocument);
        var eventValue = CreateBrowserDomEventValue(
            null,
            "selectionchange",
            new BrowserDomEventInit
            {
                Bubbles = false,
                Cancelable = false,
                Composed = false,
                IsTrusted = true
            },
            out _);
        _interpreter.SetObjectProperty(eventValue, "target", target);
        _interpreter.SetObjectProperty(eventValue, "srcElement", target);
        _interpreter.SetObjectProperty(eventValue, "currentTarget", target);

        DispatchBrowserEvent(_documentEventListeners, "selectionchange", target, eventValue);

        var handler = GetStoredHostPropertyOrUndefined(document, "onselectionchange");
        if (_interpreter.CanCallValue(handler))
        {
            TryInvokeFenJsEventCallback(handler, target, eventValue, "selectionchange");
        }
    }

    /// <summary>
    /// HTML "reset the form": clears the dirty value and checkedness flags on
    /// every control, so each one goes back to tracking its markup defaults.
    /// </summary>
    internal void ResetFormFromScript(Element element)
    {
        if (element == null || !string.Equals(element.TagName, "FORM", StringComparison.OrdinalIgnoreCase))
            return;

        try
        {
            foreach (var control in element.Descendants().OfType<Element>())
            {
                FenBrowser.FenEngine.Rendering.ElementStateManager.Instance
                    .ResetFormControlState(control);
            }

            // A select needs its selection re-derived after its options go back to
            // their defaults: a dropdown whose markup selects nothing still has to
            // end up showing its first option.
            foreach (var select in element.Descendants().OfType<Element>())
            {
                if (string.Equals(select.NodeName, "SELECT", StringComparison.OrdinalIgnoreCase))
                {
                    FenBrowser.FenEngine.Rendering.SelectSelection.AskForReset(select);
                }
            }
        }
        catch (Exception ex)
        {
            EngineLogCompat.Error($"[ResetForm] Failed: {ex.Message}", LogCategory.JavaScript);
        }
    }

    internal void SubmitFormFromScript(Element element)
    {
        if (element == null || !string.Equals(element.TagName, "FORM", StringComparison.OrdinalIgnoreCase))
            return;

        try
        {
            var action = element.GetAttribute("action") ?? string.Empty;
            var method = element.GetAttribute("method") ?? "GET";
            var doc = element.OwnerDocument;
            var baseUrlStr = _currentBaseUri?.AbsoluteUri ?? doc?.BaseURI ?? doc?.URL ?? "about:blank";
            var baseUri = new Uri(baseUrlStr);

            Uri requestUri;
            if (!string.IsNullOrEmpty(action) && Uri.TryCreate(action, UriKind.Absolute, out var absoluteUri))
            {
                requestUri = absoluteUri;
            }
            else
            {
                requestUri = new Uri(baseUri, action ?? string.Empty);
            }

            // The same entry list the user-initiated path builds: it honours
            // disabled controls, unchecked boxes and select state, none of which a
            // flat sweep of every input attribute gets right.
            var entries = FenBrowser.FenEngine.Rendering.BrowserHost
                .CollectFormSubmissionEntries(element, submitter: null);

            if (method.Equals("POST", StringComparison.OrdinalIgnoreCase))
            {
                var (body, contentType) = FenBrowser.FenEngine.Rendering.BrowserHost
                    .EncodeFormSubmissionBody(element, entries);
                _host.PostForm(requestUri, body, contentType);
                return;
            }

            var target = FenBrowser.FenEngine.Rendering.BrowserHost
                .AppendQueryToUri(requestUri, entries);
            if (!string.IsNullOrEmpty(target) && Uri.TryCreate(target, UriKind.Absolute, out var queryUri))
            {
                requestUri = queryUri;
            }

            NavigateOwningBrowsingContext(requestUri);
        }
        catch (Exception ex)
        {
            EngineLogCompat.Error($"[SubmitForm] Failed: {ex.Message}", LogCategory.JavaScript);
        }
    }

    private void SetDocumentReadyState(string documentReadyState)
    {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            _documentReadyState = string.IsNullOrWhiteSpace(documentReadyState)
                ? "loading"
                : documentReadyState;
        }
    }

    private Element GetCurrentScriptElement()
    {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            return _currentScriptElement;
        }
    }

    private BrowserScriptLoadingRecord GetCurrentScriptRecord()
    {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            return _currentScriptRecord;
        }
    }

    private void SetCurrentScriptElement(Element scriptElement, BrowserScriptLoadingRecord scriptRecord = null)
    {
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            _currentScriptElement = scriptElement;
            _currentScriptRecord = scriptElement == null ? null : scriptRecord;
        }
    }

    private Dictionary<string, JsValue> GetHostPropertyStore(object receiver)
    {
        return _hostPropertyStore.GetOrCreateValue(receiver);
    }

    private void AddBrowserEventListener(List<BrowserEventListener> listeners, IReadOnlyList<JsValue> args)
    {
        if (args.Count < 2)
        {
            return;
        }

        var type = CoerceToHostString(args[0]);
        var callback = args[1];
        if (string.IsNullOrWhiteSpace(type) || !CanInvokeBrowserEventListener(callback))
        {
            return;
        }

        var capture = false;
        var once = false;
        var signal = JsValue.Undefined;
        if (args.Count >= 3)
        {
            ParseEventListenerOptions(args[2], out capture, out once, out _, out signal);
        }

        // DOM 2.7 step 2: an already-aborted signal means the listener is never
        // added at all.
        var hasSignal = signal.Tag == JsValueTag.Object;
        if (hasSignal && ReadJsBoolProperty(signal, "aborted"))
        {
            return;
        }

        // DOM 2.7 "add an event listener" step 4: a listener whose type, callback
        // and capture flag all match one already on the target is not appended.
        // Without this, code that registers defensively -- the same handler on
        // every render, say -- got a second registration each time and the handler
        // ran once per registration.
        foreach (var existing in listeners)
        {
            if (string.Equals(existing.Type, type, StringComparison.Ordinal) &&
                existing.Capture == capture &&
                existing.Callback.Equals(callback))
            {
                return;
            }
        }

        var listener = new BrowserEventListener(type, callback, capture, once);
        listeners.Add(listener);

        // DOM 2.7 step 5: aborting the signal removes the listener. Nothing was
        // watching the signal before, so { signal } read as a no-op and the
        // handler kept firing after abort() -- the one teardown mechanism that
        // does not need the original callback to be kept around, and the reason
        // it is what modern code reaches for.
        if (!hasSignal)
        {
            return;
        }

        var addToSignal = ReadJsProperty(signal, "addEventListener");
        if (!_interpreter.CanCallValue(addToSignal))
        {
            return;
        }

        var remover = _interpreter.AllocateNativeFunction(
            "__fenAbortEventListener",
            (_, _) =>
            {
                listeners.Remove(listener);
                return JsValue.Undefined;
            },
            length: 1);

        try
        {
            _interpreter.InvokeFunction(
                addToSignal,
                new[] { JsValue.FromString("abort"), remover },
                signal);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Debug(
                $"[FenJsBridge] Could not observe an AbortSignal for '{type}': {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    private bool CanInvokeBrowserEventListener(JsValue callback)
    {
        if (_interpreter.CanCallValue(callback))
        {
            return true;
        }

        if (callback.Tag != JsValueTag.Object)
        {
            return false;
        }

        var handleEvent = ReadJsProperty(callback, "handleEvent");
        return _interpreter.CanCallValue(handleEvent);
    }

    private void RemoveBrowserEventListener(List<BrowserEventListener> listeners, IReadOnlyList<JsValue> args)
    {
        if (args.Count < 2)
        {
            return;
        }

        var type = CoerceToHostString(args[0]);
        var callback = args[1];
        var capture = false;
        if (args.Count >= 3)
        {
            ParseEventListenerOptions(args[2], out capture, out _);
        }

        for (var i = listeners.Count - 1; i >= 0; i--)
        {
            var listener = listeners[i];
            if (string.Equals(listener.Type, type, StringComparison.Ordinal) &&
                listener.Capture == capture &&
                listener.Callback.Equals(callback))
            {
                listeners.RemoveAt(i);
            }
        }
    }

    private List<BrowserEventListener> GetElementListeners(Element element)
    {
        return _elementEventListeners.GetOrCreateValue(element);
    }

    private bool ReadPropagationStopped(
        JsValue eventValue,
        BrowserDomEventDispatchState dispatchState)
    {
        return dispatchState?.StopPropagation == true ||
               ReadJsBoolProperty(eventValue, "_propagationStopped") ||
               ReadJsBoolProperty(eventValue, "cancelBubble");
    }

    private bool ReadEventDefaultPrevented(
        JsValue eventValue,
        BrowserDomEventDispatchState dispatchState)
    {
        return dispatchState?.DefaultPrevented == true ||
               ReadJsBoolProperty(eventValue, "defaultPrevented");
    }

    private bool ReadImmediatePropagationStopped(
        JsValue eventValue,
        BrowserDomEventDispatchState dispatchState)
    {
        return dispatchState?.StopImmediatePropagation == true ||
               ReadJsBoolProperty(eventValue, "_immediatePropagationStopped");
    }

    private void DispatchElementEvent(
        Element element,
        string type,
        JsValue eventValue = default,
        BrowserDomEventDispatchState dispatchState = null)
    {
        if (element != null &&
            _elementEventListeners.TryGetValue(element, out var listeners) &&
            listeners != null)
        {
            DispatchBrowserEvent(
                listeners,
                type,
                ToHostOrNull(element, HostObjectKind.DomElement),
                eventValue,
                dispatchState);
        }
    }

    /// <summary>
    /// Full WHATWG-compliant event dispatch with capture, target, and bubble phases.
    /// Dispatches to element listeners, document listeners, and window listeners
    /// following the DOM event propagation algorithm.
    /// </summary>
    private bool DispatchEventFull(
        Element target,
        string type,
        JsValue eventValue,
        BrowserDomEventDispatchState dispatchState)
    {
        if (target == null || eventValue.Tag == JsValueTag.Undefined)
            return true;

        // Listeners run arbitrary script between the reads of the event below, and a
        // collection one of them triggers must not sweep the event under the dispatch.
        using var eventPins = PinFenJsValues(eventValue);

        // Check if event bubbles
        var bubblesValue = ReadJsProperty(eventValue, "bubbles");
        var bubbles = bubblesValue.Tag == JsValueTag.Boolean && bubblesValue.AsBoolean();

        // Set target on event if not already set (JS-dispatched events may already have it)
        var existingTarget = ReadJsProperty(eventValue, "target");
        if (existingTarget.Tag == JsValueTag.Undefined || existingTarget.Tag == JsValueTag.Null)
        {
            var targetHost = ToHostOrNull(target, HostObjectKind.DomElement);
            _interpreter.SetObjectProperty(eventValue, "target", targetHost);
            _interpreter.SetObjectProperty(eventValue, "srcElement", targetHost);
        }

        // Build ancestor chain: target â†’ parent â†’ ... â†’ rootmost element
        var path = new List<Element>();
        var current = target;
        while (current != null)
        {
            path.Add(current);
            current = current.ParentElement;
        }
        // path[0] = target, path[Count-1] = rootmost element

        if (path.Count == 0)
            return !ReadEventDefaultPrevented(eventValue, dispatchState);

        var document = target.OwnerDocument;
        var docHost = document == null ? JsValue.Undefined : ToHostOrNull(document, HostObjectKind.DomDocument);
        var windowTarget = GetActiveWindowEventTarget();

        // 1. CAPTURE PHASE â€” fire capture listeners on ancestors from root down to target's parent
        _interpreter.SetObjectProperty(eventValue, "eventPhase", JsValue.FromInt32(1)); // Event.CAPTURING_PHASE
        if (windowTarget.Tag != JsValueTag.Undefined)
        {
            DispatchBrowserEventWithState(
                GetActiveWindowEventListeners(), type, windowTarget, eventValue, dispatchState, capture: true);
        }

        if (!ReadPropagationStopped(eventValue, dispatchState) &&
            docHost.Tag != JsValueTag.Undefined)
        {
            DispatchBrowserEventWithState(
                _documentEventListeners, type, docHost, eventValue, dispatchState, capture: true);
        }

        for (int i = path.Count - 1; i > 0; i--)
        {
            if (ReadPropagationStopped(eventValue, dispatchState))
                break;
            DispatchEventToElementWithPhase(path[i], type, eventValue, dispatchState, capture: true);
        }

        // 2. TARGET PHASE â€” fire all listeners on the target (both capture and non-capture)
        if (!ReadPropagationStopped(eventValue, dispatchState))
        {
            _interpreter.SetObjectProperty(eventValue, "eventPhase", JsValue.FromInt32(2)); // Event.AT_TARGET
            DispatchEventToElementWithPhase(target, type, eventValue, dispatchState, capture: null);
        }

        // 3. BUBBLE PHASE â€” fire non-capture listeners up the ancestor chain, then document, then window
        if (bubbles && !ReadPropagationStopped(eventValue, dispatchState))
        {
            _interpreter.SetObjectProperty(eventValue, "eventPhase", JsValue.FromInt32(3)); // Event.BUBBLING_PHASE
            for (int i = 1; i < path.Count; i++)
            {
                if (ReadPropagationStopped(eventValue, dispatchState))
                    break;
                DispatchEventToElementWithPhase(path[i], type, eventValue, dispatchState, capture: false);
            }

            // Document listeners
            if (!ReadPropagationStopped(eventValue, dispatchState))
            {
                if (document != null && docHost.Tag != JsValueTag.Undefined)
                {
                    DispatchBrowserEventWithState(
                        _documentEventListeners, type, docHost, eventValue, dispatchState, capture: false);

                    // Document inline on* handler
                    if (!ReadImmediatePropagationStopped(eventValue, dispatchState))
                    {
                        var docHandler = GetStoredHostPropertyOrUndefined(document, "on" + type);
                        if (_interpreter != null && _interpreter.CanCallValue(docHandler))
                        {
                            TryInvokeFenJsEventCallback(docHandler, docHost, eventValue, type);
                        }
                    }
                }
            }

            // Window listeners
            if (!ReadPropagationStopped(eventValue, dispatchState))
            {
                DispatchBrowserEventWithState(
                    GetActiveWindowEventListeners(), type, windowTarget, eventValue, dispatchState, capture: false);

                // Window inline on* handler
                if (!ReadImmediatePropagationStopped(eventValue, dispatchState) &&
                    _interpreter != null &&
                    TryReadWindowEventHandler(windowTarget, type, out var winHandler) &&
                    _interpreter.CanCallValue(winHandler))
                {
                    InvokeWindowEventHandler(winHandler, windowTarget, eventValue, type);
                }
            }
        }

        return !ReadEventDefaultPrevented(eventValue, dispatchState);
    }

    /// <summary>
    /// Dispatches an event to a single element during a specific propagation phase.
    /// Filters listeners by type and capture phase, invokes callbacks with propagation
    /// checking, handles 'once' removal, and invokes inline on* handlers during
    /// bubble/target phases.
    /// </summary>
    private void DispatchEventToElementWithPhase(
        Element element,
        string type,
        JsValue eventValue,
        BrowserDomEventDispatchState dispatchState,
        bool? capture)
    {
        if (element == null)
            return;
        if (ReadImmediatePropagationStopped(eventValue, dispatchState))
            return;

        var currentTarget = ToHostOrNull(element, HostObjectKind.DomElement);
        _interpreter.SetObjectProperty(eventValue, "currentTarget", currentTarget);

        // Fire registered event listeners. DOM §2.9 "inner invoke": the list is cloned
        // before any listener runs, so one added during this dispatch waits for the next
        // event (a test that registers an "unexpected seeked" guard inside its seeked
        // handler must not see the same event) and one removed is skipped.
        if (_elementEventListeners.TryGetValue(element, out var allListeners) &&
            allListeners != null && allListeners.Count > 0)
        {
            var snapshot = allListeners.ToArray();
            for (int i = 0; i < snapshot.Length; i++)
            {
                if (ReadImmediatePropagationStopped(eventValue, dispatchState))
                    break;

                var listener = snapshot[i];
                if (!string.Equals(listener.Type, type, StringComparison.Ordinal))
                    continue;
                if (capture.HasValue && listener.Capture != capture.Value)
                    continue;
                if (!allListeners.Contains(listener))
                    continue;

                if (listener.Once)
                {
                    allListeners.RemoveAll(existing =>
                        string.Equals(existing.Type, listener.Type, StringComparison.Ordinal) &&
                        existing.Capture == listener.Capture &&
                        existing.Callback.Equals(listener.Callback));
                }

                TryInvokeFenJsEventCallback(listener.Callback, currentTarget, eventValue, type);
            }
        }

        // Invoke inline on* handler during bubble/target phases (NOT during capture)
        if (!capture.HasValue || capture.Value == false)
        {
            if (!ReadImmediatePropagationStopped(eventValue, dispatchState))
            {
                var handler = GetStoredHostPropertyOrUndefined(element, "on" + type);
                if (_interpreter != null && _interpreter.CanCallValue(handler))
                {
                    TryInvokeFenJsEventCallback(handler, currentTarget, eventValue, type);
                }
            }
        }
    }

    /// <summary>
    /// Dispatches event listeners with propagation flag checking.
    /// Like DispatchBrowserEvent but respects stopImmediatePropagation.
    /// </summary>
    private void DispatchBrowserEventWithState(
        List<BrowserEventListener> listeners,
        string type,
        JsValue currentTarget,
        JsValue eventValue,
        BrowserDomEventDispatchState dispatchState,
        bool? capture = null)
    {
        if (listeners.Count == 0 || ReadImmediatePropagationStopped(eventValue, dispatchState))
            return;

        _interpreter.SetObjectProperty(eventValue, "currentTarget", currentTarget);

        // DOM §2.9 "inner invoke": the listener list is cloned before any listener
        // runs, so one added during this dispatch waits for the next event and one
        // removed is skipped. Walking the live list let a window capture listener
        // that re-registers itself while a page is still loading (web-vitals'
        // onLoad helper, on every <img> load) run its own new copy without end.
        var snapshot = listeners.ToArray();
        for (int i = 0; i < snapshot.Length; i++)
        {
            if (ReadImmediatePropagationStopped(eventValue, dispatchState))
                break;

            var listener = snapshot[i];
            if (!string.Equals(listener.Type, type, StringComparison.Ordinal))
                continue;
            if (capture.HasValue && listener.Capture != capture.Value)
                continue;
            if (!listeners.Contains(listener))
                continue;

            if (listener.Once)
            {
                listeners.RemoveAll(existing =>
                    string.Equals(existing.Type, listener.Type, StringComparison.Ordinal) &&
                    existing.Capture == listener.Capture &&
                    existing.Callback.Equals(listener.Callback));
            }

            TryInvokeFenJsEventCallback(listener.Callback, currentTarget, eventValue, type);
        }
    }

    // HTML 8.4 "the end": DOMContentLoaded, then - once everything that delays
    // the load event is done - readyState complete and the window's load event.
    // Returns the document when there is one to finish loading.
    private Document DispatchDomContentLoaded()
    {
        var document = _currentDomRoot as Document ?? _currentDomRoot?.OwnerDocument;
        if (document == null)
        {
            SetDocumentReadyState("complete");
            UpdateEventLoopSnapshot(snapshot =>
            {
                snapshot.Status = "completed-no-document";
                snapshot.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            });
            AddEventLoopRecord("DocumentReadyStateComplete", "no-document");
            return null;
        }

        SetDocumentReadyState("interactive");
        FireDocumentReadyStateChange(document);
        var domContentLoadedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        UpdateEventLoopSnapshot(snapshot =>
        {
            snapshot.DomContentLoadedFired = true;
            snapshot.DomContentLoadedUtc = domContentLoadedUtc;
        });
        AddEventLoopRecord("DOMContentLoadedFired", "document");
        LogEventLoop(
            "DOMContentLoadedFired",
            LogSeverity.Info,
            "[FenJsBridge] DOMContentLoaded dispatched",
            new Dictionary<string, object>
            {
                ["documentReadyState"] = "interactive"
            });
        DispatchBrowserEvent(
            _documentEventListeners,
            "DOMContentLoaded",
            ToHostOrNull(document, HostObjectKind.DomDocument));
        return document;
    }

    private void DispatchWindowLoad(Document document)
    {
        // HTML "the end" step 7: the load event waits until nothing in the
        // document is delaying it (a media element fetching its resource).
        if (TryDeferDocumentLoadCompletion())
        {
            return;
        }

        CompleteDocumentLoad(document);
    }

    /// <summary>Readiness "complete", then the load event (HTML "the end" steps 7-9).</summary>
    private void CompleteDocumentLoad(Document document)
    {
        SetDocumentReadyState("complete");
        FireDocumentReadyStateChange(document);
        InvokeBodyOnloadAttribute(document);
        DispatchWindowLoadHandlers();
        MarkEventLoopCompleted();
    }

    /// <summary>
    /// Fires the <c>readystatechange</c> event at the document after a readyState
    /// transition (HTML: the document fires readystatechange whenever its
    /// readiness changes, including the interactive and complete transitions).
    /// </summary>
    private void FireDocumentReadyStateChange(Document document)
    {
        var docHost = ToHostOrNull(document, HostObjectKind.DomDocument);
        var eventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["type"] = JsValue.FromString("readystatechange"),
            ["target"] = docHost,
            ["currentTarget"] = docHost
        });
        DispatchBrowserEvent(_documentEventListeners, "readystatechange", docHost, eventValue);

        var handler = GetStoredHostPropertyOrUndefined(document, "onreadystatechange");
        if (handler.Tag != JsValueTag.Undefined && _interpreter.CanCallValue(handler))
        {
            TryInvokeFenJsEventCallback(handler, docHost, eventValue, "readystatechange");
        }
    }

    private JsValue GetStoredHostPropertyOrUndefined(object receiver, string property)
    {
        var store = GetHostPropertyStore(receiver);
        return store.TryGetValue(property, out var value) ? value : JsValue.Undefined;
    }

    private void SetStoredHostProperty(object receiver, string property, JsValue value)
    {
        var store = GetHostPropertyStore(receiver);
        store[property] = value;
    }

    private JsValue CreateResolvedPromise(JsValue resolution)
    {
        var (promise, resolve, _) = ((IBuiltinContext)_interpreter).CreatePromiseCapability();
        _ = _interpreter.InvokeFunction(resolve, new[] { resolution }, JsValue.Undefined);
        return promise;
    }

    private JsValue CreateRejectedPromise(string message, string name)
    {
        var (promise, _, reject) = ((IBuiltinContext)_interpreter).CreatePromiseCapability();
        _ = _interpreter.InvokeFunction(reject, new[] { CreateErrorValue(name, message) }, JsValue.Undefined);
        return promise;
    }

    /// <summary>
    /// A real error object of the named kind: one of the ECMAScript error constructors, or
    /// a DOMException for the WebIDL error names. A page checks these with <c>instanceof</c>
    /// as often as it reads <c>name</c>, and an object carrying the right two properties is
    /// not the same thing.
    /// </summary>
    private JsValue CreateErrorValue(string name, string message)
    {
        name ??= "Error";
        bool isEcmaScriptError = name is "Error" or "TypeError" or "RangeError" or "SyntaxError"
            or "ReferenceError" or "EvalError" or "URIError";

        var ctor = ReadGlobalValueOrUndefined(isEcmaScriptError ? name : "DOMException");
        if (_interpreter.CanCallValue(ctor))
        {
            try
            {
                return isEcmaScriptError
                    ? _interpreter.ConstructValue(ctor, new[] { JsValue.FromString(message ?? string.Empty) })
                    : _interpreter.ConstructValue(ctor, new[] { JsValue.FromString(message ?? string.Empty), JsValue.FromString(name) });
            }
            catch
            {
                // A realm that has lost its constructors still gets something with the
                // right shape below.
            }
        }

        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["message"] = JsValue.FromString(message ?? string.Empty),
            ["name"] = JsValue.FromString(name)
        });
    }

    private JsValue CreateViewTransitionResult(JsValue updateArgument)
    {
        // CSS View Transitions Level 2: the argument is either the update callback
        // itself or an options object { update, types }. React 19's commit path uses
        // the object form, and treating that as "no callback" silently drops every
        // DOM mutation of the commit while still handing back settled promises - the
        // page then looks like it rendered nothing, with nothing thrown.
        var updateCallback = updateArgument;
        if (!_interpreter.CanCallValue(updateCallback) &&
            _interpreter.TryGetObjectProperty(updateArgument, "update", out var fromOptions))
        {
            updateCallback = fromOptions;
        }

        if (_interpreter.CanCallValue(updateCallback))
        {
            try
            {
                _ = _interpreter.InvokeFunction(updateCallback, Array.Empty<JsValue>(), JsValue.Undefined);
            }
            catch (Exception ex)
            {
                FenBrowser.Core.EngineLogCompat.Warn(
                    $"[FenJsBridge] startViewTransition callback failed: {ex.Message}",
                    FenBrowser.Core.Logging.LogCategory.JavaScript);
            }
        }

        var result = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["ready"] = CreateResolvedPromise(JsValue.Undefined),
            ["updateCallbackDone"] = CreateResolvedPromise(JsValue.Undefined),
            ["finished"] = CreateResolvedPromise(JsValue.Undefined)
        });
        _interpreter.SetObjectProperty(
            result,
            "skipTransition",
            _interpreter.AllocateNativeFunction("skipTransition", (_, _) => JsValue.Undefined, length: 0),
            enumerable: false);
        return result;
    }

    /// <summary>
    /// The URL API's parser (WHATWG URL 6.1 "URL(url, base)"): the input against the
    /// given base only -- unlike an attribute or fetch, `new URL` never consults the
    /// document's base, so a bare relative reference fails. Returns null on failure
    /// so `new URL` can throw and `URL.canParse` can answer false.
    /// </summary>
    private JsValue ParseFenJsUrl(IReadOnlyList<JsValue> args)
    {
        if (args == null ||
            args.Count == 0 ||
            args[0].Tag == JsValueTag.Undefined)
        {
            return JsValue.Null;
        }

        var input = CoerceToHostString(args[0]);
        FenBrowser.Core.Network.WhatwgUrl baseUrl = null;
        if (args.Count > 1 && args[1].Tag != JsValueTag.Undefined)
        {
            baseUrl = FenBrowser.Core.Network.WhatwgUrl.Parse(CoerceToHostString(args[1]));
            if (baseUrl == null)
            {
                return JsValue.Null;
            }
        }

        var url = FenBrowser.Core.Network.WhatwgUrl.Parse(input, baseUrl);
        if (url == null)
        {
            return JsValue.Null;
        }

        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["href"] = JsValue.FromString(url.Href),
            ["origin"] = JsValue.FromString(url.Origin),
            ["protocol"] = JsValue.FromString(url.Protocol),
            ["username"] = JsValue.FromString(url.Username),
            ["password"] = JsValue.FromString(url.Password),
            ["host"] = JsValue.FromString(url.Host),
            ["hostname"] = JsValue.FromString(url.Hostname),
            ["port"] = JsValue.FromString(url.Port),
            ["pathname"] = JsValue.FromString(url.Pathname),
            ["search"] = JsValue.FromString(url.Search),
            ["hash"] = JsValue.FromString(url.Hash)
        });
    }

    private void ApplyElementProperties(Element element, JsValue propertiesValue)
    {
        if (element == null || propertiesValue.Tag != JsValueTag.Object)
        {
            return;
        }

        var propertiesObject = _interpreter.Heap.GetObject(propertiesValue.AsObjectHandle());
        var context = (IBuiltinContext)_interpreter;
        foreach (var property in propertiesObject.EnumerateOwnProperties())
        {
            if (!property.Value.Enumerable ||
                string.IsNullOrWhiteSpace(property.Key) ||
                !context.TryGetPropertyValue(propertiesObject, propertiesValue, property.Key, out var propertyValue))
            {
                continue;
            }

            ApplyElementProperty(element, property.Key, propertyValue);
        }
    }

    // DOM 4.2.3 "insert" runs the insertion steps for every shadow-including inclusive
    // descendant. An iframe therefore loads when it lands in a shadow root, and when a
    // host whose shadow root already holds one is connected. Walking only the light tree
    // never loaded Cloudflare Turnstile's challenge iframe, which sits in a closed root.
    private void QueueFrameLoadsForTree(Node node)
    {
        if (node == null)
        {
            return;
        }

        var pending = new Stack<Node>();
        pending.Push(node);
        while (pending.Count > 0)
        {
            var current = pending.Pop();
            if (current is Element element)
            {
                if (DiagnosticPaths.IframeDiagnosticsEnabled && string.Equals(element.TagName, "iframe", StringComparison.OrdinalIgnoreCase))
                {
                    var src = element.GetAttribute("src") ?? "";
                    var isChallenge = src.Contains("challenge", StringComparison.OrdinalIgnoreCase) ||
                                     element.GetAttribute("class")?.Contains("challenge", StringComparison.OrdinalIgnoreCase) == true ||
                                     element.GetAttribute("id")?.Contains("challenge", StringComparison.OrdinalIgnoreCase) == true;
                    var label = ReferenceEquals(current, node) ? "new" : "descendant";
                    DiagnosticPaths.AppendLogText(
                        "iframe_diagnostics.txt",
                        $"{DateTimeOffset.UtcNow:O} QueueFrameLoadsForTree: {label} iframe src='{src}' isChallenge={isChallenge} connected={element.IsConnected} parent={element.ParentElement?.TagName ?? "null"}");
                }

                QueueFrameElementLoad(element);

                var attachedShadowRoot = element.GetAttachedShadowRoot();
                if (attachedShadowRoot != null)
                {
                    pending.Push(attachedShadowRoot);
                }
            }

            for (var child = current.LastChild; child != null; child = child.PreviousSibling)
            {
                pending.Push(child);
            }
        }
    }

    private static bool IsIFrameElement(Element element)
    {
        return string.Equals(element?.TagName, "iframe", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// HTML 4.8.5: an iframe in a document has a content navigable from the moment it
    /// is inserted, so its WindowProxy is reachable as window[n] and frames[n] (7.2.2
    /// indexed access) before its document has loaded, and the same object stays once
    /// it has. The page's scripts see every iframe the parser created, in tree order.
    /// </summary>
    private void EnsureChildNavigableWindows(Node domRoot)
    {
        if (domRoot == null || _fenJsGlobalThis.Tag != JsValueTag.Object)
        {
            return;
        }

        foreach (var node in domRoot.Descendants())
        {
            if (node is Element element && IsIFrameElement(element) && element.IsConnected)
            {
                try
                {
                    _ = GetOrCreateIFrameContentWindow(element);
                }
                catch (Exception ex)
                {
                    EngineLogCompat.Warn(
                        $"[FenJsBridge] Could not create the window for an iframe before scripts: {ex.GetType().Name}: {ex.Message}",
                        LogCategory.JavaScript);
                }
            }
        }
    }

    internal static bool IsCanvasElement(Element element)
    {
        return string.Equals(element?.TagName, "canvas", StringComparison.OrdinalIgnoreCase);
    }

    internal FenJsCanvasRenderingContext2DHost GetOrCreateCanvasContext(Element canvas, string contextKind)
    {
        if (!string.Equals(contextKind, "2d", StringComparison.OrdinalIgnoreCase))
        {
            // webgl/webgl2 contexts are not bridged yet; returning null surfaces
            // as JS null so feature checks fail cleanly instead of throwing.
            return null;
        }

        if (_canvasRenderingContexts.TryGetValue(canvas, out var existing))
        {
            return existing;
        }

        var created = new FenJsCanvasRenderingContext2DHost(canvas, () => RequestRender?.Invoke());
        _canvasRenderingContexts.Add(canvas, created);
        return created;
    }

    internal string CanvasToDataUrl(Element canvas, string mediaType)    {
        if (!_canvasRenderingContexts.TryGetValue(canvas, out var context) || context.Bitmap == null)
        {
            return "data:,";
        }

        var encoded = mediaType.Contains("jpeg", StringComparison.OrdinalIgnoreCase)
            ? SKImage.FromBitmap(context.Bitmap).Encode(SKEncodedImageFormat.Jpeg, 90)
            : SKImage.FromBitmap(context.Bitmap).Encode(SKEncodedImageFormat.Png, 100);
        if (encoded == null)
        {
            return "data:,";
        }

        return "data:image/" +
            (mediaType.Contains("jpeg", StringComparison.OrdinalIgnoreCase) ? "jpeg" : "png") +
            ";base64," +
            Convert.ToBase64String(encoded.ToArray());
    }

    /// <summary>
    /// document.hasFocus(): true when the document belongs to the active
    /// browsing-context tree (the current top document or one of its attached
    /// descendant frame documents).
    /// </summary>
    /// <summary>
    /// document.hasFocus(): FenBrowser exposes a single active browsing context
    /// per engine, and the JS `document` global resolves to a facade instance
    /// that is not reference-identical to the parsed document tree, so focus is
    /// reported for any live document the engine serves (matching a focused
    /// user browser; headless has no window-focus concept).
    /// </summary>
    internal bool DocumentHasFocus(Document document)
    {
        return document != null;
    }

    internal int GetCanvasContextSizeOrAttribute(Element canvas, string dimension)    {
        var raw = canvas.GetAttribute(dimension);
        if (int.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) && parsed > 0)
        {
            return parsed;
        }

        return string.Equals(dimension, "width", StringComparison.OrdinalIgnoreCase) ? 300 : 150;
    }

    private void ResizeCanvasContext(Element canvas)
    {
        if (!_canvasRenderingContexts.TryGetValue(canvas, out var context))
        {
            return;
        }

        var width = 300;
        var height = 150;
        if (int.TryParse(canvas.GetAttribute("width"), NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedWidth) && parsedWidth > 0)
        {
            width = parsedWidth;
        }

        if (int.TryParse(canvas.GetAttribute("height"), NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedHeight) && parsedHeight > 0)
        {
            height = parsedHeight;
        }

        context.Resize(width, height);
    }

    private SKBitmap ResolveCanvasImageSource(JsValue source)
    {
        var element = ResolveHostObjectOrNull<Element>(source);
        if (element == null)
        {
            return null;
        }

        if (IsCanvasElement(element) && _canvasRenderingContexts.TryGetValue(element, out var context))
        {
            return context.Bitmap;
        }

        if (IsVideoElement(element))
        {
            return CopyCurrentVideoFrame(element);
        }

        if (string.Equals(element.TagName, "img", StringComparison.OrdinalIgnoreCase))
        {
            var src = element.GetAttribute("src");
            if (!string.IsNullOrWhiteSpace(src))
            {
                var absolute = ResolveElementUrlProperty(element, "src");
                return ImageLoader.GetImage(absolute ?? src);
            }
        }

        return null;
    }

    private HttpContent CreateRequestContent(JsValue bodyValue, bool isBinaryBody)
    {
        if (isBinaryBody)
        {
            return new ByteArrayContent(ExtractBytesFromArrayLike(bodyValue));
        }

        return new StringContent(CoerceToHostString(bodyValue), Encoding.UTF8, "text/plain");
    }

    // defaultValue exists on the elements that have a default distinct from their
    // live value: input and textarea.
    private static bool IsValueDefaultingElement(Element element)
    {
        return string.Equals(element?.TagName, "input", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(element?.TagName, "textarea", StringComparison.OrdinalIgnoreCase);
    }

    // HTML §6.8.1 isContentEditable: the nearest inclusive ancestor whose
    // contenteditable attribute is in a valid state decides; an invalid value is
    // the inherit state and defers to the parent.
    private static bool IsEditingHostOrEditable(Element element)
    {
        for (var current = element; current != null; current = current.ParentElement)
        {
            switch (current.GetAttribute("contenteditable")?.ToLowerInvariant())
            {
                case "" or "true" or "plaintext-only":
                    return true;
                case "false":
                    return false;
            }
        }

        return false;
    }

    private static bool IsCheckableInputElement(Element element)
    {
        if (!string.Equals(element?.TagName, "input", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var type = element.GetAttribute("type");
        return string.Equals(type, "checkbox", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(type, "radio", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsCheckboxInputElement(Element element)
    {
        return string.Equals(element?.TagName, "input", StringComparison.OrdinalIgnoreCase) &&
               string.Equals(element.GetAttribute("type"), "checkbox", StringComparison.OrdinalIgnoreCase);
    }

    private void QueueFrameElementLoad(Element element)
    {
        if (element == null ||
            !IsIFrameElement(element) ||
            !element.IsConnected ||
            FrameElementLoader == null)
        {
            return;
        }

        // 1. Check for srcdoc (takes priority over src per HTML spec)
        var srcdoc = element.GetAttribute("srcdoc");
        if (!string.IsNullOrWhiteSpace(srcdoc))
        {
            var existingDoc = GetStoredHostPropertyOrUndefined(element, "__fenFrameSrcdocHash");
            var newHash = srcdoc.GetHashCode().ToString("x", CultureInfo.InvariantCulture);
            if (existingDoc.Tag != JsValueTag.Undefined &&
                string.Equals(CoerceToHostString(existingDoc), newHash, StringComparison.Ordinal))
            {
                return; // Already loaded this srcdoc content
            }

            SetStoredHostProperty(element, "__fenFrameSrcdocHash", JsValue.FromString(newHash));

            _ = Task.Run(async () =>
            {
                try
                {
                    await LoadFrameSrcdocAsync(element, srcdoc).ConfigureAwait(false);
                    RequestRender?.Invoke();
                }
                catch (Exception ex)
                {
                    EngineLogCompat.Warn(
                        $"[FenJsBridge] srcdoc frame load failed for <iframe>: {ex.Message}",
                        LogCategory.JavaScript);
                }
            });
            return;
        }

        // 2. Check for src URL
        var src = ResolveElementUrlProperty(element, "src");
        if (string.IsNullOrWhiteSpace(src) ||
            string.Equals(src, "about:blank", StringComparison.OrdinalIgnoreCase) ||
            src.StartsWith("javascript:", StringComparison.OrdinalIgnoreCase) ||
            src.StartsWith("data:", StringComparison.OrdinalIgnoreCase) ||
            !Uri.TryCreate(src, UriKind.Absolute, out var frameUri))
        {
            return;
        }

        var existing = GetStoredHostPropertyOrUndefined(element, "__fenFrameLoadUrl");
        if (existing.Tag != JsValueTag.Undefined &&
            string.Equals(CoerceToHostString(existing), frameUri.AbsoluteUri, StringComparison.Ordinal))
        {
            return;
        }

        SetStoredHostProperty(element, "__fenFrameLoadUrl", JsValue.FromString(frameUri.AbsoluteUri));

        _ = Task.Run(async () =>
        {
            try
            {
                await FrameElementLoader(element, frameUri).ConfigureAwait(false);
                RequestRender?.Invoke();
            }
            catch (Exception ex)
            {
                FenBrowser.Core.EngineLogCompat.Warn(
                    $"[FenJsBridge] iframe load failed for '{frameUri}': {ex.Message}",
                    FenBrowser.Core.Logging.LogCategory.JavaScript);
            }
        });
    }

    /// <summary>
    /// Parses srcdoc HTML content and loads it as the iframe's subdocument.
    /// The srcdoc content is treated as an HTML document with the parent page's
    /// base URI (per HTML spec Â§4.8.5 â€” srcdoc documents have the parent's URL
    /// for same-origin purposes).
    /// </summary>
    private async Task LoadFrameSrcdocAsync(Element frameElement, string srcdocHtml)
    {
        if (string.IsNullOrWhiteSpace(srcdocHtml) || frameElement == null || !frameElement.IsConnected)
        {
            return;
        }

        try
        {
            // srcdoc documents inherit the creator document's base URL
            var frameUri = _currentBaseUri ?? new Uri("about:srcdoc");
            var parsedDocument = HtmlParser.ParseDocument(
                srcdocHtml,
                new HtmlParserOptions { BaseUri = frameUri });

            var parsedRoot = parsedDocument?.DocumentElement;
            if (parsedRoot == null)
            {
                EngineLogCompat.Warn(
                    "[FenJsBridge] srcdoc parse produced no document element",
                    LogCategory.JavaScript);
                return;
            }

            while (frameElement.FirstChild != null)
            {
                frameElement.RemoveChild(frameElement.FirstChild);
            }

            frameElement.AppendChild(parsedDocument);

            // Wire up the frame's own DOM context and scripts.
            // The subdocument gets its own JS window bound to the frame element.
            GetOrCreateIFrameContentWindow(frameElement, parsedDocument, frameUri);
            await SetSubdocumentDomAsync(parsedRoot, frameUri).ConfigureAwait(false);

            FenBrowser.Core.EngineLogCompat.Info(
                $"[FenJsBridge] srcdoc frame loaded root='{parsedRoot.TagName}'",
                FenBrowser.Core.Logging.LogCategory.JavaScript);

            // HTML: the iframe element gets a load event once its document is there. The
            // src path already fires one; without this, a page that waits on iframe.onload
            // before talking to a srcdoc frame waits for ever.
            DispatchFrameElementLoadEvent(frameElement);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] srcdoc frame load failed: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }
    }

    /// <summary>
    /// Fires <c>load</c> at an iframe element whose document has just been put in place.
    /// It does not bubble and is not cancelable, as the specification says.
    /// </summary>
    private void DispatchFrameElementLoadEvent(Element frameElement)
    {
        if (frameElement is null || _realmAbandoned || _interpreter is null)
        {
            return;
        }

        try
        {
            var eventValue = CreateBrowserDomEventValue(
                frameElement,
                "load",
                new BrowserDomEventInit { Bubbles = false, Cancelable = false, Composed = false, IsTrusted = true },
                out var dispatchState);
            _ = DispatchEventFull(frameElement, "load", eventValue, dispatchState);
        }
        catch (Exception ex)
        {
            EngineLogCompat.Warn(
                $"[FenJsBridge] srcdoc frame load event failed: {ex.Message}",
                LogCategory.JavaScript);
        }
    }

    private void ApplyElementProperty(Element element, string property, JsValue value)
    {
        switch (property)
        {
            case "className":
                element.ClassName = CoerceToHostString(value);
                break;
            case "id":
                element.Id = CoerceToHostString(value);
                break;
            case "value":
                FenBrowser.FenEngine.Rendering.FormControlValue.Write(element, CoerceToHostString(value));
                break;
            case "defaultValue" when IsValueDefaultingElement(element):
                FenBrowser.FenEngine.Rendering.FormControlValue.WriteDefault(element, CoerceToHostString(value));
                break;
            case "checked" when IsCheckableInputElement(element):
                ElementStateManager.Instance.SetChecked(element, CoerceToHostBoolean(value));
                break;
            case "defaultChecked" when IsCheckableInputElement(element):
                // defaultChecked reflects the "checked" content attribute, which is
                // the default -- not the live checkedness.
                if (CoerceToHostBoolean(value))
                {
                    element.SetAttribute("checked", string.Empty);
                }
                else
                {
                    element.RemoveAttribute("checked");
                }
                break;
            case "type" when string.Equals(element.TagName, "input", StringComparison.OrdinalIgnoreCase):
                element.SetAttribute("type", CoerceToHostString(value));
                break;
            case "tabIndex":
                element.SetAttribute(
                    "tabindex",
                    ((int)CoerceToFiniteNumber(value, 0)).ToString(CultureInfo.InvariantCulture));
                break;
            case "width" when IsIFrameElement(element):
            case "height" when IsIFrameElement(element):
                element.SetAttribute(property, CoerceToHostString(value));
                NotifyResizeObservers(element);
                break;
            case "width" when IsCanvasElement(element):
            case "height" when IsCanvasElement(element):
                element.SetAttribute(property, CoerceToHostString(value));
                ResizeCanvasContext(element);
                break;
            case "src":
            case "srcdoc":
            case "href":
            case "nonce":
                element.SetAttribute(property, CoerceToHostString(value));
                if (string.Equals(property, "src", StringComparison.Ordinal) &&
                    IsIFrameElement(element))
                {
                    QueueFrameElementLoad(element);
                }
                if (string.Equals(property, "srcdoc", StringComparison.Ordinal) &&
                    IsIFrameElement(element))
                {
                    QueueFrameElementLoad(element);
                }
                break;
            case "innerHTML":
                element.InnerHTML = CoerceToHostString(value);
                if (ExecuteInlineScriptsOnInnerHTML)
                {
                    ExecuteInlineScriptsFromElement(element);
                }
                // The fragment parser inserted the new children: they upgrade
                // like any other insertion (HTML 4.13.4 / DOM "insert").
                UpgradeCustomElementTreeIfDefined(ToHostNodeOrNull(element));
                break;
            case "outerHTML":
            {
                // The element replaces itself, so the tree to upgrade and to run
                // inline scripts from is the parent it was replaced inside.
                var outerHtmlParent = element.ParentNode;
                element.OuterHTML = CoerceToHostString(value);
                if (outerHtmlParent is Element replacedIn)
                {
                    if (ExecuteInlineScriptsOnInnerHTML)
                    {
                        ExecuteInlineScriptsFromElement(replacedIn);
                    }
                    UpgradeCustomElementTreeIfDefined(ToHostNodeOrNull(replacedIn));
                }
                break;
            }
            case "textContent":
                element.TextContent = CoerceToHostString(value);
                break;
            default:
                SetStoredHostProperty(element, property, value);
                break;
        }
    }

    private JsValue GetOrCreateDomTokenListView(DOMTokenList tokenList)
    {
        var store = GetHostPropertyStore(tokenList);
        if (store.TryGetValue("__fenDomTokenListView", out var cached))
        {
            RefreshDomTokenIndices(cached, tokenList);
            return cached;
        }

        // Create the base view object with methods that don't need self-reference.
        var view = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["item"] = CreateDomTokenListItemMethod(tokenList),
            ["contains"] = CreateDomTokenListContainsMethod(tokenList),
            ["supports"] = CreateDomTokenListSupportsMethod(tokenList),
            ["values"] = GetOrCreateHostCallable(tokenList, "values",
                (_, _2) => BuildDomTokenArrayValue(tokenList), length: 0),
            ["keys"] = GetOrCreateHostCallable(tokenList, "keys",
                (_, _2) => BuildDomIndexArray(tokenList), length: 0),
            ["entries"] = GetOrCreateHostCallable(tokenList, "entries",
                (_, _2) => BuildDomEntryArray(tokenList), length: 0),
            ["forEach"] = GetOrCreateHostCallable(tokenList, "forEach",
                (_, _2) => JsValue.Undefined, length: 1),
            ["toString"] = GetOrCreateHostCallable(tokenList, "toString",
                (_, _2) => JsValue.FromString(tokenList.Value ?? string.Empty), length: 0),
        });

        // Now that view is declared, add the mutating methods that need self-reference.
        var viewObj = _interpreter.Heap.GetObject(view.AsObjectHandle());
        viewObj.DefineOwnProperty("add", new JsPropertyDescriptor(
            CreateDomTokenListAddMethod(tokenList, view), Writable: true, Enumerable: false, Configurable: true));
        viewObj.DefineOwnProperty("remove", new JsPropertyDescriptor(
            CreateDomTokenListRemoveMethod(tokenList, view), Writable: true, Enumerable: false, Configurable: true));
        viewObj.DefineOwnProperty("toggle", new JsPropertyDescriptor(
            CreateDomTokenListToggleMethod(tokenList, view), Writable: true, Enumerable: false, Configurable: true));
        viewObj.DefineOwnProperty("replace", new JsPropertyDescriptor(
            CreateDomTokenListReplaceMethod(tokenList, view), Writable: true, Enumerable: false, Configurable: true));
        viewObj.DefineOwnProperty(
            "value",
            JsPropertyDescriptor.Accessor(
                _interpreter.AllocateNativeFunction(
                    "get value",
                    (_, _) => JsValue.FromString(tokenList.Value ?? string.Empty),
                    length: 0),
                _interpreter.AllocateNativeFunction(
                    "set value",
                    (_, args) =>
                    {
                        tokenList.Value = args.Count > 0
                            ? CoerceToHostString(args[0])
                            : string.Empty;
                        RefreshDomTokenIndices(view, tokenList);
                        return JsValue.Undefined;
                    },
                    length: 1),
                Enumerable: true,
                Configurable: true));

        // Set length and numeric indices as refreshed data properties. `value`
        // remains a live accessor so writes update the associated DOM attribute.
        RefreshDomTokenIndices(view, tokenList);

        // Install Symbol.iterator.
        var iterSymId = _interpreter.GetWellKnownSymbolId("iterator");
        if (iterSymId != 0)
        {
            var iterFn = _interpreter.AllocateNativeFunction(
                "[Symbol.iterator]",
                (thisValue, _2) =>
                {
                    var len = tokenList.Length;
                    var items = new FenBrowser.Js.Runtime.JsValue[len];
                    for (int i = 0; i < len; i++)
                    {
                        var token = tokenList.Item(i);
                        items[i] = FenBrowser.Js.Runtime.JsValue.FromString(token ?? string.Empty);
                    }
                    var idx = 0;
                    var iteratorEntries = new Dictionary<string, JsValue>
                    {
                        ["next"] = _interpreter.AllocateNativeFunction("next",
                            (_, _3) =>
                            {
                                if (idx >= len)
                                {
                                    var doneResult = new Dictionary<string, JsValue>
                                    {
                                        ["value"] = JsValue.Undefined,
                                        ["done"] = JsValue.FromBoolean(true)
                                    };
                                    return _interpreter.AllocateObject(doneResult);
                                }
                                var resultDict = new Dictionary<string, JsValue>
                                {
                                    ["value"] = items[idx++],
                                    ["done"] = JsValue.FromBoolean(false)
                                };
                                return _interpreter.AllocateObject(resultDict);
                            }, length: 0)
                    };
                    var iterObj = _interpreter.AllocateObject(iteratorEntries);
                    var iterObjHandle = iterObj.AsObjectHandle();
                    var iterObjNative = _interpreter.Heap.GetObject(iterObjHandle);
                    iterObjNative.DefineOwnSymbolProperty(iterSymId,
                        new FenBrowser.Js.Objects.JsPropertyDescriptor(
                            _interpreter.AllocateNativeFunction("[Symbol.iterator]",
                                (self, _3) => self, length: 0),
                            Writable: true, Enumerable: false, Configurable: true));
                    return iterObj;
                },
                length: 0);
            viewObj.DefineOwnSymbolProperty(iterSymId,
                new FenBrowser.Js.Objects.JsPropertyDescriptor(
                    iterFn, Writable: true, Enumerable: false, Configurable: true));
        }

        AttachFenJsPrototype(view, "DOMTokenList");
        store["__fenDomTokenListView"] = view;
        return view;
    }

    private JsValue CreateDomTokenListItemMethod(DOMTokenList tokenList)
    {
        return GetOrCreateHostCallable(tokenList, "item",
            (_, args) =>
            {
                var index = args.Count > 0 && TryCoerceIndex(args[0], out var parsedIndex)
                    ? parsedIndex : -1;
                var item = tokenList.Item(index);
                return item == null ? JsValue.Null : JsValue.FromString(item);
            }, length: 1);
    }

    private JsValue CreateDomTokenListContainsMethod(DOMTokenList tokenList)
    {
        return GetOrCreateHostCallable(tokenList, "contains",
            (_, args) =>
            {
                var token = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                return JsValue.FromBoolean(tokenList.Contains(token));
            }, length: 1);
    }

    private JsValue CreateDomTokenListSupportsMethod(DOMTokenList tokenList)
    {
        return GetOrCreateHostCallable(tokenList, "supports",
            (_, args) =>
            {
                var token = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                return JsValue.FromBoolean(tokenList.Supports(token));
            }, length: 1);
    }

    private JsValue CreateDomTokenListAddMethod(DOMTokenList tokenList, JsValue view)
    {
        return GetOrCreateHostCallable(tokenList, "add",
            (_, args) =>
            {
                tokenList.Add(args.Select(CoerceToHostString).ToArray());
                RefreshDomTokenIndices(view, tokenList);
                return JsValue.Undefined;
            });
    }

    private JsValue CreateDomTokenListRemoveMethod(DOMTokenList tokenList, JsValue view)
    {
        return GetOrCreateHostCallable(tokenList, "remove",
            (_, args) =>
            {
                tokenList.Remove(args.Select(CoerceToHostString).ToArray());
                RefreshDomTokenIndices(view, tokenList);
                return JsValue.Undefined;
            });
    }

    private JsValue CreateDomTokenListToggleMethod(DOMTokenList tokenList, JsValue view)
    {
        return GetOrCreateHostCallable(tokenList, "toggle",
            (_, args) =>
            {
                var token = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                bool? force = null;
                if (args.Count > 1 && args[1].Tag != JsValueTag.Undefined)
                    force = CoerceToHostBoolean(args[1]);
                var result = tokenList.Toggle(token, force);
                RefreshDomTokenIndices(view, tokenList);
                return JsValue.FromBoolean(result);
            }, length: 1);
    }

    private JsValue CreateDomTokenListReplaceMethod(DOMTokenList tokenList, JsValue view)
    {
        return GetOrCreateHostCallable(tokenList, "replace",
            (_, args) =>
            {
                var oldToken = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                var newToken = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                var result = tokenList.Replace(oldToken, newToken);
                RefreshDomTokenIndices(view, tokenList);
                return JsValue.FromBoolean(result);
            }, length: 2);
    }

    private void RefreshDomTokenIndices(JsValue view, DOMTokenList tokenList)
    {
        var viewObj = _interpreter.Heap.GetObject(view.AsObjectHandle());
        // Update the derived length and numeric indices. The live `value`
        // accessor installed at view creation owns associated-attribute writes.
        viewObj.DefineOwnProperty("length",
            new JsPropertyDescriptor(
                JsValue.FromInt32(tokenList.Length),
                Writable: true, Enumerable: false, Configurable: true));
        // Set fresh numeric indices from the live token list.
        var maxOld = 0;
        foreach (var kv in viewObj.EnumerateOwnProperties())
        {
            if (kv.Key.Length > 0 && kv.Key[0] >= '0' && kv.Key[0] <= '9' &&
                int.TryParse(kv.Key, NumberStyles.Integer, CultureInfo.InvariantCulture, out var n))
            {
                maxOld = Math.Max(maxOld, n + 1);
            }
        }
        // Clear stale indices beyond the current length.
        for (var i = tokenList.Length; i < maxOld; i++)
        {
            viewObj.DeleteProperty(i.ToString(CultureInfo.InvariantCulture));
        }
        // Set/update indices for current tokens.
        for (var i = 0; i < tokenList.Length; i++)
        {
            var item = tokenList.Item(i);
            viewObj.DefineOwnProperty(
                i.ToString(CultureInfo.InvariantCulture),
                new JsPropertyDescriptor(
                    JsValue.FromString(item ?? string.Empty),
                    Writable: true, Enumerable: true, Configurable: true));
        }
    }

    // Creates a JS array-like object from the tokens.
    private JsValue BuildDomTokenArrayValue(DOMTokenList tokenList)
    {
        var entries = new Dictionary<string, JsValue>(tokenList.Length + 1)
        {
            ["length"] = JsValue.FromInt32(tokenList.Length)
        };
        for (int i = 0; i < tokenList.Length; i++)
        {
            var token = tokenList.Item(i);
            entries[i.ToString(CultureInfo.InvariantCulture)] =
                JsValue.FromString(token ?? string.Empty);
        }
        return _interpreter.AllocateObject(entries);
    }

    private JsValue BuildDomIndexArray(DOMTokenList tokenList)
    {
        var len = tokenList.Length;
        var entries = new Dictionary<string, JsValue>(len + 1)
        {
            ["length"] = JsValue.FromInt32(len)
        };
        for (int k = 0; k < len; k++)
            entries[k.ToString(CultureInfo.InvariantCulture)] = JsValue.FromInt32(k);
        return _interpreter.AllocateObject(entries);
    }

    private JsValue BuildDomEntryArray(DOMTokenList tokenList)
    {
        var len = tokenList.Length;
        var entries = new Dictionary<string, JsValue>(len + 1)
        {
            ["length"] = JsValue.FromInt32(len)
        };
        for (int k = 0; k < len; k++)
        {
            var token = tokenList.Item(k);
            var pairEntries = new Dictionary<string, JsValue>(3)
            {
                ["length"] = JsValue.FromInt32(2),
                ["0"] = JsValue.FromInt32(k),
                ["1"] = JsValue.FromString(token ?? string.Empty)
            };
            entries[k.ToString(CultureInfo.InvariantCulture)] =
                _interpreter.AllocateObject(pairEntries);
        }
        return _interpreter.AllocateObject(entries);
    }

    private JsValue GetOrCreateTemplateContent(Element template)
    {
        if (template is HtmlTemplateElement htmlTemplate)
        {
            return ToHostNodeOrNull(htmlTemplate.Content);
        }

        var cached = GetStoredHostPropertyOrUndefined(template, "__fenTemplateContent");
        if (cached.Tag != JsValueTag.Undefined)
        {
            return cached;
        }

        var fragment = template.OwnerDocument?.CreateDocumentFragment() ?? new DocumentFragment(template.OwnerDocument);
        while (template.FirstChild != null)
        {
            fragment.AppendChild(template.FirstChild);
        }

        var value = ToHostNodeOrNull(fragment);
        SetStoredHostProperty(template, "__fenTemplateContent", value);
        return value;
    }

    private JsValue GetOrCreateIFrameContentDocument(Element iframe)
    {
        if (FindFrameContentDocument(iframe) is { } activeDocument)
        {
            var activeDocumentValue = ToHostOrNull(activeDocument, HostObjectKind.DomDocument);
            SetStoredHostProperty(iframe, "__fenIframeContentDocument", activeDocumentValue);
            return activeDocumentValue;
        }

        var cached = GetStoredHostPropertyOrUndefined(iframe, "__fenIframeContentDocument");
        if (cached.Tag != JsValueTag.Undefined)
        {
            return cached;
        }

        var document = Document.CreateHtmlDocument();
        var url = ResolveElementUrlProperty(iframe, "src");
        document.URL = string.IsNullOrWhiteSpace(url) ? "about:blank" : url;
        // HTML 4.2.3 fallback base URL: an about:blank or about:srcdoc document
        // resolves against its creator's base URL, not against itself.
        var creatorBase = iframe.OwnerDocument?.BaseURI;
        document.BaseURI =
            (document.URL.StartsWith("about:blank", StringComparison.OrdinalIgnoreCase) ||
             document.URL.StartsWith("about:srcdoc", StringComparison.OrdinalIgnoreCase)) &&
            !string.IsNullOrEmpty(creatorBase)
                ? creatorBase
                : document.URL;

        if (document.ParentNode == null)
        {
            iframe.AppendChild(document);
        }

        var value = ToHostOrNull(document, HostObjectKind.DomDocument);
        SetStoredHostProperty(iframe, "__fenIframeContentDocument", value);
        return value;
    }

    private JsValue GetOrCreateIFrameContentWindow(Element iframe)
    {
        return GetOrCreateIFrameContentWindow(iframe, null, null);
    }

    private JsValue GetIFrameContentWindowForCurrentContext(Element iframe)
    {
        // A same-origin child realm can reach iframe elements in its parent's
        // document (for example through parent.document). Those elements must
        // expose the same realm-local WindowProxy objects as parent.frames;
        // creating an independent iframe window here breaks strict identity
        // checks such as event.source === iframe.contentWindow.
        if (_embeddingFrameElement != null &&
            _embeddedParentWindowProxy.Tag == JsValueTag.Object &&
            ReferenceEquals(iframe?.OwnerDocument, _embeddingFrameElement.OwnerDocument))
        {
            return ReferenceEquals(iframe, _embeddingFrameElement)
                ? _fenJsGlobalThis
                : GetOrCreateSiblingWindowProxy(iframe, _embeddedParentWindowProxy);
        }

        var window = GetOrCreateIFrameContentWindow(iframe);
        if (CanCurrentContextAccessIFrameDocument(iframe))
        {
            return window;
        }

        return GetOrCreateCrossOriginChildWindowFacade(iframe, window);
    }

    private JsValue GetOrCreateIFrameContentWindow(Element iframe, Document frameDocument, Uri frameUri)
    {
        var cached = GetStoredHostPropertyOrUndefined(iframe, "__fenIframeContentWindow");
        if (cached.Tag != JsValueTag.Undefined)
        {
            UpdateIFrameContentWindow(cached, iframe, frameDocument, frameUri);
            return cached;
        }

        var document = frameDocument == null
            ? GetOrCreateIFrameContentDocument(iframe)
            : ToHostOrNull(frameDocument, HostObjectKind.DomDocument);
        var href = ResolveIFrameWindowHref(iframe, frameDocument, frameUri);

        var frameWindowListeners = GetIFrameWindowListeners(iframe);
        var window = _interpreter.AllocateForwardingObject();
        var location = CreatePlainLocationObject(href);

        _interpreter.SetObjectProperty(window, "document", document);
        _interpreter.SetObjectProperty(window, "location", location);
        var parentCanAccessFrame = IsSameOriginFrameAccess(iframe, href, GetParentDocumentUri(iframe));
        var frameElementValue = ToHostOrNull(iframe, HostObjectKind.DomElement);
        _interpreter.SetObjectProperty(window, "__fenFrameElement", frameElementValue);
        _interpreter.SetObjectProperty(window, "frameElement", parentCanAccessFrame ? frameElementValue : JsValue.Null);
        _interpreter.SetObjectProperty(window, "window", window);
        _interpreter.SetObjectProperty(window, "self", window);
        _interpreter.SetObjectProperty(window, "frames", window);
        _interpreter.SetObjectProperty(window, "length", JsValue.FromInt32(0));
        _interpreter.SetObjectProperty(window, "closed", JsValue.FromBoolean(false));
        SetIFrameViewportProperties(window, iframe);
        var frameName = iframe.GetAttribute("name") ?? string.Empty;
        _interpreter.SetObjectProperty(window, "name", JsValue.FromString(frameName));

        var parent = _fenJsGlobalThis.Tag == JsValueTag.Undefined
            ? window
            : parentCanAccessFrame
                ? GetOrCreateSameOriginTopWindowFacade()
                : GetOrCreateTopWindowFacade();
        _interpreter.SetObjectProperty(window, "parent", parent);
        _interpreter.SetObjectProperty(window, "top", parent);
        var exposedWindow = parentCanAccessFrame
            ? window
            : GetOrCreateCrossOriginChildWindowFacade(iframe, window);
        RegisterChildFrameOnParent(parent, exposedWindow, frameName);
        _interpreter.SetObjectProperty(
            window,
            "postMessage",
            _interpreter.AllocateNativeFunction(
                "postMessage",
                (_, args) =>
                {
                    var data = args.Count > 0 ? args[0] : JsValue.Undefined;
                    ReadPostMessageTarget(args, out var targetOrigin, out var ports);
                    var hasRealm = _iframeRealms.TryGetValue(iframe, out var frameRealm);
                    if (DiagnosticPaths.AppendEnabled)
                    {
                        DiagnosticPaths.AppendLogText(
                            "postmessage_probe.txt",
                            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] parent-to-child " +
                            $"frame={iframe.GetAttribute("name") ?? "?"} ownRealm={hasRealm} " +
                            $"data={DescribePostMessageValue(data)}{Environment.NewLine}");
                    }

                    if (hasRealm)
                    {
                        frameRealm!.QueueMessageFromParent(
                            ConvertJsValueToObject(data),
                            GetCurrentWindowOrigin(),
                            targetOrigin,
                            ExtractTransferredMessagePorts(ports));
                        return JsValue.Undefined;
                    }
                    QueueWindowMessage(window, frameWindowListeners, data, _fenJsGlobalThis, ports, targetOrigin);
                    return JsValue.Undefined;
                },
                length: 1));
        _interpreter.SetObjectProperty(
            window,
            "addEventListener",
            _interpreter.AllocateNativeFunction(
                "addEventListener",
                (_, args) =>
                {
                    AddBrowserEventListener(frameWindowListeners, args);
                    return JsValue.Undefined;
                },
                length: 2));
        _interpreter.SetObjectProperty(
            window,
            "removeEventListener",
            _interpreter.AllocateNativeFunction(
                "removeEventListener",
                (_, args) =>
                {
                    RemoveBrowserEventListener(frameWindowListeners, args);
                    return JsValue.Undefined;
                },
                length: 2));
        _interpreter.SetObjectProperty(
            window,
            "dispatchEvent",
            _interpreter.AllocateNativeFunction(
                "dispatchEvent",
                (_, args) =>
                {
                    var eventValue = args.Count > 0 ? args[0] : JsValue.Undefined;
                    return JsValue.FromBoolean(DispatchFrameWindowHostEvent(window, frameWindowListeners, eventValue));
                },
                length: 1));

        // â”€â”€ Forward standard browser globals onto the iframe contentWindow â”€â”€
        // In a real browser, window === globalThis, so window.setTimeout etc. work.
        // FenBrowser uses a plain JS object for iframe contentWindow, so we must
        // explicitly copy all standard browser APIs from the interpreter's globals
        // to make scripts like reCAPTCHA (which access window.setTimeout) work.
        var globalsToForward = new[]
        {
            // Timers
            "setTimeout", "setInterval", "clearTimeout", "clearInterval",
            "requestAnimationFrame", "cancelAnimationFrame",
            // Encoding
            "atob", "btoa",
            // DOM utilities
            "getComputedStyle", "matchMedia", "queueMicrotask", "structuredClone",
            // Observers
            "MutationObserver", "IntersectionObserver", "ResizeObserver", "PerformanceObserver",
            // Fetch / XHR
            "fetch", "XMLHttpRequest", "AbortController", "AbortSignal",
            "Headers", "Request", "Response",
            // Console
            "console",
            // Navigation objects
            "navigator", "performance", "crypto", "screen",
            // Constructors
            "Event", "CustomEvent", "MessageEvent", "URL", "URLSearchParams", "Image",
            "DOMParser", "FormData", "Blob", "File",
            "TextEncoder", "TextDecoder",
            "Map", "Set", "WeakMap", "WeakSet", "WeakRef",
            "Promise", "Proxy", "Symbol", "Intl", "Reflect",
            // Security
            "isSecureContext", "crossOriginIsolated", "origin",
            // Misc browser APIs
            "Notification", "trustedTypes", "chrome",
            "alert", "confirm", "prompt",
            // Error types
            "Error", "TypeError", "RangeError", "ReferenceError", "SyntaxError", "URIError", "EvalError",
            // Core JS (needed when reCAPTCHA does window.Array etc.)
            "Array", "Object", "Function", "String", "Number", "Boolean", "RegExp", "Date", "Math", "JSON",
            "parseInt", "parseFloat", "isNaN", "isFinite", "undefined", "NaN", "Infinity",
            "encodeURI", "encodeURIComponent", "decodeURI", "decodeURIComponent",
            "ArrayBuffer", "DataView", "Float32Array", "Float64Array",
            "Int8Array", "Int16Array", "Int32Array",
            "Uint8Array", "Uint8ClampedArray", "Uint16Array", "Uint32Array",
            "BigInt", "BigInt64Array", "BigUint64Array",
        };
        foreach (var name in globalsToForward)
        {
            var globalVal = _interpreter.ReadGlobalValueOrUndefined(name);
            if (globalVal.Tag != JsValueTag.Undefined)
            {
                _interpreter.SetObjectProperty(window, name, globalVal);
            }
        }

        SetStoredHostProperty(iframe, "__fenIframeContentWindow", window);
        ForwardContentWindowToFrameRealm(window, iframe);
        var defaultViewDocument = frameDocument;
        if (defaultViewDocument == null)
        {
            foreach (var child in iframe.ChildNodes)
            {
                if (child is Document childDocument)
                {
                    defaultViewDocument = childDocument;
                    break;
                }
            }
        }

        if (defaultViewDocument != null)
        {
            SetStoredHostProperty(defaultViewDocument, "__fenDefaultView", window);
        }

        return window;
    }

    private JsValue RegisterMessageChannel(IReadOnlyList<JsValue> args)
    {
        if (args == null || args.Count < 2 ||
            args[0].Tag != JsValueTag.Object || args[1].Tag != JsValueTag.Object)
        {
            return JsValue.FromBoolean(false);
        }

        var first = new MessagePortEndpoint
        {
            TraceId = Interlocked.Increment(ref _messagePortEndpointTraceSequence)
        };
        var second = new MessagePortEndpoint
        {
            TraceId = Interlocked.Increment(ref _messagePortEndpointTraceSequence)
        };
        first.Peer = second;
        second.Peer = first;
        BindMessagePort(first, args[0]);
        BindMessagePort(second, args[1]);
        return JsValue.FromBoolean(true);
    }

    private JsValue PostMessagePort(IReadOnlyList<JsValue> args)
    {
        if (args == null || args.Count == 0 ||
            !TryGetMessagePortEndpoint(args[0], out var source))
        {
            return JsValue.FromBoolean(false);
        }

        var target = source.Peer;
        var traceEnabled = IsFenJsMessageTransportTraceEnabled;
        var messageId = traceEnabled ? Interlocked.Increment(ref _messageTransportTraceSequence) : 0;
        var sourceFrame = traceEnabled ? ProbeFrame() : string.Empty;
        var targetFrame = traceEnabled ? target?.Owner?.ProbeFrame() ?? "<unowned>" : string.Empty;
        var payload = traceEnabled
            ? args.Count > 1
                ? DescribePostMessageValue(args[1])
                : JsValueTag.Undefined.ToString()
            : string.Empty;
        var transferredPortCount = traceEnabled && args.Count > 2 ? ReadArrayLikeLength(args[2]) : 0;
        if (traceEnabled)
        {
            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                "port-send-enter",
                messageId,
                source.TraceId,
                target?.TraceId ?? 0,
                sourceFrame,
                targetFrame,
                payload,
                transferredPortCount,
                0,
                target?.Closed ?? true,
                false,
                0,
                false,
                string.Empty));
        }
        if (source.Closed || target == null || target.Closed)
        {
            // Without this the whole failure is silent: script sees postMessage
            // return, and the probe file shows nothing at all for the send.
            DiagnosticPaths.AppendLogText(
                "postmessage_probe.txt",
                $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-send-DROPPED " +
                $"port#{source.TraceId}->#{target?.TraceId ?? 0} " +
                $"sourceClosed={source.Closed} targetMissing={target == null} " +
                $"targetClosed={target?.Closed ?? true} targetOwner=" +
                $"{(target?.Owner == null ? "<none>" : target.Owner.ProbeFrame())} " +
                $"data={DescribePostMessageValue(args.Count > 1 ? args[1] : JsValue.Undefined)}{Environment.NewLine}");
            if (traceEnabled)
            {
                TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                    "port-send-dropped",
                    messageId,
                    source.TraceId,
                    target?.TraceId ?? 0,
                    sourceFrame,
                    targetFrame,
                    payload,
                    transferredPortCount,
                    0,
                    target?.Closed ?? true,
                    false,
                    0,
                    false,
                    $"sourceClosed={source.Closed}; targetMissing={target == null}; targetOwnerMissing={target?.Owner == null}"));
            }
            return JsValue.FromBoolean(true);
        }

        var data = args.Count > 1 ? ConvertJsValueToObject(args[1]) : null;
        var transferredPorts = args.Count > 2
            ? ExtractTransferredMessagePorts(args[2])
            : Array.Empty<MessagePortEndpoint>();

        // Read the owner under the transit lock: the receiving realm binds the
        // port under the same lock, so this either sees an owner to deliver to
        // or a port still in flight, never a half-bound one.
        FenJsBrowserScriptEngine targetOwner;
        lock (target.TransitLock)
        {
            targetOwner = target.Owner;
            if (targetOwner == null && !target.Closed)
            {
                var queue = target.InTransitQueue ??= new List<PendingPortMessage>();
                if (queue.Count >= MaxInTransitPortMessages)
                {
                    DiagnosticPaths.AppendLogText(
                        "postmessage_probe.txt",
                        $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-send-OVERFLOW " +
                        $"port#{source.TraceId}->#{target.TraceId} queued={queue.Count}" +
                        $"{Environment.NewLine}");
                    return JsValue.FromBoolean(true);
                }

                queue.Add(new PendingPortMessage
                {
                    Data = data,
                    Transferred = transferredPorts,
                    MessageId = messageId,
                    SourcePortId = source.TraceId,
                    SourceFrame = sourceFrame,
                    TargetFrame = targetFrame,
                    Payload = payload,
                });
                DiagnosticPaths.AppendLogText(
                    "postmessage_probe.txt",
                    $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-send-QUEUED " +
                    $"port#{source.TraceId}->#{target.TraceId} depth={queue.Count} " +
                    $"data={DescribePostMessageValue(args.Count > 1 ? args[1] : JsValue.Undefined)}" +
                    $"{Environment.NewLine}");
                return JsValue.FromBoolean(true);
            }
        }

        DiagnosticPaths.AppendLogText(
            "postmessage_probe.txt",
            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-send " +
            $"port#{source.TraceId}->#{target.TraceId} to={targetOwner.ProbeFrame()} " +
            $"data={DescribePostMessageValue(args.Count > 1 ? args[1] : JsValue.Undefined)} " +
            $"transferCount={(args.Count > 2 ? ReadArrayLikeLength(args[2]) : 0)}{Environment.NewLine}");
        targetOwner.QueueMessagePort(
            target,
            data,
            transferredPorts,
            messageId,
            source.TraceId,
            sourceFrame,
            targetFrame,
            payload);
        if (traceEnabled)
        {
            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                "port-send-enqueued",
                messageId,
                source.TraceId,
                target.TraceId,
                sourceFrame,
                targetFrame,
                payload,
                transferredPorts.Count,
                0,
                false,
                false,
                0,
                false,
                string.Empty));
        }
        return JsValue.FromBoolean(true);
    }

    private JsValue CloseMessagePort(IReadOnlyList<JsValue> args)
    {
        if (args != null && args.Count > 0 && TryGetMessagePortEndpoint(args[0], out var endpoint))
        {
            lock (endpoint.TransitLock)
            {
                endpoint.Closed = true;
                endpoint.InTransitQueue = null;
            }
            _messagePortEndpoints.Remove(args[0].AsObjectHandle().ToInt64());
        }
        return JsValue.Undefined;
    }

    private bool TryGetMessagePortEndpoint(JsValue port, out MessagePortEndpoint endpoint)
    {
        if (port.Tag == JsValueTag.Object)
        {
            return _messagePortEndpoints.TryGetValue(port.AsObjectHandle().ToInt64(), out endpoint);
        }

        endpoint = null;
        return false;
    }

    private void BindMessagePort(MessagePortEndpoint endpoint, JsValue port)
    {
        _messagePortEndpoints[port.AsObjectHandle().ToInt64()] = endpoint;

        // Hold the transit lock across the flush. A sender only reads the owner
        // under this lock, so it either still sees no owner and queues behind
        // what is being flushed, or sees one and enqueues after the flush has
        // finished. Releasing first let a concurrent send overtake the backlog
        // and the messages arrived out of order.
        lock (endpoint.TransitLock)
        {
            endpoint.Owner = this;
            endpoint.Port = port;
            endpoint.Closed = false;
            var queued = endpoint.InTransitQueue;
            endpoint.InTransitQueue = null;

            _interpreter.SetObjectProperty(port, "_fenWindow", _fenJsGlobalThis);
            _interpreter.SetObjectProperty(port, "_fenClosed", JsValue.FromBoolean(false));

            if (queued == null)
            {
                return;
            }

            // The port itself decides whether to hold these: one that has not
            // been started keeps its queue, which is exactly what these messages
            // would have met had the port never moved.
            DiagnosticPaths.AppendLogText(
                "postmessage_probe.txt",
                $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-transit-flush " +
                $"port#{endpoint.TraceId} count={queued.Count}{Environment.NewLine}");
            foreach (var pending in queued)
            {
                QueueMessagePort(
                    endpoint,
                    pending.Data,
                    pending.Transferred,
                    pending.MessageId,
                    pending.SourcePortId,
                    pending.SourceFrame,
                    pending.TargetFrame,
                    pending.Payload);
            }
        }
    }

    private IReadOnlyList<MessagePortEndpoint> ExtractTransferredMessagePorts(JsValue ports)
    {
        if (ports.Tag != JsValueTag.Object)
        {
            return Array.Empty<MessagePortEndpoint>();
        }

        var result = new List<MessagePortEndpoint>();
        var length = ReadArrayLikeLength(ports);
        for (var index = 0; index < length; index++)
        {
            var port = ReadJsProperty(ports, index.ToString(CultureInfo.InvariantCulture));
            if (!TryGetMessagePortEndpoint(port, out var endpoint) || result.Contains(endpoint))
            {
                continue;
            }

            _messagePortEndpoints.Remove(port.AsObjectHandle().ToInt64());
            _interpreter.SetObjectProperty(port, "_fenClosed", JsValue.FromBoolean(true));
            lock (endpoint.TransitLock)
            {
                endpoint.Owner = null;
                endpoint.Port = JsValue.Undefined;
            }
            result.Add(endpoint);
        }

        // A transferred port is detached here and re-bound in the receiving
        // realm. Logging both halves is what makes "handed over and then never
        // used again" distinguishable from "never handed over".
        if (result.Count > 0)
        {
            DiagnosticPaths.AppendLogText(
                "postmessage_probe.txt",
                $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-transfer-out " +
                $"ports=[{string.Join(",", result.Select(e => "#" + e.TraceId))}]{Environment.NewLine}");
        }

        return result;
    }

    private JsValue ImportTransferredMessagePorts(IReadOnlyList<MessagePortEndpoint> endpoints)
    {
        if (endpoints == null || endpoints.Count == 0)
        {
            return _interpreter.AllocateArray(Array.Empty<JsValue>());
        }

        var ports = new JsValue[endpoints.Count];
        for (var index = 0; index < endpoints.Count; index++)
        {
            var port = EvaluateWithFenJsRaw("new MessagePort()");
            BindMessagePort(endpoints[index], port);
            ports[index] = port;
        }

        DiagnosticPaths.AppendLogText(
            "postmessage_probe.txt",
            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-transfer-in " +
            $"ports=[{string.Join(",", endpoints.Select(e => "#" + e.TraceId))}]{Environment.NewLine}");
        return _interpreter.AllocateArray(ports);
    }

    private int ReadArrayLikeLength(JsValue value)
    {
        var length = ReadJsProperty(value, "length");
        return length.Tag switch
        {
            JsValueTag.Int32 => Math.Max(0, length.AsInt32()),
            JsValueTag.Number => Math.Max(0, (int)length.AsNumber()),
            _ => 0
        };
    }

    private void QueueMessagePort(
        MessagePortEndpoint target,
        object data,
        IReadOnlyList<MessagePortEndpoint> transferredEndpoints,
        long messageId,
        long sourcePortId,
        string sourceFrame,
        string targetFrame,
        string payload)
    {
        var sessionGeneration = _fenJsSessionGeneration;
        var traceEnabled = IsFenJsMessageTransportTraceEnabled;
        var queuedAt = traceEnabled ? System.Diagnostics.Stopwatch.GetTimestamp() : 0;
        var transferCount = traceEnabled ? transferredEndpoints?.Count ?? 0 : 0;
        if (traceEnabled)
        {
            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                "port-enqueued",
                messageId,
                sourcePortId,
                target.TraceId,
                sourceFrame,
                targetFrame,
                payload,
                transferCount,
                0,
                target.Closed,
                false,
                0,
                false,
                string.Empty));
        }
        lock (_windowMessageQueueLock)
        {
            _windowMessageDeliveryTail = _windowMessageDeliveryTail.ContinueWith(
                _ =>
                {
                    var queueDelayMs = traceEnabled
                        ? System.Diagnostics.Stopwatch.GetElapsedTime(queuedAt).TotalMilliseconds
                        : 0;
                    if (traceEnabled)
                    {
                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                            "port-dequeued",
                            messageId,
                            sourcePortId,
                            target.TraceId,
                            sourceFrame,
                            targetFrame,
                            payload,
                            transferCount,
                            queueDelayMs,
                            target.Closed,
                            false,
                            0,
                            false,
                            string.Empty));
                    }
                    if (sessionGeneration != _fenJsSessionGeneration ||
                        target.Owner != this || target.Closed || target.Port.Tag != JsValueTag.Object)
                    {
                        if (traceEnabled)
                        {
                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                "port-delivery-dropped",
                                messageId,
                                sourcePortId,
                                target.TraceId,
                                sourceFrame,
                                targetFrame,
                                payload,
                                transferCount,
                                queueDelayMs,
                                target.Closed,
                                false,
                                0,
                                false,
                                $"staleSession={sessionGeneration != _fenJsSessionGeneration}; wrongOwner={target.Owner != this}; portTag={target.Port.Tag}"));
                        }
                        // The send side already logged; without this the message
                        // just disappears between the two realms.
                        if (DiagnosticPaths.AppendEnabled)
                        DiagnosticPaths.AppendLogText(
                            "postmessage_probe.txt",
                            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-DROPPED " +
                            $"port#{target.TraceId} " +
                            $"staleSession={sessionGeneration != _fenJsSessionGeneration} " +
                            $"wrongOwner={target.Owner != this} closed={target.Closed} " +
                            $"portTag={target.Port.Tag}{Environment.NewLine}");
                        return;
                    }

                    if (DiagnosticPaths.AppendEnabled)
                    DiagnosticPaths.AppendLogText(
                        "postmessage_probe.txt",
                        $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-deliver " +
                        $"port#{target.TraceId} from#{sourcePortId}{Environment.NewLine}");

                    try
                    {
                        if (traceEnabled)
                        {
                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                "port-worker-enter",
                                messageId,
                                sourcePortId,
                                target.TraceId,
                                sourceFrame,
                                targetFrame,
                                payload,
                                transferCount,
                                queueDelayMs,
                                false,
                                false,
                                0,
                                false,
                                string.Empty));
                        }
                        RunFenJsWithLargeStack<object>(() =>
                        {
                            SetFenJsWorkerPhase("messageport:waiting-interpreter-lock");
                            using (ScriptEngineLockProbe.Hold(_fenJsLock))
                            {
                                SetFenJsWorkerPhase("messageport:importing-ports");
                                // Import transferred ports in the receiving realm only after
                                // its queued delivery owns the interpreter lock. Acquiring the
                                // receiver lock synchronously from the sending realm deadlocks
                                // when two MessagePort handlers post to each other concurrently.
                                var transferredPorts = ImportTransferredMessagePorts(transferredEndpoints);
                                var eventValue = CreateMessageEventValue(
                                    ConvertObjectToJsValue(data),
                                    string.Empty,
                                    JsValue.Null,
                                    _fenJsGlobalThis,
                                    transferredPorts);
                                _interpreter.SetObjectProperty(eventValue, "target", target.Port);
                                _interpreter.SetObjectProperty(eventValue, "currentTarget", target.Port);
                                _interpreter.SetObjectProperty(eventValue, "srcElement", target.Port);

                                using (ActivateWindowCallbackContext(_fenJsGlobalThis, _windowEventListeners))
                                {
                                    SetFenJsWorkerPhase("messageport:dispatching-handler");
                                    var probeHandler = ReadJsProperty(target.Port, "onmessage");
                                    var probeListeners = ReadJsProperty(target.Port, "_fenListeners");
                                    var handlerCallable = _interpreter.CanCallValue(probeHandler);
                                    var listenerCount = ReadArrayLikeLength(probeListeners);
                                    var portEnabled = ReadJsBoolProperty(target.Port, "_fenEnabled");
                                    if (DiagnosticPaths.AppendEnabled)
                                    {
                                        DiagnosticPaths.AppendLogText(
                                            "postmessage_probe.txt",
                                            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] port-handlers " +
                                            $"port#{target.TraceId} onmessage=" +
                                            $"{handlerCallable} " +
                                            $"listeners={listenerCount} " +
                                            $"enabled={portEnabled}" +
                                            $"{Environment.NewLine}");
                                    }

                                    // Hand it to the port rather than walking its
                                    // handlers here: a port that has not been
                                    // started yet has to keep the message, and
                                    // only the port knows that.
                                    var deliverToPort = ReadJsProperty(target.Port, "_fenDeliver");
                                    var deliverCallable = _interpreter.CanCallValue(deliverToPort);
                                    if (traceEnabled)
                                    {
                                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                            "port-handler-state",
                                            messageId,
                                            sourcePortId,
                                            target.TraceId,
                                            sourceFrame,
                                            targetFrame,
                                            payload,
                                            transferCount,
                                            queueDelayMs,
                                            false,
                                            handlerCallable,
                                            listenerCount,
                                            portEnabled,
                                            $"deliverCallable={deliverCallable}"));
                                    }
                                    if (deliverCallable)
                                    {
                                        if (traceEnabled)
                                        {
                                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                                "port-handler-enter",
                                                messageId,
                                                sourcePortId,
                                                target.TraceId,
                                                sourceFrame,
                                                targetFrame,
                                                payload,
                                                transferCount,
                                                queueDelayMs,
                                                false,
                                                handlerCallable,
                                                listenerCount,
                                                portEnabled,
                                                string.Empty));
                                        }
                                        _interpreter.InvokeFunction(deliverToPort, new[] { eventValue }, target.Port);
                                        if (traceEnabled)
                                        {
                                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                                "port-handler-complete",
                                                messageId,
                                                sourcePortId,
                                                target.TraceId,
                                                sourceFrame,
                                                targetFrame,
                                                payload,
                                                transferCount,
                                                queueDelayMs,
                                                false,
                                                handlerCallable,
                                                listenerCount,
                                                portEnabled,
                                                string.Empty));
                                        }
                                    }
                                    else if (traceEnabled)
                                    {
                                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                            "port-handler-missing",
                                            messageId,
                                            sourcePortId,
                                            target.TraceId,
                                            sourceFrame,
                                            targetFrame,
                                            payload,
                                            transferCount,
                                            queueDelayMs,
                                            false,
                                            handlerCallable,
                                            listenerCount,
                                            portEnabled,
                                            string.Empty));
                                    }
                                }
                                SetFenJsWorkerPhase("messageport:microtask-checkpoint");
                                if (traceEnabled)
                                {
                                    TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                        "port-checkpoint-enter",
                                        messageId,
                                        sourcePortId,
                                        target.TraceId,
                                        sourceFrame,
                                        targetFrame,
                                        payload,
                                        transferCount,
                                        queueDelayMs,
                                        false,
                                        false,
                                        0,
                                        false,
                                        string.Empty));
                                }
                                _interpreter.PumpMicrotasks();
                                SetFenJsWorkerPhase("messageport:checkpoint-complete");
                                if (traceEnabled)
                                {
                                    TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                        "port-checkpoint-complete",
                                        messageId,
                                        sourcePortId,
                                        target.TraceId,
                                        sourceFrame,
                                        targetFrame,
                                        payload,
                                        transferCount,
                                        queueDelayMs,
                                        false,
                                        false,
                                        0,
                                        false,
                                        string.Empty));
                                }
                            }
                            return null;
                        }, waitForWorkerMs: -1, instructionBudget: ResolveFenJsTaskInstructionBudget());
                        if (traceEnabled)
                        {
                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                "port-delivery-complete",
                                messageId,
                                sourcePortId,
                                target.TraceId,
                                sourceFrame,
                                targetFrame,
                                payload,
                                transferCount,
                                queueDelayMs,
                                false,
                                false,
                                0,
                                false,
                                string.Empty));
                        }
                    }
                    catch (Exception ex)
                    {
                        if (traceEnabled)
                        {
                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                "port-delivery-failed",
                                messageId,
                                sourcePortId,
                                target.TraceId,
                                sourceFrame,
                                targetFrame,
                                payload,
                                transferCount,
                                queueDelayMs,
                                target.Closed,
                                false,
                                0,
                                false,
                                $"{ex.GetType().Name}: {ex.Message}"));
                        }
                        FenBrowser.Core.EngineLogCompat.Warn(
                            $"[FenJsBridge] MessagePort delivery failed: {ex}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }

                    try { RequestRender?.Invoke(); } catch { }
                },
                CancellationToken.None,
                TaskContinuationOptions.None,
                TaskScheduler.Default);
        }
    }

    /// <summary>
    /// The referrer this document reports. A framed document reports the
    /// document that embedded it; a top-level one reports what it was navigated
    /// from, which for a fresh load is nothing.
    /// </summary>
    private string ResolveDocumentReferrer()
    {
        if (_embeddingFrameElement == null)
        {
            // A top-level document reports what it was navigated from, and a
            // fresh load has nothing to report.
            return string.Empty;
        }

        return GetParentDocumentUri(_embeddingFrameElement)?.AbsoluteUri ?? string.Empty;
    }

    private void ConfigureEmbeddedRealmGlobals()
    {
        var embeddingFrame = _embeddingFrameElement;
        if (embeddingFrame == null)
        {
            return;
        }

        var parentDocumentUri = GetParentDocumentUri(embeddingFrame);
        var frameUri = _currentBaseUri ?? TryCreateUri((_currentDomRoot as Document ?? _currentDomRoot?.OwnerDocument)?.URL);
        var sameOrigin = IsSameOriginFrameAccess(embeddingFrame, frameUri?.AbsoluteUri, parentDocumentUri);
        var parentProxy = _interpreter.AllocateObject(new Dictionary<string, JsValue>());
        _embeddedParentWindowProxy = parentProxy;
        _interpreter.SetObjectProperty(parentProxy, "window", parentProxy);
        _interpreter.SetObjectProperty(parentProxy, "self", parentProxy);
        _interpreter.SetObjectProperty(parentProxy, "parent", parentProxy);
        _interpreter.SetObjectProperty(parentProxy, "top", parentProxy);
        _interpreter.SetObjectProperty(parentProxy, "frames", parentProxy);
        _interpreter.SetObjectProperty(
            parentProxy,
            "innerWidth",
            JsValue.FromNumber(_parentRealmOwner?.WindowWidth ?? WindowWidth));
        _interpreter.SetObjectProperty(
            parentProxy,
            "innerHeight",
            JsValue.FromNumber(_parentRealmOwner?.WindowHeight ?? WindowHeight));
        var frameName = embeddingFrame.GetAttribute("name") ?? string.Empty;
        _interpreter.RegisterGlobalValue("name", JsValue.FromString(frameName));
        if (sameOrigin && embeddingFrame.OwnerDocument != null)
        {
            _interpreter.SetObjectProperty(
                parentProxy,
                "document",
                ToHostOrNull(embeddingFrame.OwnerDocument, HostObjectKind.DomDocument));
            _interpreter.SetObjectProperty(
                parentProxy,
                "location",
                CreatePlainLocationObject(parentDocumentUri?.AbsoluteUri ?? "about:blank"));
            _interpreter.SetObjectProperty(
                parentProxy,
                "addEventListener",
                _interpreter.AllocateNativeFunction(
                    "addEventListener",
                    (_, args) =>
                    {
                        AddBrowserEventListener(_embeddedParentWindowListeners, args);
                        return JsValue.Undefined;
                    },
                    length: 2));
            _interpreter.SetObjectProperty(
                parentProxy,
                "removeEventListener",
                _interpreter.AllocateNativeFunction(
                    "removeEventListener",
                    (_, args) =>
                    {
                        RemoveBrowserEventListener(_embeddedParentWindowListeners, args);
                        return JsValue.Undefined;
                    },
                    length: 2));
        }
        _interpreter.SetObjectProperty(
            parentProxy,
            "postMessage",
            _interpreter.AllocateNativeFunction(
                "postMessage",
                (_, args) =>
                {
                    DiagnosticPaths.AppendLogText(
                        "postmessage_probe.txt",
                        $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] frame-to-parent data={DescribePostMessageValue(args.Count > 0 ? args[0] : JsValue.Undefined)} " +
                        $"targetOrigin={(args.Count > 1 ? CoerceToHostString(args[1]) : "*")} " +
                        $"transferCount={(args.Count > 2 ? ReadArrayLikeLength(args[2]) : 0)}{Environment.NewLine}");
                    var data = args.Count > 0 ? ConvertJsValueToObject(args[0]) : null;
                    ReadPostMessageTarget(args, out var targetOrigin, out var transferValue);
                    var ports = ExtractTransferredMessagePorts(transferValue);
                    var parentRealm = _parentRealmOwner;
                    if (parentRealm != null)
                    {
                        parentRealm.QueueCrossRealmMessage(() => parentRealm.QueueMessageFromFrame(
                            embeddingFrame,
                            data,
                            targetOrigin,
                            ports));
                    }
                    return JsValue.Undefined;
                },
                length: 1));

        _embeddedParentWindowTarget = parentProxy;
        if (sameOrigin && _parentRealmOwner != null)
        {
            // Names the parent page defined resolve through the parent realm
            // (BrowserScriptEngineRuntime.ParentWindowAccess.cs).
            var windowProxy = CreateSameOriginParentWindowProxy(parentProxy);
            if (windowProxy.Tag == JsValueTag.Object && !windowProxy.Equals(parentProxy))
            {
                _embeddedParentWindowProxy = windowProxy;
                foreach (var selfName in new[] { "window", "self", "parent", "top", "frames" })
                {
                    _interpreter.SetObjectProperty(parentProxy, selfName, windowProxy);
                }

                parentProxy = windowProxy;
            }
        }

        _interpreter.RegisterGlobalValue("parent", parentProxy);
        _interpreter.RegisterGlobalValue("top", parentProxy);
        _interpreter.RegisterGlobalValue(
            "frameElement",
            sameOrigin
                ? ToHostOrNull(embeddingFrame, HostObjectKind.DomElement)
                : JsValue.Null);
        RefreshEmbeddedParentFrameTable();
        InstallOwnedFrameScrollGlobals();
    }

    /// <summary>
    /// Publishes the parent's child browsing contexts on the parent window this
    /// realm sees. Per HTML, a WindowProxy's indexed properties are the child
    /// browsing contexts of its document in tree order and its named properties
    /// are their browsing-context names, which is how a frame reaches a
    /// *sibling*: `parent.frames[i]`, `parent.frames[name]`, `parent[name]`.
    /// We used to publish a single child — this frame itself — so every sibling
    /// lookup answered undefined. reCAPTCHA's challenge frame talks to its
    /// anchor sibling that way and died on `undefined.postMessage`.
    /// Must run with <see cref="_fenJsLock"/> held and the parent proxy already
    /// rooted as the `parent` global.
    /// </summary>
    private void RefreshEmbeddedParentFrameTable()
    {
        var parentProxy = _embeddedParentWindowProxy;
        // Writes go to the plain stand-in: a same-origin frame's parent is a
        // Proxy over it, and SetObjectProperty on the Proxy bypasses its traps.
        var parentTarget = _embeddedParentWindowTarget.Tag == JsValueTag.Object
            ? _embeddedParentWindowTarget
            : parentProxy;
        var embeddingFrame = _embeddingFrameElement;
        if (parentProxy.Tag != JsValueTag.Object || embeddingFrame == null || _interpreter == null)
        {
            return;
        }

        var children = EnumerateChildBrowsingContexts(embeddingFrame.OwnerDocument);
        if (children.Count == 0)
        {
            children.Add(embeddingFrame);
        }

        using var constructionWindow = _interpreter.Heap.BeginConstructionWindow();

        for (var index = 0; index < children.Count; index++)
        {
            var frame = children[index];
            var window = ReferenceEquals(frame, embeddingFrame)
                ? _fenJsGlobalThis
                : GetOrCreateSiblingWindowProxy(frame, parentProxy);
            if (window.Tag != JsValueTag.Object)
            {
                continue;
            }

            _interpreter.SetObjectProperty(parentTarget, index.ToString(CultureInfo.InvariantCulture), window);
            var name = frame.GetAttribute("name");
            if (!string.IsNullOrWhiteSpace(name))
            {
                _interpreter.SetObjectProperty(parentTarget, name, window);
            }
        }

        _interpreter.SetObjectProperty(parentTarget, "length", JsValue.FromInt32(children.Count));

        // Drop proxies for frames that have left the tree: everything still in
        // the map stays reachable from the rooted parent proxy, so nothing we
        // keep can be swept out from under us.
        var stale = _siblingWindowProxies.Keys.Where(frame => !children.Contains(frame)).ToArray();
        foreach (var frame in stale)
        {
            _siblingWindowProxies.Remove(frame);
        }
    }

    /// <summary>
    /// The frame elements that form a document's child browsing contexts. The
    /// walk stops at each frame because this engine attaches frame content
    /// under the frame element itself, so descending further would collect the
    /// grandchildren of nested documents as if they were siblings.
    /// </summary>
    private static List<Element> EnumerateChildBrowsingContexts(Node documentRoot)
    {
        var frames = new List<Element>();
        if (documentRoot == null)
        {
            return frames;
        }

        void Walk(Node node)
        {
            for (var child = node.FirstChild; child != null; child = child.NextSibling)
            {
                if (child is Element element && IsIFrameElement(element))
                {
                    frames.Add(element);
                    continue;
                }

                Walk(child);
            }
        }

        Walk(documentRoot);
        return frames;
    }

    /// <summary>
    /// A stand-in, allocated in THIS realm, for a sibling frame's window.
    /// A sibling runs in its own realm on its own heap, so its objects can
    /// never be handed across; we expose the WindowProxy surface a sibling may
    /// see and route postMessage back through the parent realm, which is the
    /// only holder of the frame -> realm map.
    /// </summary>
    private JsValue GetOrCreateSiblingWindowProxy(Element frame, JsValue parentProxy)
    {
        if (frame == null)
        {
            return JsValue.Undefined;
        }

        if (_siblingWindowProxies.TryGetValue(frame, out var cached) && cached.Tag == JsValueTag.Object)
        {
            return cached;
        }

        var proxy = _interpreter.AllocateObject(new Dictionary<string, JsValue>());
        _interpreter.SetObjectProperty(proxy, "window", proxy);
        _interpreter.SetObjectProperty(proxy, "self", proxy);
        _interpreter.SetObjectProperty(proxy, "frames", proxy);
        _interpreter.SetObjectProperty(proxy, "length", JsValue.FromInt32(0));
        _interpreter.SetObjectProperty(proxy, "closed", JsValue.FromBoolean(false));
        _interpreter.SetObjectProperty(proxy, "parent", parentProxy);
        _interpreter.SetObjectProperty(proxy, "top", parentProxy);
        _interpreter.SetObjectProperty(
            proxy,
            "name",
            JsValue.FromString(frame.GetAttribute("name") ?? string.Empty));

        var href = ResolveIFrameWindowHref(frame, null, null);
        if (IsSameOriginFrameAccess(frame, href, _currentBaseUri))
        {
            _interpreter.SetObjectProperty(proxy, "location", CreatePlainLocationObject(href));
        }

        DefineSiblingWindowProxyDocument(frame, proxy);

        var owner = _parentRealmOwner;
        var sourceFrame = _embeddingFrameElement;
        _interpreter.SetObjectProperty(
            proxy,
            "postMessage",
            _interpreter.AllocateNativeFunction(
                "postMessage",
                (_, args) =>
                {
                    var data = args.Count > 0 ? ConvertJsValueToObject(args[0]) : null;
                    ReadPostMessageTarget(args, out var targetOrigin, out var transferValue);
                    var ports = ExtractTransferredMessagePorts(transferValue);
                    if (DiagnosticPaths.AppendEnabled)
                    {
                        DiagnosticPaths.AppendLogText(
                            "postmessage_probe.txt",
                            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] sibling-route " +
                            $"owner={(owner == null ? "NULL" : "ok")} " +
                            $"from={sourceFrame?.GetAttribute("name") ?? "<none>"} " +
                            $"to={frame.GetAttribute("name") ?? "?"} ports={ports?.Count ?? -1} " +
                            $"data={DescribePostMessageValue(args.Count > 0 ? args[0] : JsValue.Undefined)}{Environment.NewLine}");
                    }
                    owner?.RouteMessageBetweenChildFrames(
                        sourceFrame,
                        frame,
                        data,
                        GetCurrentWindowOrigin(),
                        targetOrigin,
                        ports);
                    return JsValue.Undefined;
                },
                length: 1));

        _siblingWindowProxies[frame] = proxy;
        return proxy;
    }

    /// <summary>
    /// Publishes a same-origin sibling's document on the realm-local
    /// WindowProxy. HTML gives same-origin sibling browsing contexts full
    /// access to each other's Document; with the property missing,
    /// `parent.frames[name].document` answered undefined and a sibling that is
    /// genuinely reachable read as one that was never created. reCAPTCHA's
    /// anchor frame gates its entire challenge-frame channel on exactly that
    /// read, so the challenge frame's setup handshake arrived with nobody
    /// listening for it.
    /// It has to be a live accessor: the proxy is minted as soon as the frame
    /// element joins the tree, which is well before that frame has a document,
    /// and the sibling can also navigate afterwards. The Document is a host
    /// object both realms share, so each realm wraps it with a handle of its
    /// own; no handle is ever carried across heaps.
    /// </summary>
    private void DefineSiblingWindowProxyDocument(Element frame, JsValue proxy)
    {
        if (frame == null || proxy.Tag != JsValueTag.Object || _interpreter == null)
        {
            return;
        }

        _interpreter.Heap.GetObject(proxy.AsObjectHandle()).DefineOwnProperty(
            "document",
            JsPropertyDescriptor.Accessor(
                _interpreter.AllocateNativeFunction(
                    "get document",
                    (_, _) =>
                    {
                        if (!CanCurrentContextAccessIFrameDocument(frame))
                        {
                            return JsValue.Undefined;
                        }

                        var siblingDocument = FindFrameContentDocument(frame);
                        return siblingDocument == null
                            ? JsValue.Undefined
                            : ToHostOrNull(siblingDocument, HostObjectKind.DomDocument);
                    },
                    length: 0),
                JsValue.Undefined,
                Enumerable: true,
                Configurable: true));
    }

    /// <summary>
    /// The Document a frame element currently hosts, or null while the frame
    /// has not produced one. Unlike <see cref="GetOrCreateIFrameContentDocument"/>
    /// this never fabricates a placeholder document and never caches a handle on
    /// the element: the element is shared by every realm that can see the frame,
    /// so a handle cached from one heap would be read back from another.
    /// </summary>
    /// <remarks>
    /// The most recently attached document is the active one. A frame's window, and with
    /// it its initial about:blank document, exists before any script runs, so a document
    /// attached later (by a load, or directly by an embedder) has to win over it.
    /// </remarks>
    private static Document FindFrameContentDocument(Element frame)
    {
        Document active = null;
        for (var child = frame.FirstChild; child != null; child = child.NextSibling)
        {
            if (child is Document frameDocument)
            {
                active = frameDocument;
            }
            else if (child is Element frameRoot && frameRoot.OwnerDocument != null)
            {
                active = frameRoot.OwnerDocument;
            }
        }

        return active;
    }

    /// <summary>
    /// Carries a postMessage from one child frame of this document to another.
    /// Sender and receiver each own a realm; the parent holds the only map from
    /// frame element to realm, so it is the only place the two can be joined.
    /// </summary>
    private void RouteMessageBetweenChildFrames(
        Element sourceFrame,
        Element targetFrame,
        object data,
        string sourceOrigin,
        string targetOrigin,
        IReadOnlyList<MessagePortEndpoint> transferredEndpoints)
    {
        if (targetFrame == null || !_iframeRealms.TryGetValue(targetFrame, out var targetRealm))
        {
            return;
        }

        targetRealm.QueueCrossRealmMessage(() => targetRealm.QueueMessageFromSibling(
            sourceFrame,
            data,
            sourceOrigin,
            targetOrigin,
            transferredEndpoints));
    }

    private void QueueMessageFromSibling(
        Element sourceFrame,
        object data,
        string sourceOrigin,
        string targetOrigin,
        IReadOnlyList<MessagePortEndpoint> transferredEndpoints)
    {
        QueueOnDeliveryTail(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                var ports = ImportTransferredMessagePorts(transferredEndpoints);
                using var constructionWindow = _interpreter.Heap.BeginConstructionWindow();
                // A newly attached sibling can postMessage while its own startup
                // scripts are still running, before the normal post-load refresh
                // reaches existing realms. Publish the current table before
                // exposing event.source so identity checks against parent.frames
                // observe the same WindowProxy.
                RefreshEmbeddedParentFrameTable();
                var source = GetOrCreateSiblingWindowProxy(sourceFrame, _embeddedParentWindowProxy);
                QueueWindowMessage(
                    _fenJsGlobalThis,
                    _windowEventListeners,
                    ConvertObjectToJsValue(data),
                    source.Tag == JsValueTag.Object ? source : _embeddedParentWindowProxy,
                    ports,
                    targetOrigin,
                    GetCurrentWindowOrigin(),
                    sourceOrigin);
            }
        }, "sibling postMessage enqueue failed");
    }

    /// <summary>
    /// A new child document changes every sibling's view of `parent.frames`, so
    /// republish the table in each child realm. reCAPTCHA builds its challenge
    /// frame long after the anchor frame; without this the anchor realm would
    /// never see the sibling it has to talk to.
    /// </summary>
    private void RefreshChildFrameTables()
    {
        foreach (var realm in _iframeRealms.Select(entry => entry.Value).Distinct().ToArray())
        {
            realm.QueueParentFrameTableRefresh();
        }
    }

    private void QueueParentFrameTableRefresh()
    {
        if (_embeddedParentWindowProxy.Tag != JsValueTag.Object)
        {
            return;
        }

        QueueOnDeliveryTail(
            () =>
            {
                using (ScriptEngineLockProbe.Hold(_fenJsLock))
                {
                    RefreshEmbeddedParentFrameTable();
                }
            },
            "parent frame table refresh failed");
    }

    private string DescribePostMessageValue(JsValue value)
    {
        if (value.Tag == JsValueTag.String)
        {
            var text = value.AsString() ?? string.Empty;
            return $"String({text.Length}):{text[..Math.Min(text.Length, 120)]}";
        }

        if (value.Tag != JsValueTag.Object || _interpreter == null)
        {
            return value.Tag.ToString();
        }

        try
        {
            var obj = _interpreter.Heap.GetObject(value.AsObjectHandle());
            var keys = obj?.EnumerateOwnProperties()
                .Select(entry => entry.Key)
                .Take(12)
                .ToArray() ?? Array.Empty<string>();
            return $"{obj?.GetType().Name ?? "Object"} keys=[{string.Join(",", keys)}]";
        }
        catch (Exception ex)
        {
            return $"Object(unavailable:{ex.GetType().Name})";
        }
    }

    private void NotifyEmbeddedFramesOfParentWindowEvent(string type, JsValue sourceEvent)
    {
        if (string.IsNullOrWhiteSpace(type))
        {
            return;
        }

        object data = null;
        string origin = string.Empty;
        if (sourceEvent.Tag == JsValueTag.Object)
        {
            var dataValue = ReadJsProperty(sourceEvent, "data");
            if (dataValue.Tag != JsValueTag.Undefined)
            {
                data = ConvertJsValueToObject(dataValue);
            }
            var originValue = ReadJsProperty(sourceEvent, "origin");
            if (originValue.Tag == JsValueTag.String)
            {
                origin = originValue.AsString();
            }
        }

        foreach (var frameRealm in _iframeRealms.Select(entry => entry.Value).Distinct().ToArray())
        {
            frameRealm.QueueEmbeddedParentWindowEvent(type, data, origin);
        }
    }

    private void QueueEmbeddedParentWindowEvent(string type, object data, string origin)
    {
        if (_embeddedParentWindowListeners.Count == 0 || _embeddedParentWindowProxy.Tag != JsValueTag.Object)
        {
            return;
        }

        _ = Task.Factory.StartNew(
            () => RunFenJsWithLargeStack<object>(() =>
            {
                using (ScriptEngineLockProbe.Hold(_fenJsLock))
                {
                    if (_embeddedParentWindowListeners.Count == 0 ||
                        _embeddedParentWindowProxy.Tag != JsValueTag.Object)
                    {
                        return null;
                    }

                    var eventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
                    {
                        ["type"] = JsValue.FromString(type),
                        ["data"] = ConvertObjectToJsValue(data),
                        ["origin"] = JsValue.FromString(origin ?? string.Empty)
                    });
                    PrepareDispatchedEvent(eventValue, _embeddedParentWindowProxy);
                    DispatchBrowserEvent(
                        _embeddedParentWindowListeners,
                        type,
                        _embeddedParentWindowProxy,
                        eventValue);
                    return null;
                }
            }),
            CancellationToken.None,
            TaskCreationOptions.DenyChildAttach,
            TaskScheduler.Default);
    }

    private void InstallOwnedFrameScrollGlobals()
    {
        var initial = ReadOwnedFrameScroll();
        SetOwnedScrollGlobals(initial.X, initial.Y);

        var scrollTo = _interpreter.AllocateNativeFunction(
            "scrollTo",
            (_, args) =>
            {
                var (x, y) = ReadScrollArguments(args, relative: false);
                ScrollOwnedFrameTo(x, y);
                return JsValue.Undefined;
            },
            length: 2);
        var scrollBy = _interpreter.AllocateNativeFunction(
            "scrollBy",
            (_, args) =>
            {
                var (x, y) = ReadScrollArguments(args, relative: true);
                ScrollOwnedFrameTo(x, y);
                return JsValue.Undefined;
            },
            length: 2);
        _interpreter.RegisterGlobalValue("scrollTo", scrollTo);
        _interpreter.RegisterGlobalValue("scroll", scrollTo);
        _interpreter.RegisterGlobalValue("scrollBy", scrollBy);
    }

    private (double X, double Y) ReadScrollArguments(IReadOnlyList<JsValue> args, bool relative)
    {
        var current = ReadOwnedFrameScroll();
        var x = relative ? current.X : 0d;
        var y = relative ? current.Y : 0d;
        if (args.Count > 0 && args[0].Tag == JsValueTag.Object)
        {
            var left = ReadJsProperty(args[0], "left");
            var top = ReadJsProperty(args[0], "top");
            if (left.Tag != JsValueTag.Undefined)
            {
                x = (relative ? current.X : 0d) + CoerceToFiniteNumber(left, 0);
            }
            if (top.Tag != JsValueTag.Undefined)
            {
                y = (relative ? current.Y : 0d) + CoerceToFiniteNumber(top, 0);
            }
            return (x, y);
        }

        if (args.Count > 0)
        {
            x = (relative ? current.X : 0d) + CoerceToFiniteNumber(args[0], 0);
        }
        if (args.Count > 1)
        {
            y = (relative ? current.Y : 0d) + CoerceToFiniteNumber(args[1], 0);
        }
        return (x, y);
    }

    private (double X, double Y) ReadOwnedFrameScroll() =>
        _embeddingFrameElement != null && FrameScrollReader != null
            ? FrameScrollReader(_embeddingFrameElement)
            : (0d, 0d);

    private void ScrollOwnedFrameTo(double x, double y)
    {
        if (_embeddingFrameElement == null)
        {
            return;
        }

        FrameScrollWriter?.Invoke(_embeddingFrameElement, Math.Max(0, x), Math.Max(0, y));
        var actual = ReadOwnedFrameScroll();
        UpdateOwnedScroll(actual.X, actual.Y);
        RequestRender?.Invoke();
    }

    private void QueueMessageFromFrame(
        Element frame,
        object data,
        string targetOrigin,
        IReadOnlyList<MessagePortEndpoint> transferredEndpoints)
    {
        if (frame == null)
        {
            return;
        }

        QueueOnDeliveryTail(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                var sourceWindow = GetOrCreateIFrameContentWindow(frame);
                var ports = ImportTransferredMessagePorts(transferredEndpoints);
                QueueWindowMessage(
                    _fenJsGlobalThis,
                    _windowEventListeners,
                    ConvertObjectToJsValue(data),
                    sourceWindow,
                    ports,
                    targetOrigin,
                    _currentBaseUri?.GetLeftPart(UriPartial.Authority));
            }
        }, "frame postMessage enqueue failed");
    }

    private void QueueCrossRealmMessage(Action delivery)
    {
        var sessionGeneration = _fenJsSessionGeneration;
        lock (_windowMessageQueueLock)
        {
            _windowMessageDeliveryTail = _windowMessageDeliveryTail.ContinueWith(
                _ =>
                {
                    if (sessionGeneration != _fenJsSessionGeneration)
                    {
                        return;
                    }

                    try
                    {
                        delivery();
                    }
                    catch (Exception ex)
                    {
                        FenBrowser.Core.EngineLogCompat.Warn(
                            $"[FenJsBridge] Cross-realm message delivery failed: {ex.Message}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }
                },
                CancellationToken.None,
                TaskContinuationOptions.None,
                TaskScheduler.Default);
        }
    }

    private void QueueMessageFromParent(
        object data,
        string sourceOrigin,
        string targetOrigin,
        IReadOnlyList<MessagePortEndpoint> transferredEndpoints)
    {
        QueueOnDeliveryTail(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                var ports = ImportTransferredMessagePorts(transferredEndpoints);
                QueueWindowMessage(
                    _fenJsGlobalThis,
                    _windowEventListeners,
                    ConvertObjectToJsValue(data),
                    _embeddedParentWindowProxy,
                    ports,
                    targetOrigin,
                    GetCurrentWindowOrigin(),
                    sourceOrigin);
            }
        }, "parent postMessage enqueue failed");
    }

/// <summary>
    /// Delivers a postMessage from a child frame (iframe) to this realm.
    /// Called when a cross-origin iframe invokes parent.postMessage().
    /// Computes the exposedWindow (contentWindow or cross-origin facade) that
    /// the parent registered for this iframe, so event.source matches what the
    /// parent's event listener expects (anchorFrame.contentWindow).
    /// </summary>
    private void QueueMessageFromChildFrame(
        Element sourceFrame,
        object data,
        string sourceOrigin,
        string targetOrigin,
        IReadOnlyList<MessagePortEndpoint> transferredEndpoints)
    {
        if (DiagnosticPaths.IframeDiagnosticsEnabled)
        {
            var dataStr = data?.ToString() ?? "null";
            if (dataStr.Length > 200) dataStr = dataStr.Substring(0, 200) + "...";
            DiagnosticPaths.AppendLogText(
                "iframe_diagnostics.txt",
                $"{DateTimeOffset.UtcNow:O} QueueMessageFromChildFrame: sourceFrame=<{sourceFrame.TagName}> id='{sourceFrame.GetAttribute("id") ?? ""}' class='{sourceFrame.GetAttribute("class") ?? ""}' data={dataStr} sourceOrigin={sourceOrigin} targetOrigin={targetOrigin} ports={transferredEndpoints?.Count ?? 0}");
        }

        QueueOnDeliveryTail(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                var ports = ImportTransferredMessagePorts(transferredEndpoints);
                // Use the exposedWindow the parent already registered for this iframe
                // so event.source === anchorFrame.contentWindow in the parent's listener.
                JsValue source = JsValue.Undefined;
                var iframe = sourceFrame;
                var window = GetOrCreateIFrameContentWindow(iframe);
                if (window.Tag == JsValueTag.Object)
                {
                    var href = ResolveIFrameWindowHref(iframe, null, null);
                    var parentCanAccessFrame = IsSameOriginFrameAccess(iframe, href, _currentBaseUri);
                    source = parentCanAccessFrame
                        ? window
                        : GetOrCreateCrossOriginChildWindowFacade(iframe, window);
                }

                if (source.Tag == JsValueTag.Undefined)
                {
                    // Fallback to sibling proxy
                    source = GetOrCreateSiblingWindowProxy(iframe, _embeddedParentWindowProxy);
                }

                QueueWindowMessage(
                    _fenJsGlobalThis,
                    _windowEventListeners,
                    ConvertObjectToJsValue(data),
                    source.Tag == JsValueTag.Object ? source : _embeddedParentWindowProxy,
                    ports,
                    targetOrigin,
                    GetCurrentWindowOrigin(),
                    sourceOrigin);
            }
        }, "child frame postMessage enqueue failed");
    }

    /// <summary>
    /// Runs a delivery body on the shared FenJS worker with the interpreter
    /// lock held there, chained onto the window-message delivery tail. Cross-
    /// realm postMessage entry points must never take <see cref="_fenJsLock"/>
    /// on their calling thread: importing transferred MessagePorts blocks on
    /// the worker, and the worker's current item needs the same lock — a
    /// guaranteed self-deadlock that freezes every later JS dispatch (timers,
    /// pointer events) in the realm. This mirrors the QueueMessagePort
    /// delivery pattern.
    /// </summary>
    private void QueueOnDeliveryTail(Action body, string failureLogPrefix)
    {
        var sessionGeneration = _fenJsSessionGeneration;
        lock (_windowMessageQueueLock)
        {
            _windowMessageDeliveryTail = _windowMessageDeliveryTail.ContinueWith(
                _ =>
                {
                    if (sessionGeneration != _fenJsSessionGeneration)
                    {
                        return;
                    }

                    try
                    {
                        RunFenJsWithLargeStack<object>(() =>
                        {
                            body();
                            return null;
                        }, waitForWorkerMs: -1, instructionBudget: ResolveFenJsTaskInstructionBudget());
                    }
                    catch (Exception ex)
                    {
                        FenBrowser.Core.EngineLogCompat.Warn(
                            $"[FenJsBridge] {failureLogPrefix}: {ex.Message}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }
                },
                CancellationToken.None,
                TaskContinuationOptions.None,
                TaskScheduler.Default);
        }
    }

    private void CopyFrameRealmObservables(
        FenJsBrowserScriptEngine realm,
        JsValue proxy,
        IReadOnlyDictionary<string, object> observables)
    {
        var frame = realm._embeddingFrameElement;
        var sameOrigin = IsSameOriginFrameAccess(
            frame,
            realm._currentBaseUri?.AbsoluteUri,
            GetParentDocumentUri(frame));
        foreach (var (name, value) in observables)
        {
            var converted = ConvertObjectToJsValue(value);
            _interpreter.SetObjectProperty(proxy, name, converted);
            if (sameOrigin)
            {
                _interpreter.SetObjectProperty(_fenJsGlobalThis, name, converted);
            }
        }
    }

    private Dictionary<string, object> CaptureObservableWindowProperties()
    {
        var result = new Dictionary<string, object>(StringComparer.Ordinal);
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            if (_fenJsGlobalThis.Tag != JsValueTag.Object || _interpreter == null)
            {
                return result;
            }

            var global = _interpreter.Heap.GetObject(_fenJsGlobalThis.AsObjectHandle());
            foreach (var property in global.EnumerateOwnProperties())
            {
                if (!property.Key.StartsWith("__", StringComparison.Ordinal) ||
                    property.Key.StartsWith("__fen", StringComparison.Ordinal))
                {
                    continue;
                }
                var value = property.Value.Value;
                result[property.Key] = ConvertJsValueToObject(value);
            }
        }

        return result;
    }

    private JsValue ConvertObjectToJsValue(object value, int depth = 0)
    {
        if (value == null || depth > 16) return JsValue.Null;
        return value switch
        {
            bool boolean => JsValue.FromBoolean(boolean),
            byte number => JsValue.FromInt32(number),
            short number => JsValue.FromInt32(number),
            int number => JsValue.FromInt32(number),
            long number when number is >= int.MinValue and <= int.MaxValue => JsValue.FromInt32((int)number),
            long number => JsValue.FromNumber(number),
            float number => JsValue.FromNumber(number),
            double number => JsValue.FromNumber(number),
            decimal number => JsValue.FromNumber((double)number),
            string text => JsValue.FromString(text),
            IDictionary<string, object> dictionary => _interpreter.AllocateObject(
                dictionary.ToDictionary(
                    entry => entry.Key,
                    entry => ConvertObjectToJsValue(entry.Value, depth + 1),
                    StringComparer.Ordinal)),
            IEnumerable<object> sequence => CreateJsArray(sequence, depth + 1),
            _ => JsValue.FromString(value.ToString() ?? string.Empty)
        };
    }

    private JsValue CreateJsArray(IEnumerable<object> sequence, int depth)
    {
        var values = sequence?.ToArray() ?? Array.Empty<object>();
        var jsValues = new JsValue[values.Length];
        for (var index = 0; index < values.Length; index++)
        {
            jsValues[index] = ConvertObjectToJsValue(values[index], depth);
        }
        return _interpreter.AllocateArray(jsValues);
    }

    private JsValue GetOrCreateTopWindowFacade()
    {
        if (_fenJsTopWindowFacade.Tag == JsValueTag.Object)
        {
            return _fenJsTopWindowFacade;
        }

        var facade = _interpreter.AllocateObject(new Dictionary<string, JsValue>());
        _fenJsTopWindowFacade = facade;
        _interpreter.SetObjectProperty(facade, "window", facade);
        _interpreter.SetObjectProperty(facade, "self", facade);
        _interpreter.SetObjectProperty(facade, "parent", facade);
        _interpreter.SetObjectProperty(facade, "top", facade);
        _interpreter.SetObjectProperty(facade, "frames", facade);
        _interpreter.SetObjectProperty(facade, "length", JsValue.FromInt32(0));
        _interpreter.SetObjectProperty(facade, "postMessage", CreateTopWindowPostMessageFunction());
        return facade;
    }

    private JsValue GetOrCreateSameOriginTopWindowFacade()
    {
        if (_fenJsSameOriginTopWindowFacade.Tag == JsValueTag.Object)
        {
            return _fenJsSameOriginTopWindowFacade;
        }

        var facade = _interpreter.AllocateObject(new Dictionary<string, JsValue>());
        _fenJsSameOriginTopWindowFacade = facade;
        foreach (var property in new[]
        {
            "document", "location", "navigator", "history",
            "innerWidth", "innerHeight", "outerWidth", "outerHeight",
            "devicePixelRatio", "dispatchEvent", "addEventListener", "removeEventListener"
        })
        {
            var value = ReadJsProperty(_fenJsGlobalThis, property);
            if (value.Tag != JsValueTag.Undefined)
            {
                _interpreter.SetObjectProperty(facade, property, value);
            }
        }

        _interpreter.SetObjectProperty(facade, "window", facade);
        _interpreter.SetObjectProperty(facade, "self", facade);
        _interpreter.SetObjectProperty(facade, "parent", facade);
        _interpreter.SetObjectProperty(facade, "top", facade);
        _interpreter.SetObjectProperty(facade, "frames", facade);
        _interpreter.SetObjectProperty(facade, "length", JsValue.FromInt32(0));
        _interpreter.SetObjectProperty(facade, "postMessage", CreateTopWindowPostMessageFunction());
        return facade;
    }

    private JsValue GetOrCreateCrossOriginChildWindowFacade(Element iframe, JsValue targetWindow)
    {
        var cached = GetStoredHostPropertyOrUndefined(iframe, "__fenCrossOriginContentWindow");
        if (cached.Tag == JsValueTag.Object)
        {
            return cached;
        }

        var facade = _interpreter.AllocateObject(new Dictionary<string, JsValue>());
        // Create a parent facade with postMessage that routes to the parent realm
        // (this realm's _parentRealmOwner) instead of the current realm.
        var parentFacade = _interpreter.AllocateObject(new Dictionary<string, JsValue>());
        _interpreter.SetObjectProperty(parentFacade, "window", parentFacade);
        _interpreter.SetObjectProperty(parentFacade, "self", parentFacade);
        _interpreter.SetObjectProperty(parentFacade, "parent", parentFacade);
        _interpreter.SetObjectProperty(parentFacade, "top", parentFacade);
        _interpreter.SetObjectProperty(parentFacade, "frames", parentFacade);
        _interpreter.SetObjectProperty(parentFacade, "length", JsValue.FromInt32(0));
        _interpreter.SetObjectProperty(parentFacade, "postMessage", CreateParentFacadePostMessageFunction(_parentRealmOwner!));

        _interpreter.SetObjectProperty(facade, "window", facade);
        _interpreter.SetObjectProperty(facade, "self", facade);
        _interpreter.SetObjectProperty(facade, "frames", facade);
        _interpreter.SetObjectProperty(facade, "parent", parentFacade);
        _interpreter.SetObjectProperty(facade, "top", parentFacade);
        _interpreter.SetObjectProperty(facade, "closed", JsValue.FromBoolean(false));
        _interpreter.SetObjectProperty(facade, "length", ReadJsProperty(targetWindow, "length"));
        _interpreter.SetObjectProperty(
            facade,
            "postMessage",
            _interpreter.AllocateNativeFunction(
                "postMessage",
                (_, args) =>
                {
                    var data = args.Count > 0 ? args[0] : JsValue.Undefined;
                    ReadPostMessageTarget(args, out var targetOrigin, out var ports);
                    var facadeHasRealm = _iframeRealms.TryGetValue(iframe, out var frameRealm);
                    if (DiagnosticPaths.AppendEnabled)
                    {
                        DiagnosticPaths.AppendLogText(
                            "postmessage_probe.txt",
                            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] parent-to-child(facade) " +
                            $"frame={iframe.GetAttribute("name") ?? "?"} ownRealm={facadeHasRealm} " +
                            $"data={DescribePostMessageValue(data)}{Environment.NewLine}");
                    }

                    if (facadeHasRealm)
                    {
                        var messageData = ConvertJsValueToObject(data);
                        var sourceOrigin = GetCurrentWindowOrigin();
                        var transferredPorts = ExtractTransferredMessagePorts(ports);
                        frameRealm!.QueueCrossRealmMessage(() => frameRealm.QueueMessageFromParent(
                            messageData,
                            sourceOrigin,
                            targetOrigin,
                            transferredPorts));
                        return JsValue.Undefined;
                    }
                    QueueWindowMessage(
                        targetWindow,
                        GetIFrameWindowListeners(iframe),
                        data,
                        GetActiveWindowEventTarget(),
                        ports,
                        targetOrigin);
                    return JsValue.Undefined;
                },
                length: 1));

        SetStoredHostProperty(iframe, "__fenCrossOriginContentWindow", facade);
        return facade;
    }

    private void UpdateIFrameContentWindow(
        JsValue window,
        Element iframe,
        Document frameDocument,
        Uri frameUri)
    {
        if (window.Tag != JsValueTag.Object)
        {
            return;
        }

        var document = frameDocument == null
            ? GetOrCreateIFrameContentDocument(iframe)
            : ToHostOrNull(frameDocument, HostObjectKind.DomDocument);
        var href = ResolveIFrameWindowHref(iframe, frameDocument, frameUri);
        _interpreter.SetObjectProperty(window, "document", document);
        _interpreter.SetObjectProperty(window, "location", CreatePlainLocationObject(href));
        var parentCanAccessFrame = IsSameOriginFrameAccess(iframe, href, GetParentDocumentUri(iframe));
        var frameElementValue = ToHostOrNull(iframe, HostObjectKind.DomElement);
        _interpreter.SetObjectProperty(window, "__fenFrameElement", frameElementValue);
        _interpreter.SetObjectProperty(window, "frameElement", parentCanAccessFrame ? frameElementValue : JsValue.Null);
        SetIFrameViewportProperties(window, iframe);
        var frameName = iframe.GetAttribute("name") ?? string.Empty;
        _interpreter.SetObjectProperty(window, "name", JsValue.FromString(frameName));
        var parent = ReadJsProperty(window, "parent");
        var exposedWindow = parentCanAccessFrame
            ? window
            : GetOrCreateCrossOriginChildWindowFacade(iframe, window);
        RegisterChildFrameOnParent(parent, exposedWindow, frameName);

        if (frameDocument != null)
        {
            SetStoredHostProperty(frameDocument, "__fenDefaultView", window);
        }
    }

    private string ResolveIFrameWindowHref(Element iframe, Document frameDocument, Uri frameUri)
    {
        var href =
            frameUri?.AbsoluteUri ??
            frameDocument?.URL ??
            frameDocument?.DocumentURI ??
            frameDocument?.BaseURI ??
            ResolveElementUrlProperty(iframe, "src");

        return string.IsNullOrWhiteSpace(href) ? "about:blank" : href;
    }

    private static Uri GetParentDocumentUri(Element iframe)
    {
        var document = iframe?.OwnerDocument;
        return TryCreateUri(document?.URL) ??
               TryCreateUri(document?.DocumentURI) ??
               TryCreateUri(document?.BaseURI);
    }

    private static bool IsSameOriginFrameAccess(Element iframe, string frameHref, Uri accessorUri)
    {
        if (iframe == null || accessorUri == null)
        {
            return false;
        }

        if (iframe.HasAttribute("sandbox"))
        {
            var flags = FenBrowser.Core.SandboxPolicy.ParseIframeSandboxFlags(iframe.GetAttribute("sandbox"));
            if ((flags & IframeSandboxFlags.SameOrigin) == 0)
            {
                return false;
            }
        }

        if (string.IsNullOrWhiteSpace(frameHref) ||
            string.Equals(frameHref, "about:blank", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(frameHref, "about:srcdoc", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        return Uri.TryCreate(frameHref, UriKind.Absolute, out var frameUri) &&
               CorsHandler.IsSameOrigin(accessorUri, frameUri);
    }

    private bool CanCurrentContextAccessIFrameDocument(Element iframe)
    {
        var href = ResolveIFrameWindowHref(iframe, null, null);
        return IsSameOriginFrameAccess(iframe, href, _currentBaseUri);
    }

    private JsValue GetMessageSourceForTarget(JsValue sourceWindow, JsValue targetWindow)
    {
        if (sourceWindow.Tag != JsValueTag.Object || targetWindow.Tag != JsValueTag.Object)
        {
            return sourceWindow;
        }

        var sourceFrame = ResolveHostObjectOrNull<Element>(ReadJsProperty(sourceWindow, "__fenFrameElement"));
        if (sourceFrame != null && targetWindow.Equals(_fenJsGlobalThis))
        {
            var sourceHref = ResolveIFrameWindowHref(sourceFrame, null, null);
            return IsSameOriginFrameAccess(sourceFrame, sourceHref, GetParentDocumentUri(sourceFrame))
                ? sourceWindow
                : GetOrCreateCrossOriginChildWindowFacade(sourceFrame, sourceWindow);
        }

        var targetFrame = ResolveHostObjectOrNull<Element>(ReadJsProperty(targetWindow, "__fenFrameElement"));
        if (targetFrame != null && sourceWindow.Equals(_fenJsGlobalThis))
        {
            var targetHref = ResolveIFrameWindowHref(targetFrame, null, null);
            return IsSameOriginFrameAccess(targetFrame, targetHref, GetParentDocumentUri(targetFrame))
                ? GetOrCreateSameOriginTopWindowFacade()
                : GetOrCreateTopWindowFacade();
        }

        return sourceWindow;
    }

    private void SetIFrameViewportProperties(JsValue window, Element iframe)
    {
        var width = TryReadDeclaredPixelDimension(iframe, "width", out var declaredWidth)
            ? declaredWidth
            : WindowWidth;
        var height = TryReadDeclaredPixelDimension(iframe, "height", out var declaredHeight)
            ? declaredHeight
            : WindowHeight;
        _interpreter.SetObjectProperty(window, "innerWidth", JsValue.FromNumber(width));
        _interpreter.SetObjectProperty(window, "innerHeight", JsValue.FromNumber(height));
        _interpreter.SetObjectProperty(window, "outerWidth", JsValue.FromNumber(width));
        _interpreter.SetObjectProperty(window, "outerHeight", JsValue.FromNumber(height));
        _interpreter.SetObjectProperty(window, "devicePixelRatio", JsValue.FromNumber(1));
        var scroll = FrameScrollReader?.Invoke(iframe) ?? (0d, 0d);
        _interpreter.SetObjectProperty(window, "pageXOffset", JsValue.FromNumber(scroll.Item1));
        _interpreter.SetObjectProperty(window, "pageYOffset", JsValue.FromNumber(scroll.Item2));
        _interpreter.SetObjectProperty(window, "scrollX", JsValue.FromNumber(scroll.Item1));
        _interpreter.SetObjectProperty(window, "scrollY", JsValue.FromNumber(scroll.Item2));
    }

    private void RegisterChildFrameOnParent(JsValue parent, JsValue window, string frameName)
    {
        if (parent.Tag != JsValueTag.Object || window.Tag != JsValueTag.Object)
        {
            return;
        }

        var frames = ReadJsProperty(parent, "frames");
        if (frames.Tag != JsValueTag.Object)
        {
            frames = parent;
            _interpreter.SetObjectProperty(parent, "frames", frames);
        }

        // The real window finds its child frames by name through WindowProperties
        // (HTML 7.2.2.3), live and in tree order; only the stand-in parent objects, which
        // have no named properties object, carry them as plain properties.
        if (!string.IsNullOrWhiteSpace(frameName) && !parent.Equals(_fenJsGlobalThis))
        {
            _interpreter.SetObjectProperty(frames, frameName, window);
            _interpreter.SetObjectProperty(parent, frameName, window);
        }

        var frameIndex = ReadJsProperty(window, "__fenFrameIndex");
        if (frameIndex.Tag != JsValueTag.Undefined)
        {
            return;
        }

        var parentLength = ReadJsProperty(frames, "length");
        var index = parentLength.Tag == JsValueTag.Number
            ? Math.Max(0, (int)parentLength.AsNumber())
            : 0;
        _interpreter.SetObjectProperty(window, "__fenFrameIndex", JsValue.FromInt32(index));
        _interpreter.SetObjectProperty(frames, index.ToString(CultureInfo.InvariantCulture), window);
        _interpreter.SetObjectProperty(frames, "length", JsValue.FromInt32(index + 1));
        if (_fenJsGlobalThis.Tag == JsValueTag.Object && !parent.Equals(_fenJsGlobalThis))
        {
            _interpreter.SetObjectProperty(_fenJsGlobalThis, index.ToString(CultureInfo.InvariantCulture), window);
            _interpreter.SetObjectProperty(_fenJsGlobalThis, "length", JsValue.FromInt32(index + 1));
        }
    }

    private JsValue CreatePlainLocationObject(string href)
    {
        var parsed = ParseFenJsUrl(new[] { JsValue.FromString(href ?? string.Empty) });
        if (parsed.Tag == JsValueTag.Object)
        {
            return parsed;
        }

        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["href"] = JsValue.FromString(href ?? string.Empty),
            ["origin"] = JsValue.FromString("null"),
            ["protocol"] = JsValue.FromString(string.Empty),
            ["host"] = JsValue.FromString(string.Empty),
            ["hostname"] = JsValue.FromString(string.Empty),
            ["port"] = JsValue.FromString(string.Empty),
            ["pathname"] = JsValue.FromString(string.Empty),
            ["search"] = JsValue.FromString(string.Empty),
            ["hash"] = JsValue.FromString(string.Empty)
        });
    }

    private void QueueWindowMessage(
        JsValue targetWindow,
        List<BrowserEventListener> listeners,
        JsValue data,
        JsValue sourceWindow,
        JsValue ports,
        string targetOrigin,
        string targetWindowOriginOverride = null,
        string sourceOriginOverride = null)
    {
        var traceEnabled = IsFenJsMessageTransportTraceEnabled;
        var messageId = traceEnabled ? Interlocked.Increment(ref _messageTransportTraceSequence) : 0;
        var sourceFrame = traceEnabled
            ? sourceOriginOverride ?? GetMessageSourceOrigin(sourceWindow)
            : string.Empty;
        var targetFrame = traceEnabled ? ProbeFrame() : string.Empty;
        var payload = traceEnabled ? DescribePostMessageValue(data) : string.Empty;
        var transferCount = traceEnabled && ports.Tag == JsValueTag.Object
            ? ReadArrayLikeLength(ports)
            : 0;
        if (traceEnabled)
        {
            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                "window-route-enter",
                messageId,
                0,
                0,
                sourceFrame,
                targetFrame,
                payload,
                transferCount,
                0,
                false,
                false,
                listeners?.Count ?? 0,
                false,
                $"targetOrigin={targetOrigin ?? string.Empty}; targetWindowOrigin={targetWindowOriginOverride ?? string.Empty}"));
        }
        if (!ShouldDeliverWindowMessage(targetWindow, targetOrigin, targetWindowOriginOverride))
        {
            if (traceEnabled)
            {
                TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                    "window-route-dropped",
                    messageId,
                    0,
                    0,
                    sourceFrame,
                    targetFrame,
                    payload,
                    transferCount,
                    0,
                    false,
                    false,
                    listeners?.Count ?? 0,
                    false,
                    $"targetOrigin={targetOrigin ?? string.Empty}; actualOrigin={targetWindowOriginOverride ?? ReadWindowOrigin(targetWindow)}"));
            }
            // A dropped message is invisible from script: the sender sees a
            // successful postMessage and the receiver simply never hears. Say so.
            if (DiagnosticPaths.AppendEnabled)
            DiagnosticPaths.AppendLogText(
                "postmessage_probe.txt",
                $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] DROPPED wanted='{NormalizePostMessageOrigin(targetOrigin)}' " +
                $"raw='{targetOrigin}' actual='{targetWindowOriginOverride ?? ReadWindowOrigin(targetWindow)}' " +
                $"override='{targetWindowOriginOverride ?? "<null>"}' " +
                $"readWindow='{ReadWindowOrigin(targetWindow)}' " +
                $"data={DescribePostMessageValue(data)}{Environment.NewLine}");
            return;
        }

        var origin = sourceOriginOverride ?? GetMessageSourceOrigin(sourceWindow);
        if (DiagnosticPaths.AppendEnabled)
        DiagnosticPaths.AppendLogText(
            "postmessage_probe.txt",
            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] deliver listeners={listeners?.Count ?? 0} " +
            $"fromOrigin={origin} targetOrigin={targetOrigin} " +
            $"ports={(ports.Tag == JsValueTag.Object ? ReadArrayLikeLength(ports) : -1)} " +
            $"data={DescribePostMessageValue(data)}{Environment.NewLine}");
        var exposedSourceWindow = GetMessageSourceForTarget(sourceWindow, targetWindow);
        var sessionGeneration = _fenJsSessionGeneration;
        var queuedAt = traceEnabled ? System.Diagnostics.Stopwatch.GetTimestamp() : 0;
        if (traceEnabled)
        {
            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                "window-enqueued",
                messageId,
                0,
                0,
                sourceFrame,
                targetFrame,
                payload,
                transferCount,
                0,
                false,
                false,
                listeners?.Count ?? 0,
                false,
                $"origin={origin}"));
        }
        // The payload values are captured by the delivery continuation, which
        // may sit queued across arbitrary engine activity; without a pin a
        // collection can sweep them before delivery runs.
        var deliveryPins = PinFenJsValues(data, exposedSourceWindow, targetWindow, ports);
        lock (_windowMessageQueueLock)
        {
            _windowMessageDeliveryTail = _windowMessageDeliveryTail.ContinueWith(
                _ =>
                {
                    var queueDelayMs = traceEnabled
                        ? System.Diagnostics.Stopwatch.GetElapsedTime(queuedAt).TotalMilliseconds
                        : 0;
                    if (traceEnabled)
                    {
                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                            "window-dequeued",
                            messageId,
                            0,
                            0,
                            sourceFrame,
                            targetFrame,
                            payload,
                            transferCount,
                            queueDelayMs,
                            false,
                            false,
                            listeners?.Count ?? 0,
                            false,
                            string.Empty));
                    }
                    try
                    {
                        if (sessionGeneration != _fenJsSessionGeneration)
                        {
                            if (traceEnabled)
                            {
                                TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                    "window-delivery-dropped",
                                    messageId,
                                    0,
                                    0,
                                    sourceFrame,
                                    targetFrame,
                                    payload,
                                    transferCount,
                                    queueDelayMs,
                                    false,
                                    false,
                                    listeners?.Count ?? 0,
                                    false,
                                    "session-changed-before-page-script-gate"));
                            }
                            return;
                        }

                        // Never in the middle of the document's own scripts.
                        WaitForPageScripts();
                        if (sessionGeneration != _fenJsSessionGeneration)
                        {
                            if (traceEnabled)
                            {
                                TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                    "window-delivery-dropped",
                                    messageId,
                                    0,
                                    0,
                                    sourceFrame,
                                    targetFrame,
                                    payload,
                                    transferCount,
                                    queueDelayMs,
                                    false,
                                    false,
                                    listeners?.Count ?? 0,
                                    false,
                                    "session-changed-after-page-script-gate"));
                            }
                            return;
                        }

                        if (traceEnabled)
                        {
                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                "window-page-scripts-ready",
                                messageId,
                                0,
                                0,
                                sourceFrame,
                                targetFrame,
                                payload,
                                transferCount,
                                queueDelayMs,
                                false,
                                false,
                                listeners?.Count ?? 0,
                                false,
                                string.Empty));
                        }

                        if (DiagnosticPaths.AppendEnabled)
                        {
                            // The line above is written when the message is
                            // queued, not when it runs. Reading it as delivery
                            // cost me an afternoon; this one is the dispatch.
                            // Whether `event.source` is the same object the frame
                            // sees as window.parent decides whether a reply sent
                            // to it reaches the parent at all.
                            DiagnosticPaths.AppendLogText(
                                "postmessage_probe.txt",
                                $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] deliver-run " +
                                $"listeners={listeners?.Count ?? 0} " +
                                $"srcIsParent={exposedSourceWindow.Equals(ReadGlobalValueOrUndefined("parent"))} " +
                                $"srcIsSelf={exposedSourceWindow.Equals(_fenJsGlobalThis)} " +
                                $"srcTag={exposedSourceWindow.Tag}{Environment.NewLine}");
                        }

                        try
                        {
                        RunFenJsWithLargeStack<object>(() =>
                        {
                            using (ScriptEngineLockProbe.Hold(_fenJsLock))
                            {
                                using (ActivateWindowCallbackContext(targetWindow, listeners))
                                {
                                    var eventValue = CreateMessageEventValue(data, origin, exposedSourceWindow, targetWindow, ports);
                                    var handler = ReadJsProperty(targetWindow, "onmessage");
                                    var handlerCallable = _interpreter.CanCallValue(handler);
                                    var listenerCount = listeners?.Count ?? 0;
                                    if (traceEnabled)
                                    {
                                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                            "window-handler-state",
                                            messageId,
                                            0,
                                            0,
                                            sourceFrame,
                                            targetFrame,
                                            payload,
                                            transferCount,
                                            queueDelayMs,
                                            false,
                                            handlerCallable,
                                            listenerCount,
                                            false,
                                            $"srcIsParent={exposedSourceWindow.Equals(ReadGlobalValueOrUndefined("parent"))}; srcIsSelf={exposedSourceWindow.Equals(_fenJsGlobalThis)}"));
                                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                            "window-handler-enter",
                                            messageId,
                                            0,
                                            0,
                                            sourceFrame,
                                            targetFrame,
                                            payload,
                                            transferCount,
                                            queueDelayMs,
                                            false,
                                            handlerCallable,
                                            listenerCount,
                                            false,
                                            string.Empty));
                                    }
                                    if (handlerCallable)
                                    {
                                        TryInvokeFenJsEventCallback(handler, targetWindow, eventValue, "message");
                                    }

                                    DispatchBrowserEvent(listeners, "message", targetWindow, eventValue);
                                    if (targetWindow.Equals(_fenJsGlobalThis))
                                    {
                                        NotifyEmbeddedFramesOfParentWindowEvent("message", eventValue);
                                    }
                                    if (traceEnabled)
                                    {
                                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                            "window-handler-complete",
                                            messageId,
                                            0,
                                            0,
                                            sourceFrame,
                                            targetFrame,
                                            payload,
                                            transferCount,
                                            queueDelayMs,
                                            false,
                                            handlerCallable,
                                            listenerCount,
                                            false,
                                            string.Empty));
                                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                            "window-checkpoint-enter",
                                            messageId,
                                            0,
                                            0,
                                            sourceFrame,
                                            targetFrame,
                                            payload,
                                            transferCount,
                                            queueDelayMs,
                                            false,
                                            false,
                                            0,
                                            false,
                                            string.Empty));
                                    }
                                    _interpreter.PumpMicrotasks();
                                    RecordMicrotaskCheckpoint("postMessage");
                                    if (traceEnabled)
                                    {
                                        TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                            "window-checkpoint-complete",
                                            messageId,
                                            0,
                                            0,
                                            sourceFrame,
                                            targetFrame,
                                            payload,
                                            transferCount,
                                            queueDelayMs,
                                            false,
                                            false,
                                            0,
                                            false,
                                            string.Empty));
                                    }
                                }
                            }

                return null;
            }, waitForWorkerMs: -1, instructionBudget: ResolveFenJsTaskInstructionBudget());
                        if (traceEnabled)
                        {
                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                "window-delivery-complete",
                                messageId,
                                0,
                                0,
                                sourceFrame,
                                targetFrame,
                                payload,
                                transferCount,
                                queueDelayMs,
                                false,
                                false,
                                0,
                                false,
                                string.Empty));
                        }
                    }
                    catch (Exception ex)
                    {
                        if (traceEnabled)
                        {
                            TraceFenJsMessageTransport(new FenJsMessageTransportTraceEvent(
                                "window-delivery-failed",
                                messageId,
                                0,
                                0,
                                sourceFrame,
                                targetFrame,
                                payload,
                                transferCount,
                                queueDelayMs,
                                false,
                                false,
                                listeners?.Count ?? 0,
                                false,
                                $"{ex.GetType().Name}: {ex.Message}"));
                        }
                        FenBrowser.Core.EngineLogCompat.Warn(
                            $"[FenJsBridge] postMessage delivery failed: {ex.Message}",
                            FenBrowser.Core.Logging.LogCategory.JavaScript);
                    }

                    try { RequestRender?.Invoke(); }
                    catch { /* render request is best-effort */ }
                    }
                    finally
                    {
                        deliveryPins?.Dispose();
                    }
                },
                CancellationToken.None,
                TaskContinuationOptions.None,
                TaskScheduler.Default);
        }
    }

    private bool DispatchFrameWindowHostEvent(
        JsValue frameWindow,
        List<BrowserEventListener> listeners,
        JsValue eventValue)
    {
        var type = ReadEventType(eventValue);
        PrepareDispatchedEvent(eventValue, frameWindow);
        DispatchBrowserEvent(listeners, type, frameWindow, eventValue);

        var handler = ReadJsProperty(frameWindow, "on" + type);
        if (_interpreter.CanCallValue(handler))
        {
            TryInvokeFenJsEventCallback(handler, frameWindow, eventValue, type);
        }

        return !ReadJsBoolProperty(eventValue, "defaultPrevented");
    }

    private JsValue CreateMessageEventValue(
        JsValue data,
        string origin,
        JsValue sourceWindow,
        JsValue targetWindow,
        JsValue ports)
    {
        AdoptTransferredMessagePorts(ports, targetWindow);
        // Every caller is the user agent firing a message event for postMessage, a
        // worker or a MessagePort (HTML 9.3.3, 9.4.4, 10.2.6), so the event is trusted
        // (DOM 2.5 isTrusted). Cloudflare Turnstile ignores untrusted messages, so its
        // widget never answered its own frame's handshake.
        var messageEvent = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["type"] = JsValue.FromString("message"),
            ["isTrusted"] = JsValue.FromBoolean(true),
            ["data"] = data,
            ["origin"] = JsValue.FromString(origin ?? string.Empty),
            ["lastEventId"] = JsValue.FromString(string.Empty),
            ["source"] = sourceWindow.Tag == JsValueTag.Undefined ? JsValue.Null : sourceWindow,
            ["ports"] = ports.Tag == JsValueTag.Object
                ? ports
                : _interpreter.AllocateArray(Array.Empty<JsValue>()),
            ["target"] = targetWindow,
            ["currentTarget"] = targetWindow,
            ["srcElement"] = targetWindow,
            ["bubbles"] = JsValue.FromBoolean(false),
            ["cancelable"] = JsValue.FromBoolean(false),
            ["defaultPrevented"] = JsValue.FromBoolean(false),
            ["timeStamp"] = JsValue.FromNumber(_fenJsClock.Elapsed.TotalMilliseconds)
        });

        // It is a MessageEvent (HTML 9.3.3), so the Event methods - stopPropagation,
        // stopImmediatePropagation, preventDefault, composedPath - come with it.
        var messageEventConstructor = ReadGlobalValueOrUndefined("MessageEvent");
        if (messageEventConstructor.Tag == JsValueTag.Object)
        {
            var prototype = ReadJsProperty(messageEventConstructor, "prototype");
            if (prototype.Tag == JsValueTag.Object)
            {
                _interpreter.Heap.GetObject(messageEvent.AsObjectHandle()).SetPrototype(prototype.AsObjectHandle());
            }
        }

        return messageEvent;
    }

    // HTML: postMessage(message, targetOrigin, transfer) and the newer
    // postMessage(message, options) where options is
    // { targetOrigin, transfer }. Only the first form was understood, so the
    // options object was stringified into the target origin, never matched a
    // real one, and the message was dropped without a word. reCAPTCHA sends its
    // setup handshake that way.
    private void ReadPostMessageTarget(
        IReadOnlyList<JsValue> args,
        out string targetOrigin,
        out JsValue transfer)
    {
        string overload;
        if (args.Count > 1 && args[1].Tag == JsValueTag.Object)
        {
            var options = args[1];
            var originValue = ReadJsProperty(options, "targetOrigin");
            // The options form defaults to "/", meaning the sender's own origin.
            targetOrigin = originValue.Tag == JsValueTag.Undefined
                ? GetCurrentWindowOrigin()
                : NormalizeSelfPostMessageOrigin(CoerceToHostString(originValue));
            transfer = ReadJsProperty(options, "transfer");
            overload = "options";
        }
        else
        {
            targetOrigin = args.Count > 1
                ? NormalizeSelfPostMessageOrigin(CoerceToHostString(args[1]))
                : "*";
            transfer = args.Count > 2 ? args[2] : JsValue.Undefined;
            overload = args.Count > 1 ? "targetOrigin" : "bare";
        }

        DetachTransferredArrayBuffers(transfer);

        // A delivery probe can only report the transfer list it was handed, so a
        // dropped port and a call that never carried one read the same downstream.
        // Naming the overload here separates "the page sent no port" from "we
        // parsed the arguments the wrong way".
        DiagnosticPaths.AppendLogText(
            "postmessage_probe.txt",
            $"{DateTimeOffset.UtcNow:O} [{ProbeFrame()}] post-args overload={overload} " +
            $"argc={args.Count} arg1Tag={(args.Count > 1 ? args[1].Tag.ToString() : "<absent>")} " +
            $"targetOrigin={targetOrigin} " +
            $"transferTag={transfer.Tag} " +
            $"transferCount={(transfer.Tag == JsValueTag.Object ? ReadArrayLikeLength(transfer) : -1)}" +
            $"{Environment.NewLine}");
    }

    /// <summary>
    /// HTML "StructuredSerializeWithTransfer" step 5 for ArrayBuffers in the transfer
    /// list: an already detached (or shared) buffer is a DataCloneError; the others are
    /// detached so the sender cannot read them after the call (mediasource-append-buffer
    /// appends a neutered buffer to see an empty append). The receiver's copy is what the
    /// message data carries; a buffer transferred but not referenced from the data is just
    /// gone, as it would be elsewhere.
    /// </summary>
    private void DetachTransferredArrayBuffers(JsValue transfer)
    {
        if (transfer.Tag != JsValueTag.Object)
        {
            return;
        }

        var length = ReadArrayLikeLength(transfer);
        var buffers = new List<FenBrowser.Js.Objects.ArrayBufferObject>();
        for (var index = 0; index < length; index++)
        {
            var item = ReadJsProperty(transfer, index.ToString(CultureInfo.InvariantCulture));
            if (item.Tag != JsValueTag.Object)
            {
                continue;
            }

            if (_interpreter.Heap.GetObject(item.AsObjectHandle()) is FenBrowser.Js.Objects.ArrayBufferObject buffer)
            {
                if (buffer.IsDetached || buffer.IsSharedArrayBuffer || buffers.Contains(buffer))
                {
                    ThrowDomException("DataCloneError", "An ArrayBuffer is detached and could not be cloned.");
                }

                buffers.Add(buffer);
            }
        }

        foreach (var buffer in buffers)
        {
            buffer.Detach();
        }
    }

    private string NormalizeSelfPostMessageOrigin(string targetOrigin) =>
        string.Equals(targetOrigin, "/", StringComparison.Ordinal)
            ? GetCurrentWindowOrigin()
            : targetOrigin;

    private bool ShouldDeliverWindowMessage(
        JsValue targetWindow,
        string targetOrigin,
        string targetWindowOriginOverride = null)
    {
        if (string.IsNullOrEmpty(targetOrigin) ||
            string.Equals(targetOrigin, "*", StringComparison.Ordinal))
        {
            return true;
        }

        // Delivery runs in the receiving realm, so when the target window object
        // cannot report an origin of its own - a bare global with no location
        // reachable through it - the realm's own document origin is the right
        // answer. Treating "no origin" as "does not match" silently dropped
        // same-origin messages, which is how reCAPTCHA's setup handshake was
        // being lost between its two frames.
        var expectedOrigin = targetWindowOriginOverride ?? ReadWindowOrigin(targetWindow);
        if (string.IsNullOrWhiteSpace(expectedOrigin))
        {
            expectedOrigin = GetCurrentWindowOrigin();
        }

        return string.Equals(
            NormalizePostMessageOrigin(targetOrigin),
            expectedOrigin,
            StringComparison.OrdinalIgnoreCase);
    }

    private string GetMessageSourceOrigin(JsValue sourceWindow)
    {
        if (sourceWindow.Tag == JsValueTag.Object)
        {
            var origin = ReadWindowOrigin(sourceWindow);
            if (!string.IsNullOrEmpty(origin))
            {
                return origin;
            }
        }

        return GetCurrentWindowOrigin();
    }

    private string ReadWindowOrigin(JsValue windowValue)
    {
        var location = ReadJsProperty(windowValue, "location");
        var origin = ReadJsProperty(location, "origin");
        if (origin.Tag != JsValueTag.Undefined && origin.Tag != JsValueTag.Null)
        {
            var originText = CoerceToHostString(origin);
            if (!string.IsNullOrWhiteSpace(originText) &&
                !string.Equals(originText, "undefined", StringComparison.Ordinal))
            {
                return originText;
            }
        }

        var href = ReadJsProperty(location, "href");
        if (href.Tag == JsValueTag.Undefined || href.Tag == JsValueTag.Null)
        {
            return null;
        }

        var hrefText = CoerceToHostString(href);
        if (string.IsNullOrWhiteSpace(hrefText) ||
            string.Equals(hrefText, "undefined", StringComparison.Ordinal))
        {
            return null;
        }

        return NormalizePostMessageOrigin(hrefText);
    }

    private string GetCurrentWindowOrigin()
    {
        if (_currentBaseUri != null)
        {
            return NormalizePostMessageOrigin(_currentBaseUri.AbsoluteUri);
        }

        return "null";
    }

    private static string NormalizePostMessageOrigin(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return string.Empty;
        }

        if (Uri.TryCreate(value, UriKind.Absolute, out var uri) &&
            (string.Equals(uri.Scheme, Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase) ||
             string.Equals(uri.Scheme, Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase)))
        {
            return uri.GetLeftPart(UriPartial.Authority);
        }

        return value;
    }

    private void ApplyHistoryUrl(FenJsLocationHost location, string url)
    {
        if (location == null || string.IsNullOrWhiteSpace(url))
        {
            return;
        }

        if (Uri.TryCreate(url, UriKind.Absolute, out var absolute))
        {
            UpdateFenJsLocation(location, absolute);
            return;
        }

        if (location.Uri != null && Uri.TryCreate(location.Uri, url, out var resolved))
        {
            UpdateFenJsLocation(location, resolved);
        }
    }

    private void UpdateFenJsLocation(FenJsLocationHost location, Uri uri)
    {
        if (location == null || uri == null)
        {
            return;
        }

        location.Uri = uri;
        _currentBaseUri = uri;
    }

    private JsValue GetOrCreateStyleObject(Element element)
    {
        var store = _hostPropertyStore.GetOrCreateValue(element) ?? new Dictionary<string, JsValue>();
        _hostPropertyStore.AddOrUpdate(element, store);
        if (store.TryGetValue("__fenJsStyle", out var cached))
            return cached;

        var styleObj = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            // cssText getter/setter is wired via Object.defineProperty below.
        });
        _interpreter.SetObjectProperty(styleObj, "setProperty", GetOrCreateHostCallable(
            element, "style.setProperty",
            (_, args) =>
            {
                var prop = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                var val = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                // cssText sentinel: replace the entire inline style.
                if (prop == "__cssText__")
                {
                    var existing = element.GetAttribute("style") ?? string.Empty;
                    if (existing != val)
                    {
                        element.SetAttribute("style", val);
                        NotifyResizeObservers(element);
                    }
                    return JsValue.Undefined;
                }
                // Replace or append the property in the existing style string.
                // Never append duplicate declarations â€” deduplicate by property name.
                var styleAttr = element.GetAttribute("style") ?? string.Empty;
                // CSSOM §6.7.1 setProperty step 4: an empty value removes the
                // declaration. Writing `display:;` instead left an empty display in
                // the cascade and google.com's Settings menu (shown via
                // `popup.style.display = ''`) never got a box.
                bool removeDeclaration = string.IsNullOrWhiteSpace(val);
                if (!removeDeclaration && HasNonPrintableCodePoint(val))
                {
                    return JsValue.Undefined;
                }
                if (!removeDeclaration && string.Equals(prop, "z-index", StringComparison.OrdinalIgnoreCase) &&
                    !IsValidZIndexValue(val))
                {
                    return JsValue.Undefined;
                }
                bool replaced = false;
                bool changed = false;
                var sb = new System.Text.StringBuilder();
                foreach (var decl in styleAttr.Split(';', StringSplitOptions.RemoveEmptyEntries))
                {
                    var trimmed = decl.Trim();
                    if (trimmed.Length == 0) continue;
                    var colonIdx = trimmed.IndexOf(':');
                    if (colonIdx < 0) continue;
                    var name = trimmed.Substring(0, colonIdx).Trim();
                    if (string.Equals(name, prop, StringComparison.OrdinalIgnoreCase))
                    {
                        replaced = true;
                        if (removeDeclaration)
                        {
                            changed = true;
                            continue;
                        }
                        // Replace the existing declaration with the new value.
                        var oldVal = trimmed.Substring(colonIdx + 1).Trim();
                        if (!string.Equals(oldVal, val, StringComparison.OrdinalIgnoreCase))
                            changed = true;
                        sb.Append(prop).Append(':').Append(val).Append(';');
                    }
                    else
                    {
                        sb.Append(trimmed).Append(';');
                    }
                }
                if (!replaced && !removeDeclaration)
                {
                    // New property â€” always a change.
                    sb.Append(prop).Append(':').Append(val).Append(';');
                    changed = true;
                }
                var newStyle = sb.ToString();
                if (changed)
                {
                    element.SetAttribute("style", newStyle);
                    NotifyResizeObservers(element);
                }
                return JsValue.Undefined;
            },
            length: 2), enumerable: true);
        _interpreter.SetObjectProperty(styleObj, "getPropertyValue", GetOrCreateHostCallable(
            element, "style.getPropertyValue",
            (_, args) =>
            {
                var prop = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                var styleAttr = element.GetAttribute("style") ?? string.Empty;
                var validDecls = ParseValidInlineDeclarations(styleAttr);
                if (prop == "__cssText__")
                {
                    if (validDecls.Count == 0) return JsValue.FromString(string.Empty);
                    return JsValue.FromString(string.Join("; ", validDecls.Select(d => $"{d.Name}: {d.Value}")) + ";");
                }
                if (string.IsNullOrEmpty(styleAttr) || string.IsNullOrEmpty(prop) || validDecls.Count == 0)
                    return JsValue.FromString(string.Empty);

                for (int j = validDecls.Count - 1; j >= 0; j--)
                {
                    if (string.Equals(validDecls[j].Name, prop, StringComparison.OrdinalIgnoreCase))
                        return JsValue.FromString(validDecls[j].Value);
                }
                return JsValue.FromString(string.Empty);
            },
            length: 1), enumerable: true);
        _interpreter.SetObjectProperty(styleObj, "removeProperty", GetOrCreateHostCallable(
            element, "style.removeProperty",
            (_, args) =>
            {
                var prop = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                var styleAttr = element.GetAttribute("style") ?? string.Empty;
                if (string.IsNullOrEmpty(styleAttr) || string.IsNullOrEmpty(prop))
                    return JsValue.FromString(string.Empty);
                // Remove the property from the style string and return its old value.
                string oldValue = string.Empty;
                var remaining = new System.Text.StringBuilder();
                foreach (var decl in styleAttr.Split(';', StringSplitOptions.RemoveEmptyEntries))
                {
                    var colonIdx = decl.IndexOf(':');
                    if (colonIdx < 0) { remaining.Append(decl).Append(';'); continue; }
                    var name = decl.Substring(0, colonIdx).Trim();
                    if (string.Equals(name, prop, StringComparison.OrdinalIgnoreCase))
                    {
                        oldValue = decl.Substring(colonIdx + 1).Trim();
                    }
                    else
                    {
                        remaining.Append(decl.Trim()).Append(';');
                    }
                }
                element.SetAttribute("style", remaining.ToString());
                NotifyResizeObservers(element);
                return JsValue.FromString(oldValue);
            },
            length: 1), enumerable: true);

        // CSSOM §6.7.3: every supported property is a camel-cased accessor
        // (plus cssFloat for float). The accessors live on one shared prototype
        // built once, so creating a style object costs nothing per property.
        var stylePrototype = GetOrCreateStylePrototype();
        if (stylePrototype.Tag == JsValueTag.Object)
        {
            _interpreter.Heap.GetObject(styleObj.AsObjectHandle()).SetPrototype(stylePrototype.AsObjectHandle());
        }

        store["__fenJsStyle"] = styleObj;
        return styleObj;
    }

    private JsValue _fenJsStylePrototype = JsValue.Undefined;

    private JsValue GetOrCreateStylePrototype()
    {
        if (_fenJsStylePrototype.Tag == JsValueTag.Object)
        {
            return _fenJsStylePrototype;
        }

        var prototype = _interpreter.AllocateObject(new Dictionary<string, JsValue>());
        var tempName = "__fenStyleProto" + Interlocked.Increment(ref _temporaryFenJsGlobalCounter)
            .ToString(CultureInfo.InvariantCulture);
        _interpreter.RegisterGlobalValue(tempName, prototype);
        try
        {
            var sb = new System.Text.StringBuilder();
            sb.Append("(function(p){function def(name, css){Object.defineProperty(p,name,{")
              .Append("get:function(){return this.getPropertyValue(css);},")
              .Append("set:function(v){if(v===null||v===undefined)v='';this.setProperty(css,''+v);},")
              .Append("enumerable:true,configurable:true});}");
            foreach (var property in FenBrowser.Core.Css.CssPropertyNames.All)
            {
                var camel = FenBrowser.Core.Css.CssPropertyNames.ToCamelCase(property);
                sb.Append("def('").Append(camel).Append("','").Append(property).Append("');");
                if (camel != property)
                {
                    // The dashed spelling is also an accessor (CSSOM §6.7.3 dashed attribute).
                    sb.Append("def('").Append(property).Append("','").Append(property).Append("');");
                }
            }
            sb.Append("def('cssFloat','float');");
            // cssText getter/setter: reading returns the full inline style string,
            // writing replaces the entire inline style via setAttribute('style', v).
            sb.Append("Object.defineProperty(p,'cssText',{")
              .Append("get:function(){return this.getPropertyValue('__cssText__');},")
              .Append("set:function(v){this.setProperty('__cssText__',''+v);},")
              .Append("enumerable:true,configurable:true});")
              .Append("})(globalThis.").Append(tempName).Append(");");
            EvaluateWithFenJsRaw(sb.ToString());
        }
        finally
        {
            _interpreter.RegisterGlobalValue(tempName, JsValue.Undefined);
        }

        _fenJsStylePrototype = prototype;
        return prototype;
    }

    // CSS 2.1 9.9.1 z-index: auto | <integer>, plus the CSS-wide keywords, and any
    // value holding var(), which is only checked once substituted (CSS Variables 1 3).
    private static bool IsValidZIndexValue(string value)
    {
        var v = value.Trim();
        return v.Equals("auto", StringComparison.OrdinalIgnoreCase) ||
               v.Equals("initial", StringComparison.OrdinalIgnoreCase) ||
               v.Equals("inherit", StringComparison.OrdinalIgnoreCase) ||
               v.Equals("unset", StringComparison.OrdinalIgnoreCase) ||
               v.Equals("revert", StringComparison.OrdinalIgnoreCase) ||
               v.Equals("revert-layer", StringComparison.OrdinalIgnoreCase) ||
               v.Contains("var(", StringComparison.OrdinalIgnoreCase) ||
               int.TryParse(v, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out _);
    }

    private static bool HasNonPrintableCodePoint(string s)
    {
        if (string.IsNullOrEmpty(s)) return false;
        for (int i = 0; i < s.Length; i++)
        {
            int cp = char.ConvertToUtf32(s, i);
            if (char.IsSurrogate(s[i])) i++;
            if ((cp >= 0 && cp <= 8) || cp == 0x0B || (cp >= 0x0E && cp <= 0x1F) || cp == 0x7F)
                return true;
        }
        return false;
    }

    private static List<(string Name, string Value)> ParseValidInlineDeclarations(string styleAttr)
    {
        var list = new List<(string Name, string Value)>();
        if (string.IsNullOrWhiteSpace(styleAttr)) return list;

        int i = 0, n = styleAttr.Length;
        while (i < n)
        {
            while (i < n && (styleAttr[i] <= ' ' || styleAttr[i] == ';')) i++;
            if (i >= n) break;

            int start = i;
            int colonIdx = -1;
            int braceDepth = 0, parenDepth = 0;
            char inQuote = '\0';
            while (i < n)
            {
                char c = styleAttr[i];
                if (inQuote != '\0')
                {
                    if (c == inQuote) inQuote = '\0';
                }
                else if (c == '"' || c == '\'')
                {
                    inQuote = c;
                }
                else if (c == '{') braceDepth++;
                else if (c == '}') { if (braceDepth > 0) braceDepth--; else break; }
                else if (c == '(') parenDepth++;
                else if (c == ')') { if (parenDepth > 0) parenDepth--; }
                else if (c == ':' && colonIdx < 0 && braceDepth == 0 && parenDepth == 0)
                {
                    colonIdx = i;
                }
                else if (c == ';' && braceDepth == 0 && parenDepth == 0)
                {
                    break;
                }
                i++;
            }

            if (colonIdx > start && inQuote == '\0' && braceDepth == 0)
            {
                var name = styleAttr.Substring(start, colonIdx - start).Trim();
                var val = styleAttr.Substring(colonIdx + 1, i - colonIdx - 1).Trim();
                if (parenDepth > 0 && i >= n && val.StartsWith("url(", StringComparison.OrdinalIgnoreCase))
                {
                    while (parenDepth > 0)
                    {
                        val += ")";
                        parenDepth--;
                    }
                }
                if (parenDepth == 0 && name.Length > 0 && val.Length > 0 && !val.StartsWith(":") && !name.Contains(':') && !name.Contains(';') && !name.Contains('{') && !name.Contains('}'))
                {
                    if (val.EndsWith("/*", StringComparison.Ordinal) || val.StartsWith("/*", StringComparison.Ordinal) || (val.Contains("/*") && !val.Contains("*/")))
                    {
                        // malformed comment
                    }
                    else
                    {
                        list.Add((name, val));
                    }
                }
            }
            if (i < n && styleAttr[i] == ';') i++;
            else if (i < n && styleAttr[i] == '}') { i++; break; }
        }
        return list;
    }

    private void NotifyResizeObservers(Element element)
    {
        RefreshFrameRealmViewport(element);
        var notify = ReadGlobalValueOrUndefined("__fenNotifyResizeObservers");
        if (_interpreter.CanCallValue(notify))
        {
            _interpreter.InvokeFunction(
                notify,
                new[] { ToHostOrNull(element, HostObjectKind.DomElement) },
                _fenJsGlobalThis);
        }
    }

    private void RefreshFrameRealmViewport(Element frameElement)
    {
        if (!IsIFrameElement(frameElement) ||
            FindRealmForFrame(frameElement) is not { } frameRealm)
        {
            return;
        }

        var width = ResolveFrameViewportDimension(frameElement, "width", WindowWidth);
        var height = ResolveFrameViewportDimension(frameElement, "height", WindowHeight);
        var proxy = GetStoredHostPropertyOrUndefined(frameElement, "__fenIframeContentWindow");
        if (proxy.Tag == JsValueTag.Object)
        {
            SetIFrameViewportProperties(proxy, frameElement);
        }
        frameRealm.UpdateOwnedViewport(width, height);
    }

    private void UpdateOwnedViewport(double width, double height)
    {
        UpdateViewportDimensions(width, height);
    }

    private void UpdateViewportDimensions(double width, double height)
    {
        var changed = false;
        var dispatchResize = false;
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            changed = Math.Abs(_windowWidth - width) > 0.001 || Math.Abs(_windowHeight - height) > 0.001;
            _windowWidth = width;
            _windowHeight = height;

            if (_interpreter == null || _fenJsGlobalThis.Tag != JsValueTag.Object)
            {
                return;
            }

            _interpreter.RegisterGlobalValue("innerWidth", JsValue.FromNumber(width));
            _interpreter.RegisterGlobalValue("innerHeight", JsValue.FromNumber(height));
            _interpreter.RegisterGlobalValue("outerWidth", JsValue.FromNumber(width));
            _interpreter.RegisterGlobalValue("outerHeight", JsValue.FromNumber(height));
            _interpreter.RegisterGlobalValue("devicePixelRatio", JsValue.FromNumber(1));
            if (_visualViewport.Tag == JsValueTag.Object)
            {
                _interpreter.SetObjectProperty(_visualViewport, "width", JsValue.FromNumber(width));
                _interpreter.SetObjectProperty(_visualViewport, "height", JsValue.FromNumber(height));
            }

            var screen = ReadGlobalValueOrUndefined("screen");
            if (screen.Tag == JsValueTag.Object)
            {
                _interpreter.SetObjectProperty(screen, "width", JsValue.FromNumber(width));
                _interpreter.SetObjectProperty(screen, "height", JsValue.FromNumber(height));
                _interpreter.SetObjectProperty(screen, "availWidth", JsValue.FromNumber(width));
                _interpreter.SetObjectProperty(screen, "availHeight", JsValue.FromNumber(height));
                var orientation = ReadJsProperty(screen, "orientation");
                if (orientation.Tag == JsValueTag.Object)
                {
                    _interpreter.SetObjectProperty(
                        orientation,
                        "type",
                        JsValue.FromString(width >= height ? "landscape-primary" : "portrait-primary"));
                }
            }

            dispatchResize = changed && _currentDomRoot != null;
        }

        if (dispatchResize)
        {
            QueueOwnedWindowEvent("resize");
            ScheduleMediaViewportCheck();
        }
    }

    public void NotifyFrameScrollChanged(Element frameElement)
    {
        if (!IsIFrameElement(frameElement))
        {
            return;
        }

        if (!_iframeRealms.TryGetValue(frameElement, out var frameRealm))
        {
            if (TryGetFrameRealm(frameElement.OwnerDocument, out var owningRealm) &&
                !ReferenceEquals(owningRealm, this))
            {
                owningRealm.NotifyFrameScrollChanged(frameElement);
            }
            return;
        }

        var scroll = FrameScrollReader?.Invoke(frameElement) ?? (0d, 0d);
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            var proxy = GetStoredHostPropertyOrUndefined(frameElement, "__fenIframeContentWindow");
            if (proxy.Tag == JsValueTag.Object)
            {
                SetWindowScrollProperties(proxy, scroll.Item1, scroll.Item2);
            }
        }
        frameRealm.UpdateOwnedScroll(scroll.Item1, scroll.Item2);
    }

    private void UpdateOwnedScroll(double x, double y)
    {
        var changed = false;
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            var previousX = ReadGlobalValueOrUndefined("scrollX");
            var previousY = ReadGlobalValueOrUndefined("scrollY");
            changed = previousX.Tag == JsValueTag.Undefined || previousY.Tag == JsValueTag.Undefined ||
                Math.Abs(CoerceToFiniteNumber(previousX, 0) - x) > 0.001 ||
                Math.Abs(CoerceToFiniteNumber(previousY, 0) - y) > 0.001;
            SetOwnedScrollGlobals(x, y);
        }

        if (changed)
        {
            QueueOwnedWindowEvent("scroll");
            // A media element may have scrolled out of the viewport (design section 5).
            ScheduleMediaViewportCheck();
        }
    }

    private void SetOwnedScrollGlobals(double x, double y)
    {
        _interpreter.RegisterGlobalValue("pageXOffset", JsValue.FromNumber(x));
        _interpreter.RegisterGlobalValue("pageYOffset", JsValue.FromNumber(y));
        _interpreter.RegisterGlobalValue("scrollX", JsValue.FromNumber(x));
        _interpreter.RegisterGlobalValue("scrollY", JsValue.FromNumber(y));
        if (_fenJsGlobalThis.Tag == JsValueTag.Object)
        {
            SetWindowScrollProperties(_fenJsGlobalThis, x, y);
        }
    }

    private void SetWindowScrollProperties(JsValue window, double x, double y)
    {
        _interpreter.SetObjectProperty(window, "pageXOffset", JsValue.FromNumber(x));
        _interpreter.SetObjectProperty(window, "pageYOffset", JsValue.FromNumber(y));
        _interpreter.SetObjectProperty(window, "scrollX", JsValue.FromNumber(x));
        _interpreter.SetObjectProperty(window, "scrollY", JsValue.FromNumber(y));
    }

    private void QueueOwnedWindowEvent(string type)
    {
        var sessionGeneration = _fenJsSessionGeneration;
        lock (_windowMessageQueueLock)
        {
            _windowMessageDeliveryTail = _windowMessageDeliveryTail.ContinueWith(
                _ =>
                {
                    if (sessionGeneration != _fenJsSessionGeneration)
                    {
                        return;
                    }

                    RunFenJsWithLargeStack<object>(() =>
                    {
                        using (ScriptEngineLockProbe.Hold(_fenJsLock))
                        {
                            var eventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
                            {
                                ["type"] = JsValue.FromString(type)
                            });
                            DispatchWindowHostEvent(eventValue);
                            if (string.Equals(type, "resize", StringComparison.Ordinal))
                            {
                                var visualEventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
                                {
                                    ["type"] = JsValue.FromString(type)
                                });
                                DispatchVisualViewportEvent(visualEventValue);
                            }
                            _interpreter.PumpMicrotasks();
                        }
                        return null;
                    });
                    try { RequestRender?.Invoke(); } catch { }
                },
                CancellationToken.None,
                TaskContinuationOptions.None,
                TaskScheduler.Default);
        }
    }

    private bool DispatchVisualViewportEvent(JsValue eventValue)
    {
        if (_visualViewport.Tag != JsValueTag.Object || eventValue.Tag != JsValueTag.Object)
        {
            return true;
        }

        var type = ReadEventType(eventValue);
        PrepareDispatchedEvent(eventValue, _visualViewport);
        DispatchBrowserEvent(_visualViewportEventListeners, type, _visualViewport, eventValue);

        var handler = ReadJsProperty(_visualViewport, "on" + type);
        if (_interpreter.CanCallValue(handler))
        {
            TryInvokeFenJsEventCallback(handler, _visualViewport, eventValue, type);
        }

        return !ReadJsBoolProperty(eventValue, "defaultPrevented");
    }

    private void AttachFenJsPrototype(JsValue target, string constructorName)
    {
        var tempName = "__fenTmp" + Interlocked.Increment(ref _temporaryFenJsGlobalCounter).ToString(CultureInfo.InvariantCulture);
        _interpreter.RegisterGlobalValue(tempName, target);
        try
        {
            EvaluateWithFenJsRaw($"Object.setPrototypeOf(globalThis.{tempName}, {constructorName}.prototype);");
        }
        finally
        {
            _interpreter.RegisterGlobalValue(tempName, JsValue.Undefined);
            EvaluateWithFenJsRaw($"delete globalThis.{tempName};");
        }
    }

    private void DispatchWindowLoadHandlers()
    {
        var windowValue = EvaluateWithFenJsRaw("window");
        var loadUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        UpdateEventLoopSnapshot(snapshot =>
        {
            snapshot.LoadFired = true;
            snapshot.LoadUtc = loadUtc;
        });
        AddEventLoopRecord("LoadFired", "window");
        LogEventLoop(
            "LoadFired",
            LogSeverity.Info,
            "[FenJsBridge] load dispatched",
            new Dictionary<string, object>
            {
                ["documentReadyState"] = "complete"
            });
        DispatchBrowserEvent(GetActiveWindowEventListeners(), "load", windowValue);

        if (TryReadWindowEventHandler(windowValue, "load", out var onload) &&
            _interpreter.CanCallValue(onload))
        {
            var eventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
            {
                ["type"] = JsValue.FromString("load"),
                ["target"] = windowValue,
                ["currentTarget"] = windowValue
            });
            TryInvokeFenJsEventCallback(onload, windowValue, eventValue, "load");
        }
        NotifyEmbeddedFramesOfParentWindowEvent("load", JsValue.Undefined);
    }

    private void InvokeBodyOnloadAttribute(Document document)
    {
        var body = document.Body;
        var onload = body?.GetAttribute("onload");
        if (string.IsNullOrWhiteSpace(onload))
        {
            return;
        }

        UpdateEventLoopSnapshot(snapshot => snapshot.BodyOnloadAttributeExecuted = true);
        AddEventLoopRecord("BodyOnloadAttributeExecuted", "body");
        var bodyValue = ToHostOrNull(body, HostObjectKind.DomElement);
        var eventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["type"] = JsValue.FromString("load"),
            ["target"] = bodyValue,
            ["currentTarget"] = bodyValue
        });

        InvokeFenJsInlineWithEvent(onload, eventValue);
    }

    /// <summary>
    /// Scans all elements in the DOM for HTML inline event-handler attributes
    /// (onclick, onchange, onsubmit, etc.) and compiles them into JS functions
    /// stored in the host property store so DispatchEventForElement can invoke
    /// them when the corresponding native event fires.
    /// </summary>
    // Event handler attribute names that correspond to DOM events.
    // Body onload is also invoked separately by InvokeBodyOnloadAttribute.
    private static readonly string[] InlineEventHandlerEventNames =
    {
        "click", "dblclick", "contextmenu",
        "mousedown", "mouseup", "mouseover", "mouseout", "mousemove",
        "keydown", "keyup", "keypress",
        "submit", "reset", "change", "input",
        "focus", "blur", "focusin", "focusout",
        "scroll", "wheel",
        "load", "error", "abort",
        "touchstart", "touchend", "touchmove", "touchcancel",
        // HTML §4.8.11.17 media events and §4.8.12 cuechange, all GlobalEventHandlers.
        "loadstart", "progress", "suspend", "emptied", "stalled", "loadedmetadata", "loadeddata",
        "canplay", "canplaythrough", "playing", "waiting", "seeking", "seeked", "ended",
        "durationchange", "timeupdate", "play", "pause", "ratechange", "resize", "volumechange",
        "cuechange",
        // EME §5 HTMLMediaElement extensions: onencrypted and onwaitingforkey.
        "encrypted", "waitingforkey"
    };

    private static readonly HashSet<string> InlineEventHandlerAttributeNames =
        new(InlineEventHandlerEventNames.Select(eventName => "on" + eventName), StringComparer.Ordinal);

    private void WireInlineEventHandlers(Node domRoot)
    {
        if (domRoot == null)
        {
            return;
        }

        var elements = domRoot.Descendants().OfType<Element>();
        foreach (var element in elements)
        {
            foreach (var eventName in InlineEventHandlerEventNames)
            {
                var attrName = "on" + eventName;
                var attrValue = element.GetAttribute(attrName);
                if (string.IsNullOrWhiteSpace(attrValue))
                {
                    continue;
                }

                CompileInlineEventHandler(element, attrName, attrValue);
            }
        }
    }

    /// <summary>
    /// HTML 8.1.8.1 event handler content attributes, "attribute change steps":
    /// a script setting an on* attribute installs the handler it names, replacing
    /// any handler assigned through the IDL property, and removing the attribute
    /// deactivates it. <paramref name="value"/> is null for a removal.
    /// </summary>
    private void ApplyEventHandlerContentAttributeChange(Element element, string attributeName, string value)
    {
        if (element == null || string.IsNullOrEmpty(attributeName))
        {
            return;
        }

        var attrName = attributeName.ToLowerInvariant();
        if (!InlineEventHandlerAttributeNames.Contains(attrName))
        {
            return;
        }

        if (value == null)
        {
            SetStoredHostProperty(element, attrName, JsValue.Null);
            return;
        }

        CompileInlineEventHandler(element, attrName, value);
    }

    private void CompileInlineEventHandler(Element element, string attrName, string attrValue)
    {
        try
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                // Wrap the attribute value in a function that receives
                // `event` as its parameter â€” matches what real browsers
                // do for inline handlers.
                var source = new SourceText(
                    "(function(event){" + attrValue + "\n})",
                    "<fenbrowser-inline-handler:" + attrName + ">");
                var compiled = _compiler.CompileScript(source);
                new BytecodeVerifier().Verify(compiled);
                var handler = _interpreter.Execute(compiled);
                // handler is now a callable function; store it so that
                // DispatchEventForElement can find it via
                // GetStoredHostPropertyOrUndefined(element, "on" + type).
                SetStoredHostProperty(element, attrName, handler);
            }
        }
        catch (Exception ex)
        {
            // A handler whose body does not compile is null, not the one it replaced.
            SetStoredHostProperty(element, attrName, JsValue.Null);
            FenLogger.Warn(
                $"[FenJsBridge] Failed to wire inline {attrName} handler on " +
                $"<{element.LocalName}>: {ex.Message}",
                LogCategory.JavaScript);
        }
    }

    private void DispatchBrowserEvent(
        List<BrowserEventListener> listeners,
        string type,
        JsValue currentTarget,
        JsValue eventValue = default,
        BrowserDomEventDispatchState dispatchState = null)
    {
        if (listeners.Count == 0)
        {
            return;
        }

        var callbacks = new List<BrowserEventListener>();
        for (var i = 0; i < listeners.Count; i++)
        {
            var listener = listeners[i];
            if (string.Equals(listener.Type, type, StringComparison.Ordinal))
            {
                callbacks.Add(listener);
            }
        }

        if (callbacks.Count == 0)
        {
            return;
        }

        var createdEventValue = false;
        if (eventValue.Tag == JsValueTag.Undefined)
        {
            eventValue = CreateBrowserDomEventValue(null, type, null, out dispatchState);
            createdEventValue = true;
        }

        // The facade lives only in C# locals between listener invocations; keep
        // it traced so a collection triggered by one listener cannot sweep it
        // before the next listener (or the post-dispatch default handling) runs.
        using var dispatchPins = PinFenJsValues(eventValue, currentTarget);

        if (createdEventValue)
        {
            _interpreter.SetObjectProperty(eventValue, "target", currentTarget);
            _interpreter.SetObjectProperty(eventValue, "srcElement", currentTarget);
        }
        _interpreter.SetObjectProperty(eventValue, "currentTarget", currentTarget);

        foreach (var listener in callbacks)
        {
            // DOM §2.10 "inner invoke": stop once a listener asked for it.
            if (ReadImmediatePropagationStopped(eventValue, dispatchState))
            {
                break;
            }

            // DOM §2.9: a listener removed by an earlier one in this dispatch is
            // skipped, and a once listener is removed before it is called.
            if (!listeners.Contains(listener))
            {
                continue;
            }

            if (listener.Once)
            {
                listeners.RemoveAll(existing =>
                    string.Equals(existing.Type, listener.Type, StringComparison.Ordinal) &&
                    existing.Capture == listener.Capture &&
                    existing.Callback.Equals(listener.Callback));
            }

            TryInvokeFenJsEventCallback(listener.Callback, currentTarget, eventValue, type);
        }
    }

    private bool DispatchDocumentHostEvent(Document document, JsValue eventValue)
    {
        if (document == null)
        {
            return true;
        }

        var type = ReadEventType(eventValue);
        var target = ToHostOrNull(document, HostObjectKind.DomDocument);
        PrepareDispatchedEvent(eventValue, target);
        DispatchBrowserEvent(_documentEventListeners, type, target, eventValue);
        return !ReadJsBoolProperty(eventValue, "defaultPrevented");
    }

    private bool DispatchWindowHostEvent(JsValue eventValue)
    {
        var type = ReadEventType(eventValue);
        var target = GetActiveWindowEventTarget();
        PrepareDispatchedEvent(eventValue, target);
        DispatchBrowserEvent(GetActiveWindowEventListeners(), type, target, eventValue);
        NotifyEmbeddedFramesOfParentWindowEvent(type, eventValue);

        if (TryReadWindowEventHandler(target, type, out var handler) &&
            _interpreter.CanCallValue(handler))
        {
            InvokeWindowEventHandler(handler, target, eventValue, type);
        }

        return !ReadJsBoolProperty(eventValue, "defaultPrevented");
    }

    private bool TryReadWindowEventHandler(JsValue target, string type, out JsValue handler)
    {
        handler = JsValue.Undefined;
        if (target.Tag == JsValueTag.Object)
        {
            handler = ReadJsProperty(target, "on" + type);
            if (handler.Tag != JsValueTag.Undefined)
            {
                return true;
            }
        }

        return _interpreter.TryReadGlobalValue("on" + type, out handler);
    }

    private bool DispatchElementHostEvent(Element element, JsValue eventValue)
    {
        if (element == null)
        {
            return true;
        }

        var type = ReadEventType(eventValue);
        var target = ToHostOrNull(element, HostObjectKind.DomElement);
        PrepareDispatchedEvent(eventValue, target);

        // Use full dispatch with capture/bubble phases. Pass null for dispatchState
        // because JS-dispatched events track propagation via _propagationStopped on
        // the event object itself (set by Event.prototype.stopPropagation).
        return DispatchElementEventWithActivation(element, type, eventValue, dispatchState: null);
    }

    private bool DispatchElementEventWithActivation(
        Element element,
        string type,
        JsValue eventValue,
        BrowserDomEventDispatchState dispatchState)
    {
        var grantsTransientActivation = string.Equals(type, "click", StringComparison.OrdinalIgnoreCase) &&
            ReadJsProperty(eventValue, "isTrusted") is { Tag: JsValueTag.Boolean } trusted &&
            trusted.AsBoolean();
        
        if (DiagnosticPaths.IframeDiagnosticsEnabled)
        {
            var tag = element?.TagName ?? "null";
            var id = element?.GetAttribute("id") ?? "";
            var classAttr = element?.GetAttribute("class") ?? "";
            var role = element?.GetAttribute("role") ?? "";
            var isTrusted = ReadJsProperty(eventValue, "isTrusted");
            var trustedBool = isTrusted is { Tag: JsValueTag.Boolean } t ? t.AsBoolean().ToString() : "undefined";
            DiagnosticPaths.AppendLogText(
                "iframe_diagnostics.txt",
                $"{DateTimeOffset.UtcNow:O} DispatchElementEventWithActivation: type={type} tag={tag} id='{id}' class='{element?.GetAttribute("class") ?? ""}' role='{role}' isTrusted={trustedBool} grantsTA={grantsTransientActivation}");
        }
        
        if (grantsTransientActivation)
        {
            _transientUserActivationDepth++;
            _stickyUserActivation = true;
            // HTML "activation notification": the transient activation outlives the click
            // handler, so an API called from a promise the click started still has one.
            _lastTransientActivation = Stopwatch.GetTimestamp();
            _transientActivationConsumed = false;
        }

        try
        {
            if (!string.Equals(type, "click", StringComparison.OrdinalIgnoreCase) ||
                !IsCheckboxInputElement(element) ||
                element.HasAttribute("disabled"))
            {
                return DispatchEventFull(element, type, eventValue, dispatchState);
            }

            var previousChecked = ElementStateManager.Instance.IsChecked(element);
            ElementStateManager.Instance.SetChecked(element, !previousChecked);

            var defaultAllowed = DispatchEventFull(element, type, eventValue, dispatchState);
            if (!defaultAllowed)
            {
                ElementStateManager.Instance.SetChecked(element, previousChecked);
                return false;
            }

            DispatchCheckboxStateEvent(element, "input");
            DispatchCheckboxStateEvent(element, "change");
            return true;
        }
        finally
        {
            if (grantsTransientActivation)
            {
                _transientUserActivationDepth--;
            }
        }
    }

    private int _transientUserActivationDepth;
    private long _lastTransientActivation;
    private bool _transientActivationConsumed;

    /// <summary>How long a click keeps granting transient activation (HTML's default).</summary>
    private static readonly TimeSpan TransientActivationDuration = TimeSpan.FromSeconds(5);

    /// <summary>
    /// HTML "transient activation": a recent interaction that has not been spent yet. This
    /// is what an API that may only run because a person asked for it looks at, and it is
    /// not the same as sticky activation, which never goes away.
    /// </summary>
    internal bool HasTransientActivation =>
        !_transientActivationConsumed &&
        (_transientUserActivationDepth > 0 ||
         (_lastTransientActivation != 0 && Stopwatch.GetElapsedTime(_lastTransientActivation) < TransientActivationDuration));

    /// <summary>
    /// HTML "consume user activation". False when there was none to spend, so the caller
    /// can refuse; a second API call in the same gesture then gets nothing.
    /// </summary>
    internal bool ConsumeTransientActivation()
    {
        if (!HasTransientActivation)
            return false;
        _transientActivationConsumed = true;
        return true;
    }

    private bool TryNormalizePopupUrl(string rawUrl, out string normalizedUrl)
    {
        if (string.IsNullOrWhiteSpace(rawUrl) ||
            string.Equals(rawUrl, "undefined", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(rawUrl, "null", StringComparison.OrdinalIgnoreCase))
        {
            normalizedUrl = "about:blank";
            return true;
        }

        if (!Uri.TryCreate(rawUrl, UriKind.Absolute, out var uri) &&
            (_currentBaseUri == null || !Uri.TryCreate(_currentBaseUri, rawUrl, out uri)))
        {
            normalizedUrl = null;
            return false;
        }

        var allowed = string.Equals(uri.Scheme, Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(uri.Scheme, Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(uri.AbsoluteUri, "about:blank", StringComparison.OrdinalIgnoreCase);
        normalizedUrl = allowed ? uri.AbsoluteUri : null;
        return allowed;
    }

    private static bool PopupFeatureEnabled(string features, string featureName)
    {
        foreach (var rawFeature in (features ?? string.Empty).Split(',', StringSplitOptions.RemoveEmptyEntries))
        {
            var pair = rawFeature.Trim().Split('=', 2, StringSplitOptions.TrimEntries);
            if (!string.Equals(pair[0], featureName, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            return pair.Length == 1 || string.IsNullOrEmpty(pair[1]) ||
                string.Equals(pair[1], "yes", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(pair[1], "true", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(pair[1], "1", StringComparison.Ordinal);
        }

        return false;
    }

    private void DispatchCheckboxStateEvent(Element element, string type)
    {
        var eventValue = CreateBrowserDomEventValue(
            element,
            type,
            new BrowserDomEventInit
            {
                Bubbles = true,
                Cancelable = false,
                Composed = true,
                IsTrusted = true
            },
            out var dispatchState);
        _ = DispatchEventFull(element, type, eventValue, dispatchState);
    }

    private string ReadEventType(JsValue eventValue)
    {
        if (eventValue.Tag == JsValueTag.Undefined || eventValue.Tag == JsValueTag.Null)
        {
            ThrowDomException("TypeError", "Failed to execute 'dispatchEvent': parameter 1 is not of type 'Event'.");
        }

        var typeValue = ReadJsProperty(eventValue, "type");
        var type = typeValue.Tag == JsValueTag.Undefined || typeValue.Tag == JsValueTag.Null
            ? string.Empty
            : CoerceToHostString(typeValue);
        if (string.IsNullOrEmpty(type))
        {
            ThrowDomException("InvalidStateError", "Failed to execute 'dispatchEvent': event type is empty.");
        }

        return type;
    }

    private void PrepareDispatchedEvent(JsValue eventValue, JsValue target)
    {
        if (eventValue.Tag != JsValueTag.Object)
        {
            return;
        }

        var currentTarget = ReadJsProperty(eventValue, "target");
        if (currentTarget.Tag == JsValueTag.Undefined || currentTarget.Tag == JsValueTag.Null)
        {
            _interpreter.SetObjectProperty(eventValue, "target", target);
            _interpreter.SetObjectProperty(eventValue, "srcElement", target);
        }

        _interpreter.SetObjectProperty(eventValue, "currentTarget", target);
    }

    private JsValue CreateBrowserDomEventValue(
        Element element,
        string type,
        BrowserDomEventInit eventInit,
        out BrowserDomEventDispatchState dispatchState)
    {
        eventInit ??= new BrowserDomEventInit();
        var state = new BrowserDomEventDispatchState();
        var target = element == null ? JsValue.Null : ToHostOrNull(element, HostObjectKind.DomElement);
        var relatedTarget = eventInit.RelatedTarget == null
            ? JsValue.Null
            : ToHostOrNull(eventInit.RelatedTarget, HostObjectKind.DomElement);
        var eventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["type"] = JsValue.FromString(type ?? string.Empty),
            ["target"] = target,
            ["currentTarget"] = target,
            ["srcElement"] = target,
            ["relatedTarget"] = relatedTarget,
            ["bubbles"] = JsValue.FromBoolean(eventInit.Bubbles),
            ["cancelable"] = JsValue.FromBoolean(eventInit.Cancelable),
            ["composed"] = JsValue.FromBoolean(eventInit.Composed),
            ["isTrusted"] = JsValue.FromBoolean(eventInit.IsTrusted),
            ["defaultPrevented"] = JsValue.FromBoolean(false),
            ["clientX"] = JsValue.FromNumber(eventInit.ClientX),
            ["clientY"] = JsValue.FromNumber(eventInit.ClientY),
            ["pageX"] = JsValue.FromNumber(eventInit.PageX),
            ["pageY"] = JsValue.FromNumber(eventInit.PageY),
            ["screenX"] = JsValue.FromNumber(eventInit.ScreenX),
            ["screenY"] = JsValue.FromNumber(eventInit.ScreenY),
            ["x"] = JsValue.FromNumber(eventInit.ClientX),
            ["y"] = JsValue.FromNumber(eventInit.ClientY),
            ["button"] = JsValue.FromInt32(eventInit.Button),
            ["buttons"] = JsValue.FromInt32(eventInit.Buttons),
            ["deltaX"] = JsValue.FromNumber(eventInit.DeltaX),
            ["deltaY"] = JsValue.FromNumber(eventInit.DeltaY),
            ["deltaZ"] = JsValue.FromNumber(0),
            ["deltaMode"] = JsValue.FromInt32(0),
            ["pointerId"] = JsValue.FromInt32(eventInit.PointerId),
            ["pointerType"] = JsValue.FromString(string.IsNullOrWhiteSpace(eventInit.PointerType) ? "mouse" : eventInit.PointerType),
            ["pressure"] = JsValue.FromNumber(eventInit.Pressure),
            ["isPrimary"] = JsValue.FromBoolean(eventInit.IsPrimary),
            ["key"] = JsValue.FromString(eventInit.Key ?? string.Empty),
            ["code"] = JsValue.FromString(eventInit.Code ?? string.Empty),
            ["which"] = JsValue.FromInt32(eventInit.KeyCode),
            ["keyCode"] = JsValue.FromInt32(eventInit.KeyCode),
            ["charCode"] = JsValue.FromInt32(eventInit.KeyCode),
            ["data"] = eventInit.Data == null ? JsValue.Null : JsValue.FromString(eventInit.Data),
            ["inputType"] = JsValue.FromString(eventInit.InputType ?? string.Empty),
            ["isComposing"] = JsValue.FromBoolean(eventInit.IsComposing),
            ["timeStamp"] = JsValue.FromNumber(_fenJsClock.Elapsed.TotalMilliseconds)
        });

        _interpreter.SetObjectProperty(eventValue, "preventDefault", _interpreter.AllocateNativeFunction(
            "preventDefault",
            (_, _) =>
            {
                if (eventInit.Cancelable)
                {
                    state.DefaultPrevented = true;
                    _interpreter.SetObjectProperty(eventValue, "defaultPrevented", JsValue.FromBoolean(true));
                }

                return JsValue.Undefined;
            },
            length: 0));
        _interpreter.SetObjectProperty(eventValue, "stopPropagation", _interpreter.AllocateNativeFunction(
            "stopPropagation",
            (_, _) =>
            {
                state.StopPropagation = true;
                _interpreter.SetObjectProperty(eventValue, "cancelBubble", JsValue.FromBoolean(true));
                return JsValue.Undefined;
            },
            length: 0));
        _interpreter.SetObjectProperty(eventValue, "stopImmediatePropagation", _interpreter.AllocateNativeFunction(
            "stopImmediatePropagation",
            (_, _) =>
            {
                state.StopPropagation = true;
                state.StopImmediatePropagation = true;
                _interpreter.SetObjectProperty(eventValue, "cancelBubble", JsValue.FromBoolean(true));
                return JsValue.Undefined;
            },
            length: 0));
        _interpreter.SetObjectProperty(eventValue, "composedPath", _interpreter.AllocateNativeFunction(
            "composedPath",
            (_, _) => _interpreter.AllocateArray(BuildComposedPathValues(element)),
            length: 0));
        _interpreter.SetObjectProperty(eventValue, "cancelBubble", JsValue.FromBoolean(false));

        dispatchState = state;
        return eventValue;
    }

    private JsValue[] BuildComposedPathValues(Element element)
    {
        if (element == null)
        {
            return Array.Empty<JsValue>();
        }

        var path = new List<JsValue>();
        var current = element;
        while (current != null)
        {
            path.Add(ToHostOrNull(current, HostObjectKind.DomElement));
            current = current.ParentElement;
        }

        var document = element.OwnerDocument;
        if (document != null)
        {
            path.Add(ToHostOrNull(document, HostObjectKind.DomDocument));
        }

        var windowTarget = GetActiveWindowEventTarget();
        if (windowTarget.Tag != JsValueTag.Undefined)
        {
            path.Add(windowTarget);
        }

        return path.ToArray();
    }

    private void InvokeFenJsCallback(JsValue callback, JsValue thisValue, JsValue eventValue)
    {
        // Snapshot the previous global event before marshaling so its handle can
        // be pinned for the whole invocation; reading it back in the finally
        // block would otherwise restore a value a collection may have swept.
        JsValue previousEvent;
        using (ScriptEngineLockProbe.Hold(_fenJsLock))
        {
            previousEvent = _interpreter.TryReadGlobalValue("event", out var existingEvent)
                ? existingEvent
                : JsValue.Undefined;
        }

        using var pins = PinFenJsValues(callback, thisValue, eventValue, previousEvent);
        RunFenJsWithLargeStack<object>(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                _interpreter.RegisterGlobalValue("event", eventValue);
                try
                {
                    _fenJsEvaluationCount++;
                    _ = _interpreter.InvokeFunction(callback, new[] { eventValue }, thisValue);
                }
                finally
                {
                    _interpreter.RegisterGlobalValue("event", previousEvent);
                }
            }

            return null;
        });
    }

    private bool TryInvokeFenJsEventCallback(JsValue callback, JsValue thisValue, JsValue eventValue, string eventType)
    {
        var invokedCallback = callback;
        try
        {
            if (_interpreter.CanCallValue(callback))
            {
                InvokeFenJsCallback(callback, thisValue, eventValue);
            }
            else
            {
                var handleEvent = ReadJsProperty(callback, "handleEvent");
                if (!_interpreter.CanCallValue(handleEvent))
                {
                    return false;
                }

                invokedCallback = handleEvent;
                InvokeFenJsCallback(handleEvent, callback, eventValue);
            }

            return true;
        }
        catch (JsThrownException ex)
        {
            _ = RecordDiagnosticCallbackFailure(
                invokedCallback,
                thisValue,
                new[] { eventValue },
                "event-listener",
                eventType,
                ex);
            var description = ex.Description;
            if (string.IsNullOrEmpty(description))
            {
                try { description = _interpreter?.DescribeThrownValue(ex.Value); } catch { }
            }

            EngineLogCompat.Warn(
                $"[FenJsBridge] Event listener for '{eventType ?? string.Empty}' failed: {description ?? ex.Message}",
                LogCategory.JavaScript);
            ReportFenJsException(ex);
            return false;
        }
        catch (Exception ex)
        {
            _ = RecordDiagnosticCallbackFailure(
                invokedCallback,
                thisValue,
                new[] { eventValue },
                "event-listener",
                eventType,
                ex);
            EngineLogCompat.Warn(
                $"[FenJsBridge] Event listener for '{eventType ?? string.Empty}' failed: {ex.GetType().Name}: {ex.Message}",
                LogCategory.JavaScript);
            return false;
        }
    }

    private void InvokeFenJsInlineWithEvent(string script, JsValue eventValue)
    {
        RunFenJsWithLargeStack<object>(() =>
        {
            using (ScriptEngineLockProbe.Hold(_fenJsLock))
            {
                var previousEvent = _interpreter.TryReadGlobalValue("event", out var existingEvent)
                    ? existingEvent
                    : JsValue.Undefined;
                _interpreter.RegisterGlobalValue("event", eventValue);
                try
                {
                    _fenJsEvaluationCount++;
                    var function = _compiler.CompileScript(new SourceText(script, "<fenbrowser-fenjs-inline-handler>"));
                    new BytecodeVerifier().Verify(function);
                    _ = _interpreter.Execute(function);
                }
                catch (Exception ex)
                {
                    FenLogger.Warn(
                        $"[FenJsBridge] Inline JS handler failed: {ex.GetType().Name}: {ex.Message}",
                        LogCategory.JavaScript);
                }
                finally
                {
                    _interpreter.RegisterGlobalValue("event", previousEvent);
                }
            }

            return null;
        });
    }

    private void ParseEventListenerOptions(JsValue options, out bool capture, out bool once)
        => ParseEventListenerOptions(options, out capture, out once, out _, out _);

    /// <summary>
    /// DOM "flatten more" (dom.spec.whatwg.org #event-flatten-more). Converting the
    /// argument to an AddEventListenerOptions dictionary reads every member, and
    /// that read is observable: the standard way to ask whether a browser supports
    /// passive listeners is to pass an object whose `passive` getter records that
    /// it ran. Only capture and once were ever read here, so that detection
    /// answered "not supported" everywhere, in every realm.
    /// </summary>
    private void ParseEventListenerOptions(
        JsValue options,
        out bool capture,
        out bool once,
        out bool passive,
        out JsValue signal)
    {
        capture = false;
        once = false;
        passive = false;
        signal = JsValue.Undefined;

        switch (options.Tag)
        {
            case JsValueTag.Undefined:
            case JsValueTag.Null:
                return;
            case JsValueTag.Boolean:
                capture = options.AsBoolean();
                return;
            case JsValueTag.Int32:
                capture = options.AsInt32() != 0;
                return;
            case JsValueTag.Number:
                capture = Math.Abs(options.AsNumber()) > 0;
                return;
            case JsValueTag.Object:
                // Dictionary member order, so a page that logs from its getters
                // sees the same sequence a browser produces.
                capture = ReadJsBoolProperty(options, "capture");
                once = ReadJsBoolProperty(options, "once");
                passive = ReadJsBoolProperty(options, "passive");
                signal = ReadJsProperty(options, "signal");
                return;
        }
    }

    private JsValue ExecuteDynamicScriptElement(Element scriptElement)
    {
        if (scriptElement == null ||
            !string.Equals(scriptElement.TagName, "SCRIPT", StringComparison.OrdinalIgnoreCase))
        {
            return JsValue.Undefined;
        }

        var scriptRecord = AddDynamicScriptLoadingRecord(scriptElement);
        var src = scriptElement.GetAttribute("src");
        if (string.Equals(scriptElement.GetAttribute("type")?.Trim(), "importmap", StringComparison.OrdinalIgnoreCase))
        {
            RegisterImportMapScript(scriptElement);
            MarkScriptSkipped(scriptRecord, "importmap");
            return ToHostNodeOrNull(scriptElement);
        }
        var discoveredFields = CreateScriptRecordFields(scriptRecord);
        discoveredFields["dynamic"] = true;
        LogScriptLoading(
            "ScriptDiscovered",
            LogSeverity.Debug,
            "[FenJsBridge] Dynamic script element seen",
            discoveredFields);

        // Inline script: execute textContent directly.
        if (string.IsNullOrWhiteSpace(src))
        {
            var inlineCode = scriptElement.TextContent;
            if (!string.IsNullOrWhiteSpace(inlineCode))
            {
                TraceScriptReady(scriptRecord, inlineCode.Length, "dynamic-inline");
                DispatchScriptElementEvent(
                    scriptElement,
                    ExecuteDynamicScriptCode(scriptElement, scriptRecord, inlineCode, "dynamic-inline", null) ? "load" : "error");
            }
            else
            {
                MarkScriptSkipped(scriptRecord, "empty-inline-code");
            }

            return ToHostNodeOrNull(scriptElement);
        }

        // Data: URLs contain inline code â€” decode and execute directly.
        if (src.StartsWith("data:", StringComparison.OrdinalIgnoreCase))
        {
            var dataCode = DecodeDataUrl(src);
            if (dataCode != null)
            {
                TraceScriptReady(scriptRecord, dataCode.Length, "dynamic-data");
                DispatchScriptElementEvent(
                    scriptElement,
                    ExecuteDynamicScriptCode(scriptElement, scriptRecord, dataCode, "dynamic-data", null) ? "load" : "error");
            }
            else
            {
                MarkScriptSkipped(scriptRecord, "invalid-data-url");
                DispatchScriptElementEvent(scriptElement, "error");
            }

            return ToHostNodeOrNull(scriptElement);
        }

        // External script: fetch and execute.
        if (!AllowExternalScripts || !Sandbox.Allows(SandboxFeature.ExternalScripts))
        {
            MarkScriptSkipped(scriptRecord, $"external-disabled:allowExternal={AllowExternalScripts};sandbox={Sandbox.Allows(SandboxFeature.ExternalScripts)}");
            return ToHostNodeOrNull(scriptElement);
        }

        var baseUri = _currentBaseUri;
        if (baseUri == null || !Uri.TryCreate(baseUri, src, out var scriptUri))
        {
            MarkScriptSkipped(scriptRecord, $"unresolvable-src:baseUri={baseUri}");
            DispatchScriptElementEvent(scriptElement, "error");
            return ToHostNodeOrNull(scriptElement);
        }

        // CSP3 6.6.3.4: this element was created and inserted by script, never by the
        // parser. Under 'strict-dynamic' it is authorized by the already-trusted script
        // that inserted it, so it must not be re-judged against the host allowlist or
        // required to carry a nonce of its own. Loaders that exist only to inject their
        // real bundle (reCAPTCHA's api.js, for one) depend on exactly this rule.
        var dynamicScriptAllowed = TrustedDynamicSubresourceAllowed ?? SubresourceAllowed;
        if (dynamicScriptAllowed != null && !dynamicScriptAllowed(scriptUri, "script"))
        {
            MarkScriptSkipped(scriptRecord, $"csp-block:{scriptUri}");
            DispatchScriptElementEvent(scriptElement, "error");
            return ToHostNodeOrNull(scriptElement);
        }

        try
        {
            UpdateScriptLoadingSnapshot(snapshot => snapshot.FetchStarted++);
            UpdateScriptLoadingRecord(scriptRecord, record =>
            {
                record.ResolvedUrl = scriptUri.AbsoluteUri;
                record.Status = "fetch-started";
            });
            var fetchStartedFields = CreateScriptRecordFields(scriptRecord);
            fetchStartedFields["url"] = scriptUri.AbsoluteUri;
            fetchStartedFields["batch"] = "dynamic";
            LogScriptLoading(
                "ScriptFetchStarted",
                LogSeverity.Debug,
                "[FenJsBridge] Dynamic external script fetch started",
                fetchStartedFields);

            Task<string> fetch;
            if (ExternalScriptFetcher != null)
            {
                fetch = ExternalScriptFetcher(scriptUri, baseUri);
            }
            else if (FetchOverride != null)
            {
                fetch = FetchOverride(scriptUri);
            }
            else
            {
                MarkScriptSkipped(scriptRecord, "fetcher-missing");
                DispatchScriptElementEvent(scriptElement, "error");
                return ToHostNodeOrNull(scriptElement);
            }

            // HTML 4.12.1 "prepare the script": an external script inserted by
            // script is async. Inserting one starts a fetch and the insertion
            // returns; the script runs later, as its own task.
            //
            // Doing it inline meant appendChild ran the whole thing: reCAPTCHA's
            // loader inserts an 853KB bundle, and the insertion sat there for
            // 3.8 seconds fetching, compiling and executing it, inside the
            // caller's own time budget.
            _ = fetch.ContinueWith(
                completed => QueueOnDeliveryTail(
                    () => FinishDynamicExternalScript(scriptElement, scriptRecord, scriptUri, completed),
                    "[FenJsBridge] dynamic script completion failed"),
                CancellationToken.None,
                TaskContinuationOptions.None,
                TaskScheduler.Default);

            return ToHostNodeOrNull(scriptElement);
        }
        catch (Exception ex)
        {
            RecordDynamicScriptFailure(scriptRecord, scriptElement, scriptUri, ex);
        }

        return ToHostNodeOrNull(scriptElement);
    }

    /// <summary>
    /// Runs an external script that was inserted by script, once its fetch has
    /// finished. Reached from the JS task chain, never from the insertion.
    /// </summary>
    private void FinishDynamicExternalScript(
        Element scriptElement,
        BrowserScriptLoadingRecord scriptRecord,
        Uri scriptUri,
        Task<string> fetch)
    {
        try
        {
            if (!fetch.IsCompletedSuccessfully)
            {
                RecordDynamicScriptFailure(
                    scriptRecord, scriptElement, scriptUri,
                    fetch.Exception?.GetBaseException() ?? new InvalidOperationException("fetch did not complete"));
                return;
            }

            var code = fetch.Result;
            UpdateScriptLoadingSnapshot(snapshot => snapshot.FetchCompleted++);
            UpdateScriptLoadingRecord(scriptRecord, record =>
            {
                record.CodeLength = code?.Length ?? 0;
                record.Status = "ready";
            });
            var fetchCompletedFields = CreateScriptRecordFields(scriptRecord);
            fetchCompletedFields["url"] = scriptUri.AbsoluteUri;
            fetchCompletedFields["batch"] = "dynamic";
            fetchCompletedFields["codeLength"] = code?.Length ?? 0;
            LogScriptLoading(
                "ScriptFetchCompleted",
                LogSeverity.Debug,
                "[FenJsBridge] Dynamic external script fetch completed",
                fetchCompletedFields);

            if (!string.IsNullOrWhiteSpace(code))
            {
                TraceScriptReady(scriptRecord, code.Length, "dynamic");
                if (!ExecuteDynamicScriptCode(scriptElement, scriptRecord, code, "dynamic", scriptUri))
                {
                    DispatchScriptElementEvent(scriptElement, "error");
                    return;
                }
            }
            else
            {
                MarkScriptSkipped(scriptRecord, "empty-code");
            }

            DispatchScriptElementEvent(scriptElement, "load");
        }
        catch (Exception ex)
        {
            RecordDynamicScriptFailure(scriptRecord, scriptElement, scriptUri, ex);
        }
    }

    private void RecordDynamicScriptFailure(
        BrowserScriptLoadingRecord scriptRecord, Element scriptElement, Uri scriptUri, Exception ex)
    {
        UpdateScriptLoadingSnapshot(snapshot => snapshot.FetchFailed++);
        UpdateScriptLoadingRecord(scriptRecord, record =>
        {
            record.Status = "fetch-failed";
            record.Failure = ex.GetType().Name + ": " + ex.Message;
            record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        });
        var fetchFailedFields = CreateScriptRecordFields(scriptRecord);
        fetchFailedFields["url"] = scriptUri.AbsoluteUri;
        fetchFailedFields["batch"] = "dynamic";
        fetchFailedFields["errorType"] = ex.GetType().Name;
        fetchFailedFields["error"] = ex.Message;
        LogScriptLoading(
            "ScriptFetchFailed",
            LogSeverity.Warn,
            "[FenJsBridge] Dynamic script fetch failed",
            fetchFailedFields);
        DispatchScriptElementEvent(scriptElement, "error");
    }

    private void TraceScriptReady(BrowserScriptLoadingRecord scriptRecord, int codeLength, string batchLabel)
    {
        UpdateScriptLoadingRecord(scriptRecord, record =>
        {
            record.CodeLength = codeLength;
            record.Status = "ready";
        });
        var readyFields = CreateScriptRecordFields(scriptRecord);
        readyFields["batch"] = batchLabel ?? string.Empty;
        readyFields["codeLength"] = codeLength;
        LogScriptLoading(
            "ScriptReady",
            LogSeverity.Debug,
            "[FenJsBridge] Script ready",
            readyFields);
    }

    private bool ExecuteDynamicScriptCode(
        Element scriptElement,
        BrowserScriptLoadingRecord scriptRecord,
        string code,
        string batchLabel,
        Uri moduleUri)
    {
        UpdateScriptLoadingSnapshot(snapshot => snapshot.ExecutionStarted++);
        UpdateScriptLoadingRecord(scriptRecord, record =>
        {
            record.Batch = batchLabel ?? string.Empty;
            record.CodeLength = code?.Length ?? record.CodeLength;
            record.Status = "execution-started";
        });
        var executionStartedFields = CreateScriptRecordFields(scriptRecord);
        executionStartedFields["batch"] = batchLabel ?? string.Empty;
        executionStartedFields["source"] = scriptRecord?.ResolvedUrl ?? scriptRecord?.Src ?? "inline";
        executionStartedFields["isModule"] = string.Equals(scriptRecord?.Kind, "module", StringComparison.OrdinalIgnoreCase);
        executionStartedFields["codeLength"] = code?.Length ?? 0;
        LogScriptLoading(
            "ScriptExecutionStarted",
            LogSeverity.Debug,
            "[FenJsBridge] Dynamic script execution started",
            executionStartedFields);

        SetCurrentScriptElement(scriptElement, scriptRecord);
        try
        {
            if (string.Equals(scriptRecord?.Kind, "module", StringComparison.OrdinalIgnoreCase))
            {
                EvaluateModuleWithFenJs(code, moduleUri);
            }
            else
            {
                EvaluateWithFenJsRaw(code);
            }

            UpdateScriptLoadingSnapshot(snapshot => snapshot.ExecutionCompleted++);
            UpdateScriptLoadingRecord(scriptRecord, record =>
            {
                record.Status = "executed";
                record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            });
            var executionCompletedFields = CreateScriptRecordFields(scriptRecord);
            executionCompletedFields["batch"] = batchLabel ?? string.Empty;
            executionCompletedFields["source"] = scriptRecord?.ResolvedUrl ?? scriptRecord?.Src ?? "inline";
            executionCompletedFields["isModule"] = string.Equals(scriptRecord?.Kind, "module", StringComparison.OrdinalIgnoreCase);
            LogScriptLoading(
                "ScriptExecutionCompleted",
                LogSeverity.Debug,
                "[FenJsBridge] Dynamic script execution completed",
                executionCompletedFields);
            return true;
        }
        catch (JsThrownException jte)
        {
            var desc = jte.Description;
            if (string.IsNullOrEmpty(desc))
            {
                try { desc = _interpreter.DescribeThrownValue(jte.Value); } catch { }
            }

            TraceDynamicScriptExecutionFailure(scriptRecord, batchLabel, "JsThrownException", desc ?? jte.Message);
            RecordMissingGlobalReference(desc ?? jte.Message, scriptRecord, _currentBaseUri);
            ReportFenJsException(jte);
            return false;
        }
        catch (Exception ex)
        {
            TraceDynamicScriptExecutionFailure(scriptRecord, batchLabel, ex.GetType().Name, ex.Message);
            return false;
        }
        finally
        {
            SetCurrentScriptElement(null);
        }
    }

    private void TraceDynamicScriptExecutionFailure(
        BrowserScriptLoadingRecord scriptRecord,
        string batchLabel,
        string errorType,
        string error)
    {
        UpdateScriptLoadingSnapshot(snapshot => snapshot.ExecutionFailed++);
        UpdateScriptLoadingRecord(scriptRecord, record =>
        {
            record.Status = "execution-failed";
            record.Failure = error ?? string.Empty;
            record.CompletedUtc = DateTimeOffset.UtcNow.ToString("O", CultureInfo.InvariantCulture);
        });
        var scriptFailedFields = CreateScriptRecordFields(scriptRecord);
        scriptFailedFields["batch"] = batchLabel ?? string.Empty;
        scriptFailedFields["origin"] = scriptRecord?.Src ?? "inline";
        scriptFailedFields["errorType"] = errorType ?? string.Empty;
        scriptFailedFields["error"] = error ?? string.Empty;
        LogScriptLoading(
            "ScriptExecutionFailed",
            LogSeverity.Error,
            "[FenJsBridge] Dynamic script error",
            scriptFailedFields,
            LogMarker.EngineBug);
    }

    private void DispatchScriptElementEvent(Element scriptElement, string type)
    {
        var eventValue = _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["type"] = JsValue.FromString(type),
            ["target"] = ToHostOrNull(scriptElement, HostObjectKind.DomElement),
            ["currentTarget"] = ToHostOrNull(scriptElement, HostObjectKind.DomElement)
        });

        var handler = GetStoredHostPropertyOrUndefined(scriptElement, "on" + type);
        if (_interpreter.CanCallValue(handler))
        {
            TryInvokeFenJsEventCallback(handler, ToHostOrNull(scriptElement, HostObjectKind.DomElement), eventValue, type);
        }
    }

    private void ExecuteInlineScriptsFromElement(Element rootElement)
    {
        if (rootElement == null)
        {
            return;
        }

        foreach (var scriptElement in rootElement.SelfAndDescendants().OfType<Element>())
        {
            if (!string.Equals(scriptElement.TagName, "SCRIPT", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            if (!string.IsNullOrWhiteSpace(scriptElement.GetAttribute("src")))
            {
                continue;
            }

            var code = CollectScriptText(scriptElement);
            if (string.IsNullOrWhiteSpace(code))
            {
                continue;
            }

            SetCurrentScriptElement(scriptElement);
            try
            {
                EvaluateWithFenJsRaw(code);
            }
            finally
            {
                SetCurrentScriptElement(null);
            }
        }
    }

    private void InsertAdjacentHtml(Element anchor, string position, string html)
    {
        if (anchor == null)
        {
            return;
        }

        // DOM Parsing 7.1 insertAdjacentHTML: the position is an ASCII case-insensitive
        // keyword; beforebegin/afterend parse in the parent's context and need a parent
        // that is not the document.
        var normalizedPosition = (position ?? string.Empty).ToLowerInvariant();
        Node context;
        switch (normalizedPosition)
        {
            case "beforebegin":
            case "afterend":
                context = anchor.ParentNode;
                if (context == null || context is Document)
                {
                    ThrowDomException("NoModificationAllowedError", "The element has no parent to insert next to.");
                    return;
                }
                break;
            case "afterbegin":
            case "beforeend":
                context = anchor;
                break;
            default:
                ThrowDomException("SyntaxError", $"'{position}' is not a valid insertion position.");
                return;
        }

        // A context that is not an element, or is the html element of an HTML
        // document, parses as if it were a body element.
        if (context is not Element contextElement ||
            (string.Equals(contextElement.LocalName, "html", StringComparison.Ordinal) &&
             string.Equals(contextElement.NamespaceUri, Namespaces.Html, StringComparison.Ordinal)))
        {
            contextElement = (anchor.OwnerDocument ?? new Document()).CreateElement("body");
        }

        var fragment = HtmlParser.ParseFragment(contextElement, html ?? string.Empty, options: null, out _);
        var insertedRoots = new List<Element>();

        void TrackInserted(Node node)
        {
            if (node is Element element)
            {
                insertedRoots.Add(element);
            }
        }

        switch (normalizedPosition)
        {
            case "afterbegin":
            {
                var parent = anchor as ContainerNode;
                var first = anchor.FirstChild;
                while (fragment.FirstChild != null)
                {
                    var node = fragment.FirstChild;
                    fragment.RemoveChild(node);
                    parent?.InsertBefore(node, first);
                    TrackInserted(node);
                }
                break;
            }
            case "beforeend":
            {
                var parent = anchor as ContainerNode;
                while (fragment.FirstChild != null)
                {
                    var node = fragment.FirstChild;
                    fragment.RemoveChild(node);
                    parent?.AppendChild(node);
                    TrackInserted(node);
                }
                break;
            }
            case "beforebegin":
            {
                var parent = anchor.ParentNode as ContainerNode;
                while (fragment.FirstChild != null)
                {
                    var node = fragment.FirstChild;
                    fragment.RemoveChild(node);
                    parent?.InsertBefore(node, anchor);
                    TrackInserted(node);
                }
                break;
            }
            case "afterend":
            {
                var parent = anchor.ParentNode as ContainerNode;
                var next = anchor.NextSibling;
                while (fragment.FirstChild != null)
                {
                    var node = fragment.FirstChild;
                    fragment.RemoveChild(node);
                    parent?.InsertBefore(node, next);
                    TrackInserted(node);
                }
                break;
            }
            default:
                return;
        }

        if (ExecuteInlineScriptsOnInnerHTML)
        {
            foreach (var insertedRoot in insertedRoots)
            {
                ExecuteInlineScriptsFromElement(insertedRoot);
            }
        }
    }

    private void OpenDocumentForWrite(Document document)
    {
        if (document == null)
        {
            return;
        }

        // HTML §8.4.1 "document open steps", step 13: the document's URL becomes the
        // entry document's URL, so markup written into an about:blank frame resolves
        // relative URLs the way it does in the page that wrote it.
        var entryUrl = _currentBaseUri?.AbsoluteUri;
        if (!string.IsNullOrWhiteSpace(entryUrl) && document.URL == "about:blank")
        {
            document.URL = entryUrl;
            document.BaseURI = entryUrl;
        }

        if (document.Body is not ContainerNode body)
        {
            return;
        }

        while (body.FirstChild != null)
        {
            body.RemoveChild(body.FirstChild);
        }
    }

    private void WriteDocumentMarkup(Document document, IReadOnlyList<JsValue> args, bool appendNewLine)
    {
        if (document == null)
        {
            return;
        }

        var html = string.Concat(args.Select(CoerceToHostString));
        if (appendNewLine)
        {
            html += Environment.NewLine;
        }

        if (string.IsNullOrEmpty(html))
        {
            return;
        }

        var contextElement = document.Body ?? document.DocumentElement;
        var fragment = HtmlParser.ParseFragment(
            contextElement,
            html,
            new HtmlParserOptions { BaseUri = _currentBaseUri },
            out _);

        if (fragment.ChildNodes == null || fragment.ChildNodes.Length == 0)
        {
            return;
        }

        var insertionParent = ResolveDocumentWriteInsertionParent(document, out var referenceNode);
        if (insertionParent == null)
        {
            return;
        }

        foreach (var child in fragment.ChildNodes.ToArray())
        {
            if (referenceNode != null)
            {
                insertionParent.InsertBefore(child, referenceNode);
            }
            else
            {
                insertionParent.AppendChild(child);
            }
        }
    }

    private ContainerNode ResolveDocumentWriteInsertionParent(Document document, out Node referenceNode)
    {
        referenceNode = null;

        var currentScript = GetCurrentScriptElement();
        if (ReferenceEquals(currentScript?.OwnerDocument, document) &&
            currentScript.ParentNode is ContainerNode scriptParent)
        {
            referenceNode = currentScript.NextSibling;
            return scriptParent;
        }

        if (document.Body is ContainerNode body)
        {
            return body;
        }

        if (document.DocumentElement is ContainerNode documentElement)
        {
            return documentElement;
        }

        return document;
    }

    private JsValue GetOrCreateHostCallable(
        object receiver,
        string name,
        Func<JsValue, IReadOnlyList<JsValue>, JsValue> call,
        int length = 0)
    {
        var methods = _hostCallableCache.GetOrCreateValue(receiver);
        if (methods.TryGetValue(name, out var existing))
        {
            return existing;
        }

        // Core throws DomException for the spec's own error cases. Left alone it
        // unwinds as a CLR exception straight past the interpreter, so a script
        // that guards the call in try/catch never gets the chance - the whole
        // script dies instead. WebIDL says these surface as ordinary catchable
        // JS exceptions, so every bridged method converts here rather than each
        // one remembering to.
        var guarded = WrapHostCallable(name, call);
        var created = _interpreter.AllocateNativeFunction(name, guarded, length);
        methods[name] = created;
        return created;
    }

    private Func<JsValue, IReadOnlyList<JsValue>, JsValue> WrapHostCallable(
        string name,
        Func<JsValue, IReadOnlyList<JsValue>, JsValue> call)
    {
        return (thisValue, args) =>
        {
            try
            {
                return call(thisValue, args);
            }
            catch (DomException domException)
            {
                ThrowDomException(
                    domException.Name,
                    string.IsNullOrEmpty(domException.Message)
                        ? $"Failed to execute '{name}'."
                        : domException.Message);
                return JsValue.Undefined; // ThrowDomException always throws.
            }
        };
    }

    /// <summary>
    /// The four child-list mutation methods for a container that has no
    /// type-specific override (DocumentFragment, ShadowRoot, or a container
    /// whose own getter declined). DOM 4.2.3 pre-insert / replace / remove.
    /// </summary>
    private JsValue CreateContainerMutationCallable(ContainerNode container, string method)
    {
        return GetOrCreateHostCallable(
            container,
            method,
            (_, args) => InvokeContainerMutation(container, method, args),
            length: method == "appendChild" || method == "removeChild" ? 1 : 2);
    }

    private JsValue InvokeContainerMutation(
        ContainerNode container,
        string method,
        IReadOnlyList<JsValue> args)
    {
        var first = args.Count > 0 ? ResolveHostObjectOrNull<Node>(args[0]) : null;
        if (first == null)
        {
            ThrowDomException("TypeError", $"Failed to execute '{method}' on 'Node': parameter 1 is not of type 'Node'.");
        }

        switch (method)
        {
            case "appendChild":
            {
                var moved = SnapshotFragmentChildren(first);
                var appended = ToHostNodeOrNull(container.AppendChild(first));
                UpgradeInsertedCustomElements(first, moved);
                QueueFrameLoadsForTree(first);
                return appended;
            }
            case "removeChild":
                return ToHostNodeOrNull(container.RemoveChild(first));
            case "insertBefore":
            {
                var reference = args.Count > 1 && args[1].Tag != JsValueTag.Null && args[1].Tag != JsValueTag.Undefined
                    ? ResolveHostObjectOrNull<Node>(args[1])
                    : null;
                if (args.Count > 1 && args[1].Tag != JsValueTag.Null && reference == null)
                {
                    ThrowDomException("TypeError", "Failed to execute 'insertBefore' on 'Node': parameter 2 is not of type 'Node'.");
                }

                var moved = SnapshotFragmentChildren(first);
                var inserted = ToHostNodeOrNull(container.InsertBefore(first, reference));
                UpgradeInsertedCustomElements(first, moved);
                QueueFrameLoadsForTree(first);
                return inserted;
            }
            case "moveBefore":
            {
                // DOM dom-node-movebefore; Node? child takes null or undefined.
                Node reference = null;
                if (args.Count > 1 && args[1].Tag != JsValueTag.Null && args[1].Tag != JsValueTag.Undefined)
                {
                    reference = ResolveHostObjectOrNull<Node>(args[1]);
                    if (reference == null)
                    {
                        ThrowDomException("TypeError", "Failed to execute 'moveBefore' on 'Node': parameter 2 is not of type 'Node'.");
                    }
                }

                container.MoveBefore(first, reference);
                return JsValue.Undefined;
            }
            default:
            {
                var child = args.Count > 1 ? ResolveHostObjectOrNull<Node>(args[1]) : null;
                if (child == null)
                {
                    ThrowDomException("TypeError", "Failed to execute 'replaceChild' on 'Node': parameter 2 is not of type 'Node'.");
                }

                var moved = SnapshotFragmentChildren(first);
                var replaced = ToHostNodeOrNull(container.ReplaceChild(first, child));
                UpgradeInsertedCustomElements(first, moved);
                QueueFrameLoadsForTree(first);
                return replaced;
            }
        }
    }

    private JsValue CreateCompareDocumentPositionCallable(Node node)
    {
        return GetOrCreateHostCallable(
            node,
            "compareDocumentPosition",
            (_, args) =>
            {
                var other = args.Count > 0 ? ResolveHostObjectOrNull<Node>(args[0]) : null;
                if (other == null)
                {
                    ThrowDomException(
                        "TypeError",
                        "Failed to execute 'compareDocumentPosition' on 'Node': parameter 1 is not of type 'Node'.");
                }

                return JsValue.FromInt32((int)node.CompareDocumentPosition(other));
            },
            length: 1);
    }

    // DOM 4.4 dom-node-getrootnode. Every host getter for a Node subtype needs
    // this, and they do not chain to one another, so it lives here alongside
    // CreateCompareDocumentPositionCallable rather than being written out once
    // per getter. The composed option walks out through shadow hosts; Core's
    // Node.GetRootNode already implements both modes.
    private JsValue CreateGetRootNodeCallable(Node node)
    {
        return GetOrCreateHostCallable(
            node,
            "getRootNode",
            (_, args) =>
            {
                var composed = false;
                if (args.Count > 0 && args[0].Tag == JsValueTag.Object)
                {
                    composed = CoerceToHostBoolean(ReadJsProperty(args[0], "composed"));
                }

                return ToHostNodeOrNull(node.GetRootNode(new GetRootNodeOptions { Composed = composed }));
            },
            length: 0);
    }

    // DOM 4.2.8 ChildNode: before(), after() and replaceWith(). Core implements
    // the mixin on Element, CharacterData and DocumentType alike, so one shared
    // callable covers every getter that needs them - the host getters do not
    // chain, and only remove() had been written out per type.
    //
    // The arguments are (Node or DOMString)..., and a string becomes a Text node
    // rather than being coerced away, so `el.replaceWith('text')` behaves.
    private JsValue CreateChildNodeMutationCallable(Node node, string name)
    {
        return GetOrCreateHostCallable(
            node,
            name,
            (_, args) =>
            {
                if (node is not IChildNode childNode)
                {
                    return JsValue.Undefined;
                }

                var owner = node.OwnerDocument;
                var nodes = new List<Node>(args.Count);
                for (var i = 0; i < args.Count; i++)
                {
                    var resolved = ResolveHostObjectOrNull<Node>(args[i]);
                    if (resolved != null)
                    {
                        nodes.Add(resolved);
                    }
                    else if (owner != null)
                    {
                        nodes.Add(owner.CreateTextNode(CoerceToHostString(args[i])));
                    }
                }

                var payload = nodes.ToArray();
                switch (name)
                {
                    case "before":
                        childNode.Before(payload);
                        break;
                    case "after":
                        childNode.After(payload);
                        break;
                    case "replaceWith":
                        childNode.ReplaceWith(payload);
                        break;
                }

                return JsValue.Undefined;
            },
            // WebIDL reports 0 for a variadic-only operation.
            length: 0);
    }

    private object ResolveHostObjectOrNull(JsValue value)
    {
        if (value.Tag != JsValueTag.HostObject)
        {
            return null;
        }

        var resolution = _interpreter.HostObjectTable.Resolve(value.AsHostObjectHandle(), _interpreter.HostResolveContext);
        return resolution.IsOk ? resolution.HostObject : null;
    }

    public bool TryResolveHostObject(JsValue value, out object hostObject)
    {
        hostObject = ResolveHostObjectOrNull(value);
        return hostObject != null;
    }

    /// <summary>
    /// Convert a FenJS JsValue to a .NET object recursively, suitable for
    /// WebDriver serialisation. Primitive values map to their .NET equivalents;
    /// arrays become List&lt;object&gt;; plain objects become Dictionary&lt;string,object&gt;;
    /// host objects are resolved through the host-object table.
    /// </summary>
    public object ConvertJsValueToObject(JsValue value)
    {
        return ConvertJsValueToObjectImpl(value, new HashSet<long>(), 0);
    }

    private object ConvertJsValueToObjectImpl(JsValue value, HashSet<long> visited, int depth)
    {
        if (depth > 16) return "[MaxDepth]";

        switch (value.Tag)
        {
            case JsValueTag.Undefined:
            case JsValueTag.Null:
                return null;
            case JsValueTag.Boolean:
                return value.AsBoolean();
            case JsValueTag.Int32:
                return value.AsInt32();
            case JsValueTag.Number:
                return value.AsNumber();
            case JsValueTag.String:
                return value.AsString();
            case JsValueTag.Symbol:
                return value.AsSymbolDescription() ?? "Symbol()";
            case JsValueTag.BigInt:
                return value.AsBigInt().ToString();
            case JsValueTag.Object:
            {
                var handle = value.AsObjectHandle();
                var objId = handle.ToInt64();
                if (!visited.Add(objId)) return "[Circular]";

                if (_interpreter == null) return "[object Object]";

                try
                {
                    var obj = _interpreter.Heap.GetObject(handle);
                    if (obj == null) return "[object Object]";

                    // Detect arrays by checking for non-negative 'length' property
                    if (obj.TryGetOwnProperty("length", out var lenDesc))
                    {
                        int arrLen = -1;
                        if (lenDesc.Value.Tag == JsValueTag.Int32)
                            arrLen = lenDesc.Value.AsInt32();
                        else if (lenDesc.Value.Tag == JsValueTag.Number)
                        {
                            var d = lenDesc.Value.AsNumber();
                            if (d >= 0 && d <= 100_000 && d == Math.Truncate(d))
                                arrLen = (int)d;
                        }

                        if (arrLen >= 0)
                        {
                            var list = new List<object>(Math.Min(arrLen, 10000));
                            for (int i = 0; i < arrLen && i < 10000; i++)
                            {
                                var key = i.ToString(System.Globalization.CultureInfo.InvariantCulture);
                                if (obj.TryGetOwnProperty(key, out var elemDesc))
                                    list.Add(ConvertJsValueToObjectImpl(elemDesc.Value, visited, depth + 1));
                                else
                                    list.Add(null);
                            }
                            visited.Remove(objId);
                            return list;
                        }
                    }

                    // Plain object â†’ dictionary
                    var dict = new Dictionary<string, object>(StringComparer.Ordinal);
                    foreach (var kv in obj.EnumerateOwnProperties())
                    {
                        if (kv.Key == "length" && (kv.Value.Value.Tag == JsValueTag.Int32 || kv.Value.Value.Tag == JsValueTag.Number))
                            continue; // length on array-like was handled above
                        dict[kv.Key] = ConvertJsValueToObjectImpl(kv.Value.Value, visited, depth + 1);
                    }
                    visited.Remove(objId);
                    return dict;
                }
                catch
                {
                    visited.Remove(objId);
                    return "[object Object]";
                }
            }
            case JsValueTag.HostObject:
            {
                if (TryResolveHostObject(value, out var hostObj))
                {
                    return hostObj; // Let BrowserApi handle element registration
                }
                return "[object HostObject]";
            }
            default:
                return "[Unknown]";
        }
    }

    private T ResolveHostObjectOrNull<T>(JsValue value) where T : class
    {
        return ResolveHostObjectOrNull(value) as T;
    }

    /// <summary>
    /// Reads a layout dimension (offsetHeight, clientWidth, etc.) for an element
    /// by resolving its layout box from the renderer.
    /// </summary>
    private JsValue ReadElementLayoutDimension(Element element, string property)
    {
        FlushPendingLayout?.Invoke(element);
        var isWidth = property is "offsetWidth" or "clientWidth" or "scrollWidth";
        var isHeight = property is "offsetHeight" or "clientHeight" or "scrollHeight";
        if (property is "clientWidth" or "clientHeight" &&
            element?.OwnerDocument?.DocumentElement == element)
        {
            var frameElement = TryGetFrameElementForDocument(element.OwnerDocument);
            if (frameElement != null &&
                TryReadDeclaredPixelDimension(
                    frameElement,
                    property == "clientWidth" ? "width" : "height",
                    out var frameViewportDimension))
            {
                return JsValue.FromNumber(frameViewportDimension);
            }

            return JsValue.FromNumber(property == "clientWidth" ? WindowWidth : WindowHeight);
        }

        // A browsing context can be resized and queried again in the same script
        // task. Until the renderer's asynchronous layout catches up, the old iframe
        // BoxModel belongs to the previous viewport and must not win over a current
        // explicit pixel size.
        if (IsIFrameElement(element) &&
            (isWidth || isHeight) &&
            TryReadDeclaredPixelDimension(element, isWidth ? "width" : "height", out var iframeDeclared))
        {
            return JsValue.FromNumber(iframeDeclared);
        }
        if ((isWidth || isHeight) &&
            TryReadExplicitIframeChildDimension(element, isWidth ? "width" : "height", out var childDeclared))
        {
            return JsValue.FromNumber(childDeclared);
        }

        var box = LayoutBoxResolver?.Invoke(element) as BoxModel;
        if (box == null)
        {
            if ((isWidth || isHeight) && TryReadDeclaredPixelDimension(element, isWidth ? "width" : "height", out var declared))
            {
                return JsValue.FromNumber(declared);
            }

            return JsValue.FromInt32(0);
        }

        return property switch
        {
            "offsetWidth" => JsValue.FromNumber(box.BorderBox.Width),
            "offsetHeight" => JsValue.FromNumber(box.BorderBox.Height),
            "clientWidth" => JsValue.FromNumber(box.PaddingBox.Width),
            "clientHeight" => JsValue.FromNumber(box.PaddingBox.Height),
            "offsetLeft" => JsValue.FromNumber(box.BorderBox.Left - OffsetParentPaddingEdge(element).X),
            "offsetTop" => JsValue.FromNumber(box.BorderBox.Top - OffsetParentPaddingEdge(element).Y),
            "clientLeft" => JsValue.FromNumber(box.BorderBox.Left - box.PaddingBox.Left),
            "clientTop" => JsValue.FromNumber(box.BorderBox.Top - box.PaddingBox.Top),
            "scrollWidth" => JsValue.FromNumber(box.ContentBox.Width),
            "scrollHeight" => JsValue.FromNumber(box.ContentBox.Height),
            "scrollTop" => JsValue.FromInt32(0),
            "scrollLeft" => JsValue.FromInt32(0),
            _ => JsValue.FromInt32(0)
        };
    }

    /// <summary>
    /// CSSOM View §9 "offsetParent": null for the root, body, a display:none or
    /// position:fixed element; otherwise the nearest ancestor that is positioned or a
    /// table cell / table, falling back to body. Google's popup positioning bails when
    /// offsetParent is missing, so the menu opened but stayed at the page origin.
    /// </summary>
    /// <summary>
    /// The padding-edge origin offsetLeft/offsetTop are measured from (CSSOM View §9);
    /// (0,0) when the offsetParent is body/null so the numbers stay page-relative there.
    /// </summary>
    private SKPoint OffsetParentPaddingEdge(Element element)
    {
        var offsetParent = ResolveOffsetParent(element);
        if (offsetParent == null || offsetParent == element.OwnerDocument?.Body)
        {
            return SKPoint.Empty;
        }

        var parentBox = LayoutBoxResolver?.Invoke(offsetParent) as BoxModel;
        return parentBox == null ? SKPoint.Empty : new SKPoint(parentBox.PaddingBox.Left, parentBox.PaddingBox.Top);
    }

    private Element ResolveOffsetParent(Element element)
    {
        if (element == null)
        {
            return null;
        }

        // offsetParent depends on computed display/position, so it flushes pending
        // style like the other layout-dependent reads; a popup that was just shown
        // (`style.display = ''`) otherwise still reads as display:none here.
        FlushPendingLayout?.Invoke(element);

        var document = element.OwnerDocument;
        var body = document?.Body;
        if (element == document?.DocumentElement || element == body)
        {
            return null;
        }

        var style = element.GetComputedStyle();
        if (style != null &&
            (string.Equals(style.Display, "none", StringComparison.OrdinalIgnoreCase) ||
             string.Equals(style.Position, "fixed", StringComparison.OrdinalIgnoreCase)))
        {
            return null;
        }

        for (var ancestor = element.ParentElement; ancestor != null; ancestor = ancestor.ParentElement)
        {
            if (ancestor == body)
            {
                return body;
            }

            var tag = ancestor.TagName?.ToUpperInvariant();
            if (tag is "TD" or "TH" or "TABLE")
            {
                return ancestor;
            }

            var ancestorStyle = ancestor.GetComputedStyle();
            var position = ancestorStyle?.Position;
            if (!string.IsNullOrEmpty(position) &&
                !string.Equals(position, "static", StringComparison.OrdinalIgnoreCase))
            {
                return ancestor;
            }
        }

        return body;
    }

    /// <summary>
    /// Returns a getBoundingClientRect result for an element from its layout box.
    /// </summary>
    private JsValue ReadElementBoundingClientRect(Element element)
    {
        FlushPendingLayout?.Invoke(element);
        var box = LayoutBoxResolver?.Invoke(element) as BoxModel;
        if (IsIFrameElement(element))
        {
            var hasDeclaredWidth = TryReadDeclaredPixelDimension(element, "width", out var declaredWidth);
            var hasDeclaredHeight = TryReadDeclaredPixelDimension(element, "height", out var declaredHeight);
            if (hasDeclaredWidth || hasDeclaredHeight)
            {
                var current = box?.BorderBox ?? default;
                return CreateDomRect(
                    current.Left,
                    current.Top,
                    hasDeclaredWidth ? declaredWidth : current.Width,
                    hasDeclaredHeight ? declaredHeight : current.Height);
            }
        }

        if (box == null)
        {
            TryReadDeclaredPixelDimension(element, "width", out var width);
            TryReadDeclaredPixelDimension(element, "height", out var height);
            return CreateDomRect(0, 0, width, height);
        }

        var r = box.BorderBox;
        var scroll = ReadAncestorScrollOffset(element);
        return CreateDomRect(r.Left - scroll.X, r.Top - scroll.Y, r.Width, r.Height);
    }

    /// <summary>
    /// Sum of the scroll offsets of every scrolling box above the element — its
    /// overflow scrollers, the embedding iframe of a nested browsing context, and
    /// the viewport. Layout boxes are unscrolled, and CSSOM View wants rects
    /// relative to the viewport.
    /// </summary>
    private (double X, double Y) ReadAncestorScrollOffset(Element element)
    {
        double x = 0, y = 0;
        if (FrameScrollReader == null)
        {
            return (0, 0);
        }

        // A fixed box is positioned against its viewport, so the scrollers between it
        // and that viewport (the embedding iframe, or the top-level window) don't
        // move it; scrolling above the frame still does.
        bool fixedToViewport = IsFixedPositioned(element);
        for (Node current = element?.ParentNode; current != null; current = current.ParentNode)
        {
            if (current is not Element ancestor)
            {
                continue;
            }

            if (IsIFrameElement(ancestor))
            {
                if (!fixedToViewport)
                {
                    var offset = FrameScrollReader(ancestor);
                    x += offset.X;
                    y += offset.Y;
                }
                fixedToViewport = IsFixedPositioned(ancestor);
            }
            else if (!fixedToViewport && IsScrollContainer(ancestor))
            {
                var offset = FrameScrollReader(ancestor);
                x += offset.X;
                y += offset.Y;
            }
            else if (!fixedToViewport && IsFixedPositioned(ancestor))
            {
                fixedToViewport = true;
            }
        }

        if (fixedToViewport)
        {
            return (x, y);
        }

        var viewport = FrameScrollReader(null);
        return (x + viewport.X, y + viewport.Y);
    }

    private static bool IsFixedPositioned(Element element) =>
        string.Equals(element?.GetComputedStyle()?.Position, "fixed", StringComparison.OrdinalIgnoreCase);

    /// <summary>
    /// CSSOM View §"scrollIntoView(arg)" + "scroll an element into view": for every
    /// scrolling box that is an ancestor of the element — nearest first, then the
    /// embedding frame of a nested browsing context — position the element's border
    /// box per the block/inline alignment. `true`/undefined align the block start,
    /// `false` the block end; an options dictionary supplies block/inline explicitly.
    /// </summary>
    private void ScrollElementIntoView(Element element, JsValue arg)
    {
        if (element == null)
        {
            return;
        }

        var block = "start";
        var inline = "nearest";
        if (arg.Tag == JsValueTag.Boolean)
        {
            block = arg.AsBoolean() ? "start" : "end";
        }
        else if (arg.Tag == JsValueTag.Object)
        {
            var blockValue = ReadJsProperty(arg, "block");
            var inlineValue = ReadJsProperty(arg, "inline");
            if (blockValue.Tag != JsValueTag.Undefined) block = CoerceToHostString(blockValue);
            if (inlineValue.Tag != JsValueTag.Undefined) inline = CoerceToHostString(inlineValue);
        }

        FlushPendingLayout?.Invoke(element);
        if (LayoutBoxResolver?.Invoke(element) is not BoxModel targetBox)
        {
            return;
        }

        var target = targetBox.BorderBox;
        var scrolled = false;
        var insideFrame = false;
        Node current = element.ParentNode;
        while (current != null)
        {
            if (current is Element ancestor &&
                (IsIFrameElement(ancestor) || IsScrollContainer(ancestor)) &&
                LayoutBoxResolver?.Invoke(ancestor) is BoxModel ancestorBox)
            {
                insideFrame |= IsIFrameElement(ancestor);
                var viewport = ancestorBox.PaddingBox;
                var currentScroll = FrameScrollReader?.Invoke(ancestor) ?? (0d, 0d);
                var y = ResolveScrollIntoViewOffset(
                    block, target.Top - viewport.Top, target.Height, viewport.Height, currentScroll.Y);
                var x = ResolveScrollIntoViewOffset(
                    inline, target.Left - viewport.Left, target.Width, viewport.Width, currentScroll.X);
                if (Math.Abs(x - currentScroll.X) > 0.001 || Math.Abs(y - currentScroll.Y) > 0.001)
                {
                    FrameScrollWriter?.Invoke(ancestor, Math.Max(0, x), Math.Max(0, y));
                    if (IsIFrameElement(ancestor))
                    {
                        NotifyFrameScrollChanged(ancestor);
                    }
                    scrolled = true;
                }
            }

            current = current.ParentNode;
        }

        // The top-level viewport's scroll is owned by the host (it translates the
        // canvas itself), so a top-level target goes through the host's provider.
        if (!insideFrame && JavaScriptEngine.TryScrollToElement(element))
        {
            scrolled = true;
        }

        if (scrolled)
        {
            RequestRender?.Invoke();
        }
    }

    /// <summary>
    /// An element whose overflow establishes a scrolling box. CSS Overflow §3.3
    /// propagates the root element's overflow (and body's, when the root's is
    /// visible) to the viewport, so neither is a scroll container of its own —
    /// the viewport (or the embedding iframe) is.
    /// </summary>
    private static bool IsScrollContainer(Element element)
    {
        if (element.ParentNode is Document)
        {
            return false;
        }

        if (element.ParentNode is Element parent &&
            parent.ParentNode is Document &&
            string.Equals(element.TagName, "BODY", StringComparison.OrdinalIgnoreCase) &&
            !HasScrollingOverflow(parent.GetComputedStyle()))
        {
            return false;
        }

        return HasScrollingOverflow(element.GetComputedStyle());
    }

    private static bool HasScrollingOverflow(CssComputed cs) =>
        cs != null &&
        (IsScrollingOverflow(cs.OverflowX) || IsScrollingOverflow(cs.OverflowY) || IsScrollingOverflow(cs.Overflow));

    private static bool IsScrollingOverflow(string overflow) =>
        overflow != null &&
        (overflow.Equals("auto", StringComparison.OrdinalIgnoreCase) ||
         overflow.Equals("scroll", StringComparison.OrdinalIgnoreCase) ||
         overflow.Equals("hidden", StringComparison.OrdinalIgnoreCase));

    /// <summary>
    /// Scroll offset that places a box of <paramref name="size"/> starting at
    /// <paramref name="offsetInContent"/> (unscrolled, relative to the scrolling box's
    /// padding edge) according to a scrollIntoView alignment keyword.
    /// </summary>
    private static double ResolveScrollIntoViewOffset(
        string alignment, double offsetInContent, double size, double viewportSize, double currentScroll)
    {
        switch (alignment?.ToLowerInvariant())
        {
            case "end":
                return offsetInContent + size - viewportSize;
            case "center":
                return offsetInContent + size / 2 - viewportSize / 2;
            case "nearest":
                {
                    var visibleStart = offsetInContent - currentScroll;
                    var visibleEnd = visibleStart + size;
                    if (visibleStart >= 0 && visibleEnd <= viewportSize)
                    {
                        return currentScroll;
                    }
                    if (size > viewportSize)
                    {
                        // Oversized boxes align the edge the viewport is already nearer to.
                        return visibleStart > 0 ? offsetInContent : offsetInContent + size - viewportSize;
                    }
                    return visibleStart < 0 ? offsetInContent : offsetInContent + size - viewportSize;
                }
            default:
                return offsetInContent;
        }
    }

    private static bool TryReadDeclaredPixelDimension(Element element, string property, out double value)
    {
        value = 0;
        string raw = null;
        foreach (var declaration in (element?.GetAttribute("style") ?? string.Empty)
            .Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var colonIndex = declaration.IndexOf(':');
            if (colonIndex <= 0 ||
                !string.Equals(declaration[..colonIndex].Trim(), property, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            raw = declaration[(colonIndex + 1)..].Trim();
        }

        raw ??= element?.GetAttribute(property);
        if (string.IsNullOrWhiteSpace(raw))
        {
            return false;
        }

        if (raw.EndsWith("px", StringComparison.OrdinalIgnoreCase))
        {
            raw = raw[..^2].TrimEnd();
        }

        return double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value) &&
            double.IsFinite(value);
    }

    private static bool TryReadExplicitIframeChildDimension(Element element, string property, out double value)
    {
        value = 0;
        if (element?.ChildNodes == null)
        {
            return false;
        }

        foreach (var child in element.ChildNodes.OfType<Element>())
        {
            if (IsIFrameElement(child) && TryReadDeclaredPixelDimension(child, property, out value))
            {
                return true;
            }
        }

        return false;
    }

    private JsValue CreateDomRect(double left, double top, double width, double height)
    {
        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["x"] = JsValue.FromNumber(left),
            ["y"] = JsValue.FromNumber(top),
            ["width"] = JsValue.FromNumber(width),
            ["height"] = JsValue.FromNumber(height),
            ["top"] = JsValue.FromNumber(top),
            ["right"] = JsValue.FromNumber(left + width),
            ["bottom"] = JsValue.FromNumber(top + height),
            ["left"] = JsValue.FromNumber(left),
        });
    }

    private JsValue CreateEmptyDomRectList()
    {
        var array = _interpreter.AllocateArray(Array.Empty<JsValue>());
        _interpreter.SetObjectProperty(
            array,
            "item",
            _interpreter.AllocateNativeFunction("item", (_, _) => JsValue.Null, length: 1),
            enumerable: false);
        return array;
    }

    private JsValue ReadElementClientRects(Element element)
    {
        FlushPendingLayout?.Invoke(element);
        var box = LayoutBoxResolver?.Invoke(element) as BoxModel;
        if (box == null)
        {
            return CreateEmptyDomRectList();
        }

        var rect = box.BorderBox;
        var scroll = ReadAncestorScrollOffset(element);
        var values = new[] { CreateDomRect(rect.Left - scroll.X, rect.Top - scroll.Y, rect.Width, rect.Height) };
        var array = _interpreter.AllocateArray(values);
        _interpreter.SetObjectProperty(
            array,
            "item",
            _interpreter.AllocateNativeFunction(
                "item",
                (_, args) =>
                {
                    var index = args.Count > 0 ? CoerceToHostUInt32(args[0], 0) : 0;
                    return index == 0 ? values[0] : JsValue.Null;
                },
                length: 1),
            enumerable: false);
        return array;
    }

    private DocumentFragment CreateContextualFragment(DomRange range, string html)
    {
        var context = ResolveRangeContextElement(range);
        if (context == null)
        {
            return (range?.CommonAncestorContainer?.OwnerDocument ?? new Document()).CreateDocumentFragment();
        }

        return HtmlParser.ParseFragment(
            context,
            html ?? string.Empty,
            new HtmlParserOptions { BaseUri = _currentBaseUri },
            out _);
    }

    private static Element ResolveRangeContextElement(DomRange range)
    {
        for (var node = range?.CommonAncestorContainer; node != null; node = node.ParentNode)
        {
            if (node is Element element)
            {
                return element;
            }

            if (node is Document document)
            {
                return document.Body ?? document.DocumentElement;
            }
        }

        return null;
    }

    private void ThrowHierarchyRequestError(string message)
    {
        ThrowDomException("HierarchyRequestError", message ?? "Hierarchy request error.");
    }

    private void ThrowDomException(string name, string message)
    {
        var exceptionName = string.IsNullOrWhiteSpace(name) ? "Error" : name;
        var exceptionMessage = message ?? string.Empty;
        var context = (FenBrowser.Js.Builtins.IBuiltinContext)_interpreter;

        // WebIDL 3.14: a DOMException thrown by the platform is an instance of
        // the realm's DOMException, so `e instanceof DOMException`, `e.code` and
        // `e.constructor === DOMException` all hold. TypeError and RangeError
        // are ECMAScript errors, not DOMExceptions.
        if (!string.Equals(exceptionName, "TypeError", StringComparison.Ordinal) &&
            !string.Equals(exceptionName, "RangeError", StringComparison.Ordinal) &&
            !string.Equals(exceptionName, "Error", StringComparison.Ordinal))
        {
            var domExceptionCtor = ReadGlobalValueOrUndefined("DOMException");
            if (_interpreter.CanCallValue(domExceptionCtor))
            {
                throw new JsThrownException(_interpreter.ConstructValue(
                    domExceptionCtor,
                    new[] { JsValue.FromString(exceptionMessage), JsValue.FromString(exceptionName) }));
            }
        }

        var errorValue = string.Equals(exceptionName, "TypeError", StringComparison.Ordinal)
            ? context.CreateTypeError(exceptionMessage)
            : string.Equals(exceptionName, "RangeError", StringComparison.Ordinal)
                ? context.CreateRangeError(exceptionMessage)
                : context.CreateError(exceptionMessage);
        var error = _interpreter.Heap.GetObject(errorValue.AsObjectHandle());
        error.DefineOwnProperty(
            "name",
            new FenBrowser.Js.Objects.JsPropertyDescriptor(
                JsValue.FromString(exceptionName),
                Writable: true,
                Enumerable: false,
                Configurable: true));

        throw new JsThrownException(errorValue);
    }

    /// <summary>
    /// Decodes a data: URL into its content string.  Supports text/plain and
    /// text/javascript with optional base64 encoding.  Returns null if the URL
    /// is not a valid data: URL or decoding fails.
    /// </summary>
    private static string DecodeDataUrl(string url)
    {
        if (string.IsNullOrWhiteSpace(url) || !url.StartsWith("data:", StringComparison.OrdinalIgnoreCase))
        {
            return null;
        }

        // data:[<mediatype>][;base64],<data>
        var commaIdx = url.IndexOf(',');
        if (commaIdx < 0)
        {
            return null;
        }

        var header = url.Substring(5, commaIdx - 5); // skip "data:"
        var data = url.Substring(commaIdx + 1);
        var isBase64 = header.EndsWith(";base64", StringComparison.OrdinalIgnoreCase);

        if (isBase64)
        {
            try
            {
                var bytes = Convert.FromBase64String(data);
                return Encoding.UTF8.GetString(bytes);
            }
            catch
            {
                return null;
            }
        }

        // URL-encoded data
        try
        {
            return Uri.UnescapeDataString(data);
        }
        catch
        {
            return data; // best-effort
        }
    }

    /// <summary>
    /// Converts a JS camelCase property name to a CSS kebab-case property name.
    /// e.g. "backgroundColor" â†’ "background-color", "zIndex" â†’ "z-index".
    /// </summary>
    private static string CamelToCssProp(string camel)
    {
        if (string.IsNullOrEmpty(camel))
        {
            return camel;
        }

        var sb = new StringBuilder(camel.Length + 4);
        for (int i = 0; i < camel.Length; i++)
        {
            var ch = camel[i];
            if (char.IsUpper(ch))
            {
                sb.Append('-');
                sb.Append(char.ToLowerInvariant(ch));
            }
            else
            {
                sb.Append(ch);
            }
        }
        return sb.ToString();
    }

    private static string CssPropToCamel(string propertyName)
    {
        if (string.IsNullOrEmpty(propertyName) || propertyName.IndexOf('-') < 0)
        {
            return propertyName;
        }

        var sb = new StringBuilder(propertyName.Length);
        var uppercaseNext = false;
        for (int i = 0; i < propertyName.Length; i++)
        {
            var ch = propertyName[i];
            if (ch == '-')
            {
                uppercaseNext = true;
                continue;
            }

            sb.Append(uppercaseNext ? char.ToUpperInvariant(ch) : ch);
            uppercaseNext = false;
        }

        return sb.ToString();
    }

    // A namespace argument is a DOMString? (WebIDL 3.2.17): null and undefined are
    // the null namespace, and so is "" once DOM "validate and extract" sees it.
    private static string ReadNullableNamespace(IReadOnlyList<JsValue> args, int index)
    {
        if (args.Count <= index || args[index].Tag is JsValueTag.Null or JsValueTag.Undefined)
        {
            return null;
        }

        var namespaceUri = CoerceToHostString(args[index]);
        return namespaceUri.Length == 0 ? null : namespaceUri;
    }

    // WebIDL 3.2.10 DOMString conversion is ECMA-262 ToString: an object goes
    // through its own toString()/valueOf() (a URL object becomes its href), and a
    // number is formatted the JS way (1e+21, Infinity). Both need the interpreter
    // that is running the calling code.
    private static string CoerceToHostString(JsValue value)
    {
        if (value.Tag is JsValueTag.Object or JsValueTag.HostObject or JsValueTag.Number &&
            BytecodeInterpreter.CurrentHostEntry is { } interpreter)
        {
            return interpreter.ToJsString(value);
        }

        return value.Tag switch
        {
            JsValueTag.Undefined => "undefined",
            JsValueTag.Null => "null",
            JsValueTag.Boolean => value.AsBoolean() ? "true" : "false",
            JsValueTag.Int32 => value.AsInt32().ToString(CultureInfo.InvariantCulture),
            JsValueTag.Number => value.AsNumber().ToString("R", CultureInfo.InvariantCulture),
            JsValueTag.String => value.AsString(),
            JsValueTag.Symbol => value.AsSymbolDescription() is string d ? $"Symbol({d})" : "Symbol()",
            JsValueTag.BigInt => value.AsBigInt().ToString(CultureInfo.InvariantCulture),
            _ => value.ToString()
        };
    }

    private static bool CoerceToHostBoolean(JsValue value)
    {
        return value.Tag switch
        {
            JsValueTag.Boolean => value.AsBoolean(),
            JsValueTag.Int32 => value.AsInt32() != 0,
            JsValueTag.Number => Math.Abs(value.AsNumber()) > double.Epsilon,
            JsValueTag.String => !string.IsNullOrEmpty(value.AsString()),
            JsValueTag.Null => false,
            JsValueTag.Undefined => false,
            _ => true
        };
    }

    private static uint CoerceToHostUInt32(JsValue value, uint fallback)
    {
        switch (value.Tag)
        {
            case JsValueTag.Int32:
                return unchecked((uint)value.AsInt32());
            case JsValueTag.Number:
                var number = value.AsNumber();
                if (double.IsFinite(number))
                {
                    return unchecked((uint)number);
                }
                break;
            case JsValueTag.String:
                if (uint.TryParse(value.AsString(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed))
                {
                    return parsed;
                }
                if (double.TryParse(value.AsString(), NumberStyles.Float, CultureInfo.InvariantCulture, out var parsedDouble) &&
                    double.IsFinite(parsedDouble))
                {
                    return unchecked((uint)parsedDouble);
                }
                break;
        }

        return fallback;
    }

    private static double CoerceToFiniteNumber(JsValue value, double fallback)
    {
        switch (value.Tag)
        {
            case JsValueTag.Int32:
                return value.AsInt32();
            case JsValueTag.Number:
                var number = value.AsNumber();
                return double.IsFinite(number) ? number : fallback;
            case JsValueTag.String:
                return double.TryParse(value.AsString(), NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed) &&
                    double.IsFinite(parsed)
                    ? parsed
                    : fallback;
            case JsValueTag.Boolean:
                return value.AsBoolean() ? 1 : 0;
            case JsValueTag.Null:
                return 0;
            default:
                return fallback;
        }
    }

    private static bool TryCoerceIndex(JsValue value, out int index)
    {
        switch (value.Tag)
        {
            case JsValueTag.Int32:
                index = value.AsInt32();
                return true;
            case JsValueTag.Number:
                var number = value.AsNumber();
                if (double.IsFinite(number) &&
                    Math.Truncate(number) == number &&
                    number >= int.MinValue &&
                    number <= int.MaxValue)
                {
                    index = (int)number;
                    return true;
                }
                break;
            case JsValueTag.String:
                if (int.TryParse(value.AsString(), NumberStyles.Integer, CultureInfo.InvariantCulture, out index))
                {
                    return true;
                }
                break;
        }

        index = -1;
        return false;
    }

    private JsValue CreateNodeArrayLike(IEnumerable<Node> nodes)
    {
        var items = new List<JsValue>();
        if (nodes != null)
        {
            foreach (var node in nodes)
            {
                items.Add(ToHostNodeOrNull(node));
            }
        }

        var array = _interpreter.AllocateArray(items);
        var itemFunction = _interpreter.AllocateNativeFunction(
            "item",
            (_, args) =>
            {
                var index = -1;
                if (args.Count > 0)
                {
                    switch (args[0].Tag)
                    {
                        case JsValueTag.Int32:
                            index = args[0].AsInt32();
                            break;
                        case JsValueTag.Number:
                            var number = args[0].AsNumber();
                            if (double.IsFinite(number) &&
                                Math.Truncate(number) == number &&
                                number >= int.MinValue &&
                                number <= int.MaxValue)
                            {
                                index = (int)number;
                            }
                            break;
                        case JsValueTag.String:
                            if (int.TryParse(args[0].AsString(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedIndex))
                            {
                                index = parsedIndex;
                            }
                            break;
                    }
                }

                if (index < 0 || index >= items.Count)
                {
                    return JsValue.Null;
                }

                return items[index];
            },
            length: 1);
        _interpreter.SetObjectProperty(array, "item", itemFunction, enumerable: false);
        return array;
    }

    private JsValue CreateNodeFilterConstantsObject()
    {
        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["FILTER_ACCEPT"] = JsValue.FromInt32((int)NodeFilterResult.Accept),
            ["FILTER_REJECT"] = JsValue.FromInt32((int)NodeFilterResult.Reject),
            ["FILTER_SKIP"] = JsValue.FromInt32((int)NodeFilterResult.Skip),
            ["SHOW_ALL"] = JsValue.FromNumber(NodeFilterShow.All),
            ["SHOW_ELEMENT"] = JsValue.FromInt32((int)NodeFilterShow.Element),
            ["SHOW_ATTRIBUTE"] = JsValue.FromInt32((int)NodeFilterShow.Attribute),
            ["SHOW_TEXT"] = JsValue.FromInt32((int)NodeFilterShow.Text),
            ["SHOW_CDATA_SECTION"] = JsValue.FromInt32((int)NodeFilterShow.CDataSection),
            ["SHOW_ENTITY_REFERENCE"] = JsValue.FromInt32((int)NodeFilterShow.EntityReference),
            ["SHOW_ENTITY"] = JsValue.FromInt32((int)NodeFilterShow.Entity),
            ["SHOW_PROCESSING_INSTRUCTION"] = JsValue.FromInt32((int)NodeFilterShow.ProcessingInstruction),
            ["SHOW_COMMENT"] = JsValue.FromInt32((int)NodeFilterShow.Comment),
            ["SHOW_DOCUMENT"] = JsValue.FromInt32((int)NodeFilterShow.Document),
            ["SHOW_DOCUMENT_TYPE"] = JsValue.FromInt32((int)NodeFilterShow.DocumentType),
            ["SHOW_DOCUMENT_FRAGMENT"] = JsValue.FromInt32((int)NodeFilterShow.DocumentFragment),
            ["SHOW_NOTATION"] = JsValue.FromInt32((int)NodeFilterShow.Notation)
        });
    }

    private bool AllowsEmbeddingSandboxFlag(IframeSandboxFlags requiredFlag)
    {
        if (_embeddingFrameElement == null || !_embeddingFrameElement.HasAttribute("sandbox"))
        {
            return true;
        }

        var flags = SandboxPolicy.ParseIframeSandboxFlags(_embeddingFrameElement.GetAttribute("sandbox"));
        return (flags & requiredFlag) == requiredFlag;
    }

    private bool AllowsEmbeddingSandboxPopup()
    {
        if (_embeddingFrameElement == null || !_embeddingFrameElement.HasAttribute("sandbox"))
        {
            return true;
        }

        var flags = SandboxPolicy.ParseIframeSandboxFlags(_embeddingFrameElement.GetAttribute("sandbox"));
        return (flags & IframeSandboxFlags.Popups) != 0 &&
               (flags & IframeSandboxFlags.PopupsToEscapeSandbox) != 0;
    }

    private void NavigateOwningBrowsingContext(Uri targetUri)
    {
        if (targetUri == null)
        {
            return;
        }

        if (_parentRealmOwner != null && _embeddingFrameElement != null)
        {
            _parentRealmOwner.QueueFrameNavigation(_embeddingFrameElement, targetUri);
            return;
        }

        _host.Navigate(targetUri);
    }

    private void QueueFrameNavigation(Element frameElement, Uri targetUri)
    {
        if (frameElement == null || targetUri == null || !frameElement.IsConnected)
        {
            return;
        }

        frameElement.SetAttribute("src", targetUri.AbsoluteUri);
        SetStoredHostProperty(frameElement, "__fenFrameLoadUrl", JsValue.Undefined);
        QueueFrameElementLoad(frameElement);
    }

    private void AdoptTransferredMessagePorts(JsValue ports, JsValue targetWindow)
    {
        if (ports.Tag != JsValueTag.Object || targetWindow.Tag != JsValueTag.Object)
        {
            return;
        }

        var lengthValue = ReadJsProperty(ports, "length");
        var length = lengthValue.Tag == JsValueTag.Number
            ? Math.Max(0, (int)lengthValue.AsNumber())
            : 0;
        for (var index = 0; index < length; index++)
        {
            var port = ReadJsProperty(ports, index.ToString(CultureInfo.InvariantCulture));
            if (port.Tag == JsValueTag.Object)
            {
                _interpreter.SetObjectProperty(port, "_fenWindow", targetWindow);
            }
        }
    }

    private JsValue CreateCssGlobalObject()
    {
        return _interpreter.AllocateObject(new Dictionary<string, JsValue>
        {
            ["supports"] = _interpreter.AllocateNativeFunction(
                "supports",
                (_, args) => JsValue.FromBoolean(CssSupports(args)),
                length: 1),
            ["escape"] = _interpreter.AllocateNativeFunction(
                "escape",
                (_, args) => JsValue.FromString(CssEscape(args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty)),
                length: 1)
        });
    }

    /// <summary>
    /// HTMLStyleElement.sheet: one CSSStyleSheet per style element, built by the
    /// prelude's __fenCreateStyleSheet and cached on the element.
    /// </summary>
    private JsValue GetOrCreateStyleElementSheet(Element element)
    {
        var existing = GetStoredHostPropertyOrUndefined(element, "sheet");
        if (existing.Tag != JsValueTag.Undefined)
        {
            return existing;
        }

        var factory = _interpreter.ReadGlobalValueOrUndefined("__fenCreateStyleSheet");
        if (!_interpreter.CanCallValue(factory))
        {
            return JsValue.Null;
        }

        var sheet = _interpreter.InvokeFunction(factory, new[] { ToHostNodeOrNull(element) }, JsValue.Undefined);
        SetStoredHostProperty(element, "sheet", sheet);
        return sheet;
    }

    /// <summary>
    /// CSSOM 6.2: the elements that own a document stylesheet - a &lt;style&gt;, or a
    /// &lt;link&gt; whose rel includes "stylesheet".
    /// </summary>
    private bool IsStyleSheetOwnerElement(Element element)
    {
        if (element == null)
        {
            return false;
        }

        if (string.Equals(element.TagName, "STYLE", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (!string.Equals(element.TagName, "LINK", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var rel = element.GetAttribute("rel");
        if (string.IsNullOrWhiteSpace(rel))
        {
            return false;
        }

        foreach (var token in rel.Split((char[])null, StringSplitOptions.RemoveEmptyEntries))
        {
            if (string.Equals(token, "stylesheet", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// CSSOM 6.2 document.styleSheets. The list object is kept per document so
    /// `document.styleSheets === document.styleSheets` holds the way it does in a
    /// browser; its contents are refreshed on every read, because the collection is
    /// live and a page adds stylesheets long after load.
    /// </summary>
    private JsValue GetDocumentStyleSheetList(Document document)
    {
        var list = GetStoredHostPropertyOrUndefined(document, "__fenStyleSheetList");
        if (list.Tag != JsValueTag.Object)
        {
            list = _interpreter.AllocateObject(new Dictionary<string, JsValue>
            {
                ["length"] = JsValue.FromInt32(0),
                ["item"] = _interpreter.AllocateNativeFunction(
                    "item",
                    (thisValue, args) =>
                    {
                        if (args.Count == 0)
                        {
                            return JsValue.Null;
                        }

                        var index = (int)CoerceToFiniteNumber(args[0], -1);
                        var indexed = ReadJsProperty(thisValue, index.ToString(CultureInfo.InvariantCulture));
                        return indexed.Tag == JsValueTag.Undefined ? JsValue.Null : indexed;
                    },
                    length: 1)
            });
            SetStoredHostProperty(document, "__fenStyleSheetList", list);
        }

        RefreshStyleSheetList(document, list);
        return list;
    }

    private void RefreshStyleSheetList(Document document, JsValue list)
    {
        var owners = CollectStyleSheetOwners(document);
        var previousLength = (int)CoerceToFiniteNumber(ReadJsProperty(list, "length"), 0);

        for (var i = 0; i < owners.Count; i++)
        {
            _interpreter.SetObjectProperty(
                list,
                i.ToString(CultureInfo.InvariantCulture),
                GetOrCreateStyleElementSheet(owners[i]));
        }

        // A stylesheet the page removed has to leave the list, not linger at the
        // index it used to occupy.
        for (var i = owners.Count; i < previousLength; i++)
        {
            _interpreter.SetObjectProperty(
                list,
                i.ToString(CultureInfo.InvariantCulture),
                JsValue.Undefined);
        }

        _interpreter.SetObjectProperty(list, "length", JsValue.FromInt32(owners.Count));
    }

    private List<Element> CollectStyleSheetOwners(Document document)
    {
        var owners = new List<Element>();
        var root = (Node)document?.DocumentElement ?? document;
        if (root == null)
        {
            return owners;
        }

        CollectStyleSheetOwners(root, owners);
        return owners;
    }

    private void CollectStyleSheetOwners(Node node, List<Element> owners)
    {
        // Tree order, which is the order the cascade applies them in and the order
        // CSSOM requires the list to be in.
        foreach (var child in node.ChildNodes)
        {
            if (child is Element element)
            {
                if (IsStyleSheetOwnerElement(element))
                {
                    owners.Add(element);
                }

                CollectStyleSheetOwners(element, owners);
            }
        }
    }

    /// <summary>
    /// Parses a style element's text with the engine's own CSS parser and returns one
    /// descriptor per rule for the CSSOM layer to wrap.
    /// </summary>
    /// <remarks>
    /// The rules have to come from the same parser the cascade uses. The previous
    /// JavaScript shim split the text on "}", which mangles @media, @supports and any
    /// brace inside a string - so what a page read back through cssRules did not match
    /// what the engine had actually applied.
    /// </remarks>
    private JsValue BuildStyleSheetRuleDescriptors(IReadOnlyList<JsValue> args)
    {
        if (args.Count == 0 || args[0].Tag != JsValueTag.HostObject)
        {
            return _interpreter.AllocateArray(Array.Empty<JsValue>());
        }

        if (ResolveHostObjectOrNull(args[0]) is not Element element ||
            !string.Equals(element.TagName, "STYLE", StringComparison.OrdinalIgnoreCase))
        {
            // A <link> sheet's text is not held by the DOM. Its rules stay empty,
            // which is also what a cross-origin sheet looks like to script.
            return _interpreter.AllocateArray(Array.Empty<JsValue>());
        }

        return ParseStyleSheetRuleDescriptors(element.TextContent);
    }

    /// <summary>
    /// Parses stylesheet text with the engine's CSS parser into CSSOM rule
    /// descriptors: a style element's text, or what a constructed sheet's
    /// replace()/replaceSync() was given.
    /// </summary>
    private JsValue ParseStyleSheetRuleDescriptors(string cssText)
    {
        if (string.IsNullOrWhiteSpace(cssText))
        {
            return _interpreter.AllocateArray(Array.Empty<JsValue>());
        }

        try
        {
            var parsed = new FenBrowser.FenEngine.Rendering.Css.CssSyntaxParser(
                new FenBrowser.FenEngine.Rendering.Css.CssTokenizer(cssText))
            {
                PreserveCssomRules = true
            }.ParseStylesheet();
            return DescribeCssRules(parsed.Rules);
        }
        catch (Exception ex)
        {
            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] cssRules parse failed: {ex.GetType().Name}: {ex.Message}",
                FenBrowser.Core.Logging.LogCategory.CSS);
            return _interpreter.AllocateArray(Array.Empty<JsValue>());
        }
    }

    /// <summary>
    /// CSSOM 6.2 adoptedStyleSheets: the prelude publishes a document's or shadow
    /// root's adopted list as [cssText, mediaText, baseURL] entries whenever the
    /// array or one of its sheets changes; the cascade reads them from the DOM.
    /// </summary>
    private JsValue SetAdoptedStyleSheets(IReadOnlyList<JsValue> args)
    {
        if (args.Count < 2)
        {
            return JsValue.Undefined;
        }

        var root = ResolveHostObjectOrNull(args[0]);
        if (root is not Document && root is not ShadowRoot)
        {
            return JsValue.Undefined;
        }

        var sheets = new List<FenBrowser.Core.Css.AdoptedStyleSheet>();
        var count = (int)CoerceToFiniteNumber(ReadJsProperty(args[1], "length"), 0);
        for (var i = 0; i < count; i++)
        {
            var entry = ReadJsProperty(args[1], i.ToString(CultureInfo.InvariantCulture));
            var baseUrl = CoerceToHostString(ReadJsProperty(entry, "2"));
            sheets.Add(new FenBrowser.Core.Css.AdoptedStyleSheet(
                CoerceToHostString(ReadJsProperty(entry, "0")),
                CoerceToHostString(ReadJsProperty(entry, "1")),
                Uri.TryCreate(baseUrl, UriKind.Absolute, out var baseUri) ? baseUri : null));
        }

        if (root is Document document)
        {
            document.SetAdoptedStyleSheets(sheets);
        }
        else
        {
            ((ShadowRoot)root).SetAdoptedStyleSheets(sheets);
        }

        return JsValue.Undefined;
    }

    private JsValue DescribeCssRules(IReadOnlyList<FenBrowser.FenEngine.Rendering.Css.CssRule> rules)
    {
        var described = new List<JsValue>(rules.Count);
        foreach (var rule in rules)
        {
            var descriptor = DescribeCssRule(rule);
            if (descriptor.Tag != JsValueTag.Undefined)
            {
                described.Add(descriptor);
            }
        }

        return _interpreter.AllocateArray(described);
    }

    /// <summary>
    /// One CSSOM rule descriptor: <c>kind</c> names the CSSOM interface the prelude
    /// wraps it in (CSSOM 6.4), plus whatever that interface reports.
    /// </summary>
    private JsValue DescribeCssRule(FenBrowser.FenEngine.Rendering.Css.CssRule rule)
    {
        Dictionary<string, JsValue> fields;
        switch (rule)
        {
            case FenBrowser.FenEngine.Rendering.Css.CssStyleRule style:
                var nested = new List<JsValue>();
                foreach (var nestedRule in style.NestedRules)
                {
                    var d = DescribeCssRule(nestedRule);
                    if (d.Tag != JsValueTag.Undefined) nested.Add(d);
                }
                if (style.NestedRules.Count > 0 && style.Declarations.Count > 0)
                {
                    // CSS Nesting 1 §3.3: declarations after nested rules become a
                    // CSSNestedDeclarations rule.
                    nested.Add(_interpreter.AllocateObject(new Dictionary<string, JsValue>
                    {
                        ["kind"] = JsValue.FromString("nested-declarations"),
                        ["declarations"] = JsValue.FromString(SerializeDeclarations(style.Declarations))
                    }));
                }
                fields = new Dictionary<string, JsValue>
                {
                    ["kind"] = JsValue.FromString("style"),
                    ["selectorText"] = JsValue.FromString(style.Selector?.NestedText ?? style.Selector?.Raw ?? string.Empty),
                    ["declarations"] = JsValue.FromString(SerializeDeclarations(style.Declarations)),
                    ["rules"] = _interpreter.AllocateArray(nested)
                };
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssMediaRule media:
                fields = DescribeGroupingRule("media", media.Rules);
                fields["conditionText"] = JsValue.FromString(media.Condition ?? string.Empty);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssSupportsRule supports:
                fields = DescribeGroupingRule("supports", supports.Rules);
                fields["conditionText"] = JsValue.FromString(supports.Condition ?? string.Empty);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssContainerRule container:
                fields = DescribeGroupingRule("container", container.Rules);
                fields["conditionText"] = JsValue.FromString(container.Condition ?? string.Empty);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssLayerRule { IsStatement: true } layerStatement:
                fields = new Dictionary<string, JsValue>
                {
                    ["kind"] = JsValue.FromString("layer-statement"),
                    ["name"] = JsValue.FromString(layerStatement.Name ?? string.Empty)
                };
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssLayerRule layer:
                fields = DescribeGroupingRule("layer-block", layer.Rules);
                fields["name"] = JsValue.FromString(layer.Name ?? string.Empty);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssScopeRule scope:
                fields = DescribeGroupingRule("scope", scope.Rules);
                fields["start"] = string.IsNullOrEmpty(scope.ScopeSelector) ? JsValue.Null : JsValue.FromString(scope.ScopeSelector);
                fields["end"] = string.IsNullOrEmpty(scope.EndSelector) ? JsValue.Null : JsValue.FromString(scope.EndSelector);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssFontFaceRule fontFace:
                fields = DescribeDeclarationRule("font-face", fontFace.Declarations);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssPropertyRule property:
                fields = DescribeDeclarationRule("property", property.Declarations);
                fields["name"] = JsValue.FromString(property.Name ?? string.Empty);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssPageRule page:
                fields = DescribeDeclarationRule("page", page.Declarations);
                fields["selectorText"] = JsValue.FromString(page.Selector ?? string.Empty);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssCounterStyleRule counterStyle:
                fields = DescribeDeclarationRule("counter-style", counterStyle.Declarations);
                fields["name"] = JsValue.FromString(counterStyle.Name ?? string.Empty);
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssImportRule import:
                fields = new Dictionary<string, JsValue>
                {
                    ["kind"] = JsValue.FromString("import"),
                    ["href"] = JsValue.FromString(import.Href ?? string.Empty),
                    ["layerName"] = import.ImportLayerName != null ? JsValue.FromString(import.ImportLayerName) : JsValue.Null,
                    ["supportsText"] = import.SupportsText != null ? JsValue.FromString(import.SupportsText) : JsValue.Null,
                    ["media"] = JsValue.FromString(import.MediaText ?? string.Empty)
                };
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssNamespaceRule ns:
                fields = new Dictionary<string, JsValue>
                {
                    ["kind"] = JsValue.FromString("namespace"),
                    ["prefix"] = JsValue.FromString(ns.Prefix ?? string.Empty),
                    ["namespaceURI"] = JsValue.FromString(ns.NamespaceUri ?? string.Empty)
                };
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssFontFeatureValuesRule featureValues:
                var blocks = new List<JsValue>(featureValues.Blocks.Count);
                foreach (var (blockName, declarations) in featureValues.Blocks)
                {
                    var entries = new List<JsValue>(declarations.Count);
                    foreach (var declaration in declarations)
                    {
                        entries.Add(_interpreter.AllocateArray(new[]
                        {
                            JsValue.FromString(declaration.Property ?? string.Empty),
                            JsValue.FromString(declaration.Value ?? string.Empty)
                        }));
                    }
                    blocks.Add(_interpreter.AllocateArray(new[] { JsValue.FromString(blockName), _interpreter.AllocateArray(entries) }));
                }
                fields = new Dictionary<string, JsValue>
                {
                    ["kind"] = JsValue.FromString("font-feature-values"),
                    ["fontFamily"] = JsValue.FromString(featureValues.FontFamily ?? string.Empty),
                    ["blocks"] = _interpreter.AllocateArray(blocks)
                };
                break;

            case FenBrowser.FenEngine.Rendering.Css.CssKeyframesRule keyframes:
                var frames = new List<JsValue>(keyframes.Keyframes.Count);
                foreach (var frame in keyframes.Keyframes)
                {
                    frames.Add(_interpreter.AllocateObject(new Dictionary<string, JsValue>
                    {
                        ["kind"] = JsValue.FromString("keyframe"),
                        ["keyText"] = JsValue.FromString(frame.KeyText ?? string.Empty),
                        ["declarations"] = JsValue.FromString(SerializeDeclarations(frame.Declarations))
                    }));
                }
                fields = new Dictionary<string, JsValue>
                {
                    ["kind"] = JsValue.FromString("keyframes"),
                    ["name"] = JsValue.FromString(keyframes.Name ?? string.Empty),
                    ["rules"] = _interpreter.AllocateArray(frames)
                };
                break;

            default:
                return JsValue.Undefined;
        }

        return _interpreter.AllocateObject(fields);
    }

    private Dictionary<string, JsValue> DescribeGroupingRule(string kind, IReadOnlyList<FenBrowser.FenEngine.Rendering.Css.CssRule> rules)
    {
        return new Dictionary<string, JsValue>
        {
            ["kind"] = JsValue.FromString(kind),
            ["rules"] = DescribeCssRules(rules)
        };
    }

    private static Dictionary<string, JsValue> DescribeDeclarationRule(
        string kind,
        IReadOnlyList<FenBrowser.FenEngine.Rendering.Css.CssDeclaration> declarations)
    {
        return new Dictionary<string, JsValue>
        {
            ["kind"] = JsValue.FromString(kind),
            ["declarations"] = JsValue.FromString(SerializeDeclarations(declarations))
        };
    }

    private static string SerializeDeclarations(
        IReadOnlyList<FenBrowser.FenEngine.Rendering.Css.CssDeclaration> declarations)
    {
        if (declarations == null || declarations.Count == 0)
        {
            return string.Empty;
        }

        var builder = new StringBuilder();
        foreach (var declaration in declarations)
        {
            if (string.IsNullOrEmpty(declaration?.Property))
            {
                continue;
            }

            if (builder.Length > 0)
            {
                builder.Append(' ');
            }

            builder.Append(declaration.Property).Append(": ").Append(declaration.Value);
            if (declaration.IsImportant)
            {
                builder.Append(" !important");
            }

            builder.Append(';');
        }

        return builder.ToString();
    }

    private static bool CssSupports(IReadOnlyList<JsValue> args)
    {
        if (args.Count == 0)
        {
            return false;
        }

        if (args.Count == 1)
        {
            return IsPlausibleCssSupportsCondition(CoerceToHostString(args[0]));
        }

        var property = CoerceToHostString(args[0]).Trim();
        var value = CoerceToHostString(args[1]).Trim();
        return IsPlausibleCssPropertyName(property) &&
               !string.IsNullOrWhiteSpace(value) &&
               !ContainsCssParseBreaker(value) &&
               HasBalancedCssGrouping(value);
    }

    private static bool IsPlausibleCssSupportsCondition(string condition)
    {
        var text = condition?.Trim();
        if (string.IsNullOrEmpty(text) || ContainsCssParseBreaker(text))
        {
            return false;
        }

        return HasBalancedCssGrouping(text);
    }

    private static bool IsPlausibleCssPropertyName(string property)
    {
        if (string.IsNullOrWhiteSpace(property))
        {
            return false;
        }

        if (property.StartsWith("--", StringComparison.Ordinal))
        {
            return property.Length > 2 && property.All(ch => char.IsLetterOrDigit(ch) || ch == '-' || ch == '_');
        }

        return property.All(ch => char.IsLetterOrDigit(ch) || ch == '-');
    }

    private static bool ContainsCssParseBreaker(string text)
        => text.IndexOf('{') >= 0 || text.IndexOf('}') >= 0 || text.IndexOf(';') >= 0;

    private static bool HasBalancedCssGrouping(string text)
    {
        var parentheses = 0;
        var brackets = 0;
        var inSingleQuote = false;
        var inDoubleQuote = false;
        var escaping = false;

        foreach (var ch in text)
        {
            if (escaping)
            {
                escaping = false;
                continue;
            }

            if (ch == '\\')
            {
                escaping = true;
                continue;
            }

            if (inSingleQuote)
            {
                if (ch == '\'')
                {
                    inSingleQuote = false;
                }

                continue;
            }

            if (inDoubleQuote)
            {
                if (ch == '"')
                {
                    inDoubleQuote = false;
                }

                continue;
            }

            switch (ch)
            {
                case '\'':
                    inSingleQuote = true;
                    break;
                case '"':
                    inDoubleQuote = true;
                    break;
                case '(':
                    parentheses++;
                    break;
                case ')':
                    if (--parentheses < 0)
                    {
                        return false;
                    }

                    break;
                case '[':
                    brackets++;
                    break;
                case ']':
                    if (--brackets < 0)
                    {
                        return false;
                    }

                    break;
            }
        }

        return parentheses == 0 && brackets == 0 && !inSingleQuote && !inDoubleQuote && !escaping;
    }

    private static string CssEscape(string value)
    {
        if (string.IsNullOrEmpty(value))
        {
            return string.Empty;
        }

        var sb = new StringBuilder(value.Length);
        for (var i = 0; i < value.Length; i++)
        {
            var ch = value[i];
            if (ch == '\0')
            {
                sb.Append('\uFFFD');
                continue;
            }

            if ((i == 0 && char.IsDigit(ch)) ||
                (i == 1 && value[0] == '-' && char.IsDigit(ch)))
            {
                sb.Append('\\');
                sb.Append(((int)ch).ToString("x", CultureInfo.InvariantCulture));
                sb.Append(' ');
                continue;
            }

            if (i == 0 && ch == '-' && value.Length == 1)
            {
                sb.Append("\\-");
                continue;
            }

            if (ch >= 0x80 || ch == '-' || ch == '_' || char.IsLetterOrDigit(ch))
            {
                sb.Append(ch);
                continue;
            }

            sb.Append('\\');
            sb.Append(ch);
        }

        return sb.ToString();
    }

    private NodeFilter CreateTreeWalkerFilter(JsValue filterValue)
    {
        if (filterValue.Tag == JsValueTag.Undefined || filterValue.Tag == JsValueTag.Null)
        {
            return null;
        }

        if (_interpreter.CanCallValue(filterValue))
        {
            return node => ToNodeFilterResult(
                _interpreter.InvokeFunction(filterValue, new[] { ToHostNodeOrNull(node) }, JsValue.Undefined));
        }

        if (filterValue.Tag != JsValueTag.Object && filterValue.Tag != JsValueTag.HostObject)
        {
            ThrowDomException("TypeError", "Failed to convert value to 'NodeFilter': not an object or function.");
        }

        // WebIDL 3.12 "call a user object's operation": a callback interface
        // object has acceptNode looked up with [[Get]] on every call, and a
        // missing or non-callable acceptNode is a TypeError raised at that call,
        // not when the traverser is created.
        return node =>
        {
            var callback = ReadJsProperty(filterValue, "acceptNode");
            if (!_interpreter.CanCallValue(callback))
            {
                ThrowDomException("TypeError", "NodeFilter.acceptNode is not a function.");
            }

            return ToNodeFilterResult(
                _interpreter.InvokeFunction(callback, new[] { ToHostNodeOrNull(node) }, filterValue));
        };
    }

    // DOM 6.1 "filter" step 5 converts the callback's return value to
    // unsigned short and the traversal algorithms compare it against
    // FILTER_ACCEPT / FILTER_REJECT / FILTER_SKIP individually, so a value
    // that is none of them (false, 0, 7) has to reach them unchanged: it is
    // not an accept, it does not stop a descent the way REJECT does, and it
    // does not descend the way SKIP does in "traverse children".
    private static NodeFilterResult ToNodeFilterResult(JsValue value)
    {
        var numeric = value.Tag switch
        {
            JsValueTag.Int32 => value.AsInt32(),
            JsValueTag.Number => double.IsFinite(value.AsNumber()) ? (int)value.AsNumber() : 0,
            JsValueTag.Boolean => value.AsBoolean() ? 1 : 0,
            JsValueTag.String when double.TryParse(value.AsString(), NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed) && double.IsFinite(parsed) => (int)parsed,
            JsValueTag.Undefined or JsValueTag.Null => 0,
            _ => 0
        };

        return (NodeFilterResult)(ushort)(numeric & 0xFFFF);
    }

