    private sealed class BrowserFenJsHostHooks : IHostHooks
    {
        private const int FunctionPrototypePropertyLimit = 2048;
        private const int FunctionPrototypePropertyLengthLimit = 256;
        private readonly HashSet<string> _functionPrototypeProperties = new(StringComparer.Ordinal);
        private FenJsBrowserScriptEngine _owner;
        private Document _document;
        internal Document CurrentDocument => _document;
        private BrowserSurfaceProfile _navigator;
        private FenJsLocationHost _location;
        private Uri _baseUri;

        public void Reset()
        {
            _functionPrototypeProperties.Clear();
            _owner = null;
            _document = null;
            _navigator = null;
            _location = null;
            _baseUri = null;
        }

        public void Bind(
            FenJsBrowserScriptEngine owner,
            Document document,
            BrowserSurfaceProfile navigator,
            FenJsLocationHost location,
            Uri baseUri)
        {
            _functionPrototypeProperties.Clear();
            _owner = owner;
            _document = document;
            _navigator = navigator;
            _location = location;
            _baseUri = baseUri;
        }

        public void EnqueuePromiseJob(PromiseJob job)
        {
            _owner?._interpreter.EnqueueHostedPromiseJob(job);
        }

        public void ReportPromiseRejection(JsValue promise, PromiseRejectionOperation operation)
        {
            if (operation != PromiseRejectionOperation.Reject || _owner == null)
            {
                return;
            }

            var reason = "<unknown>";
            try
            {
                if (promise.Tag == JsValueTag.Object &&
                    _owner._interpreter.Heap.GetObject(promise.AsObjectHandle()) is PromiseInstance promiseInstance)
                {
                    reason = _owner.DescribePromiseRejectionReason(promiseInstance.Promise.GetResultUnchecked());
                }
            }
            catch
            {
                reason = "<unavailable>";
            }

            FenBrowser.Core.EngineLogCompat.Warn(
                $"[FenJsBridge] Unhandled promise rejection: {reason}",
                FenBrowser.Core.Logging.LogCategory.JavaScript);
        }

        public void ObserveFunctionPrototypePropertyDefinition(string property, JsValue value)
        {
            if (value.Tag != JsValueTag.Boolean ||
                !value.AsBoolean() ||
                string.IsNullOrEmpty(property) ||
                property.Length > FunctionPrototypePropertyLengthLimit ||
                _functionPrototypeProperties.Count >= FunctionPrototypePropertyLimit)
            {
                return;
            }

            _functionPrototypeProperties.Add(property);
        }

        public bool TryGetHostProperty(HostObjectHandle handle, string property, out JsValue value)
            => TryGetHostProperty(handle, property, HostPropertyAccessKind.Read, out value);

        /// <summary>
        /// WebIDL 3.9 [[OwnPropertyKeys]] for the collection-shaped host objects:
        /// the indices, then the supported property names (an element's id and
        /// name, each once, in tree order - DOM 4.2.10.2), so Object.keys and
        /// for-in see what bracket access can reach.
        /// </summary>
        public bool TryGetHostOwnKeys(HostObjectHandle handle, out IReadOnlyList<string> keys)
        {
            keys = Array.Empty<string>();
            if (_owner == null || _owner._interpreter == null)
            {
                return false;
            }

            var resolution = _owner._interpreter.HostObjectTable.Resolve(handle, _owner._interpreter.HostResolveContext);
            if (!resolution.IsOk)
            {
                return false;
            }

            switch (resolution.HostObject)
            {
                case FenJsHtmlCollectionHost collectionHost:
                {
                    var list = new List<string>();
                    var names = new HashSet<string>(StringComparer.Ordinal);
                    var index = 0;
                    var namedCandidates = new List<string>();
                    foreach (var element in collectionHost.Collection)
                    {
                        list.Add(index.ToString(CultureInfo.InvariantCulture));
                        index++;
                        var id = element.Id;
                        if (!string.IsNullOrEmpty(id) && names.Add(id)) namedCandidates.Add(id);
                        var name = element.GetAttribute("name");
                        if (!string.IsNullOrEmpty(name) && names.Add(name)) namedCandidates.Add(name);
                    }

                    list.AddRange(namedCandidates);
                    keys = list;
                    return true;
                }
                case NodeList nodeList:
                {
                    var list = new List<string>(nodeList.Length);
                    for (var i = 0; i < nodeList.Length; i++)
                    {
                        list.Add(i.ToString(CultureInfo.InvariantCulture));
                    }

                    keys = list;
                    return true;
                }
                case DOMTokenList tokenList:
                {
                    var list = new List<string>();
                    for (var i = 0; i < tokenList.Length; i++)
                    {
                        list.Add(i.ToString(CultureInfo.InvariantCulture));
                    }

                    keys = list;
                    return true;
                }
                default:
                    return false;
            }
        }

        public bool TryGetHostProperty(
            HostObjectHandle handle,
            string property,
            HostPropertyAccessKind accessKind,
            out JsValue value)
        {
            if (_owner == null || _owner._interpreter == null)
            {
                value = JsValue.Undefined;
                return false;
            }
            var resolution = _owner._interpreter.HostObjectTable.Resolve(handle, _owner._interpreter.HostResolveContext);
            if (!resolution.IsOk)
            {
                value = JsValue.Undefined;
                return false;
            }

            var hostObject = resolution.HostObject;

            // HTML §3.2.6.1 DOMStringMap: the map's own properties are exactly the
            // element's data-* attributes. A read of an absent key is undefined, but
            // `"cthref" in el.dataset` must be false - google.com's document click
            // handler navigates to data-cthref whenever that test passes, and answering
            // true for every key sent it to /null.
            if (hostObject is FenJsDomStringMapHost datasetHost && accessKind != HostPropertyAccessKind.Read)
            {
                var exists = datasetHost.Element.HasAttribute(PropertyNameToDatasetAttribute(property));
                value = exists ? JsValue.FromString(datasetHost.Element.GetAttribute(PropertyNameToDatasetAttribute(property)) ?? string.Empty) : JsValue.Undefined;
                return exists;
            }

            // CSSOM View 4: reading one of these resolves layout. Asking whether the
            // member exists must not - `'clientWidth' in el` is a feature test, and
            // making it flush the whole document is both wrong and expensive. They
            // are answered by name for anything that is an element.
            if (accessKind != HostPropertyAccessKind.Read &&
                hostObject is Element &&
                IsLayoutResolvingElementMember(property))
            {
                value = JsValue.Undefined;
                return true;
            }

            var found = TryGetHostObjectDefinedProperty(hostObject, property, out value);

            if (!found)
            {
                // Naming the interface means a catalog lookup, and it is only
                // wanted to report a property we could not find. Every DOM read
                // and every DOM method call was paying for it on the way past.
                RecordMissingHostApi(
                    hostObject, GetHostApiOwnerName(hostObject), property, ToMissingApiOperationKind(accessKind));
            }

            return found;
        }

        /// <summary>
        /// Element members whose value cannot be produced without resolving layout.
        /// </summary>
        private static bool IsLayoutResolvingElementMember(string property) => property switch
        {
            "clientWidth" or "clientHeight" or "clientTop" or "clientLeft" or
            "scrollWidth" or "scrollHeight" or "scrollTop" or "scrollLeft" or
            "offsetWidth" or "offsetHeight" or "offsetTop" or "offsetLeft" or
            "offsetParent" => true,
            _ => false
        };

        public void ObserveMissingHostPropertyOperation(
            HostObjectHandle handle,
            string property,
            HostPropertyAccessKind accessKind)
        {
            if (_owner == null || _owner._interpreter == null)
            {
                return;
            }

            var resolution = _owner._interpreter.HostObjectTable.Resolve(
                handle,
                _owner._interpreter.HostResolveContext);
            if (!resolution.IsOk || resolution.HostObject == null)
            {
                return;
            }

            var hostObject = resolution.HostObject;
            RecordMissingHostApi(
                hostObject,
                GetHostApiOwnerName(hostObject),
                property,
                ToMissingApiOperationKind(accessKind));
        }

        private bool TryGetHostObjectDefinedProperty(object hostObject, string property, out JsValue value)
        {
            bool found;
            switch (hostObject)
            {
                case Document document:
                    found = TryGetDocumentProperty(document, property, out value) ||
                            TryGetNodeProperty(document, property, out value);
                    break;
                case Element element:
                    found = TryGetElementProperty(element, property, out value) ||
                            TryGetNodeProperty(element, property, out value);
                    break;
                case FenJsDomImplementationHost implementation:
                    found = TryGetDomImplementationProperty(implementation, property, out value);
                    break;
                case Attr attr:
                    found = TryGetAttrProperty(attr, property, out value);
                    break;
                case NamedNodeMap namedNodeMap:
                    found = TryGetNamedNodeMapProperty(namedNodeMap, property, out value);
                    break;
                case DOMTokenList tokenList:
                    found = TryGetDomTokenListProperty(tokenList, property, out value);
                    break;
                case CharacterData characterData:
                    found = TryGetCharacterDataProperty(characterData, property, out value) ||
                            TryGetNodeProperty(characterData, property, out value);
                    break;
                case DocumentFragment fragment:
                    found = TryGetDocumentFragmentProperty(fragment, property, out value) ||
                            TryGetNodeProperty(fragment, property, out value);
                    break;
                case Node node:
                    found = TryGetNodeProperty(node, property, out value);
                    break;
                case DomRange range:
                    found = TryGetRangeProperty(range, property, out value);
                    break;
                case FenJsHtmlCollectionHost htmlCollection:
                    found = TryGetHtmlCollectionProperty(htmlCollection, property, out value);
                    break;
                case NodeList nodeList:
                    found = TryGetNodeListProperty(nodeList, property, out value);
                    break;
                case FenJsTreeWalkerHost treeWalker:
                    found = TryGetTreeWalkerProperty(treeWalker, property, out value);
                    break;
                case FenJsNodeIteratorHost nodeIterator:
                    found = TryGetNodeIteratorProperty(nodeIterator, property, out value);
                    break;
                case FenJsAnimationHost animation:
                    found = TryGetAnimationProperty(animation, property, out value);
                    break;
                case FenJsDomStringMapHost domStringMap:
                    found = TryGetDomStringMapProperty(domStringMap, property, out value);
                    break;
                case FenStorageAreaHost storageArea:
                    found = TryGetStorageProperty(storageArea, property, out value);
                    break;
                case FenJsCanvasRenderingContext2DHost canvasContext:
                    found = TryGetCanvasContextProperty(canvasContext, property, out value);
                    break;
                case FenJsCanvasGradientHost canvasGradient:
                    found = TryGetCanvasGradientProperty(canvasGradient, property, out value);
                    break;
                case FenJsTextMetricsHost textMetrics:
                    found = TryGetTextMetricsProperty(textMetrics, property, out value);
                    break;
                case FenJsImageDataHost imageData:
                    found = TryGetImageDataProperty(imageData, property, out value);
                    break;
                case BrowserSurfaceProfile navigator:
                    if (TryGetNavigatorProperty(navigator, property, out value))
                    {
                        return true;
                    }
                    // Fall back to user-assigned properties stored via TrySetHostProperty
                    // (e.g. Google stubs navigator.sendBeacon).
                    value = _owner.GetStoredHostPropertyOrUndefined(navigator, property);
                    found = value.Tag != JsValueTag.Undefined;
                    break;
                case FenJsLocationHost location:
                    found = TryGetLocationProperty(location, property, out value);
                    break;
                case FenJsHistoryHost history:
                    found = TryGetHistoryProperty(history, property, out value);
                    break;
                case FenJsMutationObserverHost mutationObserver:
                    found = _owner.TryGetMutationObserverProperty(mutationObserver, property, out value);
                    break;
                default:
                    value = JsValue.Undefined;
                    found = false;
                    break;
            }

            return found;
        }

        private static string GetHostApiOwnerName(object hostObject)
        {
            return hostObject switch
            {
                Document => "Document",
                Element element => HtmlElementInterfaceCatalog.ResolveInterfaceName(
                    element.LocalName,
                    element.NamespaceUri) ?? "Element",
                FenJsDomImplementationHost => "DOMImplementation",
                Attr => "Attr",
                NamedNodeMap => "NamedNodeMap",
                DOMTokenList => "DOMTokenList",
                CharacterData => "CharacterData",
                ShadowRoot => "ShadowRoot",
                DocumentFragment => "DocumentFragment",
                DomRange => "Range",
                FenJsHtmlCollectionHost => "HTMLCollection",
                NodeList => "NodeList",
                FenJsTreeWalkerHost => "TreeWalker",
                FenJsNodeIteratorHost => "NodeIterator",
                FenJsAnimationHost => "Animation",
                FenJsDomStringMapHost => "DOMStringMap",
                BrowserSurfaceProfile => "Navigator",
                FenJsLocationHost => "Location",
                FenJsHistoryHost => "History",
                FenJsMutationObserverHost => "MutationObserver",
                _ => hostObject?.GetType().Name ?? "HostObject"
            };
        }

        private void RecordMissingHostApi(
            object receiver,
            string ownerName,
            string property,
            MissingApiOperationKind operationKind = MissingApiOperationKind.Read)
        {
            // The engine asking its own surface what it implements is not a site
            // hitting a gap. Without this the bootstrap's interface probe files a
            // report for every member it declines to publish, and missing_apis.json
            // - which exists to say what a page actually needed - fills up with the
            // engine talking to itself.
            if (_owner != null && _owner._probingHostInterfaceMembers)
            {
                return;
            }

            if (!ShouldRecordMissingHostApi(ownerName, property))
            {
                return;
            }

            _owner?.RecordMissingHostProperty(
                receiver,
                ownerName,
                property,
                _baseUri,
                _functionPrototypeProperties.Contains(property),
                operationKind);
        }

        private static MissingApiOperationKind ToMissingApiOperationKind(HostPropertyAccessKind accessKind)
            => accessKind switch
            {
                HostPropertyAccessKind.InCheck => MissingApiOperationKind.InCheck,
                HostPropertyAccessKind.DescriptorOperation => MissingApiOperationKind.DescriptorOperation,
                HostPropertyAccessKind.PrototypeAccess => MissingApiOperationKind.PrototypeAccess,
                _ => MissingApiOperationKind.Read
            };

        private void RecordAssignedHostApi(object receiver, string ownerName, string property)
        {
            if (!ShouldRecordMissingHostApi(ownerName, property))
            {
                return;
            }

            _owner?.RecordHostPropertyAssignment(receiver, ownerName, property, _baseUri);
        }

        private static bool ShouldRecordMissingHostApi(string ownerName, string property)
        {
            if (string.IsNullOrWhiteSpace(ownerName) || string.IsNullOrWhiteSpace(property))
            {
                return false;
            }

            if (property == "then" ||
                property == "constructor" ||
                property == "prototype" ||
                property == "__proto__" ||
                property.StartsWith("__", StringComparison.Ordinal) ||
                property.StartsWith("_", StringComparison.Ordinal) ||
                property.StartsWith("on", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            return !property.All(char.IsDigit);
        }

        public bool TrySetHostProperty(HostObjectHandle handle, string property, JsValue value)
        {
            // A setter that fails per spec (table.tHead = <div>, a cyclic
            // insertion) throws a DomException from the DOM layer; it has to
            // reach script as a DOMException like a method call's would, not
            // escape the interpreter as a CLR exception.
            try
            {
                return TrySetHostPropertyCore(handle, property, value);
            }
            catch (DomException domException)
            {
                _owner.ThrowDomException(
                    domException.Name,
                    string.IsNullOrEmpty(domException.Message)
                        ? $"Failed to set the '{property}' property."
                        : domException.Message);
                return false;
            }
        }

        private bool TrySetHostPropertyCore(HostObjectHandle handle, string property, JsValue value)
        {
            if (_owner == null || _owner._interpreter == null)
            {
                return false;
            }
            var resolution = _owner._interpreter.HostObjectTable.Resolve(handle, _owner._interpreter.HostResolveContext);
            if (!resolution.IsOk)
            {
                return false;
            }

            switch (resolution.HostObject)
            {
                case Document document when string.Equals(property, "fonts", StringComparison.Ordinal):
                    // Allow Google Font Loading API: document.fonts = { ... }.
                    _owner.SetStoredHostProperty(document, "fonts", value);
                    return true;
                case Document document when string.Equals(property, "title", StringComparison.Ordinal):
                    document.Title = CoerceToHostString(value);
                    return true;
                case Document document when string.Equals(property, "cookie", StringComparison.Ordinal):
                    var cookieStr = CoerceToHostString(value);
                    document.Cookie = cookieStr;
                    // Persist cookies through the host bridge so they survive
                    // navigations (critical for WAF challenge tokens).
                    if (_owner.CookieWriteBridge != null && _owner._currentBaseUri != null)
                    {
                        _owner.CookieWriteBridge(_owner._currentBaseUri, cookieStr);
                        if (cookieStr.StartsWith("SG_SS=", StringComparison.Ordinal))
                        {
                            var captureId = -Interlocked.Increment(ref _owner._diagnosticCookieCaptureCounter);
                            _owner.CaptureNavigationGlobals(_owner._currentBaseUri, captureId);
                        }
                    }
                    return true;
                case Document document when string.Equals(property, "domain", StringComparison.Ordinal):
                    _owner.SetStoredHostProperty(document, "domain", JsValue.FromString(CoerceToHostString(value)));
                    return true;
                case Document document:
                    // Catch-all for arbitrary document properties (e.g. Google
                    // sets __gwbp, __jsl, and other internal bookkeeping).
                    RecordAssignedHostApi(document, "Document", property);
                    _owner.SetStoredHostProperty(document, property, value);
                    return true;
                case Element element when IsMediaElement(element) && _owner.TrySetMediaElementProperty(element, property, value):
                    return true;
                case Element element when IsTrackElement(element) && _owner.TrySetTrackElementProperty(element, property, value):
                    return true;
                case Element element when string.Equals(property, "className", StringComparison.Ordinal):
                    element.ClassName = CoerceToHostString(value);
                    return true;
                case Element element when string.Equals(property, "id", StringComparison.Ordinal):
                    element.Id = CoerceToHostString(value);
                    return true;
                case Element element when
                    string.Equals(property, "value", StringComparison.Ordinal) &&
                    IsSelectElement(element):
                    FenBrowser.FenEngine.Rendering.SelectSelection.SetValue(
                        element, CoerceToHostString(value));
                    return true;
                case Element element when string.Equals(property, "value", StringComparison.Ordinal):
                    FenBrowser.FenEngine.Rendering.FormControlValue.Write(element, CoerceToHostString(value));
                    return true;
                case Element element when
                    string.Equals(property, "defaultValue", StringComparison.Ordinal) &&
                    IsValueDefaultingElement(element):
                    FenBrowser.FenEngine.Rendering.FormControlValue.WriteDefault(
                        element, CoerceToHostString(value));
                    return true;
                case Element element when
                    string.Equals(property, "defaultChecked", StringComparison.Ordinal) &&
                    IsCheckableInputElement(element):
                    // defaultChecked reflects the "checked" content attribute --
                    // the default, not the live checkedness.
                    if (CoerceToHostBoolean(value))
                    {
                        element.SetAttribute("checked", string.Empty);
                    }
                    else
                    {
                        element.RemoveAttribute("checked");
                    }
                    return true;
                case Element element when
                    string.Equals(property, "type", StringComparison.Ordinal) &&
                    string.Equals(element.TagName, "input", StringComparison.OrdinalIgnoreCase):
                    element.SetAttribute("type", CoerceToHostString(value));
                    return true;
                case Element element when
                    string.Equals(property, "checked", StringComparison.Ordinal) &&
                    IsCheckableInputElement(element):
                    ElementStateManager.Instance.SetChecked(element, CoerceToHostBoolean(value));
                    return true;
                case Element element when string.Equals(property, "tabIndex", StringComparison.Ordinal):
                    element.SetAttribute(
                        "tabindex",
                        ((int)CoerceToFiniteNumber(value, 0)).ToString(CultureInfo.InvariantCulture));
                    return true;
                case Element element when string.Equals(property, "title", StringComparison.Ordinal):
                    element.SetAttribute("title", CoerceToHostString(value));
                    return true;
                case Element element when string.Equals(property, "contentEditable", StringComparison.Ordinal):
                    // HTML §6.8.1 contentEditable setter: "inherit" removes the attribute,
                    // the three states set it, anything else is a SyntaxError.
                    switch (CoerceToHostString(value).ToLowerInvariant())
                    {
                        case "inherit":
                            element.RemoveAttribute("contenteditable");
                            break;
                        case var state and ("true" or "false" or "plaintext-only"):
                            element.SetAttribute("contenteditable", state);
                            break;
                        default:
                            _owner.ThrowDomException("SyntaxError",
                                "Failed to set the 'contentEditable' property on 'HTMLElement': The value provided is not one of 'true', 'false', 'plaintext-only', or 'inherit'.");
                            break;
                    }
                    return true;
                case Element element when string.Equals(property, "draggable", StringComparison.Ordinal):
                    element.SetAttribute("draggable", CoerceToHostBoolean(value) ? "true" : "false");
                    return true;
                case Element element when string.Equals(property, "name", StringComparison.Ordinal):
                    element.SetAttribute("name", CoerceToHostString(value));
                    return true;
                case Element element when
                    IsCanvasElement(element) &&
                    (string.Equals(property, "width", StringComparison.Ordinal) ||
                     string.Equals(property, "height", StringComparison.Ordinal)):
                    element.SetAttribute(property, CoerceToHostString(value));
                    _owner.ResizeCanvasContext(element);
                    return true;
                case Element element when string.Equals(property, "content", StringComparison.Ordinal):
                    element.SetAttribute("content", CoerceToHostString(value));
                    return true;
                case Element element when string.Equals(property, "src", StringComparison.Ordinal):
                    element.SetAttribute("src", CoerceToHostString(value));
                    if (IsIFrameElement(element))
                    {
                        if (DiagnosticPaths.IframeDiagnosticsEnabled)
                        {
                            var newSrc = CoerceToHostString(value);
                            var isChallenge = newSrc.Contains("challenge", StringComparison.OrdinalIgnoreCase) ||
                                             element.GetAttribute("class")?.Contains("challenge", StringComparison.OrdinalIgnoreCase) == true ||
                                             element.GetAttribute("id")?.Contains("challenge", StringComparison.OrdinalIgnoreCase) == true;
                            DiagnosticPaths.AppendLogText(
                                "iframe_diagnostics.txt",
                                $"{DateTimeOffset.UtcNow:O} SetAttribute(src) on iframe: newSrc='{newSrc}' isChallenge={isChallenge} connected={element.IsConnected} element={element.TagName} id='{element.GetAttribute("id") ?? ""}' class='{element.GetAttribute("class") ?? ""}'");
                        }
                        _owner.QueueFrameElementLoad(element);
                    }
                    return true;
                case Element element when string.Equals(property, "href", StringComparison.Ordinal):
                    element.SetAttribute("href", CoerceToHostString(value));
                    return true;
                case Element element when string.Equals(property, "nonce", StringComparison.Ordinal):
                    element.SetAttribute("nonce", CoerceToHostString(value));
                    return true;
                case Element element when IsIFrameElement(element) &&
                    string.Equals(property, "sandbox", StringComparison.Ordinal):
                    element.SetAttribute("sandbox", CoerceToHostString(value));
                    return true;
                case Element element when IsIFrameElement(element) &&
                    string.Equals(property, "scrolling", StringComparison.Ordinal):
                    element.SetAttribute("scrolling", CoerceToHostString(value));
                    return true;
                case Element element when IsMetaElement(element) &&
                    string.Equals(property, "httpEquiv", StringComparison.Ordinal):
                    element.SetAttribute("http-equiv", CoerceToHostString(value));
                    return true;
                case Element element when IsScriptElement(element) &&
                    string.Equals(property, "async", StringComparison.Ordinal):
                    SetBooleanAttribute(element, "async", CoerceToHostBoolean(value));
                    return true;
                case Element element when IsScriptElement(element) &&
                    (string.Equals(property, "type", StringComparison.Ordinal) ||
                     string.Equals(property, "charset", StringComparison.Ordinal) ||
                     string.Equals(property, "integrity", StringComparison.Ordinal)):
                    element.SetAttribute(property, CoerceToHostString(value));
                    return true;
                case Element element when IsScriptElement(element) &&
                    string.Equals(property, "crossOrigin", StringComparison.Ordinal):
                    if (value.Tag == JsValueTag.Null)
                    {
                        element.RemoveAttribute("crossorigin");
                    }
                    else
                    {
                        element.SetAttribute("crossorigin", CoerceToHostString(value));
                    }
                    return true;
                case Element element when property.StartsWith("on", StringComparison.OrdinalIgnoreCase):
                    _owner.SetStoredHostProperty(element, property.ToLowerInvariant(), value);
                    return true;
                case Element element when string.Equals(property, "innerHTML", StringComparison.Ordinal):
                    element.InnerHTML = CoerceToHostString(value);
                    if (_owner.ExecuteInlineScriptsOnInnerHTML)
                    {
                        _owner.ExecuteInlineScriptsFromElement(element);
                    }
                    _owner.UpgradeCustomElementTreeIfDefined(_owner.ToHostNodeOrNull(element));
                    return true;
                case Element element when string.Equals(property, "textContent", StringComparison.Ordinal):
                    element.TextContent = CoerceToHostString(value);
                    return true;
                case Element element when string.Equals(property, "innerText", StringComparison.Ordinal):
                    WriteInnerText(element, CoerceToHostString(value));
                    return true;
                case Element element when
                    (string.Equals(property, "width", StringComparison.Ordinal) ||
                     string.Equals(property, "height", StringComparison.Ordinal)) &&
                    IsImageElement(element):
                    element.SetAttribute(property, Math.Max(0, (int)CoerceToFiniteNumber(value, 0)).ToString(CultureInfo.InvariantCulture));
                    return true;
                case Element element when TryMapAriaReflection(property, out var ariaAttribute):
                    if (value.Tag is JsValueTag.Null or JsValueTag.Undefined)
                    {
                        element.RemoveAttribute(ariaAttribute);
                    }
                    else
                    {
                        element.SetAttribute(ariaAttribute, CoerceToHostString(value));
                    }
                    return true;
                case Element element when
                    string.Equals(property, "text", StringComparison.Ordinal) &&
                    IsScriptElement(element):
                    // HTML dom-script-text is defined as a child-text-content
                    // setter, so it replaces the script's children.
                    element.TextContent = CoerceToHostString(value);
                    return true;
                case Element element when
                    string.Equals(property, "defaultValue", StringComparison.Ordinal) &&
                    IsTextAreaElement(element):
                    element.TextContent = CoerceToHostString(value);
                    return true;
                case Element element when
                    string.Equals(property, "type", StringComparison.Ordinal) &&
                    IsStyleElement(element):
                    element.SetAttribute("type", CoerceToHostString(value));
                    return true;
                case Element element when
                    string.Equals(property, "disabled", StringComparison.Ordinal) &&
                    IsFieldSetElement(element):
                    SetBooleanAttribute(element, "disabled", CoerceToHostBoolean(value));
                    return true;
                case Element element when
                    string.Equals(property, "selected", StringComparison.Ordinal) &&
                    IsOptionElement(element):
                    // Selectedness is live state; the "selected" content attribute
                    // is defaultSelected and stays where the markup put it. Going
                    // through the state machine also applies the single-selection
                    // rule to the option's siblings.
                    FenBrowser.FenEngine.Rendering.SelectSelection.SetSelected(
                        element, CoerceToHostBoolean(value));
                    return true;
                case Element element when
                    string.Equals(property, "defaultSelected", StringComparison.Ordinal) &&
                    IsOptionElement(element):
                    SetBooleanAttribute(element, "selected", CoerceToHostBoolean(value));
                    return true;
                case Element element when
                    string.Equals(property, "selectedIndex", StringComparison.Ordinal) &&
                    IsSelectElement(element):
                    FenBrowser.FenEngine.Rendering.SelectSelection.SetSelectedIndex(
                        element, (int)CoerceToFiniteNumber(value, -1));
                    return true;
                case Element element when
                    string.Equals(property, "hash", StringComparison.Ordinal) &&
                    IsHyperlinkElement(element):
                    // HTML 4.6.3 dom-hyperlink-hash setter: replace the fragment
                    // on the existing href, dropping a leading "#" from the input.
                    var newFragment = CoerceToHostString(value);
                    if (newFragment.StartsWith("#", StringComparison.Ordinal))
                    {
                        newFragment = newFragment.Substring(1);
                    }

                    var currentHref = element.GetAttribute("href") ?? string.Empty;
                    var existingHash = currentHref.IndexOf('#');
                    if (existingHash >= 0)
                    {
                        currentHref = currentHref.Substring(0, existingHash);
                    }

                    element.SetAttribute(
                        "href",
                        newFragment.Length == 0 ? currentHref : currentHref + "#" + newFragment);
                    return true;
                case Element element when string.Equals(property, "onload", StringComparison.Ordinal):
                    _owner.SetStoredHostProperty(element, "onload", value);
                    return true;
                case Element element when string.Equals(property, "onerror", StringComparison.Ordinal):
                    _owner.SetStoredHostProperty(element, "onerror", value);
                    return true;
                case Element element when IsIFrameElement(element) &&
                    (string.Equals(property, "width", StringComparison.Ordinal) ||
                     string.Equals(property, "height", StringComparison.Ordinal)):
                    element.SetAttribute(property, CoerceToHostString(value));
                    _owner.NotifyResizeObservers(element);
                    return true;
                case Element element when HtmlTableDom.IsTable(element) &&
                                          (property == "caption" || property == "tHead" || property == "tFoot"):
                    // HTML dom-table-caption/thead/tfoot setters: null removes,
                    // an element of the wrong kind is a HierarchyRequestError.
                    {
                        var replacement = value.Tag == JsValueTag.Null || value.Tag == JsValueTag.Undefined
                            ? null
                            : _owner.ResolveHostObjectOrNull<Element>(value);
                        // WebIDL: the attribute types are HTMLTableCaptionElement and
                        // HTMLTableSectionElement, so anything else fails conversion
                        // with a TypeError; a section of the wrong kind (a tbody for
                        // tHead) converts fine and is the HierarchyRequestError the
                        // setter algorithm throws.
                        var acceptable = replacement != null &&
                            string.Equals(replacement.NamespaceUri, Namespaces.Html, StringComparison.Ordinal) &&
                            (property == "caption"
                                ? string.Equals(replacement.LocalName, "caption", StringComparison.OrdinalIgnoreCase)
                                : HtmlTableDom.IsSection(replacement));
                        if (!acceptable && value.Tag != JsValueTag.Null && value.Tag != JsValueTag.Undefined)
                        {
                            _owner.ThrowDomException("TypeError", $"Failed to set the '{property}' property on 'HTMLTableElement'.");
                        }

                        switch (property)
                        {
                            case "caption": HtmlTableDom.SetCaption(element, replacement); break;
                            case "tHead": HtmlTableDom.SetTHead(element, replacement); break;
                            default: HtmlTableDom.SetTFoot(element, replacement); break;
                        }

                        return true;
                    }
                case Element element when HtmlAttributeReflection.TryGetEntry(element, property, out var reflected):
                    // HTML §2.6.1: the setter of a reflected IDL attribute sets the
                    // content attribute, so `input.disabled = true` is observable to
                    // selectors (:disabled) and to getAttribute like any other attribute.
                    HtmlAttributeReflection.Write(
                        element, reflected, value, CoerceToHostString, CoerceToHostBoolean, v => CoerceToFiniteNumber(v, 0));
                    return true;
                case Element element:
                    // Catch-all for arbitrary element properties (e.g. Google sets
                    // __gwbp, __jsl, and other internal bookkeeping properties on
                    // DOM elements). Store for later retrieval via TryGetElementProperty.
                    RecordAssignedHostApi(element, GetHostApiOwnerName(element), property);
                    _owner.SetStoredHostProperty(element, property, value);
                    return true;
                case Attr attr when string.Equals(property, "value", StringComparison.Ordinal):
                    attr.Value = CoerceToHostString(value);
                    return true;
                case Attr attr when string.Equals(property, "nodeValue", StringComparison.Ordinal):
                    attr.Value = CoerceToHostString(value);
                    return true;
                case Attr attr when string.Equals(property, "textContent", StringComparison.Ordinal):
                    attr.Value = CoerceToHostString(value);
                    return true;
                case CharacterData characterData when string.Equals(property, "data", StringComparison.Ordinal):
                    characterData.Data = CoerceToHostString(value);
                    return true;
                case CharacterData characterData when string.Equals(property, "nodeValue", StringComparison.Ordinal):
                    characterData.NodeValue = CoerceToHostString(value);
                    return true;
                case CharacterData characterData when string.Equals(property, "textContent", StringComparison.Ordinal):
                    characterData.TextContent = CoerceToHostString(value);
                    return true;
                // DOM 4.4: the textContent setter is "string replace all" for
                // DocumentFragment exactly as it is for Element. The read side
                // already exposed it (TryGetDocumentFragmentProperty), so without
                // this case the write fell through to `default: return false` and
                // the interpreter raised "refused by embedder" - a TypeError on a
                // perfectly ordinary assignment. ContainerNode.TextContent
                // implements the replace-all, and ShadowRoot inherits this path.
                case DocumentFragment documentFragment when
                    string.Equals(property, "textContent", StringComparison.Ordinal):
                    documentFragment.TextContent = CoerceToHostString(value);
                    return true;
                case ShadowRoot shadowRoot when string.Equals(property, "innerHTML", StringComparison.Ordinal):
                    shadowRoot.InnerHTML = CoerceToHostString(value);
                    _owner.UpgradeCustomElementTreeIfDefined(_owner.ToHostNodeOrNull(shadowRoot));
                    return true;
                case FenJsDomStringMapHost domStringMap:
                    domStringMap.Element.SetAttribute(PropertyNameToDatasetAttribute(property), CoerceToHostString(value));
                    return true;
                case FenStorageAreaHost storageArea:
                    // Per spec, storage[key] = value is equivalent to storage.setItem(key, value).
                    var setError = storageArea.SetItem(property, CoerceToHostString(value));
                    if (setError != null)
                    {
                        // QuotaExceededError â€” the JS side should throw.
                        // For now we silently ignore quota errors; a full
                        // implementation would throw a DOMException.
                    }
                    return true;
                case FenJsCanvasRenderingContext2DHost canvasContext:
                    return TrySetCanvasContextProperty(canvasContext, property, value);
                case FenJsTreeWalkerHost treeWalker when string.Equals(property, "currentNode", StringComparison.Ordinal):
                    var currentNode = _owner.ResolveHostObjectOrNull<Node>(value);
                    if (currentNode == null)
                    {
                        return false;
                    }

                    treeWalker.TreeWalker.CurrentNode = currentNode;
                    return true;
                case FenJsAnimationHost animation when string.Equals(property, "id", StringComparison.Ordinal):
                    animation.Id = CoerceToHostString(value);
                    return true;
                case FenJsAnimationHost animation when string.Equals(property, "currentTime", StringComparison.Ordinal):
                    animation.CurrentTime = value.Tag == JsValueTag.Null ? null : CoerceToFiniteNumber(value, 0);
                    return true;
                case FenJsAnimationHost animation when string.Equals(property, "startTime", StringComparison.Ordinal):
                    animation.StartTime = value.Tag == JsValueTag.Null ? null : CoerceToFiniteNumber(value, 0);
                    return true;
                case FenJsAnimationHost animation when string.Equals(property, "playbackRate", StringComparison.Ordinal):
                    animation.PlaybackRate = CoerceToFiniteNumber(value, 1);
                    return true;
                case FenJsAnimationHost animation:
                    RecordAssignedHostApi(animation, "Animation", property);
                    _owner.SetStoredHostProperty(animation, property, value);
                    return true;
                case FenJsLocationHost location when string.Equals(property, "href", StringComparison.Ordinal):
                    var hrefStr = CoerceToHostString(value);
                    if (!string.IsNullOrWhiteSpace(hrefStr) && Uri.TryCreate(location.Uri, hrefStr, out var navUri))
                        _owner.NavigateOwningBrowsingContext(navUri);
                    return true;
                case FenJsHistoryHost history
                    when string.Equals(property, "pushState", StringComparison.Ordinal) ||
                         string.Equals(property, "replaceState", StringComparison.Ordinal):
                    _owner.SetStoredHostProperty(history, property, value);
                    return true;
                case FenJsHistoryHost history
                    when string.Equals(property, "scrollRestoration", StringComparison.Ordinal):
                    // HTML 7.10.3: the setter takes a ScrollRestoration enum, and
                    // WebIDL enum conversion means anything outside the enumeration
                    // leaves the current value alone rather than storing garbage.
                    var restoration = CoerceToHostString(value);
                    if (string.Equals(restoration, "auto", StringComparison.Ordinal) ||
                        string.Equals(restoration, "manual", StringComparison.Ordinal))
                    {
                        _owner.SetStoredHostProperty(history, "scrollRestoration", JsValue.FromString(restoration));
                    }

                    return true;
                case BrowserSurfaceProfile navigator:
                    // Allow scripts to set arbitrary properties on navigator (e.g.
                    // Google stubs navigator.sendBeacon). Store for later retrieval.
                    RecordAssignedHostApi(navigator, "Navigator", property);
                    _owner.SetStoredHostProperty(navigator, property, value);
                    return true;
                default:
                    return false;
            }
        }

        public JsValue CallHostFunction(int functionId, JsValue thisValue, ReadOnlySpan<JsValue> args)
        {
            // Host function invocation not yet wired â€” the interpreter does not
            // currently emit CallHostFunction opcodes. When it does, map functionId
            // to a registered host callable and invoke it here.
            _ = functionId;
            _ = thisValue;
            _ = args;
            return JsValue.Undefined;
        }

        public bool TryConvertHostObjectToPrimitive(
            HostObjectHandle handle,
            string hint,
            out JsValue value)
        {
            if (_owner?._interpreter == null)
            {
                value = JsValue.Undefined;
                return false;
            }

            var resolution = _owner._interpreter.HostObjectTable.Resolve(
                handle,
                _owner._interpreter.HostResolveContext);
            if (resolution.IsOk && resolution.HostObject is FenJsLocationHost location)
            {
                value = JsValue.FromString(location.Uri?.AbsoluteUri ?? string.Empty);
                return true;
            }

            value = JsValue.Undefined;
            return false;
        }

        private bool TryGetDocumentProperty(Document document, string property, out JsValue value)
        {
            switch (property)
            {
                case "nodeName":
                    value = JsValue.FromString("#document");
                    return true;
                case "nodeType":
                    value = JsValue.FromInt32((int)document.NodeType);
                    return true;
                case "parentNode":
                case "ownerDocument":
                    value = JsValue.Null;
                    return true;
                case "firstChild":
                    value = _owner.ToHostNodeOrNull(document.FirstChild);
                    return true;
                case "lastChild":
                    value = _owner.ToHostNodeOrNull(document.LastChild);
                    return true;
                case "previousSibling":
                case "nextSibling":
                    value = JsValue.Null;
                    return true;
                case "childNodes":
                    value = _owner.ToHostOrNull(document.ChildNodes, HostObjectKind.Other);
                    return true;
                // DOM §4.2.6 ParentNode mixin: Document has it too. github.com's
                // behaviors bundle reads document.firstElementChild.classList.
                case "children":
                    {
                        var kids = new List<Node>();
                        for (int i = 0; i < document.ChildNodes.Length; i++)
                            if (document.ChildNodes[i] is Element) kids.Add(document.ChildNodes[i]);
                        value = _owner.CreateNodeArrayLike(kids);
                    }
                    return true;
                case "firstElementChild":
                    value = _owner.ToHostNodeOrNull(document.FirstElementChild);
                    return true;
                case "lastElementChild":
                    value = _owner.ToHostNodeOrNull(document.LastElementChild);
                    return true;
                case "childElementCount":
                    value = JsValue.FromInt32(document.ChildElementCount);
                    return true;
                case "id":
                    // Document nodes have no id attribute; return empty string per Chrome behavior.
                    value = JsValue.FromString(string.Empty);
                    return true;
                case "localName":
                    // Document nodes have no localName per DOM spec.
                    value = JsValue.Null;
                    return true;
                case "readyState":
                    // Only the active page document follows the engine navigation
                    // lifecycle; documents created via DOMImplementation carry their
                    // own complete readyState per HTML spec (resource-metadata
                    // management).
                    var currentDomRoot = _owner._currentDomRoot;
                    var isActivePageDocument = ReferenceEquals(document, currentDomRoot)
                        || (currentDomRoot?.OwnerDocument != null && ReferenceEquals(document, currentDomRoot.OwnerDocument));
                    value = JsValue.FromString(
                        isActivePageDocument
                            ? _owner.GetDocumentReadyState()
                            : document.ReadyState.ToString().ToLowerInvariant());
                    return true;
                case "compatMode":
                    // HTML 3.1.2 compatMode: "BackCompat" in quirks mode, else "CSS1Compat".
                    value = JsValue.FromString(document.CompatMode ?? "CSS1Compat");
                    return true;
                case "hasFocus":
                    value = _owner.GetOrCreateHostCallable(
                        document,
                        "hasFocus",
                        (_, _) => JsValue.FromBoolean(_owner.DocumentHasFocus(document)),
                        length: 0);
                    return true;
                case "styleSheets":
                    value = _owner.GetDocumentStyleSheetList(document);
                    return true;
                case "prerendering":
                    value = JsValue.FromBoolean(false);
                    return true;
                case "fonts":
                    // CSS Font Loading API: return the user-assigned fonts object
                    // (set by Google's inline script: document.fonts = { load: ..., ready: ... }).
                    value = _owner.GetStoredHostPropertyOrUndefined(document, "fonts");
                    return value.Tag != JsValueTag.Undefined;
                case "URL":
                case "documentURI":
                    value = JsValue.FromString(document.URL ?? string.Empty);
                    return true;
                case "referrer":
                    // HTML 3.1.5: the address of the document that navigated
                    // here. For a frame that is its parent's, and a frame with
                    // no other way to learn where it is embedded has to read it
                    // from here -- reCAPTCHA's challenge frame carries no origin
                    // in its own URL and derives the one it must post to from
                    // this. Returning the empty string left it unable to name a
                    // target and it never opened its channel.
                    value = JsValue.FromString(_owner.ResolveDocumentReferrer());
                    return true;
                case "baseURI":
                    value = JsValue.FromString(
                        document.BaseURI ??
                        document.DocumentURI ??
                        document.URL ??
                        _baseUri?.AbsoluteUri ??
                        string.Empty);
                    return true;
                case "domain":
                    value = _owner.GetStoredHostPropertyOrUndefined(document, "domain");
                    if (value.Tag == JsValueTag.Undefined)
                    {
                        value = JsValue.FromString(TryGetDocumentUri(document)?.Host ?? _baseUri?.Host ?? string.Empty);
                    }
                    return true;
                case "location":
                    value = _owner.ToHostOrNull(_location, HostObjectKind.Other);
                    return true;
                case "contentType":
                    value = JsValue.FromString(document.ContentType ?? "text/html");
                    return true;
                case "visibilityState":
                    value = JsValue.FromString(document.Hidden ? "hidden" : "visible");
                    return true;
                case "hidden":
                    value = JsValue.FromBoolean(document.Hidden);
                    return true;
                case "title":
                    value = JsValue.FromString(document.Title ?? string.Empty);
                    return true;
                case "cookie":
                    // Merge host-persisted cookies with any DOM-level cookies
                    // so the WAF challenge can read back cookies it previously set.
                    var hostCookies = _owner.CookieReadBridge != null && _owner._currentBaseUri != null
