        private static Uri TryGetDocumentUri(Document document)
        {
            if (document == null)
            {
                return null;
            }

            var raw =
                document.URL ??
                document.DocumentURI ??
                document.BaseURI;

            return Uri.TryCreate(raw, UriKind.Absolute, out var uri) ? uri : null;
        }

        private bool TryGetNodeProperty(Node node, string property, out JsValue value)
        {
            switch (property)
            {
                case "nodeName":
                    value = JsValue.FromString(node.NodeName ?? string.Empty);
                    return true;
                case "nodeType":
                    value = JsValue.FromInt32((int)node.NodeType);
                    return true;
                case "nodeValue":
                    value = node.NodeValue == null
                        ? JsValue.Null
                        : JsValue.FromString(node.NodeValue);
                    return true;
                case "textContent":
                    value = node.TextContent == null
                        ? JsValue.Null
                        : JsValue.FromString(node.TextContent);
                    return true;
                case "parentNode":
                    value = _owner.ToHostNodeOrNull(node.ParentNode);
                    return true;
                case "ownerDocument":
                    value = _owner.ToHostOrNull(node.OwnerDocument, HostObjectKind.DomDocument);
                    return true;
                case "firstChild":
                    value = _owner.ToHostNodeOrNull(node.FirstChild);
                    return true;
                case "lastChild":
                    value = _owner.ToHostNodeOrNull(node.LastChild);
                    return true;
                case "previousSibling":
                    value = _owner.ToHostNodeOrNull(node.PreviousSibling);
                    return true;
                case "nextSibling":
                    value = _owner.ToHostNodeOrNull(node.NextSibling);
                    return true;
                case "childNodes":
                    value = _owner.ToHostOrNull(node.ChildNodes, HostObjectKind.Other);
                    return true;
                case "compareDocumentPosition":
                    value = _owner.CreateCompareDocumentPositionCallable(node);
                    return true;
                case "getRootNode":
                    value = _owner.CreateGetRootNodeCallable(node);
                    return true;
                // DOM 4.4: the rest of the Node interface, shared by every node
                // kind. Type-specific getters run first and may override any of
                // these; this is what a doctype, a text node or a document falls
                // back to so no Node member is missing on any kind.
                case "name" when node is DocumentType doctypeName:
                    value = JsValue.FromString(doctypeName.Name ?? string.Empty);
                    return true;
                case "publicId" when node is DocumentType doctypePublic:
                    value = JsValue.FromString(doctypePublic.PublicId ?? string.Empty);
                    return true;
                case "systemId" when node is DocumentType doctypeSystem:
                    value = JsValue.FromString(doctypeSystem.SystemId ?? string.Empty);
                    return true;
                case "parentElement":
                    value = _owner.ToHostNodeOrNull(node.ParentElement);
                    return true;
                case "isConnected":
                    value = JsValue.FromBoolean(node.IsConnected);
                    return true;
                case "baseURI":
                    value = JsValue.FromString(node.OwnerDocument?.BaseURI ?? (node as Document)?.BaseURI ?? string.Empty);
                    return true;
                case "hasChildNodes":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "hasChildNodes",
                        (_, _) => JsValue.FromBoolean(node.HasChildNodes),
                        length: 0);
                    return true;
                case "cloneNode":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "cloneNode",
                        (_, args) =>
                        {
                            var deep = args.Count > 0 && CoerceToHostBoolean(args[0]);
                            return _owner.ToHostNodeOrNull(node.CloneNode(deep));
                        },
                        length: 1);
                    return true;
                case "isEqualNode":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "isEqualNode",
                        (_, args) =>
                        {
                            var other = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            return JsValue.FromBoolean(other != null && node.IsEqualNode(other));
                        },
                        length: 1);
                    return true;
                case "isSameNode":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "isSameNode",
                        (_, args) =>
                        {
                            var other = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            return JsValue.FromBoolean(other != null && node.IsSameNode(other));
                        },
                        length: 1);
                    return true;
                case "contains":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "contains",
                        (_, args) =>
                        {
                            var other = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            return JsValue.FromBoolean(other != null && node.Contains(other));
                        },
                        length: 1);
                    return true;
                case "normalize":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "normalize",
                        (_, _) =>
                        {
                            node.Normalize();
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "lookupPrefix":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "lookupPrefix",
                        (_, args) =>
                        {
                            var ns = args.Count > 0 && args[0].Tag != JsValueTag.Null && args[0].Tag != JsValueTag.Undefined
                                ? CoerceToHostString(args[0])
                                : null;
                            var prefix = DomNamespaceLookup.LookupPrefix(node, ns);
                            return prefix == null ? JsValue.Null : JsValue.FromString(prefix);
                        },
                        length: 1);
                    return true;
                case "lookupNamespaceURI":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "lookupNamespaceURI",
                        (_, args) =>
                        {
                            var prefix = args.Count > 0 && args[0].Tag != JsValueTag.Null && args[0].Tag != JsValueTag.Undefined
                                ? CoerceToHostString(args[0])
                                : null;
                            var ns = DomNamespaceLookup.LookupNamespaceUri(node, prefix);
                            return ns == null ? JsValue.Null : JsValue.FromString(ns);
                        },
                        length: 1);
                    return true;
                case "isDefaultNamespace":
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        "isDefaultNamespace",
                        (_, args) =>
                        {
                            var ns = args.Count > 0 && args[0].Tag != JsValueTag.Null && args[0].Tag != JsValueTag.Undefined
                                ? CoerceToHostString(args[0])
                                : null;
                            if (ns == string.Empty) ns = null;
                            return JsValue.FromBoolean(string.Equals(DomNamespaceLookup.LookupNamespaceUri(node, null), ns, StringComparison.Ordinal));
                        },
                        length: 1);
                    return true;
                case "appendChild":
                case "insertBefore":
                case "moveBefore":
                case "replaceChild":
                case "removeChild":
                    if (node is ContainerNode container)
                    {
                        value = _owner.CreateContainerMutationCallable(container, property);
                        return true;
                    }

                    // DOM 4.2.3: a leaf node (Text, Comment, DocumentType, ...) still
                    // has these members; every call is a HierarchyRequestError
                    // (or NotFoundError for removeChild) since it has no children.
                    value = _owner.GetOrCreateHostCallable(
                        node,
                        property,
                        (_, _) =>
                        {
                            _owner.ThrowDomException(
                                property == "removeChild" ? "NotFoundError" : "HierarchyRequestError",
                                property == "removeChild"
                                    ? "The node to be removed is not a child of this node."
                                    : "This node type does not support children.");
                            return JsValue.Undefined;
                        },
                        length: property == "appendChild" || property == "removeChild" ? 1 : 2);
                    return true;
                default:
                    value = JsValue.Undefined;
                    return false;
            }
        }

        /// <summary>
        /// HTML §4.9.1-4.9.11: the table, table section, row and cell DOM
        /// members that are not attribute reflection.
        /// </summary>
        private bool TryGetTableProperty(Element element, string property, out JsValue value)
        {
            value = JsValue.Undefined;
            if (HtmlTableDom.IsTable(element))
            {
                switch (property)
                {
                    case "caption":
                        value = _owner.ToHostNodeOrNull(HtmlTableDom.GetCaption(element));
                        return true;
                    case "tHead":
                        value = _owner.ToHostNodeOrNull(HtmlTableDom.GetTHead(element));
                        return true;
                    case "tFoot":
                        value = _owner.ToHostNodeOrNull(HtmlTableDom.GetTFoot(element));
                        return true;
                    case "tBodies":
                        value = _owner.ToHostOrNull(new FenJsHtmlCollectionHost(HtmlTableDom.GetTBodies(element)), HostObjectKind.Other);
                        return true;
                    case "rows":
                        value = _owner.ToHostOrNull(
                            new FenJsHtmlCollectionHost(new ComputedHTMLCollection(() => HtmlTableDom.GetRows(element))),
                            HostObjectKind.Other);
                        return true;
                    case "createCaption":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, _) => _owner.ToHostNodeOrNull(HtmlTableDom.CreateCaption(element)), length: 0);
                        return true;
                    case "deleteCaption":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, _) => { HtmlTableDom.DeleteCaption(element); return JsValue.Undefined; }, length: 0);
                        return true;
                    case "createTHead":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, _) => _owner.ToHostNodeOrNull(HtmlTableDom.CreateTHead(element)), length: 0);
                        return true;
                    case "deleteTHead":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, _) => { HtmlTableDom.DeleteTHead(element); return JsValue.Undefined; }, length: 0);
                        return true;
                    case "createTFoot":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, _) => _owner.ToHostNodeOrNull(HtmlTableDom.CreateTFoot(element)), length: 0);
                        return true;
                    case "deleteTFoot":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, _) => { HtmlTableDom.DeleteTFoot(element); return JsValue.Undefined; }, length: 0);
                        return true;
                    case "createTBody":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, _) =>
                        {
                            // dom-table-createtbody: after the last tbody child, else appended.
                            var tbody = element.OwnerDocument.CreateElement("tbody");
                            Node lastTBody = null;
                            for (var child = element.FirstChild; child != null; child = child.NextSibling)
                            {
                                if (child is Element el && string.Equals(el.LocalName, "tbody", StringComparison.OrdinalIgnoreCase))
                                    lastTBody = el;
                            }

                            element.InsertBefore(tbody, lastTBody?.NextSibling);
                            return _owner.ToHostNodeOrNull(tbody);
                        }, length: 0);
                        return true;
                    case "insertRow":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, args) =>
                            _owner.ToHostNodeOrNull(HtmlTableDom.InsertRow(element, ReadTableIndex(args))), length: 0);
                        return true;
                    case "deleteRow":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, args) =>
                        {
                            HtmlTableDom.DeleteRow(element, ReadTableIndex(args));
                            return JsValue.Undefined;
                        }, length: 1);
                        return true;
                }

                return false;
            }

            if (HtmlTableDom.IsSection(element))
            {
                switch (property)
                {
                    case "rows":
                        value = _owner.ToHostOrNull(
                            new FenJsHtmlCollectionHost(new ComputedHTMLCollection(() => HtmlTableDom.GetSectionRows(element))),
                            HostObjectKind.Other);
                        return true;
                    case "insertRow":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, args) =>
                            _owner.ToHostNodeOrNull(HtmlTableDom.InsertSectionRow(element, ReadTableIndex(args))), length: 0);
                        return true;
                    case "deleteRow":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, args) =>
                        {
                            HtmlTableDom.DeleteSectionRow(element, ReadTableIndex(args));
                            return JsValue.Undefined;
                        }, length: 1);
                        return true;
                }

                return false;
            }

            if (HtmlTableDom.IsRow(element))
            {
                switch (property)
                {
                    case "rowIndex":
                        value = JsValue.FromInt32(HtmlTableDom.GetRowIndex(element));
                        return true;
                    case "sectionRowIndex":
                        value = JsValue.FromInt32(HtmlTableDom.GetSectionRowIndex(element));
                        return true;
                    case "cells":
                        value = _owner.ToHostOrNull(
                            new FenJsHtmlCollectionHost(new ComputedHTMLCollection(() => HtmlTableDom.GetCells(element))),
                            HostObjectKind.Other);
                        return true;
                    case "insertCell":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, args) =>
                            _owner.ToHostNodeOrNull(HtmlTableDom.InsertCell(element, ReadTableIndex(args))), length: 0);
                        return true;
                    case "deleteCell":
                        value = _owner.GetOrCreateHostCallable(element, property, (_, args) =>
                        {
                            HtmlTableDom.DeleteCell(element, ReadTableIndex(args));
                            return JsValue.Undefined;
                        }, length: 1);
                        return true;
                }

                return false;
            }

            if (HtmlTableDom.IsCell(element) && property == "cellIndex")
            {
                value = JsValue.FromInt32(HtmlTableDom.GetCellIndex(element));
                return true;
            }

            return false;
        }

        /// <summary>
        /// HTML §4.10.3 form.elements / form.length, §4.10.7 select.options /
        /// add / remove / length / selectedOptions, §4.10.10 option.index.
        /// </summary>
        private bool TryGetFormProperty(Element element, string property, out JsValue value)
        {
            value = JsValue.Undefined;
            if (HtmlFormDom.IsForm(element))
            {
                switch (property)
                {
                    case "elements":
                        value = _owner.ToHostOrNull(
                            new FenJsHtmlCollectionHost(new ComputedHTMLCollection(() => HtmlFormDom.ListedElements(element), nameMatches: true)),
                            HostObjectKind.Other);
                        return true;
                    case "length":
                        value = JsValue.FromInt32(HtmlFormDom.ListedElements(element).Count);
                        return true;
                    default:
                        // dom-form-nameditem: a control by id or name is a property
                        // of the form itself (form.first).
                        if (int.TryParse(property, NumberStyles.Integer, CultureInfo.InvariantCulture, out var index))
                        {
                            var listed = HtmlFormDom.ListedElements(element);
                            if (index >= 0 && index < listed.Count)
                            {
                                value = _owner.ToHostNodeOrNull(listed[index]);
                                return true;
                            }

                            return false;
                        }

                        foreach (var control in HtmlFormDom.ListedElements(element))
                        {
                            if (control.Id == property || control.GetAttribute("name") == property)
                            {
                                value = _owner.ToHostNodeOrNull(control);
                                return true;
                            }
                        }

                        return false;
                }
            }

            if (HtmlFormDom.IsSelect(element))
            {
                switch (property)
                {
                    case "options":
                        value = _owner.ToHostOrNull(
                            new FenJsHtmlCollectionHost(new ComputedHTMLCollection(() => HtmlFormDom.Options(element), nameMatches: true)),
                            HostObjectKind.Other);
                        return true;
                    case "length":
                        value = JsValue.FromInt32(HtmlFormDom.Options(element).Count);
                        return true;
                    case "selectedOptions":
                        value = _owner.ToHostOrNull(
                            new FenJsHtmlCollectionHost(new ComputedHTMLCollection(() =>
                                HtmlFormDom.Options(element).FindAll(FenBrowser.FenEngine.Rendering.SelectSelection.IsSelected))),
                            HostObjectKind.Other);
                        return true;
                    case "add":
                        value = _owner.GetOrCreateHostCallable(element, "add", (_, args) =>
                        {
                            var added = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Element>(args[0]) : null;
                            Element beforeElement = null;
                            int? beforeIndex = null;
                            if (args.Count > 1 && args[1].Tag != JsValueTag.Null && args[1].Tag != JsValueTag.Undefined)
                            {
                                beforeElement = _owner.ResolveHostObjectOrNull<Element>(args[1]);
                                if (beforeElement == null)
                                {
                                    beforeIndex = (int)CoerceToFiniteNumber(args[1], -1);
                                }
                            }

                            HtmlFormDom.Add(element, added, beforeElement, beforeIndex);
                            FenBrowser.FenEngine.Rendering.SelectSelection.AskForReset(element);
                            return JsValue.Undefined;
                        }, length: 1);
                        return true;
                    case "remove":
                        value = _owner.GetOrCreateHostCallable(element, "remove", (_, args) =>
                        {
                            if (args.Count == 0)
                            {
                                // ChildNode.remove() when called without an index.
                                (element.ParentNode as ContainerNode)?.RemoveChild(element);
                                return JsValue.Undefined;
                            }

                            HtmlFormDom.Remove(element, (int)CoerceToFiniteNumber(args[0], -1));
                            FenBrowser.FenEngine.Rendering.SelectSelection.AskForReset(element);
                            return JsValue.Undefined;
                        }, length: 0);
                        return true;
                    case "item":
                        value = _owner.GetOrCreateHostCallable(element, "item", (_, args) =>
                        {
                            var options = HtmlFormDom.Options(element);
                            var index = args.Count > 0 ? (int)CoerceToFiniteNumber(args[0], -1) : -1;
                            return index >= 0 && index < options.Count ? _owner.ToHostNodeOrNull(options[index]) : JsValue.Null;
                        }, length: 1);
                        return true;
                    default:
                        if (int.TryParse(property, NumberStyles.Integer, CultureInfo.InvariantCulture, out var optionIndex))
                        {
                            var options = HtmlFormDom.Options(element);
                            if (optionIndex >= 0 && optionIndex < options.Count)
                            {
                                value = _owner.ToHostNodeOrNull(options[optionIndex]);
                                return true;
                            }
                        }

                        return false;
                }
            }

            if (HtmlFormDom.IsOption(element))
            {
                switch (property)
                {
                    case "index":
                        value = JsValue.FromInt32(HtmlFormDom.OptionIndex(element));
                        return true;
                    case "form":
                        value = _owner.ToHostNodeOrNull(HtmlFormDom.FormOwner(element));
                        return true;
                }

                return false;
            }

            if (property == "form" && HtmlFormDom.IsListedElement(element))
            {
                // dom-fae-form: the control's form owner.
                value = _owner.ToHostNodeOrNull(HtmlFormDom.FormOwner(element));
                return true;
            }

            return false;
        }

        // WebIDL long with a default of -1 for the row/cell index arguments.
        private static int ReadTableIndex(IReadOnlyList<JsValue> args)
        {
            if (args.Count == 0 || args[0].Tag == JsValueTag.Undefined)
                return -1;
            var number = CoerceToFiniteNumber(args[0], -1);
            return (int)Math.Truncate(Math.Max(int.MinValue, Math.Min(int.MaxValue, number)));
        }

        private bool TryGetElementProperty(Element element, string property, out JsValue value)
        {
            if (IsMediaElement(element) && _owner.TryGetMediaElementProperty(element, property, out value))
            {
                return true;
            }

            if (IsTrackElement(element) && _owner.TryGetTrackElementProperty(element, property, out value))
            {
                return true;
            }

            switch (property)
            {
                case "id":
                    value = JsValue.FromString(element.Id ?? string.Empty);
                    return true;
                case "className":
                    value = JsValue.FromString(element.ClassName ?? string.Empty);
                    return true;
                case "name":
                    value = JsValue.FromString(element.GetAttribute("name") ?? string.Empty);
                    return true;
                case "tagName":
                case "nodeName":
                    value = JsValue.FromString(element.TagName ?? string.Empty);
                    return true;
                case "prefix":
                    // DOM 4.9 dom-element-prefix: null when the element has none.
                    value = string.IsNullOrEmpty(element.Prefix) ? JsValue.Null : JsValue.FromString(element.Prefix);
                    return true;
                case "localName":
                    value = JsValue.FromString(element.LocalName ?? string.Empty);
                    return true;
                case "href":
                    value = JsValue.FromString(ResolveElementUrlProperty(element, "href"));
                    return true;
                case "relList" when IsRelListElement(element):
                    // HTML dom-link-rellist: shared by link, a and area.
                    value = _owner.GetOrCreateDomTokenListView(element.RelList);
                    return true;
                case "hash" when IsHyperlinkElement(element):
                    // HTML 4.6.3 dom-hyperlink-hash: the fragment of the resolved
                    // URL including the leading "#", empty when there is none.
                    var hyperlinkUrl = ResolveElementUrlProperty(element, "href");
                    var fragmentIndex = hyperlinkUrl.IndexOf('#');
                    value = JsValue.FromString(
                        fragmentIndex >= 0 && fragmentIndex < hyperlinkUrl.Length - 1
                            ? hyperlinkUrl.Substring(fragmentIndex)
                            : string.Empty);
                    return true;
                case "origin" or "protocol" or "username" or "password" or "host" or "hostname" or "port" or "pathname" or "search"
                    when IsHyperlinkElement(element):
                    value = JsValue.FromString(ReadHyperlinkUrlPart(element, property));
                    return true;
                case "type" when IsHyperlinkElement(element) || IsStyleElement(element):
                    // Both reflect a plain type content attribute.
                    value = JsValue.FromString(element.GetAttribute("type") ?? string.Empty);
                    return true;
                case "type" when IsButtonElement(element):
                    // HTML dom-button-type is a limited-value reflection with a
                    // missing/invalid default of "submit", so a bare <button>
                    // reports "submit" rather than "". Forms code branches on it.
                    var buttonType = (element.GetAttribute("type") ?? string.Empty).ToLowerInvariant();
                    value = JsValue.FromString(
                        buttonType is "reset" or "button" or "submit" ? buttonType : "submit");
                    return true;
                case "type" when IsSelectElement(element):
                    // HTML dom-select-type: derived from the multiple attribute
                    // rather than from a type attribute at all.
                    value = JsValue.FromString(
                        element.HasAttribute("multiple") ? "select-multiple" : "select-one");
                    return true;
                case "text" when IsScriptElement(element):
                    // HTML dom-script-text: the script's child text content.
                    value = JsValue.FromString(element.TextContent ?? string.Empty);
                    return true;
                case "disabled" when IsFieldSetElement(element):
                    value = JsValue.FromBoolean(element.HasAttribute("disabled"));
                    return true;
                case "selected" when IsOptionElement(element):
                    // HTML dom-option-selected: live selectedness, which follows
                    // the "selected" attribute only until something moves it.
                    value = JsValue.FromBoolean(
                        FenBrowser.FenEngine.Rendering.SelectSelection.IsSelected(element));
                    return true;
                case "defaultSelected" when IsOptionElement(element):
                    value = JsValue.FromBoolean(element.HasAttribute("selected"));
                    return true;
                case "src" when IsSourceElement(element):
                    // HTML 4.8.2 dom-source-src reflects as a URL: a whitespace-only
                    // value is the document URL, as a media element's currentSrc reports.
                    value = JsValue.FromString(ReflectUrlAttribute(element, "src"));
                    return true;
                case "src":
                    value = JsValue.FromString(ResolveElementUrlProperty(element, "src"));
                    return true;
                case "nonce":
                    value = JsValue.FromString(element.GetAttribute("nonce") ?? string.Empty);
                    return true;
                case "title":
                    value = JsValue.FromString(element.GetAttribute("title") ?? string.Empty);
                    return true;
                case "value" when IsSelectElement(element):
                    value = JsValue.FromString(
                        FenBrowser.FenEngine.Rendering.SelectSelection.Value(element));
                    return true;
                case "selectedIndex" when IsSelectElement(element):
                    value = JsValue.FromInt32(
                        FenBrowser.FenEngine.Rendering.SelectSelection.SelectedIndex(element));
                    return true;
                case "value":
                    value = JsValue.FromString(ReadElementValue(element));
                    return true;
                case "defaultValue" when IsValueDefaultingElement(element):
                    value = JsValue.FromString(ReadElementDefaultValue(element));
                    return true;
                case "defaultChecked" when IsCheckableInputElement(element):
                    value = JsValue.FromBoolean(element.HasAttribute("checked"));
                    return true;
                case "type" when string.Equals(element.TagName, "input", StringComparison.OrdinalIgnoreCase):
                    value = JsValue.FromString(ReadInputType(element));
                    return true;
                case "checked" when IsCheckableInputElement(element):
                    value = JsValue.FromBoolean(ElementStateManager.Instance.IsChecked(element));
                    return true;
                case "tabIndex":
                    value = JsValue.FromInt32(ReadElementTabIndex(element));
                    return true;
                case "contentWindow" when IsIFrameElement(element):
                    value = _owner.GetIFrameContentWindowForCurrentContext(element);
                    return true;
                case "contentDocument" when IsIFrameElement(element):
                    value = _owner.CanCurrentContextAccessIFrameDocument(element)
                        ? _owner.GetOrCreateIFrameContentDocument(element)
                        : JsValue.Null;
                    return true;
                case "sandbox" when IsIFrameElement(element):
                    value = element.NamespaceUri == "http://www.w3.org/1999/xhtml"
                        ? _owner.GetOrCreateDomTokenListView(element.SandboxList)
                        : JsValue.Undefined;
                    return true;
                case "getContext" when FenJsBrowserScriptEngine.IsCanvasElement(element):
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "getContext",
                        (_, args) =>
                        {
                            var kind = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            var context = _owner.GetOrCreateCanvasContext(element, kind);
                            return context != null
                                ? _owner.ToHostOrNull(context, HostObjectKind.Other)
                                : JsValue.Null;
                        },
                        length: 1);
                    return true;
                case "toDataURL" when FenJsBrowserScriptEngine.IsCanvasElement(element):
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "toDataURL",
                        (_, args) =>
                        {
                            var mediaType = args.Count > 0 ? CoerceToHostString(args[0]) : "image/png";
                            return JsValue.FromString(_owner.CanvasToDataUrl(element, mediaType));
                        },
                        length: 0);
                    return true;
                case "width" when FenJsBrowserScriptEngine.IsCanvasElement(element):
                    value = JsValue.FromInt32(_owner.GetCanvasContextSizeOrAttribute(element, "width"));
                    return true;
                case "height" when FenJsBrowserScriptEngine.IsCanvasElement(element):
                    value = JsValue.FromInt32(_owner.GetCanvasContextSizeOrAttribute(element, "height"));
                    return true;
                case "scrolling" when IsIFrameElement(element):
                    value = JsValue.FromString(element.GetAttribute("scrolling") ?? string.Empty);
                    return true;
                case "httpEquiv" when IsMetaElement(element):
                    value = JsValue.FromString(element.GetAttribute("http-equiv") ?? string.Empty);
                    return true;
                case "async" when IsScriptElement(element):
                    value = JsValue.FromBoolean(element.HasAttribute("async"));
                    return true;
                case "type" when IsScriptElement(element):
                case "charset" when IsScriptElement(element):
                case "integrity" when IsScriptElement(element):
                    value = JsValue.FromString(element.GetAttribute(property) ?? string.Empty);
                    return true;
                case "crossOrigin" when IsScriptElement(element):
                    value = element.HasAttribute("crossorigin")
                        ? JsValue.FromString(element.GetAttribute("crossorigin") ?? string.Empty)
                        : JsValue.Null;
                    return true;
                case "content" when IsTemplateElement(element):
                    value = _owner.GetOrCreateTemplateContent(element);
                    return true;
                case "content":
                    value = JsValue.FromString(element.GetAttribute("content") ?? string.Empty);
                    return true;
                case "shadowRoot":
                    value = _owner.ToHostNodeOrNull(element.ShadowRoot);
                    return true;
                case "complete" when IsImageElement(element):
                    value = JsValue.FromBoolean(_owner.IsImageComplete(element));
                    return true;
                case "naturalWidth" when IsImageElement(element):
                    value = JsValue.FromInt32(_owner.GetImageNaturalSize(element).Width);
                    return true;
                case "naturalHeight" when IsImageElement(element):
                    value = JsValue.FromInt32(_owner.GetImageNaturalSize(element).Height);
                    return true;
                case "open" when IsDialogElement(element):
                    value = JsValue.FromBoolean(element.HasAttribute("open"));
                    return true;
                case "showModal" when IsDialogElement(element):
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "showModal",
                        (_, _) =>
                        {
                            element.SetAttribute("open", "");
                            element.SetAttribute("data-top-layer", "modal");
                            // OwnerDocument walks up _parentNode to find the Document.
                            // If the element was obtained via getElementById in a FenJS
                            // host-object context, the CLR parent chain is intact and
                            // OwnerDocument is non-null.  If it is null (e.g. detached
                            // element), skip the TopLayer path â€” the dialog will still
                            // render as a normal positioned element via CSS.
                            var doc = element.OwnerDocument;
                            if (doc != null)
                            {
                                if (!doc.TopLayer.Contains(element))
                                    doc.TopLayer.Add(element);
                            }
                            // Mark style/layout/paint dirty so the renderer rebuilds
                            // the paint tree and picks up the TopLayer change.
                            FenJsBrowserScriptEngine.InvalidatePaintForElement(element);
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "show" when IsDialogElement(element):
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "show",
                        (_, _) =>
                        {
