                                {
                                    _owner.ExecuteDynamicScriptElement(childElement);
                                }
                            }

                            return JsValue.Undefined;
                        },
                        length: 1);
                    return true;
                case "prepend":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "prepend",
                        (_, args) =>
                        {
                            var referenceNode = element.FirstChild;
                            foreach (var arg in args)
                            {
                                if (_owner.ResolveHostObjectOrNull<Attr>(arg) != null)
                                {
                                    _owner.ThrowHierarchyRequestError("Attributes cannot be inserted as child nodes.");
                                }

                                Node child = _owner.ResolveHostObjectOrNull<Node>(arg);
                                if (child == null)
                                {
                                    child = element.OwnerDocument?.CreateTextNode(CoerceToHostString(arg));
                                }

                                if (child == null)
                                {
                                    continue;
                                }

                                var scriptCandidates = child is DocumentFragment fragment
                                    ? fragment.ChildNodes.OfType<Element>().ToArray()
                                    : child is Element childElement
                                        ? new[] { childElement }
                                        : Array.Empty<Element>();

                                var moved = SnapshotFragmentChildren(child);
                                element.InsertBefore(child, referenceNode);
                                _owner.UpgradeInsertedCustomElements(child, moved);
                                _owner.QueueFrameLoadsForTree(child);
                                foreach (var scriptElement in scriptCandidates)
                                {
                                    if (string.Equals(scriptElement.TagName, "SCRIPT", StringComparison.OrdinalIgnoreCase))
                                    {
                                        _owner.ExecuteDynamicScriptElement(scriptElement);
                                    }
                                }
                            }

                            return JsValue.Undefined;
                        },
                        length: 1);
                    return true;
                case "cloneNode":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "cloneNode",
                        (_, args) =>
                        {
                            var deep = args.Count > 0 && CoerceToHostBoolean(args[0]);
                            return _owner.ToHostNodeOrNull(element.CloneNode(deep));
                        },
                        length: 1);
                    return true;
                case "insertBefore":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "insertBefore",
                        (_, args) =>
                        {
                            if (args.Count > 0 && _owner.ResolveHostObjectOrNull<Attr>(args[0]) != null)
                            {
                                _owner.ThrowHierarchyRequestError("Attributes cannot be inserted as child nodes.");
                            }

                            var child = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            if (child == null)
                            {
                                return JsValue.Null;
                            }

                            var referenceNode = args.Count > 1 ? _owner.ResolveHostObjectOrNull<Node>(args[1]) : null;
                            var moved = SnapshotFragmentChildren(child);
                            var inserted = element.InsertBefore(child, referenceNode);
                            _owner.QueueFrameLoadsForTree(inserted);
                            if (child is Element childElement &&
                                string.Equals(childElement.TagName, "SCRIPT", StringComparison.OrdinalIgnoreCase))
                            {
                                _owner.ExecuteDynamicScriptElement(childElement);
                            }

                            _owner.UpgradeInsertedCustomElements(child, moved);
                            return _owner.ToHostNodeOrNull(inserted);
                        },
                        length: 2);
                    return true;
                case "moveBefore":
                    // DOM dom-node-movebefore: a state-preserving move within one tree.
                    // Node? child takes null or undefined; anything else that is not a
                    // node is a TypeError, as for insertBefore.
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "moveBefore",
                        (_, args) =>
                        {
                            var node = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            if (node == null)
                            {
                                _owner.ThrowDomException("TypeError", "Failed to execute 'moveBefore' on 'Node': parameter 1 is not of type 'Node'.");
                            }

                            Node referenceChild = null;
                            if (args.Count > 1 && args[1].Tag != JsValueTag.Null && args[1].Tag != JsValueTag.Undefined)
                            {
                                referenceChild = _owner.ResolveHostObjectOrNull<Node>(args[1]);
                                if (referenceChild == null)
                                {
                                    _owner.ThrowDomException("TypeError", "Failed to execute 'moveBefore' on 'Node': parameter 2 is not of type 'Node'.");
                                }
                            }

                            element.MoveBefore(node, referenceChild);
                            return JsValue.Undefined;
                        },
                        length: 2);
                    return true;
                case "removeChild":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "removeChild",
                        (_, args) =>
                        {
                            var child = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            if (child == null)
                            {
                                _owner.ThrowDomException("TypeError", "Child must be a DOM node.");
                            }

                            try
                            {
                                return _owner.ToHostNodeOrNull(element.RemoveChild(child));
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Undefined;
                            }
                        },
                        length: 1);
                    return true;
                case "replaceChild":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "replaceChild",
                        (_, args) =>
                        {
                            if (args.Count > 0 && _owner.ResolveHostObjectOrNull<Attr>(args[0]) != null)
                            {
                                _owner.ThrowHierarchyRequestError("Attributes cannot be inserted as child nodes.");
                            }

                            var child = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            if (child == null)
                            {
                                _owner.ThrowDomException("TypeError", "Replacement child must be a DOM node.");
                            }

                            var oldChild = args.Count > 1 ? _owner.ResolveHostObjectOrNull<Node>(args[1]) : null;
                            if (oldChild == null)
                            {
                                _owner.ThrowDomException("TypeError", "Child must be a DOM node.");
                            }

                            try
                            {
                                var moved = SnapshotFragmentChildren(child);
                                var replaced = element.ReplaceChild(child, oldChild);
                                if (child is Element childElement &&
                                    string.Equals(childElement.TagName, "SCRIPT", StringComparison.OrdinalIgnoreCase))
                                {
                                    _owner.ExecuteDynamicScriptElement(childElement);
                                }

                                _owner.UpgradeInsertedCustomElements(child, moved);
                                return _owner.ToHostNodeOrNull(replaced);
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Undefined;
                            }
                        },
                        length: 2);
                    return true;
                case "remove":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "remove",
                        (_, _) =>
                        {
                            if (element.ParentNode is ContainerNode parent)
                            {
                                parent.RemoveChild(element);
                            }

                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "matches":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "matches",
                        (_, args) =>
                        {
                            var selector = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            try
                            {
                                return JsValue.FromBoolean(element.Matches(selector));
                            }
                            catch (DomException)
                            {
                                return JsValue.FromBoolean(false);
                            }
                        },
                        length: 1);
                    return true;
                case "closest":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "closest",
                        (_, args) =>
                        {
                            var selector = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            try
                            {
                                return _owner.ToHostNodeOrNull(element.Closest(selector));
                            }
                            catch (DomException)
                            {
                                return JsValue.Null;
                            }
                        },
                        length: 1);
                    return true;
                case "querySelector":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "querySelector",
                        (_, args) =>
                        {
                            var selector = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            try
                            {
                                return _owner.ToHostNodeOrNull(element.QuerySelector(selector));
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Null;
                            }
                        },
                        length: 1);
                    return true;
                case "querySelectorAll":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "querySelectorAll",
                        (_, args) =>
                        {
                            var selector = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            if (string.IsNullOrWhiteSpace(selector))
                            {
                                return _owner.CreateNodeArrayLike(Array.Empty<Node>());
                            }

                            try
                            {
                                return _owner.CreateNodeArrayLike(element.QuerySelectorAll(selector));
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return _owner.CreateNodeArrayLike(Array.Empty<Node>());
                            }
                        },
                        length: 1);
                    return true;
                case "getElementsByTagName":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "getElementsByTagName",
                        (_, args) =>
                        {
                            var qualifiedName = args.Count > 0 ? CoerceToHostString(args[0]) : "*";
                            return _owner.ToHostOrNull(
                                new FenJsHtmlCollectionHost(element.GetElementsByTagName(qualifiedName)),
                                HostObjectKind.Other);
                        },
                        length: 1);
                    return true;
                case "getElementsByClassName":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "getElementsByClassName",
                        (_, args) =>
                        {
                            var className = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            return _owner.ToHostOrNull(
                                new FenJsHtmlCollectionHost(element.GetElementsByClassName(className)),
                                HostObjectKind.Other);
                        },
                        length: 1);
                    return true;
                case "insertAdjacentElement":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "insertAdjacentElement",
                        (_, args) =>
                        {
                            var where = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            var target = args.Count > 1 ? _owner.ResolveHostObjectOrNull<Element>(args[1]) : null;
                            if (target == null)
                            {
                                _owner.ThrowDomException(
                                    "TypeError",
                                    "Failed to execute 'insertAdjacentElement': parameter 2 is not of type 'Element'.");
                                return JsValue.Undefined;
                            }

                            try
                            {
                                return _owner.ToHostNodeOrNull(element.InsertAdjacent(where, target));
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Undefined;
                            }
                        },
                        length: 2);
                    return true;
                case "insertAdjacentText":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "insertAdjacentText",
                        (_, args) =>
                        {
                            // DOM 4.9: a new Text node with the data, inserted adjacent.
                            var where = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            var data = args.Count > 1 ? CoerceToHostString(args[1]) : "undefined";
                            var text = (element.OwnerDocument ?? CurrentDocument).CreateTextNode(data);
                            try
                            {
                                element.InsertAdjacent(where, text);
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                            }

                            return JsValue.Undefined;
                        },
                        length: 2);
                    return true;
                case "insertAdjacentHTML":
                    value = _owner.GetOrCreateHostCallable(
                        element,
                        "insertAdjacentHTML",
                        (_, args) =>
                        {
                            var position = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            var html = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                            _owner.InsertAdjacentHtml(element, position, html);
                            // beforebegin/afterend land in the parent; upgrade from there.
                            _owner.UpgradeCustomElementTreeIfDefined(_owner.ToHostNodeOrNull(
                                string.Equals(position, "beforebegin", StringComparison.OrdinalIgnoreCase) ||
                                string.Equals(position, "afterend", StringComparison.OrdinalIgnoreCase)
                                    ? element.ParentNode ?? element
                                    : element));
                            return JsValue.Undefined;
                        },
                        length: 2);
                    return true;
                // --- Geometry / layout ---
                case "nodeType":
                    value = JsValue.FromInt32((int)element.NodeType);
                    return true;
                case "isConnected":
                    value = JsValue.FromBoolean(element.IsConnected);
                    return true;
                case "assignedSlot":
                    value = _owner.ToHostNodeOrNull(element.AssignedSlot);
                    return true;
                case "childNodes":
                    // DOM 4.4: childNodes is the same live NodeList on every read. A copy
                    // never shrinks, so bing.com's `for(;f.length;) frag.appendChild(f[0])`
                    // drain loop spun until the script budget ran out.
                    value = _owner.ToHostOrNull(element.ChildNodes, HostObjectKind.Other);
                    return true;
                case "children":
                    {
                        var kids = new List<Node>();
                        for (int i = 0; i < element.ChildNodes.Length; i++)
                            if (element.ChildNodes[i] is Element) kids.Add(element.ChildNodes[i]);
                        value = _owner.CreateNodeArrayLike(kids);
                    }
                    return true;
                case "firstChild":
                    value = _owner.ToHostNodeOrNull(element.FirstChild);
                    return true;
                case "lastChild":
                    value = _owner.ToHostNodeOrNull(element.LastChild);
                    return true;
                case "nextElementSibling":
                    value = _owner.ToHostNodeOrNull(element.NextElementSibling);
                    return true;
                case "previousElementSibling":
                    value = _owner.ToHostNodeOrNull(element.PreviousElementSibling);
                    return true;
                case "contains":
                    value = _owner.GetOrCreateHostCallable(
                        element, "contains",
                        (_, args) =>
                        {
                            var other = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Node>(args[0]) : null;
                            return JsValue.FromBoolean(other != null && element.Contains(other));
                        },
                        length: 1);
                    return true;
                case "compareDocumentPosition":
                    value = _owner.CreateCompareDocumentPositionCallable(element);
                    return true;
                case "getRootNode":
                    value = _owner.CreateGetRootNodeCallable(element);
                    return true;
                case "before":
                case "after":
                case "replaceWith":
                    value = _owner.CreateChildNodeMutationCallable(element, property);
                    return true;
                case "offsetWidth":
                case "offsetHeight":
                case "offsetLeft":
                case "offsetTop":
                case "clientWidth":
                case "clientHeight":
                case "clientLeft":
                case "clientTop":
                case "scrollWidth":
                case "scrollHeight":
                case "scrollTop":
                case "scrollLeft":
                    value = _owner.ReadElementLayoutDimension(element, property);
                    return true;
                case "offsetParent":
                    value = _owner.ToHostNodeOrNull(_owner.ResolveOffsetParent(element));
                    return true;
                case "getBoundingClientRect":
                    value = _owner.GetOrCreateHostCallable(
                        element, "getBoundingClientRect",
                        (_, _) => _owner.ReadElementBoundingClientRect(element),
                        length: 0);
                    return true;
                case "getClientRects":
                    value = _owner.GetOrCreateHostCallable(
                        element, "getClientRects",
                        (_, _) => _owner.ReadElementClientRects(element),
                        length: 0);
                    return true;
                case "scrollIntoView":
                    value = _owner.GetOrCreateHostCallable(
                        element, "scrollIntoView",
                        (_, args) =>
                        {
                            _owner.ScrollElementIntoView(element, args.Count > 0 ? args[0] : JsValue.Undefined);
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "style":
                    value = _owner.GetOrCreateStyleObject(element);
                    return true;
                case "currentStyle":
                    value = _owner.CreateComputedStyleObjectForElement(element);
                    return true;
                default:
                    // HTML §4.9 table DOM (caption/tHead/tFoot/tBodies/rows,
                    // insertRow, cells, rowIndex, ...).
                    if (TryGetTableProperty(element, property, out value))
                    {
                        return true;
                    }

                    // HTML §4.10 form, select and option members.
                    if (TryGetFormProperty(element, property, out value))
                    {
                        return true;
                    }

                    // HTML §2.6.1 reflected IDL attributes (disabled, htmlFor,
                    // colSpan, ...) read straight from the content attribute.
                    if (HtmlAttributeReflection.TryGetEntry(element, property, out var reflected))
                    {
                        value = HtmlAttributeReflection.Read(
                            element, reflected, raw => ResolveElementUrlProperty(element, reflected.Attribute));
                        return true;
                    }

                    // Fall back to user-assigned properties (e.g. Google sets
                    // __gwbp, __jsl on elements for internal bookkeeping).
                    value = _owner.GetStoredHostPropertyOrUndefined(element, property);
                    return value.Tag != JsValueTag.Undefined;
            }
        }

        private bool TryGetDomImplementationProperty(FenJsDomImplementationHost implementation, string property, out JsValue value)
        {
            switch (property)
            {
                case "hasFeature":
                    value = _owner.GetOrCreateHostCallable(
                        implementation,
                        "hasFeature",
                        (_, _) => JsValue.FromBoolean(true),
                        length: 2);
                    return true;
                case "createDocument":
                    value = _owner.GetOrCreateHostCallable(
                        implementation,
                        "createDocument",
                        (_, args) =>
                        {
                            var namespaceUri = args.Count > 0 && args[0].Tag != JsValueTag.Null
                                ? CoerceToHostString(args[0])
                                : null;
                            var qualifiedName = args.Count > 1 && args[1].Tag != JsValueTag.Null
                                ? CoerceToHostString(args[1])
                                : null;
                            var created = Document.CreateXmlDocument(namespaceUri, qualifiedName);
                            // DOM 4.5.1 dom-domimplementation-createdocument step 5: an
                            // optional doctype is appended (adopted) before the element.
                            var doctype = args.Count > 2 ? _owner.ResolveHostObjectOrNull<DocumentType>(args[2]) : null;
                            if (doctype != null)
                            {
                                created.InsertBefore(doctype, created.FirstChild);
                            }

                            return _owner.ToHostOrNull(created, HostObjectKind.DomDocument);
                        },
                        length: 2);
                    return true;
                case "createDocumentType":
                    // DOM 4.5.1 dom-domimplementation-createdocumenttype: validate the
                    // qualified name, then a doctype owned by this implementation's
                    // document.
                    value = _owner.GetOrCreateHostCallable(
                        implementation,
                        "createDocumentType",
                        (_, args) =>
                        {
                            var name = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            var publicId = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                            var systemId = args.Count > 2 ? CoerceToHostString(args[2]) : string.Empty;
                            if (!DomNames.IsValidDoctypeName(name))
                            {
                                throw new DomException("InvalidCharacterError", $"The qualified name '{name}' is not valid.");
                            }

                            return _owner.ToHostNodeOrNull(new DocumentType(name, publicId, systemId, implementation.OwnerDocument));
                        },
                        length: 3);
                    return true;
                case "createHTMLDocument":
                    value = _owner.GetOrCreateHostCallable(
                        implementation,
                        "createHTMLDocument",
                        (_, args) =>
                        {
                            var title = args.Count > 0 && args[0].Tag != JsValueTag.Null
                                ? CoerceToHostString(args[0])
                                : null;
                            var created = Document.CreateHtmlDocument(title);
                            // The new document's URL is about:blank and it has no browsing
                            // context, so its fallback base URL is the creator's base URL
                            // (HTML "fallback base URL"): a relative media src in it resolves
                            // as it would in the associated document.
                            var creator = implementation.OwnerDocument;
                            var creatorBase = creator?.BaseURI ?? creator?.URL;
                            if (!string.IsNullOrWhiteSpace(creatorBase) && creatorBase != "about:blank")
                            {
                                created.BaseURI = creatorBase;
                            }

                            return _owner.ToHostOrNull(created, HostObjectKind.DomDocument);
                        },
                        length: 1);
                    return true;
                default:
                    value = JsValue.Undefined;
                    return false;
            }
        }

        private bool TryGetNamedNodeMapProperty(NamedNodeMap namedNodeMap, string property, out JsValue value)
        {
            switch (property)
            {
                case "length":
                    value = JsValue.FromInt32(namedNodeMap.Length);
                    return true;
                case "item":
                    value = _owner.GetOrCreateHostCallable(
                        namedNodeMap,
                        "item",
                        (_, args) =>
                        {
                            var index = args.Count > 0 && TryCoerceIndex(args[0], out var parsedIndex)
                                ? parsedIndex
                                : -1;
                            return _owner.ToHostOrNull(namedNodeMap.Item(index), HostObjectKind.Other);
                        },
                        length: 1);
                    return true;
                case "getNamedItem":
                    value = _owner.GetOrCreateHostCallable(
                        namedNodeMap,
                        "getNamedItem",
                        (_, args) =>
                        {
                            var name = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            return _owner.ToHostOrNull(namedNodeMap.GetNamedItem(name), HostObjectKind.Other);
                        },
                        length: 1);
                    return true;
                case "getNamedItemNS":
                    value = _owner.GetOrCreateHostCallable(
                        namedNodeMap,
                        "getNamedItemNS",
                        (_, args) =>
                        {
                            var namespaceUri = args.Count > 0 && args[0].Tag != JsValueTag.Null
                                ? CoerceToHostString(args[0])
                                : null;
                            var localName = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                            return _owner.ToHostOrNull(namedNodeMap.GetNamedItemNS(namespaceUri, localName), HostObjectKind.Other);
                        },
                        length: 2);
                    return true;
                case "setNamedItem":
                    value = _owner.GetOrCreateHostCallable(
                        namedNodeMap,
                        "setNamedItem",
                        (_, args) =>
                        {
                            var attr = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Attr>(args[0]) : null;
                            if (attr == null)
                            {
                                return JsValue.Null;
                            }

                            try
                            {
                                return _owner.ToHostOrNull(namedNodeMap.SetNamedItem(attr), HostObjectKind.Other);
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Undefined;
                            }
                        },
                        length: 1);
                    return true;
                case "setNamedItemNS":
                    value = _owner.GetOrCreateHostCallable(
                        namedNodeMap,
                        "setNamedItemNS",
                        (_, args) =>
                        {
                            var attr = args.Count > 0 ? _owner.ResolveHostObjectOrNull<Attr>(args[0]) : null;
                            if (attr == null)
                            {
                                return JsValue.Null;
                            }

                            try
                            {
                                return _owner.ToHostOrNull(namedNodeMap.SetNamedItemNS(attr), HostObjectKind.Other);
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Undefined;
                            }
                        },
                        length: 1);
                    return true;
                case "removeNamedItem":
                    value = _owner.GetOrCreateHostCallable(
                        namedNodeMap,
                        "removeNamedItem",
                        (_, args) =>
                        {
                            var name = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            try
                            {
                                return _owner.ToHostOrNull(namedNodeMap.RemoveNamedItem(name), HostObjectKind.Other);
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Undefined;
                            }
                        },
                        length: 1);
                    return true;
                case "removeNamedItemNS":
                    value = _owner.GetOrCreateHostCallable(
                        namedNodeMap,
                        "removeNamedItemNS",
                        (_, args) =>
                        {
                            var namespaceUri = args.Count > 0 && args[0].Tag != JsValueTag.Null
                                ? CoerceToHostString(args[0])
                                : null;
                            var localName = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                            try
                            {
                                return _owner.ToHostOrNull(namedNodeMap.RemoveNamedItemNS(namespaceUri, localName), HostObjectKind.Other);
                            }
                            catch (DomException ex)
                            {
                                _owner.ThrowDomException(ex.Name, ex.Message);
                                return JsValue.Undefined;
                            }
                        },
                        length: 2);
                    return true;
                default:
                    if (int.TryParse(property, NumberStyles.Integer, CultureInfo.InvariantCulture, out var index))
                    {
                        value = _owner.ToHostOrNull(namedNodeMap.Item(index), HostObjectKind.Other);
                        return true;
                    }

                    var named = namedNodeMap.GetNamedItem(property);
                    if (named != null)
                    {
                        value = _owner.ToHostOrNull(named, HostObjectKind.Other);
                        return true;
                    }

                    value = JsValue.Undefined;
                    return false;
            }
        }

        private bool TryGetDomTokenListProperty(DOMTokenList tokenList, string property, out JsValue value)
        {
            switch (property)
            {
                case "length":
                    value = JsValue.FromInt32(tokenList.Length);
                    return true;
                case "value":
