                        fragment,
                        "removeEventListener",
                        (_, args) =>
                        {
                            _owner.RemoveBrowserEventListener(
                                _owner._elementEventListeners.GetOrCreateValue(fragment),
                                args);
                            return JsValue.Undefined;
                        },
                        length: 2);
                    return true;
                case "dispatchEvent":
