                case "ready":
                case "finished":
                    value = _owner.CreateResolvedPromise(_owner.ToHostOrNull(animation, HostObjectKind.Other));
                    return true;
                case "cancel":
                    value = _owner.GetOrCreateHostCallable(
                        animation,
                        "cancel",
                        (_, _) =>
                        {
                            animation.PlayState = "idle";
                            animation.Pending = false;
                            animation.CurrentTime = 0;
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "finish":
                    value = _owner.GetOrCreateHostCallable(
                        animation,
                        "finish",
                        (_, _) =>
                        {
                            animation.PlayState = "finished";
                            animation.Pending = false;
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "play":
                    value = _owner.GetOrCreateHostCallable(
                        animation,
                        "play",
                        (_, _) =>
                        {
                            animation.PlayState = "running";
                            animation.Pending = false;
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "pause":
                    value = _owner.GetOrCreateHostCallable(
                        animation,
                        "pause",
                        (_, _) =>
                        {
                            animation.PlayState = "paused";
                            animation.Pending = false;
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "reverse":
                    value = _owner.GetOrCreateHostCallable(
                        animation,
                        "reverse",
                        (_, _) =>
                        {
                            animation.PlaybackRate = animation.PlaybackRate == 0 ? -1 : -animation.PlaybackRate;
                            animation.PlayState = "running";
                            animation.Pending = false;
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "updatePlaybackRate":
                    value = _owner.GetOrCreateHostCallable(
                        animation,
                        "updatePlaybackRate",
                        (_, args) =>
                        {
                            animation.PlaybackRate = args.Count > 0
                                ? CoerceToFiniteNumber(args[0], animation.PlaybackRate)
                                : animation.PlaybackRate;
                            return JsValue.Undefined;
                        },
                        length: 1);
                    return true;
                case "persist":
                case "commitStyles":
                    value = _owner.GetOrCreateHostCallable(
                        animation,
                        property,
                        (_, _) => JsValue.Undefined,
                        length: 0);
                    return true;
                case "addEventListener":
                case "removeEventListener":
