        private bool TryGetDomStringMapProperty(FenJsDomStringMapHost domStringMap, string property, out JsValue value)
        {
            var attributeName = PropertyNameToDatasetAttribute(property);
            var attributeValue = domStringMap.Element.GetAttribute(attributeName);
            value = attributeValue == null ? JsValue.Undefined : JsValue.FromString(attributeValue);
            return true;
        }

        private static string PropertyNameToDatasetAttribute(string propertyName)
        {
            if (string.IsNullOrEmpty(propertyName))
            {
                return "data-";
            }

            var builder = new StringBuilder("data-");
            for (var i = 0; i < propertyName.Length; i++)
            {
                var ch = propertyName[i];
                if (char.IsUpper(ch))
                {
                    builder.Append('-');
                    builder.Append(char.ToLowerInvariant(ch));
                }
                else
                {
                    builder.Append(ch);
                }
            }

            return builder.ToString();
        }

        private static bool TryCoerceIndex(JsValue value, out int index)
        {
            switch (value.Tag)
            {
                case JsValueTag.Int32:
                    index = value.AsInt32();
                    return true;
                case JsValueTag.Number:
                    var number = value.AsNumber();
                    if (double.IsFinite(number) && Math.Truncate(number) == number && number >= int.MinValue && number <= int.MaxValue)
                    {
                        index = (int)number;
                        return true;
                    }
                    break;
                case JsValueTag.String:
                    if (int.TryParse(value.AsString(), NumberStyles.Integer, CultureInfo.InvariantCulture, out index))
                    {
                        return true;
                    }
                    break;
            }

            index = -1;
            return false;
        }

        private bool TryGetNavigatorProperty(BrowserSurfaceProfile navigator, string property, out JsValue value)
        {
            switch (property)
            {
                case "userAgent":
                    value = JsValue.FromString(navigator.UserAgent ?? string.Empty);
                    return true;
                case "doNotTrack":
                    // HTML dom-navigator-donottrack: "1" when the preference is
                    // enabled, otherwise null. The profile stores "0" for the
                    // disabled case, but exposing that string would read as
                    // enabled-with-value-0 to feature detection; Chrome returns
                    // null here, and the surface profile is the source of truth
                    // for the SendDoNotTrack policy toggle.
                    value = string.Equals(navigator.DoNotTrack, "1", StringComparison.Ordinal)
                        ? JsValue.FromString("1")
                        : JsValue.Null;
                    return true;
                case "platform":
                    value = JsValue.FromString(navigator.PlatformToken ?? string.Empty);
                    return true;
                case "vendor":
                    value = JsValue.FromString(navigator.Vendor ?? string.Empty);
                    return true;
                case "cookieEnabled":
                    value = JsValue.FromBoolean(navigator.CookieEnabled);
                    return true;
                case "webdriver":
                    // NavigatorAutomationInformation: false unless the user agent
                    // itself was started under remote automation control. Leaving it
                    // undefined is a visible difference from every real browser, and
                    // pages that fingerprint the navigator read it constantly.
                    value = JsValue.FromBoolean(false);
                    return true;
                case "hardwareConcurrency":
                    value = JsValue.FromInt32(Math.Max(1, Environment.ProcessorCount));
                    return true;
                case "maxTouchPoints":
                    value = JsValue.FromInt32(0);
                    return true;
                case "deviceMemory":
                    value = JsValue.FromNumber(4); // common default
                    return true;
                case "language":
                    value = JsValue.FromString(navigator.Language ?? System.Globalization.CultureInfo.CurrentCulture.TwoLetterISOLanguageName);
                    return true;
                case "languages":
                    // Must return a frozen array per spec. Bot detection checks Array.isArray(navigator.languages).
                    {
                        var lang = navigator.Language ?? "en-US";
                        var shortLang = lang.Contains("-") ? lang.Substring(0, lang.IndexOf('-')) : lang;
                        value = _owner._interpreter.AllocateArray(new[]
                        {
                            JsValue.FromString(lang),
                            JsValue.FromString(shortLang)
                        });
                    }
                    return true;
                case "onLine":
                    value = JsValue.FromBoolean(true);
                    return true;
                case "appName":
                    value = JsValue.FromString("Netscape");
                    return true;
                case "appVersion":
                    value = JsValue.FromString("5.0");
                    return true;
                case "product":
                    value = JsValue.FromString("Gecko");
                    return true;
                case "serviceWorker":
                    value = _owner.GetStoredHostPropertyOrUndefined(navigator, "serviceWorker");
                    if (value.Tag == JsValueTag.Undefined)
                    {
                        value = _owner.CreateDefaultServiceWorkerStub();
                        _owner.SetStoredHostProperty(navigator, "serviceWorker", value);
                    }
                    return true;
                case "storage":
                    value = _owner.GetStoredHostPropertyOrUndefined(navigator, "storage");
                    if (value.Tag == JsValueTag.Undefined)
                    {
                        value = _owner.CreateDefaultStorageStub();
                        _owner.SetStoredHostProperty(navigator, "storage", value);
                    }
                    return true;
                default:
                    value = JsValue.Undefined;
                    return false;
            }
        }

        private static bool TrySetCanvasContextProperty(
            FenJsCanvasRenderingContext2DHost context,
            string property,
            JsValue value)
        {
            switch (property)
            {
                case "fillStyle":
                    context.SetFillStyle(CoerceToHostString(value));
                    return true;
                case "strokeStyle":
                    context.SetStrokeStyle(CoerceToHostString(value));
                    return true;
                case "lineWidth":
                    context.SetLineWidth((float)CoerceToFiniteNumber(value, 1d));
                    return true;
                case "globalAlpha":
                    context.SetGlobalAlpha((float)CoerceToFiniteNumber(value, 1d));
                    return true;
                case "lineCap":
                    context.SetLineCap(CoerceToHostString(value));
                    return true;
                case "lineJoin":
                    context.SetLineJoin(CoerceToHostString(value));
                    return true;
                case "miterLimit":
                    context.SetMiterLimit((float)CoerceToFiniteNumber(value, 10d));
                    return true;
                case "font":
                    context.SetFont(CoerceToHostString(value));
                    return true;
                case "textAlign":
                    context.SetTextAlign(CoerceToHostString(value));
                    return true;
                case "textBaseline":
                    context.SetTextBaseline(CoerceToHostString(value));
                    return true;
                case "lineDashOffset":
                    context.SetLineDashOffset((float)CoerceToFiniteNumber(value, 0d));
                    return true;
                case "imageSmoothingEnabled":
                    context.ImageSmoothingEnabled = CoerceToHostBoolean(value);
                    return true;
                case "globalCompositeOperation":
                    context.GlobalCompositeOperation = CoerceToHostString(value);
                    return true;
                default:
                    return false;
            }
        }

        private static double CanvasArg(IReadOnlyList<JsValue> args, int index, double fallback)
        {
            return args != null && args.Count > index
                ? CoerceToFiniteNumber(args[index], fallback)
                : fallback;
        }

