        private bool TryReadNumberList(JsValue value, ref float[] segments)
        {
            var numbers = new List<float>();
            if (value.Tag == JsValueTag.Object)
            {
                var lengthValue = _owner.ReadJsProperty(value, "length");
                if (lengthValue.Tag == JsValueTag.Number)
                {
                    var count = (int)lengthValue.AsNumber();
                    for (var i = 0; i < count; i++)
                    {
                        var item = _owner.ReadJsProperty(value, i.ToString(CultureInfo.InvariantCulture));
                        if (item.Tag == JsValueTag.Number)
                        {
                            numbers.Add((float)item.AsNumber());
                        }
                    }
                }
            }

            segments = numbers.ToArray();
            return numbers.Count > 0;
        }

        private bool TryGetCanvasGradientProperty(
            FenJsCanvasGradientHost gradient,
            string property,
            out JsValue value)
        {
            if (string.Equals(property, "addColorStop", StringComparison.Ordinal))
            {
                value = _owner.GetOrCreateHostCallable(
                    gradient, "addColorStop",
                    (_, args) =>
                    {
                        var offset = (float)CanvasArg(args, 0, 0d);
                        var color = args.Count > 1 ? CoerceToHostString(args[1]) : "#000000";
                        try
                        {
                            gradient.AddColorStop(offset, color);
                        }
                        catch (ArgumentOutOfRangeException)
                        {
                            _owner.ThrowDomException(
                                "SyntaxError",
                                "Failed to execute 'addColorStop': invalid color stop offset.");
                        }

                        return JsValue.Undefined;
                    },
                    length: 2);
                return true;
            }

            value = JsValue.Undefined;
            return false;
        }

        private bool TryGetStorageProperty(FenStorageAreaHost storageArea, string property, out JsValue value)
        {
            switch (property)
            {
                case "length":
                    value = JsValue.FromInt32(storageArea.Length);
                    return true;
                case "key":
                    value = _owner.GetOrCreateHostCallable(
                        storageArea, "key",
                        (_, args) =>
                        {
                            var index = args.Count > 0 ? (int)CoerceToFiniteNumber(args[0], 0) : 0;
                            var result = storageArea.Key(index);
                            return result != null ? JsValue.FromString(result) : JsValue.Null;
                        },
                        length: 1);
                    return true;
                case "getItem":
                    value = _owner.GetOrCreateHostCallable(
                        storageArea, "getItem",
                        (_, args) =>
                        {
                            var key = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            var result = storageArea.GetItem(key);
                            return result != null ? JsValue.FromString(result) : JsValue.Null;
                        },
                        length: 1);
                    return true;
                case "setItem":
                    value = _owner.GetOrCreateHostCallable(
                        storageArea, "setItem",
                        (_, args) =>
                        {
                            var key = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            var val = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                            storageArea.SetItem(key, val);
                            return JsValue.Undefined;
                        },
                        length: 2);
                    return true;
                case "removeItem":
                    value = _owner.GetOrCreateHostCallable(
                        storageArea, "removeItem",
                        (_, args) =>
                        {
                            var key = args.Count > 0 ? CoerceToHostString(args[0]) : string.Empty;
                            storageArea.RemoveItem(key);
                            return JsValue.Undefined;
                        },
                        length: 1);
                    return true;
                case "clear":
                    value = _owner.GetOrCreateHostCallable(
                        storageArea, "clear",
                        (_, _) =>
                        {
                            storageArea.Clear();
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                default:
                    // Per spec, storage[key] is equivalent to storage.getItem(key).
                    var item = storageArea.GetItem(property);
                    if (item != null)
                    {
                        value = JsValue.FromString(item);
                        return true;
                    }
                    value = JsValue.Undefined;
                    return false;
            }
        }

        private bool TryGetHistoryProperty(FenJsHistoryHost history, string property, out JsValue value)
        {
            if (string.Equals(property, "pushState", StringComparison.Ordinal) ||
                string.Equals(property, "replaceState", StringComparison.Ordinal))
            {
                value = _owner.GetStoredHostPropertyOrUndefined(history, property);
                if (value.Tag != JsValueTag.Undefined)
                {
                    return true;
                }
            }

            switch (property)
            {
                case "length":
                    value = JsValue.FromInt32(_owner._historyBridge?.Length ?? history.Length);
                    return true;
                case "state":
                    value = _owner._historyBridge != null
                        ? CoerceBridgeHistoryState(_owner._historyBridge.State)
                        : history.State;
                    return true;
                case "scrollRestoration":
                    // HTML 7.10.3: a ScrollRestoration enum, "auto" by default.
                    // Frameworks read it to decide whether to manage scroll
                    // position themselves (Next.js does on every route change).
                    value = _owner.GetStoredHostPropertyOrUndefined(history, "scrollRestoration");
                    if (value.Tag != JsValueTag.String)
                    {
                        value = JsValue.FromString("auto");
                    }

                    return true;
                case "pushState":
                    value = _owner.GetOrCreateHostCallable(
                        history,
                        "pushState",
                        (_, args) =>
                        {
                            var state = args.Count > 0 ? args[0] : JsValue.Null;
                            var title = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                            var url = args.Count > 2 && args[2].Tag != JsValueTag.Undefined
                                ? CoerceToHostString(args[2])
                                : string.Empty;

                            if (_owner._historyBridge != null)
                            {
                                _owner._historyBridge.PushState(state, title, url);
                                history.Length = _owner._historyBridge.Length;
                                history.State = CoerceBridgeHistoryState(_owner._historyBridge.State);
                                _owner.UpdateFenJsLocation(history.Location, _owner._historyBridge.CurrentUrl);
                            }
                            else
                            {
                                history.State = state;
                                history.Length = Math.Max(1, history.Length + 1);
                                _owner.ApplyHistoryUrl(history.Location, url);
                            }

                            return JsValue.Undefined;
                        },
                        length: 2);
                    return true;
                case "replaceState":
                    value = _owner.GetOrCreateHostCallable(
                        history,
                        "replaceState",
                        (_, args) =>
                        {
                            var state = args.Count > 0 ? args[0] : JsValue.Null;
                            var title = args.Count > 1 ? CoerceToHostString(args[1]) : string.Empty;
                            var url = args.Count > 2 && args[2].Tag != JsValueTag.Undefined
                                ? CoerceToHostString(args[2])
                                : string.Empty;

                            if (_owner._historyBridge != null)
                            {
                                _owner._historyBridge.ReplaceState(state, title, url);
                                history.Length = _owner._historyBridge.Length;
                                history.State = CoerceBridgeHistoryState(_owner._historyBridge.State);
                                _owner.UpdateFenJsLocation(history.Location, _owner._historyBridge.CurrentUrl);
                            }
                            else
                            {
                                history.State = state;
                                _owner.ApplyHistoryUrl(history.Location, url);
                            }

                            return JsValue.Undefined;
                        },
                        length: 2);
                    return true;
                case "go":
                    value = _owner.GetOrCreateHostCallable(
                        history,
                        "go",
                        (_, args) =>
                        {
                            var delta = args.Count > 0 ? (int)CoerceToFiniteNumber(args[0], 0) : 0;
                            _owner._historyBridge?.Go(delta);
                            if (_owner._historyBridge != null)
                            {
                                history.Length = _owner._historyBridge.Length;
                                history.State = CoerceBridgeHistoryState(_owner._historyBridge.State);
                                _owner.UpdateFenJsLocation(history.Location, _owner._historyBridge.CurrentUrl);
                            }
                            return JsValue.Undefined;
                        },
                        length: 1);
                    return true;
                case "back":
                    value = _owner.GetOrCreateHostCallable(
                        history,
                        "back",
                        (_, _) =>
                        {
                            _owner._historyBridge?.Go(-1);
                            if (_owner._historyBridge != null)
                            {
                                history.Length = _owner._historyBridge.Length;
                                history.State = CoerceBridgeHistoryState(_owner._historyBridge.State);
                                _owner.UpdateFenJsLocation(history.Location, _owner._historyBridge.CurrentUrl);
                            }
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                case "forward":
                    value = _owner.GetOrCreateHostCallable(
                        history,
                        "forward",
                        (_, _) =>
                        {
                            _owner._historyBridge?.Go(1);
                            if (_owner._historyBridge != null)
                            {
                                history.Length = _owner._historyBridge.Length;
                                history.State = CoerceBridgeHistoryState(_owner._historyBridge.State);
                                _owner.UpdateFenJsLocation(history.Location, _owner._historyBridge.CurrentUrl);
                            }
                            return JsValue.Undefined;
                        },
                        length: 0);
                    return true;
                default:
                    value = JsValue.Undefined;
                    return false;
            }
        }

        private static JsValue CoerceBridgeHistoryState(object state)
        {
            return state switch
            {
                null => JsValue.Null,
                JsValue jsValue => jsValue,
                string text => JsValue.FromString(text),
                bool boolean => JsValue.FromBoolean(boolean),
                int int32 => JsValue.FromInt32(int32),
                double number => JsValue.FromNumber(number),
                float number => JsValue.FromNumber(number),
                long integer => JsValue.FromNumber(integer),
                _ => JsValue.Null
            };
        }

        private bool TryGetLocationProperty(FenJsLocationHost location, string property, out JsValue value)
        {
            var uri = location.Uri;
            var absolute = uri?.AbsoluteUri ?? string.Empty;
            switch (property)
            {
                case "href":
                    value = JsValue.FromString(absolute);
                    return true;
                case "origin":
                    value = JsValue.FromString(uri?.GetLeftPart(UriPartial.Authority) ?? string.Empty);
                    return true;
                case "protocol":
                    value = JsValue.FromString(uri?.Scheme is string scheme && scheme.Length > 0 ? scheme + ":" : string.Empty);
                    return true;
                case "host":
                    value = JsValue.FromString(uri?.IsDefaultPort == false ? $"{uri.Host}:{uri.Port}" : uri?.Host ?? string.Empty);
                    return true;
                case "hostname":
                    value = JsValue.FromString(uri?.Host ?? string.Empty);
                    return true;
                case "pathname":
                    value = JsValue.FromString(uri?.AbsolutePath ?? string.Empty);
                    return true;
                case "search":
                    value = JsValue.FromString(uri?.Query ?? string.Empty);
                    return true;
                case "hash":
                    value = JsValue.FromString(uri?.Fragment ?? string.Empty);
                    return true;
                case "port":
                    // HTML 7.10.5 dom-location-port: the URL's port, serialized
                    // empty when the scheme's default port is in use - which is
                    // why `host` above only appends it when IsDefaultPort is false.
                    value = JsValue.FromString(
                        uri == null || uri.IsDefaultPort
                            ? string.Empty
                            : uri.Port.ToString(CultureInfo.InvariantCulture));
                    return true;
                case "toString":
                    value = _owner.GetOrCreateHostCallable(
                        location,
                        "toString",
                        (_, _) => JsValue.FromString(location.Uri?.AbsoluteUri ?? string.Empty),
                        length: 0);
                    return true;
                case "reload":
                    value = _owner.GetOrCreateHostCallable(
                        location, "reload",
                        (_, _2) => { _owner.NavigateOwningBrowsingContext(uri); return JsValue.Undefined; },
                        length: 1);
                    return true;
                case "replace":
                    value = _owner.GetOrCreateHostCallable(
                        location, "replace",
                        (_, args) =>
                        {
                            var url = args.Count > 0 ? CoerceToHostString(args[0]) : null;
                            if (!string.IsNullOrWhiteSpace(url) && Uri.TryCreate(uri, url, out var navUri))
                                _owner.NavigateOwningBrowsingContext(navUri);
                            return JsValue.Undefined;
                        }, length: 1);
                    return true;
                case "assign":
                    value = _owner.GetOrCreateHostCallable(
                        location, "assign",
                        (_, args) =>
                        {
                            var url = args.Count > 0 ? CoerceToHostString(args[0]) : null;
                            if (!string.IsNullOrWhiteSpace(url) && Uri.TryCreate(uri, url, out var navUri))
                                _owner.NavigateOwningBrowsingContext(navUri);
                            return JsValue.Undefined;
                        }, length: 1);
                    return true;
                default:
                    value = JsValue.Undefined;
                    return false;
            }
        }

        private static string ResolveElementUrlProperty(Element element, string attributeName)
        {
            var raw = element?.GetAttribute(attributeName) ?? string.Empty;
            if (string.IsNullOrWhiteSpace(raw))
            {
                return string.Empty;
            }

            if (Uri.TryCreate(raw, UriKind.Absolute, out var absolute))
            {
                return absolute.AbsoluteUri;
            }

            var ownerDocument = element.OwnerDocument;
            var baseRaw =
                ownerDocument?.BaseURI ??
                ownerDocument?.DocumentURI ??
                ownerDocument?.URL;

            if (Uri.TryCreate(baseRaw, UriKind.Absolute, out var baseUri) &&
                Uri.TryCreate(baseUri, raw, out var resolved))
            {
                return resolved.AbsoluteUri;
            }

            return raw;
        }

        private static bool IsImageElement(Element element)
        {
            return string.Equals(element?.TagName, "img", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(element?.TagName, "image", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsMetaElement(Element element) =>
            string.Equals(element?.TagName, "meta", StringComparison.OrdinalIgnoreCase);

        private static bool IsScriptElement(Element element) =>
            string.Equals(element?.TagName, "script", StringComparison.OrdinalIgnoreCase);

        private static bool IsStyleElement(Element element) =>
            string.Equals(element?.TagName, "style", StringComparison.OrdinalIgnoreCase);

        private static bool IsTextAreaElement(Element element) =>
            string.Equals(element?.TagName, "textarea", StringComparison.OrdinalIgnoreCase);

        private static bool IsOptionElement(Element element) =>
            string.Equals(element?.TagName, "option", StringComparison.OrdinalIgnoreCase);

        private static bool IsButtonElement(Element element) =>
            string.Equals(element?.TagName, "button", StringComparison.OrdinalIgnoreCase);

        private static bool IsSelectElement(Element element) =>
            string.Equals(element?.TagName, "select", StringComparison.OrdinalIgnoreCase);

        private static bool IsFieldSetElement(Element element) =>
            string.Equals(element?.TagName, "fieldset", StringComparison.OrdinalIgnoreCase);

        // HTML groups a and area as "hyperlink elements": they share href, hash,
        // type and the rest of the URL-decomposition members.
        private static bool IsHyperlinkElement(Element element) =>
            string.Equals(element?.TagName, "a", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(element?.TagName, "area", StringComparison.OrdinalIgnoreCase);

        // HTML 4.6.3 HTMLHyperlinkElementUtils getters read the element's url, parsed from
        // its resolved href. With no href, or one that does not parse, every part is empty
        // except protocol, which is ":". search is empty when the query is empty too.
        private string ReadHyperlinkUrlPart(Element element, string part)
        {
            var url = element.GetAttribute("href") == null
                ? null
                : FenBrowser.Core.Network.WhatwgUrl.Parse(ResolveElementUrlProperty(element, "href"));
            if (url == null)
            {
                return part == "protocol" ? ":" : string.Empty;
            }

            return part switch
            {
                "origin" => url.Origin,
                "protocol" => url.Protocol,
                "username" => url.Username,
                "password" => url.Password,
                "host" => url.Host,
                "hostname" => url.Hostname,
                "port" => url.Port,
                "pathname" => url.Pathname,
                "search" => url.Search == "?" ? string.Empty : url.Search,
                _ => string.Empty
            };
        }

        // rel/relList is defined on link in addition to the hyperlink elements.
        private static bool IsRelListElement(Element element) =>
            IsHyperlinkElement(element) ||
            string.Equals(element?.TagName, "link", StringComparison.OrdinalIgnoreCase);

        private static void SetBooleanAttribute(Element element, string attributeName, bool enabled)
        {
            if (enabled)
            {
                element.SetAttribute(attributeName, string.Empty);
            }
            else
            {
                element.RemoveAttribute(attributeName);
            }
        }

        private static bool IsDialogElement(Element element)
        {
            return string.Equals(element?.TagName, "dialog", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsTemplateElement(Element element)
        {
            return string.Equals(element?.TagName, "template", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsIFrameElement(Element element)
        {
            return string.Equals(element?.TagName, "iframe", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsCheckableInputElement(Element element)
        {
            if (!string.Equals(element?.TagName, "input", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            var type = element.GetAttribute("type");
            return string.Equals(type, "checkbox", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(type, "radio", StringComparison.OrdinalIgnoreCase);
        }

        private static string ReadElementValue(Element element)
            => FenBrowser.FenEngine.Rendering.FormControlValue.Read(element);

        private static string ReadInputType(Element element)
            => FenBrowser.FenEngine.Rendering.FormControlValue.ReadInputType(element);

        private static void SetElementValue(Element element, string value)
            => FenBrowser.FenEngine.Rendering.FormControlValue.Write(element, value);

        private static string ReadElementDefaultValue(Element element)
            => FenBrowser.FenEngine.Rendering.FormControlValue.ReadDefault(element);

        private static void SetElementDefaultValue(Element element, string value)
            => FenBrowser.FenEngine.Rendering.FormControlValue.WriteDefault(element, value);

        private static int ReadElementTabIndex(Element element)
        {
            var raw = element?.GetAttribute("tabindex");
            if (int.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed))
            {
                return parsed;
            }

            if (element == null)
            {
                return -1;
            }

            var tagName = element.TagName ?? string.Empty;
            if (string.Equals(tagName, "a", StringComparison.OrdinalIgnoreCase))
            {
                return element.HasAttribute("href") ? 0 : -1;
            }

            return
                string.Equals(tagName, "button", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(tagName, "input", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(tagName, "select", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(tagName, "textarea", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(tagName, "iframe", StringComparison.OrdinalIgnoreCase)
                    ? 0
                    : -1;
        }
    }
}

/// <summary>
/// Centralized runtime selection for browser script execution.
/// The browser now runs on the FenJS-backed runtime by default; the legacy
/// FenEngine runtime remains reachable only as an explicit escape hatch via
/// <summary>
/// Static factory for browser script engine instances.
/// FenJS is the only runtime â€” no legacy fallback.
/// </summary>
public static class BrowserScriptEngineRuntime
{
    private static Func<IJsHost, IBrowserScriptEngine> _factory = CreateConfiguredDefault;

    public static Func<IJsHost, IBrowserScriptEngine> Factory
    {
        get => _factory;
        set => _factory = value ?? CreateConfiguredDefault;
    }

    public static IBrowserScriptEngine Create(IJsHost host)
    {
        return _factory(host);
    }

    public static void Reset()
    {
        _factory = CreateConfiguredDefault;
    }

    private static IBrowserScriptEngine CreateConfiguredDefault(IJsHost host)
    {
        return new FenJsBrowserScriptEngine(host);
    }
}

/// <summary>
/// Diagnostic Promise rejection tracker that defers reporting until the
/// microtask checkpoint so same-turn handlers do not produce false failures.
/// Delegates to the inner tracker for normal operation.
/// </summary>
internal sealed class FenJsDiagnosticPromiseRejectionTracker : IHostPromiseRejectionTracker
{
    private readonly IHostPromiseRejectionTracker _inner;
    private readonly Action<JsValue, PromiseRejectionOperation> _lifecycleObserver;
    private readonly Func<JsValue, string> _unhandledObserver;
    private readonly object _sync = new();
    private readonly List<JsValue> _pending = new();
    private int _rejectedCount;
    private int _handledCount;

    public FenJsDiagnosticPromiseRejectionTracker(
        IHostPromiseRejectionTracker inner,
        Action<JsValue, PromiseRejectionOperation> lifecycleObserver,
        Func<JsValue, string> unhandledObserver)
    {
        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
        _lifecycleObserver = lifecycleObserver ?? throw new ArgumentNullException(nameof(lifecycleObserver));
        _unhandledObserver = unhandledObserver ?? throw new ArgumentNullException(nameof(unhandledObserver));
    }

    public void Track(JsValue promise, PromiseRejectionOperation operation)
    {
        _inner.Track(promise, operation);
        var observed = false;
        lock (_sync)
        {
            if (operation == PromiseRejectionOperation.Reject)
            {
                if (_pending.Count < 128 || _pending.Contains(promise))
                {
                    if (!_pending.Contains(promise))
                    {
                        _pending.Add(promise);
                    }
                    observed = true;
                }
            }
            else if (operation == PromiseRejectionOperation.Handle)
            {
                _pending.Remove(promise);
                Interlocked.Increment(ref _handledCount);
                observed = true;
            }
        }

        if (observed)
        {
            try
            {
                _lifecycleObserver(promise, operation);
            }
            catch
            {
                // Diagnostics must not change Promise settlement or handler behavior.
            }
        }
    }

    public void FlushPending()
    {
        JsValue[] pending;
        lock (_sync)
        {
            if (_pending.Count == 0)
            {
                return;
            }

            pending = _pending.ToArray();
            _pending.Clear();
        }

        foreach (var promise in pending)
        {
            var count = Interlocked.Increment(ref _rejectedCount);
            var reason = string.Empty;
            try
            {
                reason = _unhandledObserver(promise) ?? string.Empty;
            }
            catch
            {
                // Diagnostics must not change Promise settlement or handler behavior.
            }

            if (count <= 20)
            {
                FenLogger.Warn(
                    reason.Length == 0
                        ? $"[PromiseRejection] Unhandled rejection #{count}, reason unavailable"
                        : $"[PromiseRejection] Unhandled rejection #{count}: {Truncate(reason, 300)}",
                    LogCategory.JavaScript);
            }
        }
    }

    private static string Truncate(string value, int max)
    {
        var single = value.Replace('\r', ' ').Replace('\n', ' ');
        return single.Length <= max ? single : single.Substring(0, max) + "...";
    }

    public void Reset()
    {
        lock (_sync)
        {
            _pending.Clear();
        }
        Interlocked.Exchange(ref _rejectedCount, 0);
        Interlocked.Exchange(ref _handledCount, 0);
    }
}
